} LTE_TransportChannelConfig;

// Function to initialize and populate a dynamic array of LTE_TransportChannelConfig structures
LTE_TransportChannelConfig** init_transport_channels(int num_cells, int num_transport_channels) {
    // Check for invalid input parameters
    if (num_cells <= 0 || num_transport_channels <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the dynamic array of LTE_TransportChannelConfig structures
    LTE_TransportChannelConfig** transport_channels = (LTE_TransportChannelConfig**)malloc(num_cells * sizeof(LTE_TransportChannelConfig*));
    if (!transport_channels) {
        fprintf(stderr, "Failed to allocate memory for transport channels\n");
        return NULL;
    }

    // Initialize each structure in the dynamic array with sufficient memory for its fields
    for (int i = 0; i < num_cells; i++) {
        transport_channels[i] = (LTE_TransportChannelConfig*)malloc(sizeof(LTE_TransportChannelConfig));
        if (!transport_channels[i]) {
            fprintf(stderr, "Failed to allocate memory for transport channel %d\n", i);
            return NULL;
        }
    }

    // Populate the dynamic array with data from external sources
    for (int i = 0; i < num_cells; i++) {
        for (int j = 0; j < num_transport_channels; j++) {
            transport_channels[i][j].cell_id = i + 1;
            transport_channels[i][j].transport_channel_name = "Transport Channel";
            transport_channels[i][j].transport_channel_type = 0;
        }
    }

    // Validate the data from external sources to ensure correctness
    for (int i = 0; i < num_cells; i++) {
        for (int j = 0; j < num_transport_channels; j++) {
            if (!transport_channels[i][j].cell_id || !transport_channels[i][j].transport_channel_name || transport_channels[i][j].transport_channel_type < 0) {
                fprintf(stderr, "Invalid data for cell %d and transport channel %d\n", i + 1, j + 1);
                return NULL;
            }
        }
    }

    // Return the initialized dynamic array of LTE_TransportChannelConfig structures
    return transport_channels;
}

// Function to free memory allocated for the dynamic array of LTE_TransportChannelConfig structures
void free_transport_channels(LTE_TransportChannelConfig** transport_channels, int num_cells) {
    // Check for invalid input parameters
    if (!transport_channels || num_cells <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Free memory allocated for each structure in the dynamic array
    for (int i = 0; i < num_cells; i++) {
        free(transport_channels[i]);
    }

    // Free memory allocated for the dynamic array of LTE_TransportChannelConfig structures
    free(transport_channels);
}
