// Define a structure to represent a record
typedef struct {
    int key;
    double timestamp;
    char status_flag;
} Record;

// Define a function to initialize an array of records
void init_records(Record** records, size_t num_records, int min_key, int max_key) {
    // Allocate memory for the array of records
    *records = (Record*)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize each record with a random integer key and timestamp
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].key = rand() % (max_key - min_key + 1) + min_key;
        (*records)[i].timestamp = (double)rand() / RAND_MAX;
        (*records)[i].status_flag = 'A';
    }
}

// Define a function to free the memory allocated for an array of records
void free_records(Record** records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}

int main() {
    // Define the number of records to initialize
    size_t num_records = 1000000;

    // Define the minimum and maximum values for the integer key field
    int min_key = 0;
    int max_key = 1000000;

    // Initialize an array of records with random integer keys and timestamps
    Record* records = NULL;
    init_records(&records, num_records, min_key, max_key);

    // Free the memory allocated for the array of records
    free_records(&records);

    return 0;
}
