#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

// Define a struct to store DNS resolution results
struct dns_result {
    char *hostname;
    u_char ip[4];
};

// Define a queue data structure to manage concurrent DNS requests
typedef struct {
    int size;
    int front, rear;
    struct dns_result **queue;
} queue_t;

// Function to perform DNS resolution for a given hostname
int resolve_dns(char *hostname) {
    // Create a socket and connect to the DNS server
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(53);
    inet_pton(AF_INET, "8.8.8.8", &serv_addr.sin_addr);

    // Send a DNS query to the server and receive the response
    char *query = "QUERY TYPE=A HOSTNAME=";
    strcat(query, hostname);
    sendto(sock, query, strlen(query), 0, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
    struct dns_result *result = malloc(sizeof(struct dns_result));
    result->hostname = hostname;
    recvfrom(sock, &result->ip, sizeof(u_char) * 4, 0, NULL, NULL);

    // Close the socket and return the DNS resolution results
    close(sock);
    return result;
}

// Function to process a line from the log file
void process_line(char *line) {
    // Split the line into fields using "," as the delimiter
    char **fields = strsplit(line, ",");

    // Perform DNS resolution for each hostname in the line
    int num_hosts = 0;
    struct dns_result **dns_results = malloc(sizeof(struct dns_result *) * 10);
    for (int i = 0; fields[i] != NULL; i++) {
        if (strncmp(fields[i], "HOSTNAME", 8) == 0) {
            char *hostname = fields[i + 1];
            struct dns_result *dns_result = resolve_dns(hostname);
            dns_results[num_hosts++] = dns_result;
        }
    }

    // Calculate the average of the last two numerical fields in the line
    int num1 = 0, num2 = 0;
    for (int i = 0; i < num_hosts; i++) {
        char *hostname = dns_results[i]->hostname;
        u_char *ip = dns_results[i]->ip;
        if (strncmp(hostname, "HOSTNAME1", 9) == 0) {
            num1 = ip[3];
        } else if (strncmp(hostname, "HOSTNAME2", 9) == 0) {
            num2 = ip[3];
        }
    }
    int average = (num1 + num2) / 2;

    // Print the contents of the line in a comma-separated format
    printf("%s,%d\n", line, average);

    // Free the allocated memory for the DNS resolution results
    for (int i = 0; i < num_hosts; i++) {
        free(dns_results[i]);
    }
    free(dns_results);
}

// Function to read from a potentially large log file and process each line
void read_log_file(char *filename) {
    // Open the log file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening log file");
        exit(1);
    }

    // Dynamically allocate memory for each line to store its content
    char *line = malloc(sizeof(char) * 1024);
    while (fgets(line, 1024, fp) != NULL) {
        process_line(line);
    }

    // Free the allocated memory for the line buffer
    free(line);
}

// Main function to read from a potentially large log file and perform DNS resolution
int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    // Initialize a queue to manage concurrent DNS requests
    queue_t *queue = malloc(sizeof(queue_t));
    queue->size = 10;
    queue->front = queue->rear = 0;
    queue->queue = malloc(sizeof(struct dns_result *) * queue->size);

    // Read from the log file and process each line
    read_log_file(argv[1]);

    // Free the allocated memory for the queue
    free(queue->queue);
    free(queue);

    return 0;
}
