// Validate the input file path for existence and readability, considering symbolic links and permissions
int validate_input_file_path(const char* input_file_path) {
  // Check if the input file path exists and is a regular file
  struct stat buffer;
  return (stat(input_file_path, &buffer) == 0 && S_ISREG(buffer.st_mode));
