  if (read_bytes != KEY_SIZE) {
    free(encryption_key);
    return NULL;
  }

  // Close the configuration file and return the encryption key
  fclose(config_file);
  return encryption_key;
}

// Cache previously computed cipher objects for efficiency, balancing cache size limits against hit rates
int cache_hit(const char* input_file_path) {
