void insert_sorted(std::vector<int>& vec, int value, int comparison_value, std::function<bool(int, int)> compare) {
    // Find the first occurrence of the comparison value in the vector
    auto it = std::find(vec.begin(), vec.end(), comparison_value);

    // If the comparison value is not found, insert at the end of the vector
    if (it == vec.end()) {
        vec.push_back(value);
    } else {
        // Insert the new value after the first occurrence of the comparison value
        vec.insert(it + 1, value);

        // Ensure that the vector remains sorted based on the provided comparison function
        std::sort(vec.begin(), vec.end(), compare);
    }
}
