using System;
using System.Xml;

namespace XmlUtils
{
    public static class XmlParser
    {
        public static XmlElement FindFirstElement(string xml, string tagName)
        {
            try
            {
                var doc = new XmlDocument();
                doc.LoadXml(xml);
                return doc.GetElementsByTagName(tagName)[0];
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
                return null;
            }
        }

        public static void SerializeElements(IEnumerable<XmlElement> elements, string outputFilePath)
        {
            try
            {
                var doc = new XmlDocument();
                foreach (var element in elements)
                {
                    doc.AppendChild(doc.ImportNode(element, true));
                }
                doc.Save(outputFilePath);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
        }
    }
}
