use std::env;
use std::fs;
use std::path::PathBuf;

pub mod directory_manager {
    pub fn create_directory(name: &str) -> Result<(), String> {
        let mut path = PathBuf::from(env::var("HOME").unwrap());
        path.push(name);

        if !path.exists() {
            fs::create_dir(&path).map_err(|e| e.to_string())?;
        }

        Ok(())
    }

    pub fn update_env_var(name: &str, value: &str) -> Result<(), String> {
        let mut path = PathBuf::from(env::var("HOME").unwrap());
        path.push(".bashrc");

        if !path.exists() {
            return Err(format!("File {} does not exist", path.display()));
        }

        let mut file = fs::OpenOptions::new().append(true).open(&path).map_err(|e| e.to_string())?;
        writeln!(file, "export {}={}", name, value)?;

        Ok(())
    }
}
