function updateUserProfile($userId, $lastActiveTimestamp, $userAgentString, $ipAddress) {
    // Check if user exists in the database
    $user = getUserById($userId);
    if (!$user) {
        throw new Exception("User does not exist");
    }

    // Update last active timestamp and user agent string
    $updatedUser = updateLastActiveTimestampAndUserAgentString($user, $lastActiveTimestamp, $userAgentString);

    // Log user activity to external logging service
    logUserActivity($userId, $lastActiveTimestamp, $userAgentString, $ipAddress);

    // Notify user via email with confirmation message
    sendEmailConfirmationMessage($userId, "Your profile has been updated successfully.");

    // Rate-limit updates to prevent abuse
    rateLimitUpdates($userId);

    // Optimize database operations for high traffic during peak hours
    optimizeDatabaseOperations();
}

function getUserById($userId) {
    // Implement logic to retrieve user from database
    $user = query("SELECT * FROM users WHERE id = ?", [$userId]);
    return $user;
}

function updateLastActiveTimestampAndUserAgentString($user, $lastActiveTimestamp, $userAgentString) {
    // Implement logic to update last active timestamp and user agent string in database
    query("UPDATE users SET last_active = ?, user_agent = ? WHERE id = ?", [$lastActiveTimestamp, $userAgentString, $user->id]);
}

function logUserActivity($userId, $lastActiveTimestamp, $userAgentString, $ipAddress) {
    // Implement logic to log user activity to external logging service
    $logEntry = array(
        "userId" => $userId,
        "lastActiveTimestamp" => $lastActiveTimestamp,
        "userAgentString" => $userAgentString,
        "ipAddress" => $ipAddress
    );
    log($logEntry);
}

function sendEmailConfirmationMessage($userId, $message) {
    // Implement logic to send email confirmation message to user
    $email = getUserEmailById($userId);
    sendEmail($email, "Your profile has been updated successfully.", $message);
}

function rateLimitUpdates($userId) {
    // Implement logic to rate-limit updates for user
    $rateLimited = isRateLimited($userId);
    if ($rateLimited) {
        throw new Exception("Too many updates, please try again later.");
    }
}

function optimizeDatabaseOperations() {
    // Implement logic to optimize database operations for high traffic during peak hours
    $optimized = optimizeDatabaseOperations();
    if (!$optimized) {
        throw new Exception("Failed to optimize database operations, please try again later.");
    }
}

function getUserEmailById($userId) {
    // Implement logic to retrieve user email from database
    $email = query("SELECT email FROM users WHERE id = ?", [$userId]);
    return $email;
}

function sendEmail($to, $subject, $message) {
    // Implement logic to send email message
    $sent = mail($to, $subject, $message);
    if (!$sent) {
        throw new Exception("Failed to send email, please try again later.");
    }
}

function isRateLimited($userId) {
    // Implement logic to check if user is rate-limited
    $rateLimited = query("SELECT rate_limited FROM users WHERE id = ?", [$userId]);
    return $rateLimited;
}

function optimizeDatabaseOperations() {
    // Implement logic to optimize database operations for high traffic during peak hours
    $optimized = query("OPTIMIZE TABLE users");
    if (!$optimized) {
        throw new Exception("Failed to optimize database operations, please try again later.");
    }
}
