const fs = require('fs');
const crypto = require('crypto');
const cache = new Map();

async function readConfig(configFilePath, sessionIdLength, charSet) {
  const config = await fs.promises.readFile(configFilePath);
  const parsedConfig = parseConfig(config);
  if (!parsedConfig) {
    throw new Error('Invalid configuration file');
  }
  const sessionId = generateSessionId(sessionIdLength, charSet);
  cache.set(sessionId, parsedConfig);
  return { config: parsedConfig, sessionId };
}

function parseConfig(config) {
  const lines = config.split('\n');
  const configObj = {};
  for (const line of lines) {
    const [key, value] = line.split(';');
    if (!key || !value) {
      return null;
    }
    try {
      configObj[key] = JSON.parse(value);
    } catch (e) {
      return null;
    }
  }
  return configObj;
}

function generateSessionId(length, charSet) {
  const id = crypto.randomBytes(length).toString('hex');
  if (cache.has(id)) {
    return generateSessionId(length, charSet);
  }
  return id;
}

module.exports = readConfig;
```"]

