function fetchAndCombineCertificates(streamPath, certificateConfig) {
  // Initialize variables to store the combined PEM file and the current position in the stream
  let combinedPem = Buffer.alloc(0);
  let currentPosition = 0;

  // Create a new stream from the input stream path
  const stream = fs.createReadStream(streamPath);

  // Set up event listeners for the 'data' and 'end' events of the stream
  stream.on('data', (chunk) => {
    // Combine the current chunk with the combined PEM file
    combinedPem = Buffer.concat([combinedPem, chunk]);
  });

  stream.on('end', () => {
    // Return the combined PEM file as a buffer object
    return combinedPem;
  });

  // Set up event listeners for the 'error' and 'close' events of the stream
  stream.on('error', (err) => {
    // Handle potential network latency or intermittent connectivity issues
    console.log(`Error occurred while fetching certificates: ${err}`);
  });

  stream.on('close', () => {
    // Close the stream when it is no longer needed
    stream.destroy();
  });

  // Return the combined PEM file as a buffer object
  return combinedPem;
}
