// Structure to represent an FSA state
typedef struct {
    int id; // Unique identifier for the state
    char *label; // Label for the state (e.g., "q0")
    int next[]; // Array of pointers to the next states
} fsa_state_t;

// Structure to represent an FSA transition rule
typedef struct {
    int from; // State ID where the transition originates
    int to; // State ID where the transition leads
    char *label; // Label for the transition (e.g., "a")
} fsa_transition_t;

// Structure to represent an FSA
typedef struct {
    int num_states; // Number of states in the FSA
    int num_transitions; // Number of transitions in the FSA
    fsa_state_t *states; // Array of FSA states
    fsa_transition_t *transitions; // Array of FSA transitions
} fsa_t;

// Function to add a new state to an FSA
fsa_state_t* add_state(fsa_t *fsa, int id, char *label) {
    // Check if the ID is already in use
    for (int i = 0; i < fsa->num_states; i++) {
        if (fsa->states[i].id == id) {
            return NULL;
        }
    }

    // Allocate memory for the new state
    fsa_state_t *new_state = malloc(sizeof(fsa_state_t));
    if (!new_state) {
        return NULL;
    }

    // Initialize the new state
    new_state->id = id;
    new_state->label = label;
    new_state->next = NULL;

    // Add the new state to the FSA's state list
    fsa->states[fsa->num_states++] = *new_state;

    return new_state;
}

// Function to add a transition to an FSA
void add_transition(fsa_t *fsa, int from, int to, char *label) {
    // Check if the transition is valid
    for (int i = 0; i < fsa->num_transitions; i++) {
        if (fsa->transitions[i].from == from && fsa->transitions[i].to == to) {
            return;
        }
    }

    // Allocate memory for the new transition
    fsa_transition_t *new_transition = malloc(sizeof(fsa_transition_t));
    if (!new_transition) {
        return;
    }

    // Initialize the new transition
    new_transition->from = from;
    new_transition->to = to;
    new_transition->label = label;

    // Add the new transition to the FSA's transition list
    fsa->transitions[fsa->num_transitions++] = *new_transition;
}

// Function to validate an FSA state
int validate_state(fsa_t *fsa, int id) {
    // Check if the ID is valid
    for (int i = 0; i < fsa->num_states; i++) {
        if (fsa->states[i].id == id) {
            return 1;
        }
    }

    return 0;
}

// Function to validate an FSA transition
int validate_transition(fsa_t *fsa, int from, int to) {
    // Check if the transition is valid
    for (int i = 0; i < fsa->num_transitions; i++) {
        if (fsa->transitions[i].from == from && fsa->transitions[i].to == to) {
            return 1;
        }
    }

    return 0;
}

// Function to add a new state to an FSA and validate its transitions
fsa_state_t* add_state_and_validate(fsa_t *fsa, int id, char *label) {
    // Add the new state to the FSA
    fsa_state_t *new_state = add_state(fsa, id, label);
    if (!new_state) {
        return NULL;
    }

    // Validate the transitions from the new state
    for (int i = 0; i < fsa->num_transitions; i++) {
        if (fsa->transitions[i].from == id) {
            int to = fsa->transitions[i].to;
            char *label = fsa->transitions[i].label;
            if (!validate_state(fsa, to)) {
                // Reject the transition if the target state is not valid
                return NULL;
            } else if (!validate_transition(fsa, id, to)) {
                // Reject the transition if it is not valid according to the FSA's transition rules
                return NULL;
            }
        }
    }

    return new_state;
}

// Function to add a batch of states to an FSA and validate their transitions
void add_states_and_validate(fsa_t *fsa, int num_states, fsa_state_t **states) {
    // Add the new states to the FSA
    for (int i = 0; i < num_states; i++) {
        add_state(fsa, states[i]->id, states[i]->label);
    }

    // Validate the transitions from each state in the batch
    for (int i = 0; i < fsa->num_transitions; i++) {
        int from = fsa->transitions[i].from;
        int to = fsa->transitions[i].to;
        char *label = fsa->transitions[i].label;
        if (!validate_state(fsa, from)) {
            // Reject the transition if the source state is not valid
            continue;
        } else if (!validate_transition(fsa, from, to)) {
            // Reject the transition if it is not valid according to the FSA's transition rules
            continue;
        }
    }
}

// Function to report statistics on the number of successfully added states and rejected states due to invalid transitions
void report_stats(fsa_t *fsa) {
    int num_successful = 0;
    int num_rejected = 0;

    // Count the number of successful and rejected states
    for (int i = 0; i < fsa->num_states; i++) {
        if (fsa->states[i].next) {
            num_successful++;
        } else {
