using namespace std;

// Define a struct to represent an attack and its cooldown period
struct Attack {
    int id;
    double cooldown;
};

// Define a vector of attacks with their cooldown periods
vector<Attack> attacks = {
    {1, 9.0}, // attack 1 has a cooldown period of 9 seconds
    {2, 6.0}  // attack 2 has a cooldown period of 6 seconds
};

// Define an unordered map to store the frequency of each attack used in the session
unordered_map<int, int> attackFrequencies;

// Define a mutex to ensure thread safety
mutex mtx;

void selectAttack(int attackId) {
    // Acquire the lock on the mutex
    unique_lock<mutex> lck(mtx);

    // Check if the attack is already in cooldown
    auto it = attacks.begin();
    while (it != attacks.end()) {
        if (it->id == attackId && it->cooldown > 0) {
            break;
        }
        ++it;
    }

    // If the attack is not in cooldown, select it and update the frequency log
    if (it != attacks.end()) {
        cout << "Selected attack: " << it->id << endl;
        attackFrequencies[it->id]++;
        it->cooldown = 9.0; // set cooldown period to 9 seconds
    } else {
        cout << "Attack not available" << endl;
    }
}

int main() {
    // Simulate concurrent calls from multiple instances of the game process
    thread t1(selectAttack, 1);
    thread t2(selectAttack, 2);
    thread t3(selectAttack, 1);
    thread t4(selectAttack, 2);
    thread t5(selectAttack, 1);
    thread t6(selectAttack, 2);

    // Join all threads to ensure they have completed execution
    t1.join();
    t2.join();
    t3.join();
    t4.join();
    t5.join();
    t6.join();

    // Print the frequency of each attack used in the session
    for (auto it = attackFrequencies.begin(); it != attackFrequencies.end(); ++it) {
        cout << "Attack " << it->first << ": " << it->second << endl;
    }

    return 0;
}
