using System;

public class DynamicValueGenerator
{
    private float _minimum;
    private float _maximum;

    public DynamicValueGenerator(float minimum = 0.0f, float maximum = 10.0f)
    {
        this._minimum = minimum;
        this._maximum = maximum;
    }

    public float Minimum
    {
        get => this._minimum;
        set
        {
            if (value >= this._maximum)
            {
                throw new ArgumentException("Minimum value must be less than the maximum value.");
            }
            this._minimum = value;
        }
    }

    public float Maximum
    {
        get => this._maximum;
        set
        {
            if (value <= this._minimum)
            {
                throw new ArgumentException("Maximum value must be greater than the minimum value.");
            }
            this._maximum = value;
        }
    }

    public float GenerateRandomFloatValue(bool inclusive = true)
    {
        if (inclusive)
        {
            return UnityEngine.Random.Range(this._minimum, this._maximum);
        }
        else
        {
            return UnityEngine.Random.Range(this._minimum, this._maximum - 1);
        }
    }

    public int GenerateRandomIntegerValue(bool inclusive = true)
    {
        if (inclusive)
        {
            return UnityEngine.Random.Range((int)this._minimum, (int)this._maximum);
        }
        else
        {
            return UnityEngine.Random.Range((int)this._minimum, (int)(this._maximum - 1));
        }
    }

    public override string ToString()
    {
        return $"Min: {this._minimum}, Max: {this._maximum}";
    }

    public void ValidateRange()
    {
        if (this._minimum >= this._maximum)
        {
            throw new ArgumentException("Invalid range.");
        }
    }

    public void ResetToDefault(float minimum = 0.0f, float maximum = 10.0f)
    {
        this._minimum = minimum;
        this._maximum = maximum;
    }
}
```
