#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <md5.h>

struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    char md5[MD5_DIGEST_LENGTH];
};

int processTiffImage(const char* filename, struct tiff_info* info) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        return -1;
    }

    // Check for supported bits per sample
    int bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        TIFFClose(tif);
        return -2;
    }

    // Calculate MD5 hash of image file content
    MD5_CTX ctx;
    MD5Init(&ctx);
    unsigned char buf[4096];
    while (TIFFReadScanline(tif, buf, 0, 0) > 0) {
        MD5Update(&ctx, buf, sizeof(buf));
    }
    MD5Final(info->md5, &ctx);

    // Extract image information
    info->bits_per_sample = bits_per_sample;
    info->samples_per_pixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
    info->extra_samples = TIFFGetField(tif, TIFFTAG_EXTRASAMPLES);

    // Close TIFF file
    TIFFClose(tif);

    return 0;
}
