char* generateUniqueFilename(const char* filename, const char* config) {
    // Parse the original filename to extract the base name and extension
    const char* baseName = strrchr(filename, '.');
    if (baseName == NULL) {
        return NULL;
    }
    size_t baseLen = baseName - filename;
    if (baseLen == 0) {
        return NULL;
    }
    const char* extension = baseName + 1;

    // Determine the number of digits to append based on the last character of the base name
    int numDigits = 3;
    if (baseLen > 0 && !isalnum(baseName[-1])) {
        numDigits = 2;
    }

    // Generate a random 3-digit number and append it to the base name
    srand(time(NULL));
    int randNum = rand() % (int)pow(10, numDigits);
    char* newBaseName = malloc(baseLen + numDigits + 1);
    if (newBaseName == NULL) {
        return NULL;
    }
    memcpy(newBaseName, filename, baseLen - 1);
    snprintf(newBaseName + baseLen - 1, numDigits + 1, "%0*d", numDigits, randNum);

    // Construct a new filename by replacing the original extension with a new one determined by the first two characters of the base name
    const char* newExtension = "txt";
    if (baseLen > 1 && isalnum(baseName[-2])) {
        newExtension = baseName - 2;
    }
    size_t newFilenameLen = strlen(newBaseName) + strlen(newExtension) + 1;
    char* newFilename = malloc(newFilenameLen);
    if (newFilename == NULL) {
        free(newBaseName);
        return NULL;
    }
    snprintf(newFilename, newFilenameLen, "%s.%s", newBaseName, newExtension);

    // Validate the proposed filename against a list of reserved filenames to avoid conflicts
    const char* reservedNames[] = {"CON", "PRN", "AUX", "NUL"};
    for (size_t i = 0; i < sizeof(reservedNames) / sizeof(*reservedNames); ++i) {
        if (strcmp(newFilename, reservedNames[i]) == 0) {
            free(newBaseName);
            free(newFilename);
            return NULL;
        }
    }

    // Handle collisions by appending a unique identifier generated from the current timestamp
    struct stat sb;
    while (stat(newFilename, &sb) == 0) {
        snprintf(newFilename + newFilenameLen - 1, 128, "%d", rand());
    }

    // Ensure the total length of the new filename does not exceed 128 characters, truncating if necessary, but prioritizing readability over strict length constraints
    size_t maxLength = 128;
    if (strlen(newFilename) > maxLength) {
        free(newBaseName);
        free(newFilename);
        return NULL;
    }

    // Manage potential memory allocation failures during string manipulation and handle them gracefully, returning NULL in case of failure
    char* result = malloc(maxLength + 1);
    if (result == NULL) {
        free(newBaseName);
        free(newFilename);
        return NULL;
    }
    snprintf(result, maxLength + 1, "%s", newFilename);

    // Free any allocated memory and return the newly generated filename as a string
    free(newBaseName);
    free(newFilename);
    return result;
}
```
