// Function to initialize AES-256-CBC cipher with given password
void* init_cipher(const char* password) {
    // Set IV length and key length
    const int iv_len = 16;
    const int key_len = 32;

    // Derive encryption key from password using SHA-1 hash function
    unsigned char key[key_len];
    SHA1(password, strlen(password), key);

    // Initialize AES-256-CBC cipher with derived key and IV
    AES_KEY aes_key;
    AES_set_encrypt_key(key, iv_len * 8, &aes_key);

    // Enable cipher and return pointer to cipher context
    AES_cbc_encrypt_ctx ctx;
    AES_cbc_encrypt_init(&aes_key, NULL, iv_len, &ctx);
    return (void*)&ctx;
}

