#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>
#include <semaphore.h>

// Define the maximum number of concurrent commands that can be executed
#define MAX_CONCURRENT_COMMANDS 20

// Define the timeout value for each command (in seconds)
#define COMMAND_TIMEOUT 60

// Define the maximum number of retries for a failed command
#define MAX_RETRIES 3

// Define the sleep time between retries (in milliseconds)
#define RETRY_SLEEP_TIME 1000

// Define the size of the buffer for storing command outputs
#define BUFFER_SIZE 4096

// Define the maximum number of concurrent commands that can be executed without exceeding system resource limits
#define MAX_SYSTEM_RESOURCE_LIMITS 10

// Define the semaphore for synchronizing access to the command metadata
sem_t *command_metadata_sem;

// Define the mutex for protecting the command metadata
pthread_mutex_t command_metadata_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a command is completed
pthread_cond_t command_completed_cv = PTHREAD_COND_INITIALIZER;

// Define the structure for storing command metadata
typedef struct {
    int pid; // Process ID of the command
    char *command; // Command string
    int status; // Status of the command (0: success, 1: failure)
    int retries; // Number of retries for the command
} command_metadata_t;

// Define the array for storing command metadata
command_metadata_t commands[MAX_CONCURRENT_COMMANDS];

int execute_command(char *command, int timeout, int max_concurrent_commands) {
    // Check if there are any available slots in the command metadata array
    if (sem_wait(command_metadata_sem) == -1) {
        perror("Error waiting for semaphore");
        return -1;
    }

    // Acquire the mutex for protecting the command metadata
    pthread_mutex_lock(&command_metadata_mutex);

    // Find an available slot in the command metadata array
    int i = 0;
    while (i < MAX_CONCURRENT_COMMANDS && commands[i].pid != 0) {
        i++;
    }

    // Check if there are any available slots in the command metadata array
    if (i == MAX_CONCURRENT_COMMANDS) {
        pthread_mutex_unlock(&command_metadata_mutex);
        sem_post(command_metadata_sem);
        return -1;
    }

    // Fork a new process to execute the command
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: Execute the command and exit
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("Error executing command");
        exit(1);
    } else if (pid < 0) {
        // Parent process: Handle fork error
        pthread_mutex_unlock(&command_metadata_mutex);
        sem_post(command_metadata_sem);
        perror("Error forking new process");
        return -1;
    }

    // Update the command metadata
    commands[i].pid = pid;
    commands[i].command = command;
    commands[i].status = 0;
    commands[i].retries = 0;

    // Release the mutex for protecting the command metadata
    pthread_mutex_unlock(&command_metadata_mutex);

    // Wait for the command to complete or timeout
    int status = -1;
    while (status == -1) {
        // Check if the command has completed
        status = waitpid(pid, NULL, WNOHANG);

        // Sleep for a short time before checking again
        usleep(RETRY_SLEEP_TIME);

        // Increment the number of retries
        commands[i].retries++;

        // Check if the command has exceeded the maximum number of retries
        if (commands[i].retries > MAX_RETRIES) {
            // Kill the command process and update the status
            kill(pid, SIGKILL);
            commands[i].status = 1;
            break;
        }
    }

    // Signal that a command has completed
    pthread_cond_signal(&command_completed_cv);

    // Release the semaphore for synchronizing access to the command metadata
    sem_post(command_metadata_sem);

    // Return the status of the command execution
    return commands[i].status;
}

int main() {
    // Initialize the semaphore for synchronizing access to the command metadata
    if (sem_init(&command_metadata_sem, 0, MAX_CONCURRENT_COMMANDS) == -1) {
        perror("Error initializing semaphore");
        return -1;
    }

    // Create a new thread for handling command completion notifications
    pthread_t notification_thread;
    if (pthread_create(&notification_thread, NULL, handle_command_completion, NULL) != 0) {
        perror("Error creating notification thread");
        return -1;
    }

    // Execute a command in the background and wait for it to complete or timeout
    char *command = "sleep 60";
    int timeout = COMMAND_TIMEOUT;
    int max_concurrent_commands = MAX_SYSTEM_RESOURCE_LIMITS;
    execute_command(command, timeout, max_concurrent_commands);

    // Wait for the command to complete or timeout
    while (1) {
        // Check if the command has completed
        pthread_mutex_lock(&command_metadata_mutex);
        int i = 0;
        while (i < MAX_CONCURRENT_COMMANDS && commands[i].pid != 0) {
            if (commands[i].status == 1) {
                // Command has failed: Handle the failure gracefully
                printf("Command %s has failed\n", commands[i].command);
                break;
            } else if (commands[i].retries > MAX_RETRIES) {
                // Command has exceeded the maximum number of retries: Kill the process and update the status
                kill(commands[i].pid, SIGKILL);
                commands[i].status = 1;
            } else if (commands[i].retries > 0 && commands[i].status == 0) {
                // Command has been retried: Update the status
                printf("Command %s has been retried\n", commands[i].command);
                break;
            }
            i++;
        }
        pthread_mutex_unlock(&command_metadata_mutex);

        // Check if the command has completed or timed out
        if (i < MAX_CONCURRENT_COMMANDS && commands[i].status != 0) {
            break;
        }
    }

    // Clean up resources
    pthread_join(notification_thread, NULL);
    sem_destroy(&command_metadata_sem);

    return 0;
}

void *handle_command_completion(void *arg) {
    while (1) {
        // Wait for a command to complete or timeout
        pthread_mutex_lock(&command_metadata_mutex);
        int i = 0;
        while (i < MAX_CONCURRENT_COMMANDS && commands[i].pid != 0) {
            if (commands[i].status == 1) {
                // Command has failed: Handle the failure gracefully
                printf("Command %s has failed\n", commands[i].command);
                break;
            } else if (commands[i].retries > MAX_RETRIES) {
                // Command has exceeded the maximum number of retries: Kill the process and update the status
                kill(commands[i].pid, SIGKILL);
                commands[i].status = 1;
            } else if (commands[i].retries > 0 && commands[i].status == 0) {
                // Command has been retried: Update the status
                printf("Command %s has been retried\n", commands[i].command);
                break;
            }
            i++;
        }
        pthread_mutex_unlock(&command_metadata_mutex);

        // Check if a command has completed or timed out
        if (i < MAX_CONCURRENT_COMMANDS && commands[i].status != 0) {
            break;
        }
    }

    return NULL;
}
