using System;
using System.IO;
using System.Linq;
using System.Xml.Linq;

public static void AddSite(string directoryPath, string siteName)
{
    // Check if the directory exists and is accessible
    if (!Directory.Exists(directoryPath))
    {
        throw new Exception($"The directory '{directoryPath}' does not exist or is not accessible.");
    }

    // Verify the presence of a web.config file
    string configFilePath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(configFilePath))
    {
        // Generate a default template for the web.config file
        XDocument configTemplate = new XDocument(
            new XElement("configuration",
                new XElement("system.webServer",
                    new XElement("defaultDocument",
                        new XAttribute("enabled", "true"),
                        new XElement("files",
                            new XElement("add value='Default.aspx' />")
                        )
                    )
                )
            )
        );
        configTemplate.Save(configFilePath);
    }

    // Check for existing site instances and avoid starting duplicates
    string[] existingSites = Directory.GetDirectories(directoryPath, "*.Site");
    if (existingSites.Any(s => s.EndsWith($"{siteName}.Site")))
    {
        throw new Exception($"A site with the name '{siteName}' already exists in the directory.");
    }

    // Create a new site instance and start it
    string siteInstancePath = Path.Combine(directoryPath, $"{siteName}.Site");
    Directory.CreateDirectory(siteInstancePath);
    Process.Start("cmd", $"/c \"cd {siteInstancePath} & dotnet run\"");

    // Log the operation and provide feedback
    Console.WriteLine($"Added site '{siteName}' to directory '{directoryPath}'.");
}
