        return -3;
    }
    if (timeout < 0 || timeout > 60000) {
        return -4;
    }

    // Decrypt message
    unsigned char *encrypted_message = NULL;
    size_t encrypted_len = 0;
    int ret = readEncryptedMessage(&encrypted_message, &encrypted_len);
    if (ret != 0) {
        return -5;
    }
    unsigned char *decrypted_message = NULL;
    size_t decrypted_len = 0;
    ret = des_ede3_cbc_decrypt(encrypted_message, encrypted_len, key, iv, &decrypted_message, &decrypted_len);
    if (ret != 1) {
        return -6;
    }

    // Handle potential errors and resource leaks
    free(encrypted_message);
    if (decrypted_message == NULL) {
        return -7;
    }

    // Return decrypted message
    return 0;
}
