    private readonly string _inputFilePath;
    private readonly string _outputFilePath;
    private readonly Func<string, string> _transformationFunction;
    private readonly Predicate<string> _predicate;
    private readonly ILogger _logger;

    public TextFileProcessor(string inputFilePath, string outputFilePath, Func<string, string> transformationFunction, Predicate<string> predicate, ILogger logger)
    {
        _inputFilePath = inputFilePath;
        _outputFilePath = outputFilePath;
        _transformationFunction = transformationFunction;
        _predicate = predicate;
        _logger = logger;
    }

    public async Task ProcessAsync()
    {
        using (var reader = new StreamReader(_inputFilePath))
        using (var writer = new StreamWriter(_outputFilePath))
        {
            string line;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                if (_predicate(line))
                {
                    var transformedLine = _transformationFunction(line);
                    writer.WriteLine(transformedLine);
                }
            }
        }
    }
}
