using System;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace DecryptionService
{
    public class FlexibleDecryptionService : IDecryptionService
    {
        private readonly IKeyManager _keyManager;
        private readonly IVectorGenerator _vectorGenerator;
        private readonly HmacSha256SignatureComputer _signatureComputer;
        private readonly Random _random;

        public FlexibleDecryptionService(IKeyManager keyManager, IVectorGenerator vectorGenerator, HmacSha256SignatureComputer signatureComputer)
        {
            _keyManager = keyManager;
            _vectorGenerator = vectorGenerator;
            _signatureComputer = signatureComputer;
            _random = new Random();
        }

        public async Task<DecryptionResult> DecryptAsync(byte[] ciphertext, CancellationToken cancellationToken)
        {
            // Generate a new key and IV for each session
            var key = await _keyManager.GenerateKeyAsync(_random);
            var iv = _vectorGenerator.GenerateIV();

            // Initialize the AES decryption algorithm with the generated key and IV
            using var aesAlgorithm = new AesCryptoServiceProvider { Key = key, IV = iv };

            // Decrypt the ciphertext using the AES algorithm
            var plaintext = await DecryptAsync(ciphertext, aesAlgorithm, cancellationToken);

            // Compute the HMAC-SHA256 signature over the plaintext
            var signature = _signatureComputer.ComputeSignature(plaintext);

            // Validate the integrity of the decrypted data using the computed signature
            if (!ValidateSignature(ciphertext, signature))
            {
                throw new DecryptionException("Decryption failed: Signature validation failed");
            }

            return new DecryptionResult(plaintext);
        }

        private async Task<byte[]> DecryptAsync(byte[] ciphertext, AesCryptoServiceProvider aesAlgorithm, CancellationToken cancellationToken)
        {
            // Pad the ciphertext to ensure alignment with block boundaries
            var paddedCiphertext = Pkcs7Padding.Pad(ciphertext);

            // Decrypt the padded ciphertext using the AES algorithm
            var plaintext = await aesAlgorithm.DecryptAsync(paddedCiphertext, cancellationToken);

            return plaintext;
        }

        private bool ValidateSignature(byte[] ciphertext, byte[] signature)
        {
            // Compute the HMAC-SHA256 signature over the ciphertext
            var computedSignature = _signatureComputer.ComputeSignature(ciphertext);

            // Compare the computed and provided signatures for equality
            return computedSignature.SequenceEqual(signature);
        }
    }
}
```
