using System.IO.Compression;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class LoadAndDeserializeData
{
    private const int DefaultCompressionThreshold = 1024 * 1024; // 1 MB
    private const int MaxRetries = 3;
    private const int RetryDelayMilliseconds = 500;

    public static async Task<T> LoadAndDeserializeDataAsync<T>(string filePath, CancellationToken cancellationToken = default) where T : class
    {
        // Check if the file exists and is not empty
        if (!File.Exists(filePath) || new FileInfo(filePath).Length == 0)
        {
            throw new FileNotFoundException($"The file '{filePath}' does not exist or is empty.");
        }

        // Open the file for reading and decompress it using GZipStream
        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        using (var gzipStream = new GZipStream(fileStream, CompressionMode.Decompress))
        {
            // Deserialize the data from the decompressed stream
            var serializer = new JsonSerializer();
            return await Task.Run(() => serializer.Deserialize<T>(gzipStream), cancellationToken);
        }
    }

    public static async Task SaveAndSerializeDataAsync<T>(string filePath, T data, CancellationToken cancellationToken = default) where T : class
    {
        // Check if the file exists and is not empty
        if (File.Exists(filePath))
        {
            throw new FileNotFoundException($"The file '{filePath}' already exists.");
        }

        // Open the file for writing and compress it using GZipStream
        using (var fileStream = new FileStream(filePath, FileMode.CreateNew, FileAccess.Write))
        using (var gzipStream = new GZipStream(fileStream, CompressionMode.Compress))
        {
            // Serialize the data to the compressed stream
            var serializer = new JsonSerializer();
            await Task.Run(() => serializer.Serialize(gzipStream, data), cancellationToken);
        }
    }
}
```
