import json
from typing import Dict, List, Optional, Type, Union

class JSONHandler:
    def __init__(self):
        self.factory_registry: Dict[str, List[Type]] = {}
        self.default_factories: Dict[str, Type] = {}

    def register_factory(self, id: str, factory: Type) -> None:
        if id not in self.factory_registry:
            self.factory_registry[id] = []
        self.factory_registry[id].append(factory)

    def unregister_factory(self, id: str, factory: Type) -> None:
        if id in self.factory_registry and factory in self.factory_registry[id]:
            self.factory_registry[id].remove(factory)

    def deserialize(self, json_string: str) -> Union[Dict, List]:
        data = json.loads(json_string)
        return self._deserialize(data)

    def serialize(self, data: Union[Dict, List]) -> str:
        return json.dumps(data)

    def _deserialize(self, data: Dict) -> Union[Dict, List]:
        if "type" in data:
            id = data["type"]
            if id in self.factory_registry:
                for factory in self.factory_registry[id]:
                    try:
                        return factory(data)
                    except Exception as e:
                        pass
            elif id in self.default_factories:
