type NFAPI_CRC_INDICATION_PDU_T = HashMap<String, String>;

fn generate_nfapi_crc_indication_pdu(rx_ue_information_tag: &str, rnti: &str, crc_indication_rel8_tag: &str) -> NFAPI_CRC_INDICATION_PDU_T {
    let mut pdu = HashMap::new();
    pdu.insert("RX_UE_INFORMATION_TAG".to_string(), rx_ue_information_tag.to_string());
    pdu.insert("RNTI".to_string(), rnti.to_string());
    pdu.insert("CRC_INDICATION_REL8_TAG".to_string(), crc_indication_rel8_tag.to_string());
    return pdu;
}

fn generate_nfapi_crc_indications(num_pdu: usize) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let mut pdus = vec![];
    for i in 0..num_pdu {
        let rx_ue_information_tag = format!("RX_UE_INFORMATION_TAG_{}", i);
        let rnti = format!("RNTI_{}", i);
        let crc_indication_rel8_tag = format!("CRC_INDICATION_REL8_TAG_{}", i);
        pdus.push(generate_nfapi_crc_indication_pdu(&rx_ue_information_tag, &rnti, &crc_indication_rel8_tag));
    }
    return pdus;
}

fn generate_http_client(url: &str) -> Client<HttpConnector> {
    let connector = HttpConnector::new();
    let client = Client::builder().build(connector);
    return client.unwrap();
}

fn send_http_request(client: &Client<HttpConnector>, url: &str, body: Body) -> Result<Response<Body>, hyper::Error> {
    let request = Request::builder()
        .uri(url)
        .body(body)?;
    return client.request(request);
}

fn handle_http_response(response: Response<Body>) -> Result<(), hyper::Error> {
    if response.status().is_success() {
        println!("HTTP request successful");
        return Ok(());
    } else {
        println!("HTTP request failed with status code {}", response.status());
        return Err(hyper::Error::new("HTTP request failed"));
    }
}

fn retry_http_request(client: &Client<HttpConnector>, url: &str, body: Body) -> Result<(), hyper::Error> {
    let mut attempts = 0;
    while attempts < 3 {
        match send_http_request(client, url, body.clone()) {
            Ok(response) => return handle_http_response(response),
            Err(error) => {
                println!("HTTP request failed with error: {}", error);
                sleep(Duration::from_secs(1));
                attempts += 1;
            }
        }
    }
    return Err(hyper::Error::new("All HTTP request attempts failed"));
}

fn main() {
    let url = "https://example.com";
    let client = generate_http_client(url);
    let pdus = generate_nfapi_crc_indications(10);
    for pdu in &pdus {
        let body = Body::from(serde_json::to_string(&pdu).unwrap());
        match retry_http_request(&client, url, body.clone()) {
            Ok(_) => println!("HTTP request successful"),
            Err(error) => println!("HTTP request failed with error: {}", error),
        }
    }
}
