#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define a structure to store audio stream metadata
typedef struct AudioStreamMetadata {
    int sample_rate;
    int bit_depth;
    int channel_config;
} AudioStreamMetadata;

// Define a linked list node to store the audio stream metadata
typedef struct AudioStreamNode {
    AudioStreamMetadata *metadata;
    struct AudioStreamNode *next;
} AudioStreamNode;

// Define a global variable to store the head of the linked list
static AudioStreamNode *head = NULL;

// Define a mutex to protect the linked list from concurrent access
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add an audio stream metadata to the linked list
void addAudioStreamMetadata(int sample_rate, int bit_depth, int channel_config) {
    // Allocate memory for the new node
    AudioStreamNode *new_node = (AudioStreamNode *)malloc(sizeof(AudioStreamNode));
    if (!new_node) {
        printf("Error: Failed to allocate memory for audio stream metadata\n");
        return;
    }

    // Initialize the new node with the given sample rate, bit depth, and channel configuration
    new_node->metadata = (AudioStreamMetadata *)malloc(sizeof(AudioStreamMetadata));
    if (!new_node->metadata) {
        printf("Error: Failed to allocate memory for audio stream metadata\n");
        free(new_node);
        return;
    }
    new_node->metadata->sample_rate = sample_rate;
    new_node->metadata->bit_depth = bit_depth;
    new_node->metadata->channel_config = channel_config;

    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&lock);

    // Add the new node to the end of the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        AudioStreamNode *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);
}

// Function to remove an audio stream metadata from the linked list
void removeAudioStreamMetadata(int sample_rate, int bit_depth, int channel_config) {
    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the given sample rate, bit depth, and channel configuration
    AudioStreamNode *current = head;
    while (current != NULL) {
        if (current->metadata->sample_rate == sample_rate && current->metadata->bit_depth == bit_depth && current->metadata->channel_config == channel_config) {
            // Remove the node from the linked list
            if (head == current) {
                head = current->next;
            } else {
                AudioStreamNode *previous = head;
                while (previous->next != current) {
                    previous = previous->next;
                }
                previous->next = current->next;
            }

            // Free the memory allocated for the node and its metadata
            free(current->metadata);
            free(current);

            break;
        }
        current = current->next;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);
}

// Function to update an audio stream metadata in the linked list
void updateAudioStreamMetadata(int sample_rate, int bit_depth, int channel_config) {
    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the given sample rate, bit depth, and channel configuration
    AudioStreamNode *current = head;
    while (current != NULL) {
        if (current->metadata->sample_rate == sample_rate && current->metadata->bit_depth == bit_depth && current->metadata->channel_config == channel_config) {
            // Update the node with the new sample rate, bit depth, and channel configuration
            current->metadata->sample_rate = sample_rate;
            current->metadata->bit_depth = bit_depth;
            current->metadata->channel_config = channel_config;

            break;
        }
        current = current->next;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);
}

// Function to retrieve an audio stream metadata from the linked list
AudioStreamMetadata *getAudioStreamMetadata(int sample_rate, int bit_depth, int channel_config) {
    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the given sample rate, bit depth, and channel configuration
    AudioStreamNode *current = head;
    while (current != NULL) {
        if (current->metadata->sample_rate == sample_rate && current->metadata->bit_depth == bit_depth && current->metadata->channel_config == channel_config) {
            // Return the metadata of the found node
            AudioStreamMetadata *metadata = current->metadata;
            pthread_mutex_unlock(&lock);
            return metadata;
        }
        current = current->next;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);

    // Return NULL if no node with the given sample rate, bit depth, and channel configuration is found
    return NULL;
}
