namespace SimulationEnvironment {
    static std::mt19937 randomGen;
    static std::mutex randomMutex;
    static std::condition_variable randomCondVar;

    void initRandom() {
        std::random_device rd;
        unsigned seed = std::chrono::system_clock::now().time_since_epoch().count();
        randomGen.seed(seed);
    }

    float generateRandomFloat(float min, float max) {
        std::lock_guard<std::mutex> lock(randomMutex);
        return std::uniform_real_distribution<float>(min, max)(randomGen);
    }

    void executeBackgroundProcess(const std::string& command) {
        pid_t pid = fork();
        if (pid == 0) { // child process
            int status = system(command.c_str());
            exit(status);
        } else if (pid > 0) { // parent process
            waitpid(pid, NULL, 0);
        } else { // error
            std::cerr << "Error forking background process" << std::endl;
        }
    }

    bool startBackgroundProcess(const std::string& command) {
        pid_t pid = fork();
        if (pid == 0) { // child process
            int status = system(command.c_str());
            exit(status);
        } else if (pid > 0) { // parent process
            waitpid(pid, NULL, 0);
            return true;
        } else { // error
            std::cerr << "Error forking background process" << std::endl;
            return false;
        }
    }

    bool getBackgroundProcessStatus(int pid) {
        int status = -1;
        if (pid > 0) {
            waitpid(pid, &status, WNOHANG);
        }
        return status == 0;
    }
}
