// Asynchronous Module Pattern for dynamic script loading
(function() {
  // Configuration object for script loading criteria
  const config = {
    scripts: [
      { src: 'https://example.com/script1.js', async: true },
      { src: 'https://example.com/script2.js', async: false },
      { src: 'local-script.js', async: true }
    ],
    // Enable/disable specific scripts based on user preferences or runtime conditions
    enabledScripts: ['https://example.com/script1.js', 'local-script.js'],
    // Order of execution for enabled scripts
    scriptOrder: ['https://example.com/script1.js', 'local-script.js']
  };

  // Fetch API for remote file loading
  const fetchScript = (src) => {
    return fetch(src, { mode: 'cors' })
      .then((response) => response.text())
      .catch((error) => console.log(`Error loading script ${src}:`, error));
  };

  // Load and execute scripts in the correct order
  const loadScripts = () => {
    config.enabledScripts.forEach((script, index) => {
      fetchScript(script.src)
        .then((response) => {
          // Execute script with async flag set to true or false based on configuration
          if (script.async) {
            const scriptElement = document.createElement('script');
            scriptElement.textContent = response;
            document.head.appendChild(scriptElement);
          } else {
            eval(response);
          }
        })
        .catch((error) => console.log(`Error executing script ${script.src}:`, error));
    });
  };

  // Handle errors gracefully and provide informative messages
  const handleErrors = (error) => {
    console.log('Error loading or executing scripts:', error);
    alert('An error occurred while loading or executing scripts. Please try again later.');
  };

  // Log detailed information about each step in the script loading process
  const logStep = (step, message) => {
    console.log(`${step}: ${message}`);
  };

  // Test for network failures and unexpected file loads
  const testNetworkFailures = () => {
    fetchScript('https://example.com/non-existent-script.js')
      .then((response) => console.log(`Unexpected response from non-existent script:`, response))
      .catch((error) => console.log(`Error loading non-existent script:`, error));
  };

  // Test for script execution errors and fallback strategies
  const testScriptExecutionErrors = () => {
    fetchScript('https://example.com/invalid-script.js')
      .then((response) => eval(response))
      .catch((error) => console.log(`Error executing invalid script:`, error));
  };

  // Test for cross-origin resource sharing (CORS) policies and handle them effectively
  const testCORSPolicies = () => {
    fetchScript('https://example.com/script1.js')
      .then((response) => console.log(`Response from script1.js:`, response))
      .catch((error) => console.log(`Error loading script1.js due to CORS policy:`, error));
  };

  // Test for performance optimization and browser caching strategies
  const testPerformance = () => {
    fetchScript('https://example.com/script2.js')
      .then((response) => console.log(`Response from script2.js:`, response))
      .catch((error) => console.log(`Error loading script2.js due to performance optimization:`, error));
  };

  // Integrate a flexible configuration mechanism for dynamic adjustment of script loading criteria
  const configureScriptLoading = () => {
    config.enabledScripts = ['https://example.com/script1.js', 'local-script.js'];
    config.scriptOrder = ['https://example.com/script1.js', 'local-script.js'];
  };

  // Test the program in a variety of scenarios and validate script behavior under controlled circumstances
  const testScenarios = () => {
    loadScripts();
    handleErrors();
    logStep('loadScripts', 'Loading scripts');
    logStep('handleErrors', 'Handling errors gracefully');
    logStep('logStep', 'Logging detailed information about each step in the script loading process');
    testNetworkFailures();
    testScriptExecutionErrors();
    testCORSPolicies();
    testPerformance();
    configureScriptLoading();
  };

  // Initialize the program and start testing scenarios
  const init = () => {
    console.log('Initializing script loading program');
    loadScripts();
    handleErrors();
    logStep('loadScripts', 'Loading scripts');
    logStep('handleErrors', 'Handling errors gracefully');
    logStep('logStep', 'Logging detailed information about each step in the script loading process');
    testNetworkFailures();
    testScriptExecutionErrors();
    testCORSPolicies();
    testPerformance();
    configureScriptLoading();
  };

  // Start the program and begin testing scenarios
  init();
})();
