namespace PerformanceRandomGenerator
{
    public class RandomNumberGenerator
    {
        private readonly object _lock = new object();
        private readonly ThreadLocal<Random> _random = new ThreadLocal<Random>(() => new Random());

        // Inclusive boundaries for integer generation
        private int _minInt;
        private int _maxInt;

        // Exclusive boundaries for float generation
        private float _minFloat;
        private float _maxFloat;

        // Seed for random number generation
        private int _seed;

        public RandomNumberGenerator(int minInt, int maxInt, float minFloat, float maxFloat, int seed)
        {
            _minInt = minInt;
            _maxInt = maxInt;
            _minFloat = minFloat;
            _maxFloat = maxFloat;
            _seed = seed;
        }

        public void Reset(int minInt, int maxInt, float minFloat, float maxFloat, int seed)
        {
            lock (_lock)
            {
                _minInt = minInt;
                _maxInt = maxInt;
                _minFloat = minFloat;
                _maxFloat = maxFloat;
                _seed = seed;
            }
        }

        public int NextInt()
        {
            lock (_lock)
            {
                return _random.Value.Next(_minInt, _maxInt);
            }
        }

        public float NextFloat()
        {
            lock (_lock)
            {
                return (float)_random.Value.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
            }
        }

