#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>

// Define the maximum length of a filename
#define MAX_FILENAME_LENGTH 128

// Define the maximum number of retries for generating a unique filename
#define MAX_RETRIES 5

// Define the delay between retries in milliseconds
#define RETRY_DELAY 100

// Define the file extension separator character
#define FILE_EXTENSION_SEPARATOR '.'

// Define the file type separator character
#define FILE_TYPE_SEPARATOR '_'

// Define the timestamp format string
#define TIMESTAMP_FORMAT "%Y%m%d-%H%M%S"

// Define the random identifier length
#define RANDOM_IDENTIFIER_LENGTH 8

// Define the file type mapping
static const char* FILE_TYPES[] = { "txt", "pdf", "docx", "xlsx", "pptx", "jpg", "png" };

// Define the logging system
#define LOGGING_SYSTEM(...) printf(__VA_ARGS__)

// Function to generate a new filename for a given file within a specified directory
char* generate_filename(const char* directory, const char* original_filename) {
  // Get the current timestamp in milliseconds
  time_t now = time(NULL);
  struct tm* tm_now = localtime(&now);
  char* timestamp = malloc(strlen(TIMESTAMP_FORMAT) + 1);
  strftime(timestamp, strlen(TIMESTAMP_FORMAT) + 1, TIMESTAMP_FORMAT, tm_now);

  // Generate a random identifier
  char* random_identifier = malloc(RANDOM_IDENTIFIER_LENGTH + 1);
  srand(time(NULL));
  for (int i = 0; i < RANDOM_IDENTIFIER_LENGTH; i++) {
    int random_char = rand() % ('z' - 'a') + 'a';
    random_identifier[i] = random_char;
  }
  random_identifier[RANDOM_IDENTIFIER_LENGTH] = '\0';

  // Get the file extension from the original filename
  char* file_extension = strrchr(original_filename, FILE_EXTENSION_SEPARATOR);
  if (file_extension == NULL) {
    LOGGING_SYSTEM("Error: File %s has no extension\n", original_filename);
    return NULL;
  }

  // Get the file type from the file extension
  char* file_type = strrchr(file_extension, FILE_TYPE_SEPARATOR);
  if (file_type == NULL) {
    LOGGING_SYSTEM("Error: File %s has no file type\n", original_filename);
    return NULL;
  }

  // Generate the new filename
  char* new_filename = malloc(MAX_FILENAME_LENGTH + 1);
  snprintf(new_filename, MAX_FILENAME_LENGTH + 1, "%s%s%s%s", directory, FILE_TYPE_SEPARATOR, timestamp, random_identifier);

  // Check if the new filename is unique within the directory
  int retries = 0;
  while (retries < MAX_RETRIES) {
    struct stat file_stat;
    if (stat(new_filename, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
      // The new filename is not unique, generate a new one
      free(new_filename);
      new_filename = malloc(MAX_FILENAME_LENGTH + 1);
      snprintf(new_filename, MAX_FILENAME_LENGTH + 1, "%s%s%s%s", directory, FILE_TYPE_SEPARATOR, timestamp, random_identifier);
    } else {
      // The new filename is unique, break the loop
      break;
    }
    retries++;
  }

  if (retries == MAX_RETRIES) {
    LOGGING_SYSTEM("Error: Could not generate a unique filename for %s\n", original_filename);
    return NULL;
  }

  // Add the file type to the new filename
  char* file_type_str = strrchr(new_filename, FILE_TYPE_SEPARATOR);
  if (file_type_str == NULL) {
    LOGGING_SYSTEM("Error: Could not add file type to %s\n", new_filename);
    return NULL;
  }
  strcpy(file_type_str + 1, FILE_TYPES[atoi(file_type - FILE_TYPE_SEPARATOR)]);

  // Log the generated filename
  LOGGING_SYSTEM("Generated filename: %s\n", new_filename);

  return new_filename;
}
