// Define the function to process the list of integers
int process_integers(int *list, int size) {
    // Initialize the largest integer found and the list of structures
    int largest = 0;
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;

    // Allocate memory for the array of integers
    int *array = malloc(size * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for integer array\n");
        return -1;
    }

    // Allocate memory for the list of structures
    structures = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structures == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for structure array\n");
        free(array);
        return -1;
    }

    // Initialize the semaphore with an initial value of 0
    sem_t *sem = sem_open("integer_sem", O_CREAT, 0644, 0);
    if (sem == SEM_FAILED) {
        fprintf(stderr, "Error: Failed to create semaphore\n");
        free(array);
        free(structures);
        return -1;
    }

    // Iterate over the list of integers and find the largest one
    for (int i = 0; i < size; i++) {
        if (list[i] > largest) {
            largest = list[i];
        }
    }

    // Set the CRCFLAG randomly using standard library functions
    srand(time(NULL));
    int crcflag = rand() % 2;

    // Iterate over the list of integers again and create a structure for each one
    for (int i = 0; i < size; i++) {
        // Create a new structure and set its fields
        NFAPI_CRC_INDICATION_PDU_T *structure = &structures[i];
        structure->RX_UE_INFORMATION_TAG = i + 1;
        structure->RNTI = list[i];
        structure->CRC_INDICATION_REL8_TAG = crcflag;

        // Acquire the semaphore and add the structure to the array
        sem_wait(sem);
        array[i] = list[i];
        free(structure);
    }

    // Release the semaphore and delete it
    sem_post(sem);
    sem_close(sem);

    // Return the largest integer found and the list of structures
    return largest;
}
