// Define the different distribution types supported by the library
enum DistributionType { UNIFORM, NORMAL };

// Define a struct to represent a random number generator instance
struct RandomNumberGenerator {
  // The current distribution type
  DistributionType distribution;

  // The current seed value
  uint64_t seed;

  // The current state of the generator
  std::mt19937_64 mt;

  // A mutex to protect concurrent access to the generator
  std::mutex mutex;

  // A condition variable to signal when a new random number is available
  std::condition_variable cv;
};

// Define a vector of RandomNumberGenerator instances, one for each thread
