uint64_t generateRandomNumber(DistributionType distribution, uint64_t seed) {
  // Lock the mutex to prevent concurrent access to the generator
  std::lock_guard<std::mutex> lock(generators[0].mutex);

  // Set the current distribution and seed for the generator
  generators[0].distribution = distribution;
  generators[0].seed = seed;

  // Generate a random number using the specified distribution and seed
  uint64_t result = generators[0].mt();

  // Unlock the mutex
  lock.unlock();

  return result;
}

// Define a function to switch the distribution of the generator
void switchDistribution(int index, DistributionType distribution) {
  // Lock the mutex to prevent concurrent access to the generator
  std::lock_guard<std::mutex> lock(generators[index].mutex);

  // Set the new distribution for the generator
  generators[index].distribution = distribution;
}

// Define a function to save the state of the generator
void saveState(int index) {
  // Lock the mutex to prevent concurrent access to the generator
  std::lock_guard<std::mutex> lock(generators[index].mutex);

  // Save the current state of the generator
  generators[index].seed = generators[index].mt.getSeed();
}

// Define a function to load the state of the generator
