// Define the function to read a dynamic list of integers from a configuration file
int read_configuration_file(const char* filename, int** list, size_t* list_size) {
    // Open the configuration file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening configuration file: %s\n", strerror(errno));
        return ERROR_OPENING_CONFIGURATION_FILE;
    }

    // Initialize the list of integers to an empty state
    *list = NULL;
    *list_size = 0;

    // Read the configuration file line by line
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        // Ignore comments and empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Parse the integer from the line
        int value = atoi(line);
        if (value < 0) {
            printf("Error reading configuration file: invalid integer value\n");
            fclose(fp);
            return ERROR_READING_CONFIGURATION_FILE;
        }

        // Allocate memory for the list of integers if necessary
        if (*list == NULL) {
            *list = malloc(sizeof(int) * MAX_LIST_SIZE);
            if (*list == NULL) {
                printf("Error allocating memory for list: %s\n", strerror(errno));
                fclose(fp);
                return ERROR_ALLOCATING_MEMORY;
            }
        }

        // Add the integer to the list
        (*list)[*list_size] = value;
        *list_size += 1;
    }

    // Close the configuration file
    fclose(fp);

    return 0;
}

// Define the function to determine the largest integer in a list of integers
int get_largest_integer(const int* list, size_t list_size) {
    if (list == NULL || list_size == 0) {
        return -1;
    }

    int largest = list[0];
    for (size_t i = 1; i < list_size; i++) {
        if (list[i] > largest) {
            largest = list[i];
        }
    }

    return largest;
}

