    // Open the JPEG file for reading
    FILE* fp = fopen(jpeg_filename, "r");
    if (fp == NULL) {
        printf("Error opening JPEG file: %s\n", strerror(errno));
        return ERROR_OPENING_JPEG_FILE;
    }

    // Open the PDF file for writing
