    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        // Ignore comments and empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Write the line to the PDF file
        fprintf(pdf, "%s", line);
    }

    // Close the JPEG and PDF files
    fclose(fp);
    fclose(pdf);

    return 0;
}

