    char *client_id; // Unique identifier for the client
    bool connected; // Flag indicating whether the socket is connected
    int status; // Network status information (e.g., latency, throughput)
} tcp_socket_t;

// Define the structure for a network connection management system
typedef struct {
    tcp_socket_t *sockets; // Array of TCP socket connections
    size_t num_sockets; // Number of sockets in the array
    pthread_mutex_t mutex; // Mutex for protecting the socket list
} network_mgmt_system_t;

// Initialize a new network connection management system
network_mgmt_system_t *init_network_mgmt_system(size_t num_sockets) {
    network_mgmt_system_t *sys = malloc(sizeof(network_mgmt_system_t));
    sys->sockets = calloc(num_sockets, sizeof(tcp_socket_t));
    sys->num_sockets = num_sockets;
    pthread_mutex_init(&sys->mutex, NULL);
    return sys;
}

// Add a new TCP socket connection to the network management system
void add_tcp_socket(network_mgmt_system_t *sys, int fd, char *client_id) {
    pthread_mutex_lock(&sys->mutex);
    if (sys->num_sockets >= sys->sockets_size) {
        // Reallocate the socket array if necessary
        sys->sockets = realloc(sys->sockets, 2 * sys->sockets_size * sizeof(tcp_socket_t));
        sys->sockets_size *= 2;
    }
    sys->sockets[sys->num_sockets].fd = fd;
    sys->sockets[sys->num_sockets].client_id = client_id;
    sys->sockets[sys->num_sockets].connected = true;
    sys->sockets[sys->num_sockets].status = 0;
    sys->num_sockets++;
    pthread_mutex_unlock(&sys->mutex);
}

// Remove a TCP socket connection from the network management system
void remove_tcp_socket(network_mgmt_system_t *sys, int fd) {
    pthread_mutex_lock(&sys->mutex);
    for (size_t i = 0; i < sys->num_sockets; i++) {
        if (sys->sockets[i].fd == fd) {
            // Close the socket and remove it from the array
            close(sys->sockets[i].fd);
            memmove(&sys->sockets[i], &sys->sockets[i + 1], sizeof(tcp_socket_t) * (sys->num_sockets - i));
            sys->num_sockets--;
            break;
        }
    }
    pthread_mutex_unlock(&sys->mutex);
}

// Update the network status information for a TCP socket connection
void update_tcp_socket(network_mgmt_system_t *sys, int fd, int status) {
    pthread_mutex_lock(&sys->mutex);
    for (size_t i = 0; i < sys->num_sockets; i++) {
        if (sys->sockets[i].fd == fd) {
            // Update the network status information
            sys->sockets[i].status = status;
            break;
        }
    }
    pthread_mutex_unlock(&sys->mutex);
}

// Retrieve the network status information for a TCP socket connection
int get_tcp_socket_status(network_mgmt_system_t *sys, int fd) {
    pthread_mutex_lock(&sys->mutex);
    for (size_t i = 0; i < sys->num_sockets; i++) {
