typedef struct {
    char c;
    short s;
    int i;
} record;

// Define the function to manage memory for the three data structures
void manage_memory(int num_records, int max_limit) {
    // Dynamically allocate memory for the array of long offsets
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Dynamically allocate memory for the array of int keys
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Dynamically allocate memory for the array of record structures
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the char field in each record structure to a default value
    for (int i = 0; i < num_records; i++) {
        records[i].c = 'a';
    }

    // Set the short field in each record structure to a random value between -100 and 100
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].s = rand() % 200 - 100;
    }

    // Set the int field in each record structure to a random value within a user-specified range
    for (int i = 0; i < num_records; i++) {
        records[i].i = rand() % max_limit + 1;
    }

    // Free all allocated memory upon completion or early exit
    free(offsets);
    free(keys);
    free(records);
}
