```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the semaphore structure
typedef struct {
    int value; // Current value of the semaphore
    pthread_mutex_t mutex; // Mutex for synchronizing access to the semaphore
    pthread_cond_t cond; // Condition variable for waiting threads
} semaphore_t;

// Function to create a new semaphore with an initial value of 0
semaphore_t* semaphore_create(int init_value) {
    semaphore_t* sem = malloc(sizeof(semaphore_t));
    if (sem == NULL) {
        return NULL;
    }
    sem->value = init_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
    return sem;
}

// Function to delete a semaphore and reset its value to 0
void semaphore_delete(semaphore_t* sem) {
    if (sem == NULL) {
        return;
    }
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
    free(sem);
}

// Function to acquire a semaphore and decrement its value by 1
void semaphore_acquire(semaphore_t* sem) {
    if (sem == NULL) {
        return;
    }
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to release a semaphore and increment its value by 1
void semaphore_release(semaphore_t* sem) {
    if (sem == NULL) {
        return;
    }
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}
```
