// Define a structure to hold the CRC indication data
typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a buffer to hold the list of CRC indications
#define MAX_CRC_INDICATIONS 10000
static NFAPI_CRC_INDICATION_PDU_T crc_indications[MAX_CRC_INDICATIONS];

// Define a mutex to protect the buffer from concurrent access
static pthread_mutex_t crc_indication_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to add a new CRC indication to the list
void add_crc_indication(uint32_t rx_ue_information_tag, uint16_t rnti, bool crcflag) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the buffer is full and needs to be resized
    if (num_crc_indications == MAX_CRC_INDICATIONS) {
        // Resize the buffer by doubling its size
        NFAPI_CRC_INDICATION_PDU_T *new_buffer = realloc(crc_indications, 2 * MAX_CRC_INDICATIONS);
        if (new_buffer == NULL) {
            // Log an error and return if the resize fails
            printf("Error: Failed to resize CRC indication buffer\n");
            pthread_mutex_unlock(&crc_indication_mutex);
            return;
        }
        crc_indications = new_buffer;
    }

    // Add the new CRC indication to the end of the list
    crc_indications[num_crc_indications].rx_ue_information_tag = rx_ue_information_tag;
    crc_indications[num_crc_indications].rnti = rnti;
    crc_indications[num_crc_indications].crcflag = crcflag;
    num_crc_indications++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Define a function to process a batch of CRC indications
void process_crc_batch(int batch_size) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if there are any CRC indications in the buffer
    if (num_crc_indications == 0) {
        // Unlock the mutex and return if there are no CRC indications
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
    }

    // Process the batch of CRC indications
    for (int i = 0; i < batch_size && i < num_crc_indications; i++) {
        // Compute the CRC for the current CRC indication
        uint32_t crc = compute_crc(crc_indications[i].rx_ue_information_tag, crc_indications[i].rnti);

        // Check if the CRC is valid and log an error if it's not
        if (crc != crc_indications[i].crcflag) {
            printf("Error: Invalid CRC computation for RX UE information tag %u and RNTI %hu\n", crc_indications[i].rx_ue_information_tag, crc_indications[i].rnti);
        }
    }

    // Remove the processed CRC indications from the buffer
    num_crc_indications -= batch_size;
    memmove(crc_indications, &crc_indications[batch_size], sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_crc_indications);

    // Unlock the mutex and return
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Define a function to compute the CRC for a given RX UE information tag and RNTI
uint32_t compute_crc(uint32_t rx_ue_information_tag, uint16_t rnti) {
    // Compute the CRC using a fast algorithm like CRC-32 or CRC-64
    return crc32(rx_ue_information_tag, rnti);
