['```rust
use std::fs;
use std::path::Path;
use std::io::{BufReader, BufRead};
use std::collections::HashMap;
use std::str::FromStr;
use std::error::Error;
use llvm_ir::{LLVMIR, LLVMOptLevel};
use llvm_backend::{LLVMBackend, TargetArchitecture};

fn process_file(path: &Path) -> Result<(), Box<dyn Error>> {
    let file = fs::File::open(path)?;
    let reader = BufReader::new(file);
    let mut lexer = Lexer::new(reader);
    let mut parser = Parser::new();
    let mut nodes: Vec<Node> = vec![];
    while let Some(token) = lexer.next_token()? {
        nodes.push(parser.parse_node(&token)?);
    }
    let llvmir = LLVMIR::from_nodes(nodes)?;
    let backend = LLVMBackend::new();
    let target_arch = TargetArchitecture::from_str("x86-64")?;
    let optimized_llvmir = backend.optimize(&llvmir, LLVMOptLevel::O3)?;
    let binary = backend.compile(&optimized_llvmir, target_arch)?;
    println!("Binary size: {} bytes", binary.len());
    Ok(())
}

struct Lexer<'a> {
    reader: BufRead,
    current_token: Option<Token>,
    line_number: usize,
}

impl<'a> Lexer<'a> {
    fn new(reader: BufReader) -> Self {
        Self {
            reader,
            current_token: None,
            line_number: 1,
        }
    }

    fn next_token(&mut self) -> Result<Option<Token>, Box<dyn Error>> {
        if let Some(token) = self.current_token.take() {
            return Ok(Some(token));
        }
        loop {
            let mut line = String::new();
            match self.reader.read_line(&mut line)? {
                0 => break,
                _ => (),
            }
            if let Some((token, rest)) = Token::from_str(line.as_str()) {
                self.current_token = Some(token);
                self.reader = BufReader::new(rest);
                return Ok(Some(self.current_token.take().unwrap()));
            }
        }
        Ok(None)
    }
}

struct Parser {
    nodes: Vec<Node>,
}

impl Parser {
    fn new() -> Self {
        Self {
            nodes: vec![],
        }
    }

    fn parse_node(&mut self, token: &Token) -> Result<Node, Box<dyn Error>> {
        match token.kind {
            TokenKind::Identifier => Ok(Node::Identifier(token.value)),
            TokenKind::IntegerLiteral => Ok(Node::IntegerLiteral(i64::from_str(&token.value)?)),
            TokenKind::StringLiteral => Ok(Node::StringLiteral(token.value)),
            TokenKind::Keyword(keyword) => match keyword {
                Keyword::Function => self.parse_function(),
                _ => Err("Invalid keyword".into()),
            },
        }
    }

    fn parse_function(&mut self) -> Result<Node, Box<dyn Error>> {
        let mut nodes = vec![];
        while let Some(token) = self.next_token()? {
            match token.kind {
                TokenKind::Identifier => nodes.push(Node::Identifier(token.value)),
                TokenKind::IntegerLiteral => nodes.push(Node::IntegerLiteral(i64::from_str(&token.value)?)),
                TokenKind::StringLiteral => nodes.push(Node::StringLiteral(token.value)),
                TokenKind::Keyword(keyword) => match keyword {
                    Keyword::Function => break,
                    _ => Err("Invalid keyword".into()),
                },
            }
        }
        Ok(Node::Function(nodes))
    }
}

enum Node {
    Identifier(String),
    IntegerLiteral(i64),
    StringLiteral(String),
    Function(Vec<Node>),
}

struct Token {
    kind: TokenKind,
    value: String,
}

impl FromStr for Token {
    type Err = Box<dyn Error>;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut parts = s.split(' ');
        let kind = match parts.next() {
            Some("identifier") => TokenKind::Identifier,
            Some("integer_literal") => TokenKind::IntegerLiteral,
            Some("string_literal") => TokenKind::StringLiteral,
            Some(keyword) => Keyword::from_str(keyword)?,
            _ => return Err("Invalid token".into()),
        };
        let value = parts.next().ok_or("Missing token value")?;
        Ok(Token { kind, value })
    }
}

enum TokenKind {
    Identifier,
    IntegerLiteral,
    StringLiteral,
    Keyword(Keyword),
}

enum Keyword {
    Function,
}

impl FromStr for Keyword {
    type Err = Box<dyn Error>;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "function" => Ok(Keyword::Function),
            _ => Err("Invalid keyword".into()),
        }
    }
}
```']

