// Thread-safe cache for recently resolved hostnames
static char *hostname_cache[1024];
static int hostname_cache_size = 0;

// Function to resolve a hostname and return its IP address
int resolveHostname(const char *hostname) {
    // Check if the hostname is already in the cache
    for (int i = 0; i < hostname_cache_size; i++) {
        if (strcmp(hostname, hostname_cache[i]) == 0) {
            return hostname_cache[i];
        }
    }

    // Perform DNS resolution using standard library functions
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return -1; // Error resolving hostname
    }

    // Add the resolved IP address to the cache
    char *ip_address = inet_ntoa((struct in_addr *) res->ai_addr);
    if (hostname_cache_size < 1024) {
        hostname_cache[hostname_cache_size++] = ip_address;
    } else {
        // Cache is full, replace the oldest entry with the new one
        for (int i = 0; i < hostname_cache_size - 1; i++) {
            if (strcmp(hostname_cache[i], hostname) == 0) {
                hostname_cache[i] = ip_address;
                break;
            }
        }
    }

    return ip_address;
}
```
This function uses the `getaddrinfo` function from the `netdb.h` header file to perform DNS resolution, and it caches the resolved IP addresses in a static array to avoid repeated lookups for frequently used hostnames. The cache is limited to 1024 entries to prevent memory issues.

