// Define the function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateArray(int N) {
    // Validate that the allocated array can hold at least N elements
    if (N < 0 || !canAllocateArray(N)) {
        return NULL;
    }

    // Dynamically allocate an array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!arr) {
        return NULL;
    }

    // Populate the array with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        arr[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        arr[i].RNTI = rand() % 1000000000;
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        arr[i].CRCFLAG = (rand() % 2) == 0;
    }

    // Return the populated array
    return arr;
}

// Define a function to validate that the allocated array can hold at least N elements
bool canAllocateArray(int N) {
    // Calculate the required memory size for an array of NFAPI_CRC_INDICATION_PDU_T structures
    int memSize = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    // Check if the system has enough free memory to allocate the array
    if (memSize > getFreeMemory()) {
        return false;
    }

    // Return true if the system has enough free memory to allocate the array
    return true;
}

// Define a function to calculate the amount of free memory available on the system
int getFreeMemory() {
    // Calculate the total amount of memory available on the system
    int totalMem = (int)sysconf(_SC_PAGESIZE) * sysconf(_SC_PHYS_PAGES);

    // Calculate the amount of free memory available on the system
    int freeMem = 0;
    FILE* file = fopen("/proc/meminfo", "r");
    if (file != NULL) {
        char line[128];
        while (fgets(line, sizeof(line), file) != NULL) {
            if (strstr(line, "MemFree:") != NULL) {
                sscanf(line, "%*s %d", &freeMem);
                break;
            }
        }
        fclose(file);
    }

    // Return the amount of free memory available on the system
    return totalMem - freeMem;
}
