using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace GameEngine.Logging
{
    public class LoggingFramework
    {
        private readonly Dictionary<string, LogLevel> _logLevels = new Dictionary<string, LogLevel>();
        private readonly Dictionary<string, LogOutputFormat> _logOutputFormats = new Dictionary<string, LogOutputFormat>();
        private readonly Dictionary<string, string> _logFilePaths = new Dictionary<string, string>();

        public void Initialize(string configFilePath)
        {
            // Load configuration settings from JSON file
            var config = JsonConvert.DeserializeObject<LoggingConfiguration>(File.ReadAllText(configFilePath));

            // Initialize log levels, output formats, and file paths for various game components
            foreach (var component in config.Components)
            {
                _logLevels[component.Name] = component.LogLevel;
                _logOutputFormats[component.Name] = component.LogOutputFormat;
                _logFilePaths[component.Name] = component.LogFilePath;
            }
        }

        public void Log(string component, string message)
        {
            // Check if logging is enabled for the specified component
            if (_logLevels[component] == LogLevel.None)
                return;

            // Format log message according to output format
            var formattedMessage = FormatLogMessage(_logOutputFormats[component], message);

            // Write log message to file
            File.AppendAllText(_logFilePaths[component], formattedMessage + Environment.NewLine);
        }

        public void SetVerbosity(string component, LogLevel level)
        {
            _logLevels[component] = level;
        }

        private string FormatLogMessage(LogOutputFormat format, string message)
        {
            switch (format)
            {
                case LogOutputFormat.Text:
                    return message;
                case LogOutputFormat.Json:
                    return JsonConvert.SerializeObject(new { Message = message });
                default:
                    throw new ArgumentException("Invalid log output format", nameof(format));
            }
        }
    }

    public enum LogLevel
    {
        None,
        Error,
        Warning,
        Info,
        Debug
    }

    public enum LogOutputFormat
    {
        Text,
        Json
    }

    public class LoggingConfiguration
    {
        [JsonProperty("components")]
        public List<LoggingComponent> Components { get; set; }
    }

    public class LoggingComponent
    {
        [JsonProperty("name")]
        public string Name { get; set; }

        [JsonProperty("log_level")]
        public LogLevel LogLevel { get; set; }

        [JsonProperty("log_output_format")]
        public LogOutputFormat LogOutputFormat { get; set; }

        [JsonProperty("log_file_path")]
        public string LogFilePath { get; set; }
    }
}
