#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

// Define constants for command-line options and default values
#define MAX_INPUT_FILES 100
#define DEFAULT_NUM_WORKER_THREADS (get_num_cpus() / 2)
#define DEFAULT_OUTPUT_FILE "output.txt"
#define FLAG_HELP 'h'
#define FLAG_C 'c'
#define FLAG_V 'v'

// Define data structures for storing input file information and statistics
typedef struct {
    char* filename;
    int num_lines;
    long total_chars;
} input_file_info_t;

typedef struct {
    int num_input_files;
    input_file_info_t* files;
    char* output_filename;
    int num_worker_threads;
    int flag_help;
    int flag_c;
    int flag_v;
} program_options_t;

// Define function prototypes for worker threads and main thread
void* worker_thread(void* args);
int main(int argc, char** argv);

// Function to get the number of CPU cores available on the system
int get_num_cpus() {
    return sysconf(_SC_NPROCESSORS_ONLN);
}

// Function to parse command-line arguments and populate program options structure
program_options_t* parse_args(int argc, char** argv) {
    // Initialize program options structure
    program_options_t* options = (program_options_t*)malloc(sizeof(program_options_t));
    memset(options, 0, sizeof(program_options_t));

    // Parse command-line arguments and populate program options structure
    int i;
    for (i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            options->flag_help = 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            options->flag_c = 1;
        } else if (strcmp(argv[i], "-v") == 0) {
            options->flag_v = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            options->output_filename = argv[i] + 2;
        } else {
            // Add input file to list of files to process
            options->num_input_files++;
            if (options->num_input_files > MAX_INPUT_FILES) {
                fprintf(stderr, "Error: too many input files specified\n");
                exit(1);
            }
            options->files[i - 1].filename = argv[i];
        }
    }

    // Set default values for missing command-line arguments
    if (options->num_input_files == 0) {
        fprintf(stderr, "Error: no input files specified\n");
        exit(1);
    }
    if (options->output_filename == NULL) {
        options->output_filename = DEFAULT_OUTPUT_FILE;
    }
    if (options->num_worker_threads == 0) {
        options->num_worker_threads = DEFAULT_NUM_WORKER_THREADS;
    }

    return options;
}

// Function to read input file line by line in parallel using worker threads
void* worker_thread(void* args) {
    // Get thread ID and input file information from arguments
    int tid = (int)(long long)args;
    input_file_info_t* file = &options->files[tid];

    // Open input file for reading
    FILE* fp = fopen(file->filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: unable to open input file %s\n", file->filename);
        exit(1);
    }

    // Read input file line by line and calculate statistics
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Increment line count for this input file
        file->num_lines++;

        // Calculate total number of characters across all lines for files where the -c flag is provided
        if (options->flag_c) {
            file->total_chars += strlen(line);
        }

        // Print detailed line numbers and corresponding content for files where the -v flag is enabled
        if (options->flag_v) {
            printf("%d: %s", tid, line);
        }
    }

    // Close input file
    fclose(fp);

    return NULL;
}

// Function to handle errors and print informative error messages
void handle_error(char* message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(1);
}

int main(int argc, char** argv) {
    // Parse command-line arguments and populate program options structure
    options = parse_args(argc, argv);

    // Initialize semaphore for synchronizing access to shared counters and statistics
    sem_t* sem = sem_open("sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        handle_error("unable to create semaphore");
    }

    // Initialize shared counters and statistics for input files
    int* num_lines = (int*)malloc(options->num_input_files * sizeof(int));
    long* total_chars = (long*)malloc(options->num_input_files * sizeof(long));
    memset(num_lines, 0, options->num_input_files * sizeof(int));
    memset(total_chars, 0, options->num_input_files * sizeof(long));

    // Create worker threads to read input files in parallel
    pthread_t* threads = (pthread_t*)malloc(options->num_worker_threads * sizeof(pthread_t));
    int i;
    for (i = 0; i < options->num_worker_threads; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, (void*)(long long)i)) {
            handle_error("unable to create worker thread");
        }
    }

    // Wait for worker threads to complete and update shared counters and statistics
    for (i = 0; i < options->num_worker_threads; ++i) {
        if (pthread_join(threads[i], NULL)) {
            handle_error("unable to join worker thread");
        }
        sem_wait(sem);
        num_lines[i] += file.num_lines;
        total_chars[i] += file.total_chars;
        sem_post(sem);
    }

    // Print statistics for all input files
    printf("Total number of lines: %d\n", num_lines[0]);
    for (i = 1; i < options->num_input_files; ++i) {
        printf("File %s: %d lines, %ld characters\n", options->files[i].filename, num_lines[i], total_chars[i]);
    }

    // Clean up resources and exit
    free(threads);
    free(num_lines);
    free(total_chars);
    sem_close(sem);
    return 0;
}
