// Define the UE context structure
typedef struct {
    int ue_id;
    RadioResourceConfiguration rrc;
    ServingCellInfo scell;
} UEContext;

// Define a function to initialize and populate an array of UE contexts
int init_ue_context(UEContext **ue_array, int num_ues) {
    // Allocate memory for the UE context array
    *ue_array = (UEContext *)malloc(num_ues * sizeof(UEContext));
    if (*ue_array == NULL) {
        LOG_ERROR("Failed to allocate memory for UE context array");
        return -1;
    }

    // Initialize each UE context structure
    for (int i = 0; i < num_ues; i++) {
        (*ue_array)[i].ue_id = i + 1;
        (*ue_array)[i].rrc.max_mcs = 23;
        (*ue_array)[i].scell.cell_id = 0;
    }

    return 0;
}

// Define a function to update the RadioResourceConfiguration for a specific UE context
int update_rrc(UEContext *ue_context, int new_mcs) {
    if (new_mcs < 0 || new_mcs > 23) {
        LOG_ERROR("Invalid MCS value: %d", new_mcs);
        return -1;
    }

    ue_context->rrc.max_mcs = new_mcs;
    return 0;
}

// Define a function to update the ServingCellInfo for a specific UE context
int update_scell(UEContext *ue_context, int new_cell_id) {
    if (new_cell_id < 0 || new_cell_id > 15) {
        LOG_ERROR("Invalid cell ID value: %d", new_cell_id);
        return -1;
    }

    ue_context->scell.cell_id = new_cell_id;
    return 0;
}

// Define a function to retrieve specific UE context information based on a provided UE ID
UEContext *get_ue_context(UEContext **ue_array, int num_ues, int ue_id) {
    for (int i = 0; i < num_ues; i++) {
        if ((*ue_array)[i].ue_id == ue_id) {
            return &(*ue_array)[i];
        }
    }

    LOG_ERROR("UE context not found for UE ID: %d", ue_id);
    return NULL;
}

// Define a function to free the memory allocated for the UE context array
void free_ue_context(UEContext **ue_array) {
    if (*ue_array != NULL) {
        free(*ue_array);
        *ue_array = NULL;
    }
}
