// Define the function to generate traffic indications
NFAPI_TRAFFIC_INDICATION_PDU_T* generateTrafficIndications(int numStructures, int stringLength, char* macAddressRange) {
    // Validate the input parameters
    if (numStructures <= 0 || stringLength <= 0 || macAddressRange == NULL) {
        return NULL;
    }

    // Allocate memory for the structures
    NFAPI_TRAFFIC_INDICATION_PDU_T* trafficIndications = malloc(numStructures * sizeof(NFAPI_TRAFFIC_INDICATION_PDU_T));
    if (trafficIndications == NULL) {
        return NULL;
    }

    // Initialize the structures with default values
    for (int i = 0; i < numStructures; i++) {
        trafficIndications[i].RX_UE_INFORMATION_TAG = 0x1234;
        trafficIndications[i].RNTI = 0x5678;
        trafficIndications[i].CRC_INDICATION_REL8_TAG = 0x9ABC;
        trafficIndications[i].CRCFLAG = false;
    }

    // Generate a random string for each structure
    srand(time(NULL));
    for (int i = 0; i < numStructures; i++) {
        char* randomString = malloc(stringLength * sizeof(char));
        if (randomString == NULL) {
            free(trafficIndications);
            return NULL;
        }
        for (int j = 0; j < stringLength; j++) {
            randomString[j] = 'A' + rand() % ('Z' - 'A');
        }
        strcpy(trafficIndications[i].MAC_ADDRESS, randomString);
        free(randomString);
    }

    // Validate the MAC addresses and populate the structures with valid values
    for (int i = 0; i < numStructures; i++) {
        if (!validateMacAddress(trafficIndications[i].MAC_ADDRESS, macAddressRange)) {
            free(trafficIndications);
            return NULL;
        }
    }

    // Return the populated structures
    return trafficIndications;
}

// Validate a MAC address against a specified range
bool validateMacAddress(char* macAddress, char* macAddressRange) {
    // Check if the MAC address is within the specified range
    if (strncmp(macAddress, macAddressRange, strlen(macAddressRange)) == 0) {
        return true;
    } else {
        return false;
    }
