            break;
        case 'delete':
            // Delete user account
            if (!$user) {
                return json_encode(['message' => 'error', 'errors' => ['Invalid user ID']]);
            }
            deleteUser($user);
            break;
    }

    // Save user account details to database
    $saveResult = saveUser($user);
    if ($saveResult['status'] === 'error') {
        return json_encode(['message' => 'error', 'errors' => $saveResult['errors']]);
    }

    // Return JSON response
    return json_encode(['message' => 'success']);
}

