// Define the custom memory pool for the function
static void* memoryPool = NULL;
static size_t memoryPoolSize = 0;

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** allocateAndPopulateArray(size_t n) {
    // Validate that the array can hold at least N elements
    if (n > 0 && memoryPoolSize < n * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        return NULL;
    }

    // Initialize the memory pool if necessary
    if (!memoryPool) {
        memoryPool = malloc(MEMORY_POOL_SIZE);
        if (!memoryPool) {
            free(array);
            return NULL;
        }
        memoryPoolSize = MEMORY_POOL_SIZE;
    }

    // Populate the array of structures with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    size_t i;
    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)memoryPool;
        memoryPool += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        memoryPoolSize -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        array[i] = pdu;
        pdu->rxUeInformationTag = (RX_UE_INFORMATION_TAG)rand();
        pdu->rnti = (RNTI)rand();
        pdu->crcIndicationRel8Tag = (CRC_INDICATION_REL8_TAG)rand();
    }

    return array;
}

// Function to deallocate the memory pool when it is no longer needed
void deallocateMemoryPool() {
    if (memoryPool) {
        free(memoryPool);
        memoryPool = NULL;
        memoryPoolSize = 0;
    }
}
