import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

public class PokemonWeaknessReport {
    private static final int MAX_CONCURRENT_REQUESTS = 10;
    private static final long CACHE_EXPIRATION_TIME = TimeUnit.MINUTES.toMillis(30);
    private static final String API_ENDPOINT = "https://pokeapi.co/api/v2/pokemon";
    private static final Map<String, Pokemon> CACHE = new ConcurrentHashMap<>();
    private static final ExecutorService EXECUTOR_SERVICE = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);

    public static void main(String[] args) {
        List<Pokemon> pokemons = getPokemons();
        Map<String, WeaknessReport> weaknessReports = generateWeaknessReports(pokemons);
        System.out.println("Weakness reports: " + weaknessReports);
    }

    private static List<Pokemon> getPokemons() {
        // Fetch Pokemon data from API
        String response = fetchApiData(API_ENDPOINT);
        return parseResponse(response);
    }

    private static Map<String, WeaknessReport> generateWeaknessReports(List<Pokemon> pokemons) {
        // Generate weakness reports for each Pokemon
        Map<String, WeaknessReport> weaknessReports = new HashMap<>();
        for (Pokemon pokemon : pokemons) {
            WeaknessReport report = generateWeaknessReport(pokemon);
            weaknessReports.put(pokemon.getName(), report);
        }
        return weaknessReports;
    }

    private static WeaknessReport generateWeaknessReport(Pokemon pokemon) {
        // Generate a detailed report of the Pokemon's weaknesses and potential counters
        List<String> weaknesses = new ArrayList<>();
        List<String> counters = new ArrayList<>();
        for (Type type : pokemon.getTypes()) {
            Type weakness = getWeakness(type);
            if (weakness != null) {
                weaknesses.add(weakness.getName());
            }
            List<Type> countersForType = getCounters(type);
            if (!countersForType.isEmpty()) {
                counters.addAll(countersForType.stream().map(Type::getName).collect(Collectors.toList()));
            }
        }
        return new WeaknessReport(weaknesses, counters);
    }

    private static Type getWeakness(Type type) {
        // Get the weakness of a given Type
        String weaknessName = type.getWeakness();
        if (weaknessName != null) {
            return new Type(weaknessName);
        } else {
            return null;
        }
    }

    private static List<Type> getCounters(Type type) {
        // Get the counters of a given Type
        String countersString = type.getCounters();
        if (countersString != null) {
            return Arrays.stream(countersString.split(",")).map(Type::new).collect(Collectors.toList());
        } else {
            return new ArrayList<>();
        }
    }

    private static String fetchApiData(String endpoint) {
        // Fetch data from API using HTTP GET request
        try {
            URL url = new URL(endpoint);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            int responseCode = connection.getResponseCode();
            if (responseCode == 200) {
                BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String inputLine;
                StringBuilder response = new StringBuilder();
                while ((inputLine = in.readLine()) != null) {
                    response.append(inputLine);
                }
                in.close();
                return response.toString();
            } else {
                throw new IOException("Failed to fetch data from API: " + responseCode);
            }
        } catch (IOException e) {
            System.out.println("Error fetching data from API: " + e.getMessage());
            return null;
        }
    }

    private static List<Pokemon> parseResponse(String response) {
        // Parse the JSON response from the API into a list of Pokemon objects
        try {
            ObjectMapper mapper = new ObjectMapper();
            JsonNode root = mapper.readTree(response);
            List<Pokemon> pokemons = new ArrayList<>();
            for (JsonNode node : root) {
                String name = node.get("name").asText();
                Type[] types = parseTypes(node.get("types"));
                Pokemon pokemon = new Pokemon(name, types);
                pokemons.add(pokemon);
            }
            return pokemons;
        } catch (IOException e) {
            System.out.println("Error parsing JSON response: " + e.getMessage());
            return null;
        }
    }

    private static Type[] parseTypes(JsonNode typesNode) {
        // Parse the JSON array of types into a list of Type objects
        try {
            List<Type> types = new ArrayList<>();
            for (JsonNode node : typesNode) {
                String name = node.get("name").asText();
                int damageRelation = node.get("damage_relation").asInt();
                Type type = new Type(name, damageRelation);
                types.add(type);
            }
            return types.toArray(new Type[types.size()]);
        } catch (IOException e) {
            System.out.println("Error parsing JSON response: " + e.getMessage());
            return null;
        }
    }

    private static class Pokemon {
        private String name;
        private Type[] types;

        public Pokemon(String name, Type[] types) {
            this.name = name;
            this.types = types;
        }

        public String getName() {
            return name;
        }

        public Type[] getTypes() {
            return types;
        }
    }

    private static class Type {
        private String name;
        private int damageRelation;

        public Type(String name, int damageRelation) {
            this.name = name;
            this.damageRelation = damageRelation;
        }

        public String getName() {
            return name;
        }

        public int getDamageRelation() {
            return damageRelation;
        }
    }

    private static class WeaknessReport {
        private List<String> weaknesses;
        private List<String> counters;

        public WeaknessReport(List<String> weaknesses, List<String> counters) {
            this.weaknesses = weaknesses;
            this.counters = counters;
        }

        public List<String> getWeaknesses() {
            return weaknesses;
        }

        public List<String> getCounters() {
            return counters;
        }
    }
}
