using namespace std;

// Define a struct to store the filename and its corresponding timestamp
struct FileNameTimestamp {
    string filename;
    chrono::time_point<chrono::system_clock> timestamp;
};

// Define a map to store the generated filenames with their timestamps
unordered_map<string, FileNameTimestamp> generatedFilenames;

// Define a mutex to protect the generatedFilenames map in a high-concurrency environment
mutex generatedFilenamesMutex;

// Define a function to generate a unique filename based on the given parameters
string modifyAndGenerateUniqueFilename(const vector<string>& filenames, const string& filename, const string& insertString, const unordered_map<string, string>& extensionMapping) {
    // Check if the filename is already in the generatedFilenames map
    auto it = generatedFilenames.find(filename);
    if (it != generatedFilenames.end()) {
        return it->second.filename;
    }

    // Parse the original filename to extract the base name and extension
    string baseName, extension;
    size_t dotPos = filename.rfind('.');
    if (dotPos != string::npos) {
        baseName = filename.substr(0, dotPos);
        extension = filename.substr(dotPos + 1);
    } else {
        baseName = filename;
        extension = "";
    }

    // Validate the base name and extension
    if (baseName.length() > 64) {
        throw invalid_argument("Base name is too long");
    }
    if (!extensionMapping.count(extension)) {
        throw invalid_argument("Invalid extension");
    }

    // Determine the number of digits to append based on the length of the base name
    size_t numDigits = 3;
    while (numDigits < baseName.length()) {
        numDigits *= 10;
    }

    // Generate a random 3-digit number using a hash function of the base name
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<int> dist(0, numDigits - 1);
    int randomNumber = dist(gen);

    // Modify the file extension to a new one determined by the first two characters of the base name
    string newExtension = extensionMapping.at(baseName.substr(0, 2));

    // Format the filename to include a timestamp in the format YYYYMMDD_HHMMSS
    chrono::time_point<chrono::system_clock> now = chrono::system_clock::now();
    string timestamp = to_string(chrono::duration_cast<chrono::seconds>(now.time_since_epoch()).count());
    string formattedFilename = baseName + "_" + timestamp + "." + newExtension;

    // Insert the modified filename into the generatedFilenames map with its corresponding timestamp
    generatedFilenamesMutex.lock();
    generatedFilenames[formattedFilename] = {formattedFilename, now};
    generatedFilenamesMutex.unlock();

    return formattedFilename;
}

int main() {
    // Test the function with different inputs
    vector<string> filenames = {"file1.txt", "file2.jpg", "file3.pdf"};
    string filename = "file4.docx";
    string insertString = "_modified";
    unordered_map<string, string> extensionMapping = {{"txt", "txt"}, {"jpg", "jpeg"}, {"pdf", "pdf"}, {"docx", "docx"}};

    cout << modifyAndGenerateUniqueFilename(filenames, filename, insertString, extensionMapping) << endl;

    return 0;
}
