import java.io.*;
import java.util.Date;

public class MoSTState {
    private long timestamp;

    public MoSTState() {
        this.timestamp = new Date().getTime();
    }

    public long getTimestamp() {
        return this.timestamp;
    }
}

public class LoadAndValidateStateFromFile {
    public static MoSTState loadAndValidateStateFromFile(String filePath) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            MoSTState state = (MoSTState) ois.readObject();
            if (!(state instanceof MoSTState)) {
                System.out.println("Invalid object read from file");
                return null;
            }
            long currentTime = new Date().getTime();
            long timestampDiff = Math.abs(currentTime - state.getTimestamp());
            if (timestampDiff > 86400000) { // 24 hours in milliseconds
                System.out.println("State is too old");
                return null;
            }
            return state;
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error reading from file: " + e.getMessage());
            return null;
        }
    }
}
