const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

// Cache configuration
const cacheSize = 100; // Maximum number of files to store in memory
const cacheExpirationTime = 3600; // Time in seconds for cached files to expire

// Validation rules
const validationRules = {
  fileType: ['image/jpeg', 'image/png'],
  fileSize: [1024, 5 * 1024],
};

async function validateFile(filePath) {
  // Check if the file is already in the cache
  const cachedFile = getCachedFile(filePath);
  if (cachedFile) {
    return cachedFile;
  }

  // Read the file from disk and validate its content
  const fileContent = await promisify(fs.readFile)(filePath, 'utf8');
  const validationResult = validateFileContent(fileContent);

  // Add the validated file to the cache if it passes validation
  if (validationResult) {
    addCachedFile(filePath, validationResult);
  }

  return validationResult;
}

