  const cachedFiles = getCachedFiles();
  return cachedFiles[filePath];
}

function addCachedFile(filePath, validationResult) {
  const cachedFiles = getCachedFiles();
  cachedFiles[filePath] = validationResult;
}

function getCachedFiles() {
