  const fileType = getFileType(fileContent);
  const fileSize = getFileSize(fileContent);

  if (!validationRules.fileType.includes(fileType)) {
    console.log(`Invalid file type: ${fileType}`);
    return false;
  }

  if (fileSize < validationRules.fileSize[0] || fileSize > validationRules.fileSize[1]) {
    console.log(`Invalid file size: ${fileSize}`);
    return false;
  }

  return true;
}

function getFileType(fileContent) {
  // Get the file type from the file content
  const fileType = path.extname(fileContent).toLowerCase();
  return fileType;
}

function getFileSize(fileContent) {
