const testModule = require('./module');
const blueslip = require('blueslip');
const tests = [
  (module) => { /* test function 1 */ },
  (module) => { /* test function 2 */ },
  // ...
];

function runTests(tests, moduleSourcePath) {
  const module = require(moduleSourcePath);
  let testResults = [];

  for (const test of tests) {
    blueslip.reset();
    const startTime = Date.now();
    try {
      test(module);
      testResults.push({ name: test.name, duration: Date.now() - startTime });
    } catch (error) {
      console.log(`Error running test ${test.name}:`, error);
    }
  }

  return testResults;
}

function runTestsWithConfiguration(tests, moduleSourcePath, configurationServiceUrl) {
  const module = require(moduleSourcePath);
  let testResults = [];

  try {
    const configuration = fetchConfiguration(configurationServiceUrl);
    for (const test of tests) {
      blueslip.reset();
      const startTime = Date.now();
      try {
        test(module, configuration);
        testResults.push({ name: test.name, duration: Date.now() - startTime });
      } catch (error) {
        console.log(`Error running test ${test.name}:`, error);
      }
    }
  } catch (error) {
    console.log('Failed to fetch configuration from external service', error);
  }

  return testResults;
}

function fetchConfiguration(configurationServiceUrl) {
  try {
    const response = await fetch(configurationServiceUrl);
    if (!response.ok) {
      throw new Error(`Failed to fetch configuration: ${response.statusText}`);
    }
    return response.json();
  } catch (error) {
    console.log('Failed to fetch configuration from external service', error);
  }
}

function skipTests(tests, moduleSourcePath, skipConditions) {
  const module = require(moduleSourcePath);
  let testResults = [];

  for (const test of tests) {
    if (!skipConditions.includes(test.name)) {
      blueslip.reset();
      const startTime = Date.now();
      try {
        test(module);
        testResults.push({ name: test.name, duration: Date.now() - startTime });
      } catch (error) {
        console.log(`Error running test ${test.name}:`, error);
      }
    } else {
      console.log(`Skipping test ${test.name} due to skip conditions`);
    }
  }

  return testResults;
}

function handleTestFailures(tests, moduleSourcePath) {
  const module = require(moduleSourcePath);
  let testResults = [];

  for (const test of tests) {
    blueslip.reset();
    const startTime = Date.now();
    try {
      test(module);
      testResults.push({ name: test.name, duration: Date.now() - startTime });
    } catch (error) {
      console.log(`Error running test ${test.name}:`, error);
      if (error instanceof Error && error.message === 'Test failed') {
        // Handle permanent failures gracefully
        console.log('Permanent failure detected, skipping remaining tests');
        break;
      } else {
        // Retry transient failures up to a maximum number of attempts
        const maxAttempts = 3;
        let attempt = 0;
        while (attempt < maxAttempts) {
          try {
            test(module);
            testResults.push({ name: test.name, duration: Date.now() - startTime });
            break;
          } catch (error) {
            console.log(`Error running test ${test.name}:`, error);
            attempt++;
          }
        }
      }
    }
  }

  return testResults;
}
```
This code defines a `runTests` function that takes a list of test functions and a module source path as input, dynamically loads the module using `require`, executes each test function with the loaded module instance, and logs detailed information to the console. The function also resets the mocking library `blueslip` after each test execution to avoid side effects in subsequent tests.

The `runTestsWithConfiguration` function is similar to `runTests`, but it fetches configuration data from an external service using the `fetchConfiguration` function and passes the configuration data to each test function. The function also handles potential failures or delays in fetching configuration data by logging errors and skipping remaining tests if necessary.

The `skipTests` function is similar to `runTests`, but it takes a list of skip conditions as input and skips any tests that match the specified conditions.

The `handleTestFailures` function is similar to `runTests`, but it handles permanent failures by logging errors and skipping remaining tests, while handling transient failures by retrying the test execution up to a maximum number of attempts.

The code also defines a `fetchConfiguration` function that fetches configuration data from an external service using the `fetch` function and returns the response as JSON data. The function handles potential failures or delays in fetching configuration data by logging errors and returning an empty object if necessary."]

