function getBookReferences(text) {
  // Initialize an empty object to store the book references
  const bookRefs = {};

  // Split the text into individual words
  const words = text.split(' ');

  // Iterate over each word in the text
  for (const word of words) {
    // Check if the word is a valid book reference
    if (isBookReference(word)) {
      // Increment the frequency count for this book
      const book = getBookName(word);
      bookRefs[book] = (bookRefs[book] || 0) + 1;
    }
  }

  return bookRefs;
}

function isBookReference(word) {
  // Check if the word starts with a capital letter and has at least three letters
  return /^[A-Z][a-z]{2,}$/.test(word);
}

function getBookName(word) {
  // Remove any punctuation or special characters from the word
  const cleanWord = word.replace(/[^a-zA-Z]/g, '');

  // Check if the book name is a valid Bible book
  if (isValidBibleBook(cleanWord)) {
    return cleanWord;
  } else {
    throw new Error(`Invalid book reference: ${word}`);
  }
}

function isValidBibleBook(book) {
  // Check if the book is a valid Bible book using an external API
  const apiResponse = fetchBookReference(book);
  return apiResponse.isValid;
}

function fetchBookReference(book) {
  // Fetch the book reference from an external API
  const url = `https://api.example.com/bible/${book}`;
  const response = fetch(url).then(res => res.json());

  // Handle potential network failures and rate limits
  return response.catch(err => {
    console.error(`Error fetching book reference: ${err}`);
    return { isValid: false };
  });
