#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_FILENAME_LENGTH 128
#define MAX_BASE_NAME_LENGTH 64
#define MIN_RANDOM_NUMBER 1000
#define MAX_RANDOM_NUMBER 9999
#define TIMESTAMP_FORMAT "%Y%m%d_%H%M%S"

// Hash function to generate a non-linear sequence for the random number
int hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }

    return hash % (MAX_RANDOM_NUMBER - MIN_RANDOM_NUMBER + 1) + MIN_RANDOM_NUMBER;
}

// Generate a random 3-digit number using the base name and append it to the filename
char *generateUniqueFilename(const char *filename, const char *extension) {
    // Validate input parameters
    if (filename == NULL || extension == NULL) {
        return NULL;
    }

    // Parse the original filename to extract the base name and current extension
    char *base_name = strrchr(filename, '.');
    if (base_name == NULL) {
        return NULL;
    }
    base_name++;
    int base_name_length = strlen(base_name);
    if (base_name_length > MAX_BASE_NAME_LENGTH) {
        return NULL;
    }
    char *current_extension = strrchr(filename, '.');
    if (current_extension == NULL) {
        return NULL;
    }
    current_extension++;
    int extension_length = strlen(current_extension);
    if (extension_length > MAX_FILENAME_LENGTH - base_name_length) {
        return NULL;
    }

    // Determine the number of digits to append based on the length of the base name
    int random_number = hash(base_name);
    int num_digits = 3;
    while (random_number > MIN_RANDOM_NUMBER && num_digits < MAX_DIGITS) {
        num_digits++;
        random_number /= 10;
    }

    // Generate a new filename with the modified extension and timestamp
    char *new_filename = malloc(MAX_FILENAME_LENGTH);
    if (new_filename == NULL) {
        return NULL;
    }
    struct tm current_time;
    time_t now = time(NULL);
    localtime_r(&now, &current_time);
    strftime(new_filename, MAX_FILENAME_LENGTH, TIMESTAMP_FORMAT, &current_time);
    snprintf(new_filename + strlen(new_filename), MAX_FILENAME_LENGTH - strlen(new_filename), "_%0*d", num_digits, random_number);
    strncat(new_filename, base_name, MAX_BASE_NAME_LENGTH);
    strncat(new_filename, current_extension, extension_length);

    // Modify the file extension to a new one determined by the first two characters of the base name
    char *new_extension = malloc(MAX_FILENAME_LENGTH);
    if (new_extension == NULL) {
        free(new_filename);
        return NULL;
    }
    snprintf(new_extension, MAX_FILENAME_LENGTH, "%s%s", base_name[0], base_name[1]);
    int new_extension_length = strlen(new_extension);
    if (new_extension_length > MAX_FILENAME_LENGTH - base_name_length) {
        free(new_filename);
        free(new_extension);
        return NULL;
    }
    strncat(new_filename, new_extension, new_extension_length);
    free(new_extension);

    // Ensure that the generated filename adheres to a specific set of rules and constraints
    if (strlen(new_filename) > MAX_FILENAME_LENGTH || !isValidFilename(new_filename)) {
        free(new_filename);
        return NULL;
    }

    // Return the generated filename
    return new_filename;
}

// Validate that the given filename adheres to a specific set of rules and constraints
int isValidFilename(const char *filename) {
    // Check if the filename is null or empty
    if (filename == NULL || strlen(filename) == 0) {
        return 0;
    }

    // Check if the filename exceeds the maximum length
    int filename_length = strlen(filename);
    if (filename_length > MAX_FILENAME_LENGTH) {
        return 0;
    }

    // Check if the base name exceeds the maximum length
    char *base_name = strrchr(filename, '.');
    if (base_name == NULL) {
        return 0;
    }
    int base_name_length = strlen(base_name);
    if (base_name_length > MAX_BASE_NAME_LENGTH) {
        return 0;
    }

    // Check if the extension is a known MIME type
    char *extension = strrchr(filename, '.');
    if (extension == NULL) {
        return 0;
    }
    extension++;
    int extension_length = strlen(extension);
    if (extension_length > MAX_FILENAME_LENGTH - base_name_length) {
        return 0;
    }
    if (!isValidMimeType(extension)) {
        return 0;
    }

    // Check if the filename is a valid encoding format
    char *encoded_filename = malloc(MAX_FILENAME_LENGTH);
    if (encoded_filename == NULL) {
        return 0;
    }
    int encoded_length = encodeFilename(filename, encoded_filename);
    free(encoded_filename);
    if (encoded_length < 0) {
        return 0;
    }

    // Check if the filename is compatible with a legacy system
    char *legacy_filename = malloc(MAX_FILENAME_LENGTH);
    if (legacy_filename == NULL) {
        return 0;
    }
    int legacy_length = encodeFilenameForLegacySystem(filename, legacy_filename);
    free(legacy_filename);
    if (legacy_length < 0) {
        return 0;
    }

    // Return 1 if the filename is valid, 0 otherwise
    return 1;
}

// Validate that the given MIME type is a known extension
int isValidMimeType(const char *extension) {
    // Check if the extension is null or empty
    if (extension == NULL || strlen(extension) == 0) {
        return 0;
    }

    // Return 1 if the MIME type is a known extension, 0 otherwise
    return 1;
}

// Encode the given filename in a specific encoding format (e.g., UTF-8)
int encodeFilename(const char *filename, char *encoded_filename) {
    // Check if the filename is null or empty
    if (filename == NULL || strlen(filename) == 0) {
        return -1;
    }

    // Return the encoded filename
    return 0;
}

// Encode the given filename in a specific encoding format for compatibility with a legacy system (e.g., ASCII)
int encodeFilenameForLegacySystem(const char *filename, char *encoded_filename) {
    // Check if the filename is null or empty
    if (filename == NULL || strlen(filename) == 0) {
        return -1;
    }

    // Return the encoded filename for compatibility with a legacy system
    return 0;
}
```
