function copyBytes(stream, byteCount) {
  let buffer = Buffer.allocUnsafe(byteCount);
  let bytesRead = 0;
  while (bytesRead < byteCount) {
    const chunk = stream.read();
    if (!chunk) break;
    const chunkSize = Math.min(buffer.length - bytesRead, chunk.length);
    buffer.set(chunk.slice(0, chunkSize), bytesRead);
    bytesRead += chunkSize;
  }
  return buffer;
}
