  private static final int MIN_RESOURCE_THRESHOLD = 80;
  private static final int MAX_RESOURCE_THRESHOLD = 90;

  private List<Microservice> services = new ArrayList<>();
  private Map<String, Microservice> serviceMap = new HashMap<>();

  public void startService(String serviceId) {
    if (services.size() < MAX_SERVICES) {
      Microservice service = new Microservice(serviceId);
      services.add(service);
      serviceMap.put(serviceId, service);
    } else {
      System.out.println("Maximum number of services reached");
    }
