// Modular HTTP client library in Rust

use std::time::Duration;
use std::net::{TcpStream, TcpListener};
use std::io::{Read, Write};
use std::thread::sleep;
use std::sync::mpsc::channel;
use std::collections::HashMap;

// Struct to represent a request
struct Request {
    url: String,
    headers: HashMap<String, String>,
    timeout: Duration,
    proxy: Option<String>
}

// Struct to represent a response
struct Response {
    status_code: u16,
    body: Vec<u8>,
    headers: HashMap<String, String>
}

// Function to make an HTTP request
fn make_request(request: Request) -> Result<Response, String> {
    // Parse the URL and get the scheme
    let url = Url::parse(&request.url).unwrap();
    let scheme = url.scheme().to_string();

    // Create a TCP stream for the request
    let mut stream = TcpStream::connect(url.host_str().unwrap()).unwrap();

    // Set the timeout for the request
    stream.set_read_timeout(Some(request.timeout)).unwrap();
    stream.set_write_timeout(Some(request.timeout)).unwrap();

    // Send the request headers
    let mut headers = HashMap::new();
    headers.insert("Host", url.host_str().unwrap());
    headers.extend(request.headers);
    for (key, value) in headers {
        stream.write_all(format!("{}: {}\r\n", key, value).as_bytes()).unwrap();
    }
    stream.write_all(b"\r\n").unwrap();

    // Send the request body
    if let Some(body) = request.body {
        stream.write_all(&body).unwrap();
    }

    // Read the response headers
    let mut response = Response::new();
    loop {
        let mut line = String::new();
        stream.read_line(&mut line).unwrap();
        if line == "\r\n" {
            break;
        }
        let (key, value) = line.split_once(": ").unwrap();
        response.headers.insert(key.to_string(), value.to_string());
    }

    // Read the response body
    if let Some(content_length) = response.headers.get("Content-Length") {
        let content_length = content_length.parse::<usize>().unwrap();
        response.body = vec![0; content_length];
        stream.read_exact(&mut response.body).unwrap();
    }

    // Return the response
    Ok(response)
}

