<?php

class SecureRandomString {
    private $characters;
    private $length;

    public function __construct($characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $length = 16) {
        $this->characters = $characters;
        $this->length = $length;
    }

    public function generate() {
        $string = '';
        for ($i = 0; $i < $this->length; $i++) {
            $string .= $this->characters[rand(0, strlen($this->characters) - 1)];
        }
        return $string;
    }
}

class PasswordHasher {
    private $algorithm;

    public function __construct($algorithm = 'bcrypt') {
        $this->algorithm = $algorithm;
    }

    public function hash($password) {
        return password_hash($password, $this->algorithm);
    }

    public function verify($password, $hash) {
        return password_verify($password, $hash);
    }
}

class UserCredentialsVerifier {
    private $authFramework;
    private $passwordHasher;
    private $characters;
    private $length;

    public function __construct(AuthFramework $authFramework, PasswordHasher $passwordHasher, $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $length = 16) {
        $this->authFramework = $authFramework;
        $this->passwordHasher = $passwordHasher;
        $this->characters = $characters;
        $this->length = $length;
    }

    public function verifyCredentials($username, $password) {
        $user = $this->authFramework->getUserByUsername($username);
        if (!$user) {
            return false;
        }
        $hashedPassword = $this->passwordHasher->hash($password);
        return password_verify($hashedPassword, $user['password']);
    }
}
```
