<?php

function authenticateUser($username, $password) {
    // Step 1: Validate input parameters
    if (empty($username) || empty($password)) {
        throw new Exception("Invalid username or password");
    }

    // Step 2: Check if user exists in the system
    $user = getUserByUsername($username);
    if (!$user) {
        throw new Exception("User does not exist");
    }

    // Step 3: Verify password
    if (!verifyPassword($password, $user->password)) {
        throw new Exception("Invalid password");
    }

    // Step 4: Generate access token and refresh token
    $accessToken = generateAccessToken();
    $refreshToken = generateRefreshToken();

    // Step 5: Store tokens in the system
    storeTokens($user->id, $accessToken, $refreshToken);

    // Step 6: Update user profile with new token information
    updateUserProfile($user->id, [
        "access_token" => $accessToken,
        "refresh_token" => $refreshToken,
    ]);

    return [
        "access_token" => $accessToken,
        "refresh_token" => $refreshToken,
    ];
}

function getUserByUsername($username) {
    // Step 1: Query database for user with given username
    $user = queryDatabase("SELECT * FROM users WHERE username = ?", [$username]);

    // Step 2: Return user object if found, otherwise return null
    return $user ? (object) $user : null;
}

function verifyPassword($password, $storedHash) {
    // Step 1: Compare password with stored hash using bcrypt
    return password_verify($password, $storedHash);
}

function generateAccessToken() {
    // Step 1: Generate a random string of characters
    $token = bin2hex(random_bytes(64));

    // Step 2: Return token if it is not already in use
    return !isTokenInUse($token) ? $token : generateAccessToken();
}

function generateRefreshToken() {
    // Step 1: Generate a random string of characters
    $token = bin2hex(random_bytes(64));

    // Step 2: Return token if it is not already in use
    return !isTokenInUse($token) ? $token : generateRefreshToken();
}

function storeTokens($userId, $accessToken, $refreshToken) {
    // Step 1: Insert tokens into database for user
    queryDatabase("INSERT INTO tokens (user_id, access_token, refresh_token) VALUES (?, ?, ?)", [$userId, $accessToken, $refreshToken]);
}

function updateUserProfile($userId, $data) {
    // Step 1: Update user profile with new token information
    queryDatabase("UPDATE users SET access_token = ?, refresh_token = ? WHERE id = ?", [$data["access_token"], $data["refresh_token"], $userId]);
}

function isTokenInUse($token) {
    // Step 1: Query database for token in use
    $result = queryDatabase("SELECT COUNT(*) AS count FROM tokens WHERE access_token = ? OR refresh_token = ?", [$token, $token]);

    // Step 2: Return true if token is already in use, otherwise return false
    return $result->count > 0;
}

function queryDatabase($query, $params) {
    // Step 1: Connect to database using PDO
    $pdo = new PDO("mysql:host=localhost;dbname=mydatabase", "username", "password");

    // Step 2: Prepare and execute SQL query with parameters
    $stmt = $pdo->prepare($query);
    $stmt->execute($params);

    // Step 3: Return result set as an array of objects
    return $stmt->fetchAll(PDO::FETCH_OBJ);
}
