#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to represent a network configuration object
typedef struct {
    int num_interfaces;
    int *interface_indices;
    bool prioritize_low_latency;
    pthread_mutex_t mutex; // Mutex for concurrent access to the configuration
} NetworkConfig;

// Function to dynamically construct and manage a network configuration object
NetworkConfig* create_network_config(int *interface_indices, int num_interfaces, bool prioritize_low_latency) {
    // Allocate memory for the network configuration object
    NetworkConfig *config = malloc(sizeof(NetworkConfig));
    if (config == NULL) {
        return NULL;
    }

    // Initialize the number of interfaces and interface indices
    config->num_interfaces = num_interfaces;
    config->interface_indices = interface_indices;

    // Initialize the mutex for concurrent access to the configuration
    pthread_mutex_init(&config->mutex, NULL);

    // Set the priority of the configuration based on the specified criteria
    if (prioritize_low_latency) {
        config->prioritize_low_latency = true;
    } else {
        config->prioritize_low_latency = false;
    }

    return config;
}

// Function to update the reference count of the network configuration object
void update_network_config(NetworkConfig *config) {
    // Acquire the mutex for concurrent access to the configuration
    pthread_mutex_lock(&config->mutex);

    // Update the reference count of the network configuration object
    config->num_interfaces++;

    // Release the mutex for concurrent access to the configuration
    pthread_mutex_unlock(&config->mutex);
}

// Function to release the memory allocated for the network configuration object
void destroy_network_config(NetworkConfig *config) {
    // Acquire the mutex for concurrent access to the configuration
    pthread_mutex_lock(&config->mutex);

    // Release the memory allocated for the network configuration object
    free(config);

    // Release the mutex for concurrent access to the configuration
    pthread_mutex_unlock(&config->mutex);
}
