// Define the structure to hold the extracted metadata
typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int compressionType;
    int imageWidth;
    int imageHeight;
    int colorSpace;
    int extraSamplesCount;
    char** extraSamplesNames;
} tiffMetadata;

// Define the function to parse a TIFF image file and extract metadata
void parseTIFF(const char* filename, tiffMetadata* metadata) {
    // Open the TIFF file for reading
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        printf("Error: unable to open TIFF file %s\n", filename);
        return;
    }

    // Read the image header and extract metadata
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &metadata->bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &metadata->samplesPerPixel);
    TIFFGetField(tif, TIFFTAG_COMPRESSION, &metadata->compressionType);
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &metadata->imageWidth);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &metadata->imageHeight);
    TIFFGetField(tif, TIFFTAG_COLORSPACE, &metadata->colorSpace);

    // Check for extra samples and extract their names if present
    int extraSamplesCount = 0;
    char** extraSamplesNames = NULL;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamplesCount)) {
        extraSamplesNames = malloc(sizeof(char*) * extraSamplesCount);
        for (int i = 0; i < extraSamplesCount; i++) {
            char* sampleName = NULL;
            TIFFGetField(tif, TIFFTAG_EXTRASAMPLES + i, &sampleName);
            extraSamplesNames[i] = sampleName;
        }
    }
    metadata->extraSamplesCount = extraSamplesCount;
    metadata->extraSamplesNames = extraSamplesNames;

    // Close the TIFF file and return the extracted metadata
    TIFFClose(tif);
}

// Define a function to dynamically allocate memory based on the size of the input file
void* dynamicAllocation(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Error: unable to allocate memory\n");
        return NULL;
    }
    return ptr;
}

