#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the salt length and key length in bytes
#define SALT_LEN 16
#define KEY_LEN 32

// Define the number of threads to use for PBKDF2 hashing
#define NUM_THREADS 4

// Define the maximum password length in characters
#define MAX_PASSWORD_LEN 1024

// Define the IV length in bytes
#define IV_LEN 16

// Define the cipher context structure
struct cipher_ctx {
    AES_KEY key;
    unsigned char iv[IV_LEN];
};

// Function to generate a random salt
unsigned char* generate_salt() {
    // Allocate memory for the salt
    unsigned char *salt = (unsigned char*)malloc(SALT_LEN);

    // Generate a random salt using OpenSSL's RAND_bytes function
    if (!RAND_bytes(salt, SALT_LEN)) {
        printf("Error generating salt: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Return the generated salt
    return salt;
}

// Function to derive the encryption key from the password and salt using PBKDF2 with SHA-256
int pbkdf2(const unsigned char *password, const size_t password_len, const unsigned char *salt, const size_t salt_len, unsigned char *key, const size_t key_len) {
    // Define the PBKDF2 parameters
    int iter = 1000;
    int digest = EVP_sha256();

    // Derive the encryption key using PBKDF2
    if (!PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iter, digest, key_len, key)) {
        printf("Error deriving key: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    // Return the derived encryption key
    return 1;
}

// Function to initialize an AES-256-CBC cipher with a given password and salt
struct cipher_ctx* init_cipher(const unsigned char *password, const size_t password_len, const unsigned char *salt, const size_t salt_len) {
    // Allocate memory for the cipher context structure
    struct cipher_ctx *ctx = (struct cipher_ctx*)malloc(sizeof(struct cipher_ctx));

    // Generate a random IV using OpenSSL's RAND_bytes function
    if (!RAND_bytes(ctx->iv, IV_LEN)) {
        printf("Error generating IV: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Derive the encryption key from the password and salt using PBKDF2 with SHA-256
    if (!pbkdf2(password, password_len, salt, salt_len, ctx->key.key, KEY_LEN)) {
        printf("Error deriving key: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Initialize the AES-256-CBC cipher using OpenSSL's EVP_EncryptInit_ex function
    if (!EVP_EncryptInit_ex(&ctx->key, EVP_aes_256_cbc(), NULL, ctx->key.key, ctx->iv)) {
        printf("Error initializing cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return NULL;
    }

    // Return the initialized cipher context structure
    return ctx;
}

// Function to clean up and disable an AES-256-CBC cipher
void cleanup_cipher(struct cipher_ctx *ctx) {
    // Disable the AES-256-CBC cipher using OpenSSL's EVP_EncryptFinal_ex function
    if (!EVP_EncryptFinal_ex(&ctx->key, NULL, 0)) {
        printf("Error finalizing cipher: %s\n", ERR_error_string(ERR_get_error(), NULL));
    }

    // Free the memory allocated for the cipher context structure
    free(ctx);
}

// Function to encrypt data using an AES-256-CBC cipher
int encrypt(struct cipher_ctx *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Define the buffer for the encrypted data
    unsigned char *buf = (unsigned char*)malloc(plaintext_len + AES_BLOCK_SIZE);

    // Encrypt the data using OpenSSL's EVP_EncryptUpdate function
    if (!EVP_EncryptUpdate(&ctx->key, buf, &plaintext_len, plaintext, plaintext_len)) {
        printf("Error encrypting data: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    // Copy the encrypted data to the output buffer
    memcpy(ciphertext, buf, plaintext_len);

    // Free the memory allocated for the buffer
    free(buf);

    // Return the length of the encrypted data
    return plaintext_len;
}

// Function to decrypt data using an AES-256-CBC cipher
int decrypt(struct cipher_ctx *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Define the buffer for the decrypted data
    unsigned char *buf = (unsigned char*)malloc(ciphertext_len + AES_BLOCK_SIZE);

    // Decrypt the data using OpenSSL's EVP_DecryptUpdate function
    if (!EVP_DecryptUpdate(&ctx->key, buf, &ciphertext_len, ciphertext, ciphertext_len)) {
        printf("Error decrypting data: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    // Copy the decrypted data to the output buffer
    memcpy(plaintext, buf, ciphertext_len);

    // Free the memory allocated for the buffer
    free(buf);

    // Return the length of the decrypted data
    return ciphertext_len;
}
