#define MAX_FILE_SIZE 1024 * 1024 * 5 // 5 MB
#define COMPRESSION_LEVEL 9

int convert_jpegs_to_pdf(const char* input_file, const char* output_dir, const char* output_prefix, int compression_level) {
    struct stat file_stat;
    if (stat(input_file, &file_stat) == -1) {
        perror("Error: Failed to get file size");
        return 1;
    }

    // Check if the input file is a directory
    if (S_ISDIR(file_stat.st_mode)) {
        printf("Error: Input file is a directory\n");
        return 1;
    }

    // Get the file size and check if it exceeds the maximum allowed size
    long file_size = file_stat.st_size;
    if (file_size > MAX_FILE_SIZE) {
        printf("Error: File size exceeds maximum allowed size\n");
        return 1;
    }

    // Open the input file and check for errors
    int input_fd = open(input_file, O_RDONLY);
    if (input_fd == -1) {
        perror("Error: Failed to open input file");
        return 1;
    }

    // Open the output directory and check for errors
    int output_dir_fd = open(output_dir, O_RDONLY);
    if (output_dir_fd == -1) {
        perror("Error: Failed to open output directory");
        return 1;
    }

    // Get the file name and extension of the input file
    char* input_file_name = strrchr(input_file, '/');
    if (input_file_name == NULL) {
        input_file_name = input_file;
    } else {
        input_file_name++;
    }
    char* input_file_ext = strrchr(input_file_name, '.');
    if (input_file_ext == NULL) {
        printf("Error: Input file does not have an extension\n");
        return 1;
    }

    // Create a new output file name by concatenating the prefix and the input file name
    char* output_file_name = (char*)malloc(strlen(output_prefix) + strlen(input_file_name) + 1);
    sprintf(output_file_name, "%s%s", output_prefix, input_file_name);

    // Open the output file and check for errors
    int output_fd = open(output_dir, O_WRONLY | O_CREAT, 0644);
    if (output_fd == -1) {
        perror("Error: Failed to create output file");
        return 1;
    }

    // Convert the JPEG files to PDF using a third-party tool
    char* command = (char*)malloc(strlen("convert") + strlen(input_file) + strlen(output_file_name) + 2);
    sprintf(command, "convert %s %s", input_file, output_file_name);
    int system_ret = system(command);
    if (system_ret != 0) {
        printf("Error: Failed to convert JPEG files to PDF\n");
        return 1;
    }

    // Compress the resulting PDF file using a third-party tool
    char* compression_command = (char*)malloc(strlen("gzip") + strlen(output_file_name) + 2);
    sprintf(compression_command, "gzip -%d %s", compression_level, output_file_name);
    system_ret = system(compression_command);
    if (system_ret != 0) {
        printf("Error: Failed to compress PDF file\n");
        return 1;
    }

    // Check the size of the compressed file and loop until it meets the maximum allowed size
    long compressed_file_size = get_file_size(output_file_name);
    while (compressed_file_size > MAX_FILE_SIZE) {
        compression_level++;
        sprintf(compression_command, "gzip -%d %s", compression_level, output_file_name);
        system_ret = system(compression_command);
        if (system_ret != 0) {
            printf("Error: Failed to compress PDF file\n");
            return 1;
        }
        compressed_file_size = get_file_size(output_file_name);
    }

    // Log the compression process and file operations
    time_t current_time = time(NULL);
    char* log_message = (char*)malloc(strlen("Compression") + strlen(input_file) + strlen(output_file_name) + 20);
    sprintf(log_message, "Compression: %s -> %s (%ld bytes)", input_file, output_file_name, compressed_file_size);
    log_message(current_time, log_message);

    // Close the files and free memory
    close(input_fd);
    close(output_fd);
    free(command);
    free(compression_command);
    free(log_message);
    free(output_file_name);

    return 0;
}

long get_file_size(const char* file_path) {
    struct stat file_stat;
    if (stat(file_path, &file_stat) == -1) {
        perror("Error: Failed to get file size");
        return 0;
    }
    return file_stat.st_size;
}
