// Define the structure for traffic indications
typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
    uint32_t identifier;
} NFAPI_TRAFFIC_INDICATION_PDU_T;

// Define the function to generate traffic indications
void generateTrafficIndications(NFAPI_TRAFFIC_INDICATION_PDU_T **traffic_indications, int num_traffic_indications) {
    // Read the MAC address range from a JSON file
    json_object *json = json_object_from_file("mac_address_range.json");
    if (!json) {
        printf("Error reading JSON file\n");
        return;
    }

    // Parse the JSON object into a suitable data structure
    json_object *mac_addresses = json_object_get_array(json);
    int num_mac_addresses = json_object_array_length(mac_addresses);

    // Validate the MAC address format and fall within the specified range
    for (int i = 0; i < num_mac_addresses; i++) {
        json_object *mac_address = json_object_array_get_idx(mac_addresses, i);
        if (!json_is_string(mac_address)) {
            printf("Error: MAC address is not a string\n");
            return;
        }
        char *mac_address_str = (char *)json_object_get_string(mac_address);
        if (!validateMacAddress(mac_address_str)) {
            printf("Error: Invalid MAC address format\n");
            return;
        }
    }

    // Allocate memory for the traffic indications array
    *traffic_indications = (NFAPI_TRAFFIC_INDICATION_PDU_T *)malloc(num_traffic_indications * sizeof(NFAPI_TRAFFIC_INDICATION_PDU_T));
    if (!*traffic_indications) {
        printf("Error: Failed to allocate memory for traffic indications\n");
        return;
    }

    // Populate the traffic indications array with random values
    srand(time(NULL));
    for (int i = 0; i < num_traffic_indications; i++) {
        (*traffic_indications)[i].rx_ue_information_tag = rand() % 65535;
        (*traffic_indications)[i].rnti = rand() % 65535;
        (*traffic_indications)[i].crc_indication_rel8_tag = rand() % 255;
        (*traffic_indications)[i].crcflag = rand() % 255;
        (*traffic_indications)[i].identifier = generateIdentifier(mac_addresses[rand() % num_mac_addresses]);
    }

    // Deallocate memory for the JSON object and MAC address array
    json_object_put(json);
}

// Define a function to validate the MAC address format
int validateMacAddress(char *mac_address) {
    int num_colon = 0;
    for (int i = 0; i < strlen(mac_address); i++) {
        if (mac_address[i] == ':') {
            num_colon++;
        } else if (!isxdigit(mac_address[i])) {
            return 0;
        }
    }
    return num_colon == 5;
}

// Define a function to generate a unique identifier for each traffic indication based on a cryptographic hash of the MAC address and a unique timestamp
uint32_t generateIdentifier(char *mac_address) {
    // Generate a unique timestamp using the current time in seconds
    uint64_t timestamp = (uint64_t)time(NULL);

    // Hash the MAC address and timestamp using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)mac_address, strlen(mac_address), hash);
    SHA256((unsigned char *)&timestamp, sizeof(uint64_t), hash + SHA256_DIGEST_LENGTH);

    // Convert the hash to a 32-bit integer and return it
    uint32_t identifier = *(uint32_t *)hash;
    return identifier;
}
