int execute_command(char *cmd, int sig) {
  // Check if the command is valid
  if (cmd == NULL || strlen(cmd) == 0) {
    return -1;
  }

  // Fork a new process to run the command in the background
  pid_t pid = fork();
  if (pid < 0) {
    perror("fork");
    return -1;
  } else if (pid == 0) {
    // Child process: execute the command and exit
    int status = system(cmd);
    _exit(status);
  }

  // Parent process: set up signal handling and resource cleanup
  struct sigaction sa;
  memset(&sa, 0, sizeof(sa));
  sa.sa_handler = SIG_IGN;
  if (sigaction(SIGINT, &sa, NULL) < 0) {
    perror("sigaction");
    return -1;
  }

  // Close any open files or network connections before forking
  close_resources();

  // Wait for the child process to terminate and handle signal handling
  int status = waitpid(pid, NULL, WUNTRACED);
  if (status < 0) {
    perror("waitpid");
    return -1;
  } else if (WIFEXITED(status)) {
    // Command executed successfully and can be monitored via the signal handler
    return 1;
  } else if (WIFSIGNALED(status)) {
    // Command terminated due to a signal, but monitoring is compromised
    return 0;
  } else {
    // Command failed to start or monitoring is compromised
    return -1;
  }
}

void close_resources() {
  // Close any open files or network connections before forking
  // ...
}
