// Define the function to perform DNS resolution for a given hostname
void *dnsResolution(char *hostname) {
    // Initialize the DNS resolution cache
    DNS_RESOLUTION_CACHE *cache = NULL;

    // Check if the hostname is already in the cache
    bool found = false;
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(hostname, cache[i].hostname) == 0) {
            found = true;
            break;
        }
    }

    // If the hostname is not in the cache, perform DNS resolution and add it to the cache
    if (!found) {
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof(struct addrinfo));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        hints.ai_flags = AI_PASSIVE;
        if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
            // Handle DNS resolution error
            return NULL;
        }
        cache[cache->size].hostname = hostname;
        cache[cache->size].ip_address = res->ai_addr->sa_data;
        cache->size++;
    }

    // Return the IP address from the cache
    return &cache[found].ip_address;
}

