// Resolve a hostname to its IP address using DNS
in_addr_t resolveDNS(char *hostname) {
    // Check if the hostname is already in the cache
    pthread_mutex_lock(&dns_cache_mutex);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            // Return the IP address from the cache
            pthread_mutex_unlock(&dns_cache_mutex);
            return dns_cache[i].ip_address;
        }
    }
    pthread_mutex_unlock(&dns_cache_mutex);

    // Resolve the hostname to its IP address using DNS
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return 0;
    }

    // Check if the DNS query is already in progress
    pthread_mutex_lock(&dns_query_queue.mutex);
    for (int i = 0; i < dns_query_queue.size; i++) {
        if (strcmp(dns_query_queue.entries[i].hostname, hostname) == 0) {
            // Return the IP address from the cache
            pthread_mutex_unlock(&dns_query_queue.mutex);
            return dns_cache[i].ip_address;
        }
    }
    pthread_mutex_unlock(&dns_query_queue.mutex);

    // Add the DNS query to the priority queue
    struct DNSQueryEntry *entry = (struct DNSQueryEntry *)malloc(sizeof(struct DNSQueryEntry));
    entry->hostname = hostname;
    entry->ip_address = res->ai_addr->sa_data[2];
    pthread_mutex_lock(&dns_query_queue.mutex);
    if (dns_query_queue.size < MAX_DNS_QUERIES) {
        dns_query_queue.entries[dns_query_queue.size++] = entry;
    } else {
        // Retry the DNS query after a backoff period
        pthread_mutex_unlock(&dns_query_queue.mutex);
        sleep(dns_retry_backoff);
        return resolveDNS(hostname);
    }
    pthread_mutex_unlock(&dns_query_queue.mutex);

    // Resolve the DNS query asynchronously
    struct addrinfo *res = NULL;
    getaddrinfo(entry->hostname, NULL, &hints, &res);

    // Check if the DNS query was successful
    if (res == NULL) {
        // Remove the DNS query from the priority queue
        pthread_mutex_lock(&dns_query_queue.mutex);
        for (int i = 0; i < dns_query_queue.size; i++) {
            if (strcmp(dns_query_queue.entries[i].hostname, hostname) == 0) {
                dns_query_queue.size--;
                break;
            }
        }
        pthread_mutex_unlock(&dns_query_queue.mutex);

        // Retry the DNS query after a backoff period
        sleep(dns_retry_backoff);
        return resolveDNS(hostname);
    }

    // Add the IP address to the cache
    pthread_mutex_lock(&dns_cache_mutex);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            dns_cache[i].ip_address = res->ai_addr->sa_data[2];
            break;
        }
    }
    pthread_mutex_unlock(&dns_cache_mutex);

    // Return the IP address from the cache
    return dns_cache[i].ip_address;
}

// Generate a random RX_UE_INFORMATION_TAG
uint16_t generateRandomRXUEInformationTag() {
    uint16_t rx_ue_information_tag = 0;
    for (int i = 0; i < 2; i++) {
        rx_ue_information_tag += rand() % 256;
