using System;
using System.IO;
using System.Reflection;
using System.Runtime.Loader;
using System.Threading.Tasks;

public class ModuleIntegrator
{
    private static readonly AssemblyLoadContext _assemblyLoadContext = new AssemblyLoadContext();
    private static readonly Dictionary<string, Assembly> _loadedAssemblies = new Dictionary<string, Assembly>();

    public async Task<Assembly?> IntegrateModule(string moduleDirectory)
    {
        // Verify the existence of a `module-config.json` file in the specified directory
        if (!File.Exists(Path.Combine(moduleDirectory, "module-config.json")))
        {
            return null;
        }

        // Load the module assembly using the AssemblyLoadContext class
        try
        {
            var assembly = await _assemblyLoadContext.LoadFromAssemblyNameAsync(new AssemblyName(Path.Combine(moduleDirectory, "Module.dll")));
            _loadedAssemblies[assembly.FullName] = assembly;
            return assembly;
        }
        catch (Exception ex)
        {
            // Handle potential assembly loading errors gracefully by providing meaningful error messages and logging them to a `debug.log` file without halting the entire application process
            Console.WriteLine($"Error loading module: {ex.Message}");
            File.AppendAllText("debug.log", $"{DateTime.Now}: Error loading module: {ex.Message}{Environment.NewLine}");
        }

        return null;
    }

    public void UnloadModule(Assembly assembly)
    {
        // Unload the module assembly using the AssemblyLoadContext class
        _assemblyLoadContext.Unload(assembly);
        _loadedAssemblies.Remove(assembly.FullName);
    }
}
```
This code implements a `ModuleIntegrator` class that provides methods for integrating and unloading modules in an existing application directory using the `AssemblyLoadContext` class. The `IntegrateModule` method first verifies the existence of a `module-config.json` file in the specified directory, and if it exists, loads the module assembly using the `LoadFromAssemblyNameAsync` method of the `AssemblyLoadContext` class. If an error occurs during loading, the method handles it gracefully by providing meaningful error messages and logging them to a `debug.log` file without halting the entire application process.

The `UnloadModule` method unloads the specified module assembly using the `Unload` method of the `AssemblyLoadContext` class.

This implementation considers the following operational constraints:

