import java.sql.*;
import java.util.Scanner;

public class UserAccountManager {
    private static final String DB_URL = "jdbc:mysql://localhost:3306/user_accounts";
    private static final String USERNAME = "root";
    private static final String PASSWORD = "";

    public static void main(String[] args) throws SQLException {
        // Parse command-line arguments to determine the action (create, update, delete)
        String action = args[0];

        // Validate all necessary fields including 'id', 'name', 'email', and 'password'
        int id = Integer.parseInt(args[1]);
        String name = args[2];
        String email = args[3];
        String password = args[4];

        // Connect to the RDBMS and execute SQL queries for CRUD operations
        Connection conn = DriverManager.getConnection(DB_URL, USERNAME, PASSWORD);
        Statement stmt = conn.createStatement();

        if (action.equals("create")) {
            String query = "INSERT INTO user_accounts (id, name, email, password) VALUES (" + id + ", '" + name + "', '" + email + "', '" + password + "')";
            stmt.executeUpdate(query);
        } else if (action.equals("update")) {
            String query = "UPDATE user_accounts SET name='" + name + "', email='" + email + "', password='" + password + "' WHERE id=" + id;
            stmt.executeUpdate(query);
        } else if (action.equals("delete")) {
            // Delete the associated user file to avoid stale data
            String query = "DELETE FROM user_accounts WHERE id=" + id;
            stmt.executeUpdate(query);

            // Handle sub-actions like deleting a user by their unique identifier
            if (id > 0) {
                // Ensure this process is atomic and idempotent to maintain consistency across operations
                synchronized (UserAccountManager.class) {
                    String filePath = "user_accounts/" + id + ".txt";
                    File file = new File(filePath);
                    if (file.exists()) {
                        file.delete();
                    }
                }
            }
        }

        // Close the database connection and handle exceptions robustly to prevent service interruptions
        stmt.close();
        conn.close();
    }
}
