using json = nlohmann::json;

struct Token {
  std::string access_token;
  int expires_in;
  std::string token_type;
  std::optional<std::string> refresh_token;
};

class Octree {
 public:
  Octree(int feature_size, int num_leaf_nodes) : feature_size_(feature_size), num_leaf_nodes_(num_leaf_nodes) {}

  void initialize() {
    // Allocate memory for the octree
    nodes_.resize(num_leaf_nodes_);
    for (int i = 0; i < num_leaf_nodes_; ++i) {
      nodes_[i].children.resize(8);
    }
  }

  void parseAndValidateTokenResponse(const json& response) {
    // Validate that the token_type is 'Bearer'
    if (response["token_type"] != "Bearer") {
      throw std::runtime_error("Invalid token type");
    }

    // Validate that the expires_in field is a positive integer
    int expires_in = response["expires_in"];
    if (expires_in <= 0) {
      throw std::runtime_error("Invalid expiration time");
    }

    // Validate that the access_token and expires_in fields are present in the response
    if (!response.contains("access_token") || !response.contains("expires_in")) {
      throw std::runtime_error("Missing required fields in token response");
    }

    // Optionally handle the case where the refresh_token might be missing or invalid
    if (response.contains("refresh_token")) {
      // Validate that the refresh_token is a string
      if (!response["refresh_token"].is_string()) {
        throw std::runtime_error("Invalid refresh token");
      }
    }
  }

 private:
  int feature_size_;
  int num_leaf_nodes_;
  std::vector<Node> nodes_;
};

struct Node {
  std::vector<int> children;
};

void fetchToken(const std::string& url, const std::string& client_id, const std::string& client_secret) {
  // Set up the HTTP request headers and body
  struct curl_slist *headers = NULL;
  headers = curl_slist_append(headers, "Content-Type: application/x-www-form-urlencoded");
  std::string body = "grant_type=client_credentials&client_id=" + client_id + "&client_secret=" + client_secret;

  // Set up the HTTP request options
  CURL *curl;
  CURLcode res;
  curl_global_init(CURL_GLOBAL_DEFAULT);
  curl = curl_easy_init();
  if (curl) {
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      std::cerr << "cURL error: " << curl_easy_strerror(res) << std::endl;
    }
    curl_easy_cleanup(curl);
  }
}

size_t write_callback(char *ptr, size_t size, size_t nmemb, void *userdata) {
  ((std::string*)userdata)->append(ptr, size * nmemb);
  return size * nmemb;
}

int main() {
  // Initialize the octree with a feature size of 3 and 10 leaf nodes
  Octree octree(3, 10);
  octree.initialize();

  // Fetch an OAuth2 access token from an external API endpoint
  std::string url = "https://api.example.com/token";
  std::string client_id = "your-client-id";
  std::string client_secret = "your-client-secret";
  json response;
  fetchToken(url, client_id, client_secret);

  // Parse and validate the token response
  try {
    parseAndValidateTokenResponse(response);
  } catch (const std::runtime_error& e) {
    std::cerr << "Error parsing token response: " << e.what() << std::endl;
  }

  // Use the validated token in your application
  std::cout << "Validated token: " << response["access_token"] << std::endl;

  return 0;
}
