            _maxRetries = maxRetries;
            _retryDelay = retryDelay ?? TimeSpan.FromSeconds(1);
            _connectionPool = new ConnectionPool(_connectionString, _maxRetries, _retryDelay);
        }

        public async Task<DataTableReader> ProcessAsync(byte[] input)
