            var result = default(DataTableReader);
            var retryCount = 0;

            while (true)
            {
                try
                {
                    using (var connection = _connectionPool.GetConnection())
                    {
                        var command = new SqlCommand("SELECT * FROM MyTable WHERE Id IN (@Ids)", connection);
                        command.Parameters.AddWithValue("@Ids", input);
                        result = await command.ExecuteReaderAsync();
                        break;
                    }
                }
                catch (Exception ex) when (retryCount < _maxRetries && IsTransientError(ex))
                {
                    retryCount++;
                    await Task.Delay(_retryDelay);
                }
            }

            return result;
        }

