public static class StringHasher
{
    private const int MaxStringLength = 10_000;
    private const string HashAlgorithmName = "MD5";

    public static async Task<Dictionary<string, string>> GetHashesAsync(IEnumerable<string> strings)
    {
        var hashes = new Dictionary<string, string>();

        foreach (var string in strings)
        {
            if (string == null || string.Length > MaxStringLength)
            {
                throw new ArgumentException("Invalid input string", nameof(strings));
            }

            var hash = await GetHashAsync(string);
            hashes.Add(string, hash);
        }

        return hashes;
    }

    private static async Task<string> GetHashAsync(string input)
    {
        using (var md5 = MD5.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(input);
            var hash = await md5.ComputeHashAsync(bytes);
            return BitConverter.ToString(hash).Replace("-", "").ToLower();
        }
    }
}
```
