using System;
using System.Security.Cryptography;
using System.Text;

public static class AESDecryption
{
    private const int KEY_SIZE = 256; // in bits
    private const int IV_SIZE = 16; // in bytes

    public static string Decrypt(string ciphertext, byte[] key, byte[] iv)
    {
        if (ciphertext == null || key == null || iv == null)
            throw new ArgumentNullException("Invalid input parameters");

        if (key.Length != KEY_SIZE / 8 || iv.Length != IV_SIZE)
            throw new ArgumentException("Key and IV must be of the correct size");

        using (Aes aes = Aes.Create())
        {
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;
            aes.KeySize = KEY_SIZE;
            aes.BlockSize = 128;
            aes.FeedbackSize = 64;
            aes.IV = iv;
            aes.Key = key;

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, aes.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                    {
                        return srDecrypt.ReadToEnd();
                    }
                }
            }
        }
    }
}
```
