function orchestrateCommands(commands) {
  // Initialize variables for tracking command execution status and output
  let commandStatus = [];
  let commandOutput = [];

  // Iterate over each command in the sequence
  commands.forEach((command, index) => {
    // Execute the current command and capture its output
    const output = exec(command);

    // Add the output to the list of outputs for this command
    commandOutput.push(output);

    // Check if the previous command has completed successfully
    if (index > 0 && commandStatus[index - 1] === 'success') {
      // Execute the next command in the sequence
      const nextCommand = commands[index + 1];
      exec(nextCommand);
    }

    // Update the status of the current command to "in progress"
    commandStatus.push('in progress');

    // Implement a timeout mechanism for each command
    setTimeout(() => {
      if (commandStatus[index] === 'in progress') {
        // If the command has not completed, mark it as failed and log an error message
        commandStatus[index] = 'failed';
        console.error(`Command ${index} timed out`);
      }
    }, 10000);
  });

  // Implement a global timeout for the entire sequence
  setTimeout(() => {
    if (commandStatus.every(status => status === 'in progress')) {
      // If all commands have not completed, mark them as failed and log an error message
      commandStatus = ['failed'];
      console.error('Sequence timed out');
    }
  }, 60000);

  // Wait for all commands to complete before returning the final summary report
  while (commandStatus.some(status => status === 'in progress')) {
    await sleep(1000);
  }

  // Generate a final summary report detailing the overall execution outcome
  const summaryReport = {
    commandOutput,
    commandStatus,
    performanceMetrics: {
      processingTime: Date.now() - startTime,
      memoryUsage: process.memoryUsage().heapUsed / 1024 / 1024,
    },
  };
  return summaryReport;
}
```
