package com.distributedgraphdb;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class DistributedGraphDatabase {
    private ConcurrentMap<String, Vertex> vertices = new ConcurrentHashMap<>();
    private ConcurrentMap<String, Edge> edges = new ConcurrentHashMap<>();

    public void addVertex(String id, String label) {
        vertices.putIfAbsent(id, new Vertex(id, label));
    }

    public void addEdge(String sourceId, String targetId, String label) {
        Edge edge = new Edge(sourceId, targetId, label);
        edges.putIfAbsent(edge.getKey(), edge);
    }

    public Vertex getVertex(String id) {
        return vertices.get(id);
    }

    public Edge getEdge(String sourceId, String targetId) {
        return edges.get(new Edge(sourceId, targetId).getKey());
    }

    public void removeVertex(String id) {
        vertices.remove(id);
    }

    public void removeEdge(String sourceId, String targetId) {
        edges.remove(new Edge(sourceId, targetId).getKey());
    }

    private class Vertex {
        private final String id;
        private final String label;

        public Vertex(String id, String label) {
            this.id = id;
            this.label = label;
        }

        public String getId() {
            return id;
        }

        public String getLabel() {
            return label;
        }
    }

    private class Edge {
        private final String sourceId;
        private final String targetId;
        private final String label;

        public Edge(String sourceId, String targetId, String label) {
            this.sourceId = sourceId;
            this.targetId = targetId;
            this.label = label;
        }

        public String getSourceId() {
            return sourceId;
        }

        public String getTargetId() {
            return targetId;
        }

        public String getLabel() {
            return label;
        }

        public String getKey() {
            return sourceId + "-" + targetId;
        }
    }
}
```
