import threading
from typing import Dict, Callable

class UserProfile:
    def __init__(self, user_id: int, name: str, email: str):
        self.user_id = user_id
        self.name = name
        self.email = email

class UserProfileManager:
    def __init__(self):
        self.profiles: Dict[int, UserProfile] = {}
        self.factory_registry: Dict[str, Callable[[], UserProfile]] = {}

    def insert(self, user_id: int, name: str, email: str) -> None:
        profile = UserProfile(user_id, name, email)
        self.profiles[user_id] = profile

    def update(self, user_id: int, name: str, email: str) -> None:
        if user_id in self.profiles:
            self.profiles[user_id].name = name
            self.profiles[user_id].email = email
        else:
            raise ValueError(f"User with ID {user_id} does not exist")

    def retrieve(self, user_id: int) -> UserProfile:
        if user_id in self.profiles:
            return self.profiles[user_id]
        else:
            raise ValueError(f"User with ID {user_id} does not exist")

    def add_factory(self, profile_type: str, factory: Callable[[], UserProfile]) -> None:
        self.factory_registry[profile_type] = factory

    def create_instance(self, profile_type: str) -> UserProfile:
        if profile_type in self.factory_registry:
            return self.factory_registry[profile_type]()
        else:
            raise ValueError(f"Unknown profile type {profile_type}")

# Example usage:
manager = UserProfileManager()
manager.add_factory("basic", lambda: UserProfile(1, "John Doe", "johndoe@example.com"))
manager.add_factory("premium", lambda: UserProfile(2, "Jane Doe", "janedoe@example.com"))

# Insert a new user profile
manager.insert(3, "Bob Smith", "bobsmith@example.com")

# Update an existing user profile
manager.update(1, "Johnny Doe", "johnnydoe@example.com")

# Retrieve a user profile by ID
profile = manager.retrieve(3)
print(profile.name)  # Output: Bob Smith
```
