        if (!strcmp(hostname, cache[i].hostname)) {
            entry = &cache[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // If the hostname is in the cache and the cache has not expired, return the cached IP addresses
    if (entry && time(NULL) < entry->expiration) {
        *ipv4 = entry->ipv4;
        *ipv6 = entry->ipv6;
        return ERROR_SUCCESS;
    }

    // Perform DNS resolution and cache the result
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
