    int status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        return ERROR_DNS_FAILURE;
    }
    struct in_addr* ipv4_ptr = NULL;
    struct in6_addr* ipv6_ptr = NULL;
    for (struct addrinfo* rp = result; rp != NULL; rp = rp->ai_next) {
        if (rp->ai_family == AF_INET) {
            ipv4_ptr = &((struct sockaddr_in*)rp->ai_addr)->sin_addr;
        } else if (rp->ai_family == AF_INET6) {
            ipv6_ptr = &((struct sockaddr_in6*)rp->ai_addr)->sin6_addr;
        }
    }
    freeaddrinfo(result);
    if (!ipv4_ptr && !ipv6_ptr) {
        return ERROR_DNS_FAILURE;
    }
    pthread_mutex_lock(&cache_mutex);
    entry = NULL;
    for (int i = 0; i < sizeof(cache) / sizeof(*cache); ++i) {
