    if (!entry) {
        // If the hostname is not in the cache, add it to the end of the list
        entry = &cache[sizeof(cache) / sizeof(*cache) - 1];
        entry->hostname = strdup(hostname);
        entry->expiration = time(NULL) + CACHE_DURATION;
    } else {
