    if (ipv4_ptr) {
        entry->ipv4 = *ipv4_ptr;
    }
    if (ipv6_ptr) {
        entry->ipv6 = *ipv6_ptr;
    }
    pthread_mutex_unlock(&cache_mutex);
    *ipv4 = entry->ipv4;
    *ipv6 = entry->ipv6;
    return ERROR_SUCCESS;
}

