// Define the encryption and decryption functions
int encrypt_file(const char *input_path, const char *output_path) {
  // Generate a random key for encryption
  unsigned char key[32];
  RAND_bytes(key, sizeof(key));

  // Open the input file and output file
  FILE *input = fopen(input_path, "rb");
  FILE *output = fopen(output_path, "wb");

  // Create a new AES-256 GCM context
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

  // Set the encryption key and IV
  EVP_EncryptInit(ctx, EVP_aes_256_gcm(), key, NULL);

  // Encrypt the input file and write to the output file
  int len;
  unsigned char buffer[4096];
  while ((len = fread(buffer, 1, sizeof(buffer), input)) > 0) {
    EVP_EncryptUpdate(ctx, buffer, &len, buffer, len);
    fwrite(buffer, 1, len, output);
  }

  // Finalize the encryption and write the tag to the output file
  unsigned char tag[16];
  int tag_len = sizeof(tag);
  EVP_EncryptFinal(ctx, buffer, &len);
  fwrite(buffer, 1, len, output);
  EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, tag_len, tag);
  fwrite(tag, 1, tag_len, output);

  // Clean up the encryption context and close the files
  EVP_CIPHER_CTX_free(ctx);
  fclose(input);
  fclose(output);

  return 0;
}

int decrypt_file(const char *input_path, const char *output_path) {
