  FILE *output = fopen(output_path, "wb");

  // Create a new AES-256 GCM context
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

  // Set the decryption key and IV
  EVP_DecryptInit(ctx, EVP_aes_256_gcm(), key, NULL);

  // Read the tag from the input file
  unsigned char tag[16];
  int tag_len = sizeof(tag);
  fread(tag, 1, tag_len, input);

  // Decrypt the input file and write to the output file
  int len;
  unsigned char buffer[4096];
  while ((len = fread(buffer, 1, sizeof(buffer), input)) > 0) {
    EVP_DecryptUpdate(ctx, buffer, &len, buffer, len);
    fwrite(buffer, 1, len, output);
  }

  // Finalize the decryption and check the tag
  int final_len = sizeof(buffer);
  EVP_DecryptFinal(ctx, buffer, &final_len);
  if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, tag_len, tag) != 1) {
    fprintf(stderr, "Invalid tag\n");
    return -1;
  }

  // Clean up the decryption context and close the files
  EVP_CIPHER_CTX_free(ctx);
  fclose(input);
  fclose(output);

  return 0;
}
