// Custom-designed disjoint set data structure for efficient tracking of disjoint pairs
struct DisjointSet {
    int *parent;
    int *rank;
};

// Function to initialize the disjoint set data structure
void initDisjointSet(struct DisjointSet *ds, int size) {
    ds->parent = (int *)malloc(size * sizeof(int));
    ds->rank = (int *)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        ds->parent[i] = i;
        ds->rank[i] = 1;
    }
}

// Function to find the representative element of a disjoint set
int find(struct DisjointSet *ds, int x) {
    if (ds->parent[x] == x) return x;
    else return find(ds, ds->parent[x]);
}

// Function to union two disjoint sets
void union(struct DisjointSet *ds, int x, int y) {
    int rootX = find(ds, x);
    int rootY = find(ds, y);
    if (rootX == rootY) return;
    else if (ds->rank[rootX] > ds->rank[rootY]) {
        ds->parent[rootY] = rootX;
    } else {
        ds->parent[rootX] = rootY;
        if (ds->rank[rootX] == ds->rank[rootY]) ds->rank[rootY]++;
    }
}

// Function to check if two elements are disjoint
int isDisjoint(struct DisjointSet *ds, int x, int y) {
    return find(ds, x) != find(ds, y);
}

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generateList(int n, struct DisjointSet *ds) {
    // Initialize the disjoint set data structure
    initDisjointSet(ds, n);

