        // Check if the RX_UE_INFORMATION_TAG and RNTI are disjoint
        if (isDisjoint(ds, rxUeInformationTag, rnti)) {
            // If they are disjoint, create a new NFAPI_CRC_INDICATION_PDU_T structure with the random values
            struct NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.rxUeInformationTag = rxUeInformationTag;
            pdu.rnti = rnti;
            pdu.crcIndicationRel8Tag.crCFlag = rand() % 2;

            // Add the new structure to the list
            ds->parent[rxUeInformationTag] = rxUeInformationTag;
            ds->rank[rxUeInformationTag] = 1;
        } else {
            // If they are not disjoint, union the two elements in the disjoint set
            union(ds, rxUeInformationTag, rnti);
        }
    }
}

// Function to print the number of milliseconds taken to perform the disjointness check for each pair
