// Function to manage dynamic list of transport channel configurations
NR_TransportChannelConfig* manageTransportChannels(int cellID, int tci, int modulation, int codingScheme) {
    // Check for invalid input parameters
    if (cellID < 0 || tci < 0 || modulation < 0 || codingScheme < 0) {
        return NULL;
    }

