// Define the function to dynamically allocate and initialize an array of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdus(int n, int lower_bound, int upper_bound) {
    // Check if the number of elements is valid
    if (n <= 0) {
        return NULL;
    }

    // Allocate memory for the array of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (crc_indication_pdus == NULL) {
        return NULL;
    }

    // Initialize the pointers to RX UE information and RNTI in each CRC indication PDU
    for (int i = 0; i < n; i++) {
        crc_indication_pdus[i].rx_ue_information = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (crc_indication_pdus[i].rx_ue_information == NULL) {
            free(crc_indication_pdus);
            return NULL;
        }
        crc_indication_pdus[i].rnti = malloc(sizeof(RNTI));
        if (crc_indication_pdus[i].rnti == NULL) {
            free(crc_indication_pdus);
            return NULL;
        }
    }

    // Initialize the fields in each CRC indication PDU
    for (int i = 0; i < n; i++) {
        crc_indication_pdus[i].rx_ue_information->crc_flag = lower_bound + rand() % (upper_bound - lower_bound);
        crc_indication_pdus[i].rnti->value = 0;
    }

    // Verify the integrity of each CRC indication PDU using a checksum algorithm
    for (int i = 0; i < n; i++) {
        uint32_t checksum = calculate_checksum(crc_indication_pdus[i]);
        if (checksum != crc_indication_pdus[i].rx_ue_information->crc_flag) {
            // Log the anomaly to a file named "crc_log.txt"
            FILE *file = fopen("crc_log.txt", "a");
            if (file != NULL) {
                fprintf(file, "Anomaly detected in CRC indication PDU %d: checksum=%u, crc_flag=%u\n", i, checksum, crc_indication_pdus[i].rx_ue_information->crc_flag);
                fclose(file);
            }
        }
    }

    return crc_indication_pdus;
}

// Define the function to calculate the checksum of a CRC indication PDU
uint32_t calculate_checksum(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Calculate the checksum using a simple algorithm
    uint32_t checksum = 0;
    for (int i = 0; i < sizeof(RX_UE_INFORMATION_TAG); i++) {
        checksum += ((uint8_t *)pdu->rx_ue_information)[i];
    }
    return checksum;
}
