static dns_cache_t *dns_cache = NULL;

// Function to resolve a hostname and return its IP address
static int resolve_hostname(char *hostname) {
    struct addrinfo hints, *res;
    int err;

    // Initialize the DNS cache if necessary
    if (!dns_cache) {
        dns_cache = (dns_cache_t *)malloc(sizeof(dns_cache_t) * DNS_CACHE_SIZE);
        memset(dns_cache, 0, sizeof(dns_cache_t) * DNS_CACHE_SIZE);
    }

    // Check if the hostname is already in the cache
    pthread_mutex_lock(&dns_cache_lock);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(hostname, dns_cache[i].hostname) == 0) {
            // If the hostname is in the cache and its TTL has not expired, return it
            if (dns_cache[i].ttl > time(NULL)) {
                pthread_mutex_unlock(&dns_cache_lock);
                return dns_cache[i].addr.s_addr;
            } else {
                // If the hostname is in the cache but its TTL has expired, remove it from the cache
                memset(&dns_cache[i], 0, sizeof(dns_cache_t));
            }
        }
    }
    pthread_mutex_unlock(&dns_cache_lock);

    // If the hostname is not in the cache or its TTL has expired, resolve it and add it to the cache
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if ((err = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1;
    }
    struct in_addr addr = ((struct sockaddr_in *)res->ai_addr)->sin_addr;
    freeaddrinfo(res);

    pthread_mutex_lock(&dns_cache_lock);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (!dns_cache[i].hostname) {
            dns_cache[i].hostname = strdup(hostname);
            dns_cache[i].addr.s_addr = addr.s_addr;
            dns_cache[i].ttl = time(NULL) + DNS_CACHE_TIMEOUT;
            break;
        }
    }
    pthread_mutex_unlock(&dns_cache_lock);

    return addr.s_addr;
}

