#include <forward_list>
#include <string>
#include <random>
#include <algorithm>

void populateAndModifyApiList(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& apiList, const std::string& targetRnti, const std::string& crcIndicationValue, int n) {
    // Check if the list is empty or contains duplicate RNTIs
    if (apiList.empty() || std::any_of(apiList.begin(), apiList.end(), [](const NFAPI_CRC_INDICATION_PDU_T& pdu) { return pdu.RX_UE_INFORMATION_TAG.RNTI == targetRnti; })) {
        // If the list is empty or contains duplicate RNTIs, append the CRC indication value to the end of the list
        apiList.push_back({{}, {}, crcIndicationValue});
    } else {
        // If the target RNTI is present in the list, insert the CRC indication value immediately after this RNTI
        auto it = std::find(apiList.begin(), apiList.end(), [&](const NFAPI_CRC_INDICATION_PDU_T& pdu) { return pdu.RX_UE_INFORMATION_TAG.RNTI == targetRnti; });
        if (it != apiList.end()) {
            ++it;
            apiList.insert(it, {{}, {}, crcIndicationValue});
        } else {
            // If the target RNTI is not present in the list, append the CRC indication value to the end of the list
            apiList.push_back({{}, {}, crcIndicationValue});
        }
    }

    // Randomize the CRCFLAG in each CRC_INDICATION_REL8_TAG
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<uint8_t> dist(0, 255);
    for (auto& pdu : apiList) {
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = dist(gen);
    }

    // Ensure that the list size is no more than N elements
    if (apiList.size() > n) {
        apiList.resize(n);
    }
}
