        return;
    }
    pthread_mutex_lock(&mutex);
    while (!pthread_cond_wait(&cond, &mutex)) {}
    pthread_mutex_unlock(&mutex);
    pthread_join(thread, NULL);

    // Optimize the function for efficient memory usage while ensuring that the list of structures can grow dynamically to accommodate up to 10,000 entries
    int numEntries = 0;
    NFAPI_CRC_INDICATION_PDU_T *currentEntry = list;
    while (currentEntry != NULL) {
        currentEntry = currentEntry->next;
        numEntries++;
    }
    if (numEntries > 10000) {
        printf("Error: The number of entries in the list exceeds the maximum allowed value of 10,000\n");
        return;
    }
