// Define the structure for the packet buffer
typedef struct {
    PACKET_INFO info;
    SEQ_NUM seq_num;
    TX_POWER_LEVEL power_level;
} TX_PACKET_BUFFER;

// Define a mutex to protect the shared resource
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and initialize a list of packet buffers
TX_PACKET_BUFFER* allocate_packet_buffers(size_t n) {
    // Check if the requested number of buffers exceeds available resources
    if (n > MAX_NUM_BUFFERS) {
        // Reduce the number of buffers to avoid memory leaks and potential errors
        n = MAX_NUM_BUFFERS;
    }

    // Lock the mutex to protect the shared resource
    pthread_mutex_lock(&buffer_mutex);

    // Allocate memory for the packet buffers
    TX_PACKET_BUFFER* buffers = (TX_PACKET_BUFFER*)malloc(n * sizeof(TX_PACKET_BUFFER));
    if (!buffers) {
        // Handle error condition
        pthread_mutex_unlock(&buffer_mutex);
        return NULL;
    }

    // Initialize the packet buffers
    for (size_t i = 0; i < n; i++) {
        buffers[i].info.seq_num = i + 1;
        buffers[i].power_level = TX_POWER_LEVEL_MAX;
    }

    // Unlock the mutex to release the shared resource
    pthread_mutex_unlock(&buffer_mutex);

    return buffers;
}
