        configs[i].cell_id = -1;
        configs[i].num_channels = 0;
        memset(configs[i].channels, 0, sizeof(configs[i].channels));
    }

    // Validate the configuration parameters and handle edge cases
    for (int i = 0; i < num_cells; i++) {
        if (configs[i].num_channels > 10) {
            printf("Error: Too many channels specified for cell %d\n", configs[i].cell_id);
