        }
        for (int j = 0; j < configs[i].num_channels - 1; j++) {
            if (configs[i].channels[j] == configs[i].channels[j + 1]) {
                printf("Error: Overlapping channels specified for cell %d\n", configs[i].cell_id);
                return NULL;
            }
        }
    }

    // Return the initialized array of LTE PHY RX configurations
    return configs;
}

