        fclose(file);
        return NULL;
    }

    // Read the file into the state object
    size_t bytes_read = fread(state_object, 1, file_size, file);
    if (bytes_read != file_size) {
        printf("Error: unable to read entire file\n");
        free(state_object);
        fclose(file);
        return NULL;
    }

    // Close the file
    fclose(file);

    return state_object;
}
