typedef struct {
    int size;
    int capacity;
    Item* items;
} Bundle;

// Define a function to load the configuration resource bundle from a file
int load_bundle(const char* path, Bundle* bundle) {
    // Open the file and read its contents into a buffer
    FILE* fp = fopen(path, "r");
    if (fp == NULL) {
        return -1;
    }
    fseek(fp, 0, SEEK_END);
    long len = ftell(fp);
    rewind(fp);
    char* buffer = malloc(len + 1);
    if (buffer == NULL) {
        return -2;
    }
    fread(buffer, 1, len, fp);
    buffer[len] = '\0';
    fclose(fp);

    // Parse the contents of the file into a bundle
    int num_items = 0;
    char* line = strtok(buffer, "\n");
    while (line != NULL) {
        char* key = strtok(line, "=");
        char* value = strtok(NULL, "=");
        if (key == NULL || value == NULL) {
            continue;
        }
        Item item = {.key = key, .value = value};
        bundle->items[bundle->size++] = item;
        num_items++;
        line = strtok(NULL, "\n");
    }

    // Clean up the buffer and return the number of items in the bundle
    free(buffer);
    return num_items;
}

