```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the MAC Entity Context structure
typedef struct {
    uint32_t macEntityId;
    ListOfActiveBWPs listOfActiveBWPs;
    configStatus configStatus;
} MAC_EC_T;

// Define a dynamic array to store the MAC Entity Context structures
MAC_EC_T *macEcArray = NULL;
size_t macEcArraySize = 0;
pthread_mutex_t macEcMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new MAC Entity Context structure to the array
void addMacEntityContext(uint32_t macEntityId, ListOfActiveBWPs listOfActiveBWPs, configStatus configStatus) {
    // Lock the mutex to prevent concurrent access to the array
    pthread_mutex_lock(&macEcMutex);

    // Check if the array needs to be resized
    if (macEcArraySize == 0 || macEcArraySize == macEcArray->size) {
        // Resize the array by a factor of 2
        size_t newSize = macEcArraySize * 2;
        MAC_EC_T *newMacEcArray = realloc(macEcArray, newSize);
        if (newMacEcArray == NULL) {
            // Handle the error by returning early
            pthread_mutex_unlock(&macEcMutex);
            return;
        }
        macEcArray = newMacEcArray;
        macEcArraySize = newSize;
    }

    // Add the new MAC Entity Context structure to the array
    macEcArray[macEcArraySize].macEntityId = macEntityId;
    macEcArray[macEcArraySize].listOfActiveBWPs = listOfActiveBWPs;
    macEcArray[macEcArraySize].configStatus = configStatus;
    macEcArraySize++;

    // Unlock the mutex
    pthread_mutex_unlock(&macEcMutex);
}

// Function to remove a MAC Entity Context structure from the array
void removeMacEntityContext(uint32_t macEntityId) {
    // Lock the mutex to prevent concurrent access to the array
    pthread_mutex_lock(&macEcMutex);

    // Find the index of the MAC Entity Context structure with the given ID
    size_t i;
    for (i = 0; i < macEcArraySize; i++) {
        if (macEcArray[i].macEntityId == macEntityId) {
            break;
        }
    }

    // Check if the MAC Entity Context structure was found
    if (i == macEcArraySize) {
        // Handle the error by returning early
        pthread_mutex_unlock(&macEcMutex);
        return;
    }

    // Remove the MAC Entity Context structure from the array
    for (size_t j = i + 1; j < macEcArraySize; j++) {
        macEcArray[j - 1] = macEcArray[j];
    }
    macEcArraySize--;

    // Unlock the mutex
    pthread_mutex_unlock(&macEcMutex);
}

// Function to iterate over all MAC Entity Context structures in the array
void iterateMacEntityContexts(void (*callback)(MAC_EC_T *)) {
    // Lock the mutex to prevent concurrent access to the array
    pthread_mutex_lock(&macEcMutex);

    // Iterate over all MAC Entity Context structures in the array
    for (size_t i = 0; i < macEcArraySize; i++) {
        callback(&macEcArray[i]);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&macEcMutex);
}
