#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Define the structure to hold UE information
typedef struct {
    uint16_t rnti; // RNTI (Radio Network Temporary Identifier)
    uint8_t crc[4]; // CRC (Cyclic Redundancy Check)
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list to hold the UE information
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data; // Pointer to the data structure
    struct Node *next; // Pointer to the next node in the list
} LinkedListNode;

// Function to construct and populate a linked list of UE information
void constructLinkedList(NFAPI_CRC_INDICATION_PDU_T **list, uint16_t numUEs) {
    // Initialize the head node of the linked list
    LinkedListNode *head = malloc(sizeof(LinkedListNode));
    head->data = NULL;
    head->next = NULL;

    // Iterate through each UE and add it to the linked list
    for (uint16_t i = 0; i < numUEs; i++) {
        NFAPI_CRC_INDICATION_PDU_T *ueInfo = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ueInfo->rnti = i + 1; // Set the RNTI to a unique value for each UE
        memset(ueInfo->crc, 0, sizeof(ueInfo->crc)); // Initialize the CRC field

        // Add the UE information to the linked list
        LinkedListNode *node = malloc(sizeof(LinkedListNode));
        node->data = ueInfo;
        node->next = head->next;
        head->next = node;
    }
}

// Function to process a single packet and add it to the linked list
void processPacket(NFAPI_CRC_INDICATION_PDU_T **list, uint8_t *packetData) {
    // Extract the RNTI from the packet data
    uint16_t rnti = (packetData[0] << 8) | packetData[1];

    // Find the node in the linked list that corresponds to the RNTI
    LinkedListNode *node = head;
    while (node != NULL && node->data->rnti != rnti) {
        node = node->next;
    }

    // If the node was found, update its CRC field with the packet data
    if (node != NULL) {
        memcpy(node->data->crc, packetData + 2, sizeof(node->data->crc));
    } else {
