// Define a function to initialize and populate the network node and its bearers
void init_network_node(NetworkNode *node, int num_bearers) {
    assert(node != NULL);
    assert(num_bearers > 0);

    // Allocate memory for the bearer configurations
    node->bearers = (RadioBearerConfig *)malloc(sizeof(RadioBearerConfig) * num_bearers);
    if (node->bearers == NULL) {
        printf("Failed to allocate memory for bearer configurations\n");
        return;
    }

    // Initialize the node identifier and number of bearers
    node->id = 0;
    node->num_bearers = num_bearers;

    // Populate the bearer configurations with necessary parameters
    for (int i = 0; i < num_bearers; i++) {
        node->bearers[i].id = i + 1;
        node->bearers[i].priority = i + 1;
        // Other fields...
    }
}

// Define a function to validate the network node and bearer configurations
void validate_network_node(NetworkNode *node) {
    assert(node != NULL);

    // Validate the node identifier and number of bearers
    if (node->id < 0 || node->num_bearers <= 0) {
        printf("Invalid network node configuration\n");
        return;
    }

    // Validate each bearer configuration
    for (int i = 0; i < node->num_bearers; i++) {
        if (node->bearers[i].id <= 0 || node->bearers[i].priority <= 0) {
            printf("Invalid radio bearer configuration\n");
            return;
        }
    }
}

// Define a function to log detailed information about each node and bearer setup
void log_network_node(NetworkNode *node) {
    assert(node != NULL);

    // Log the node identifier and number of bearers
    printf("Node ID: %d, Number of Bearers: %d\n", node->id, node->num_bearers);

    // Log each bearer configuration
    for (int i = 0; i < node->num_bearers; i++) {
        printf("Bearer ID: %d, Priority: %d\n", node->bearers[i].id, node->bearers[i].priority);
    }
}
