// Initialize the memory pool at program startup with a fixed capacity
MemoryPool mempool = {NULL, 10000}; // 10,000 structures can be allocated in total

// Define a sorting function that sorts an array of NFAPI_CRC_INDICATION_PDU_T structures based on RNTI values in ascending order
void sort_structures(NFAPI_CRC_INDICATION_PDU_T* structures, size_t n) {
    // Check if the input is valid and allocate memory for the sorted array
    assert(n > 0 && n <= mempool.size);
    NFAPI_CRC_INDICATION_PDU_T* sorted = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!sorted) {
        fprintf(stderr, "Error: Failed to allocate memory for the sorted array\n");
        return;
    }

    // Sort the structures based on RNTI values in ascending order
    size_t i, j;
    for (i = 0; i < n; i++) {
        for (j = i + 1; j < n; j++) {
            if (structures[i].RNTI > structures[j].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = structures[i];
                structures[i] = structures[j];
                structures[j] = temp;
            }
        }
    }

    // Print the sorted list to the console
    for (i = 0; i < n; i++) {
        printf("RNTI: %d, CRCFLAG: %d\n", structures[i].RNTI, structures[i].CRCFLAG);
    }

    // Free the sorted array and return
    free(sorted);
}

// Define a function to allocate memory for an NFAPI_CRC_INDICATION_PDU_T structure in the custom memory pool
NFAPI_CRC_INDICATION_PDU_T* alloc_structure() {
    // Check if there is enough capacity in the memory pool
    if (mempool.size == 0) {
        fprintf(stderr, "Error: Memory pool is full\n");
        return NULL;
    }

    // Allocate a new structure from the memory pool and update its size
    NFAPI_CRC_INDICATION_PDU_T* structure = mempool.data;
    mempool.data += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    mempool.size--;

    // Initialize the structure with random values for RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    structure->RX_UE_INFORMATION_TAG = rand() % 10000;
    structure->RNTI = rand() % 65536;
    structure->CRCFLAG = rand() % 2;

    return structure;
}

// Define a function to free memory for an NFAPI_CRC_INDICATION_PDU_T structure in the custom memory pool
void free_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    // Check if the input is valid and update the memory pool size
    assert(structure != NULL);
    mempool.size++;

    // Free the structure from the memory pool
    free(structure);
}

int main() {
