// Define the structure for holding UE information
typedef struct {
    uint16_t rnti;
    uint8_t payload[20];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the queue data structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t front, rear;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} queue_t;

// Initialize the queue with a fixed capacity
void init_queue(queue_t *q) {
    q->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 50000);
    q->capacity = 50000;
    q->front = q->rear = 0;
    pthread_mutex_init(&q->mutex, NULL);
    semaphore_init(&q->semaphore, 0, 1);
}

// Enqueue a new element to the queue
void enqueue(queue_t *q, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&q->mutex);
    while (q->rear == q->capacity) {
        semaphore_wait(&q->semaphore);
    }
    memcpy(q->data + q->rear, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->rear = (q->rear + 1) % q->capacity;
    semaphore_post(&q->semaphore);
    pthread_mutex_unlock(&q->mutex);
}

// Dequeue an element from the queue
NFAPI_CRC_INDICATION_PDU_T *dequeue(queue_t *q) {
    NFAPI_CRC_INDICATION_PDU_T *data = NULL;
    pthread_mutex_lock(&q->mutex);
    while (q->front == q->rear) {
        semaphore_wait(&q->semaphore);
    }
    data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(data, q->data + q->front, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->front = (q->front + 1) % q->capacity;
    semaphore_post(&q->semaphore);
    pthread_mutex_unlock(&q->mutex);
    return data;
}

// Free the queue resources
void free_queue(queue_t *q) {
    pthread_mutex_destroy(&q->mutex);
    semaphore_destroy(&q->semaphore);
    free(q->data);
}
