// Define function to initialize and manage dynamic array of LTE PHY RX configurations
void init_rx_config(int num_cells, int max_channels) {
    // Allocate memory for the dynamic array
    LTE_PHY_RX_CONFIG_T *rx_config = (LTE_PHY_RX_CONFIG_T *)malloc(num_cells * sizeof(LTE_PHY_RX_CONFIG_T));

    // Initialize each structure in the array with default values
    for (int i = 0; i < num_cells; i++) {
        rx_config[i].cell_id = -1;
        rx_config[i].rx_ue_information_tag = -1;
        rx_config[i].rnti = -1;
        rx_config[i].crc_indication_rel8_tag = -1;
        rx_config[i].crcflag = -1;
    }

    // Dynamically allocate memory for each cell's uplink channel array
    for (int i = 0; i < num_cells; i++) {
        rx_config[i].uplink_channel = (int *)malloc(max_channels * sizeof(int));
    }

    // Initialize each cell's uplink channel array with default values
    for (int i = 0; i < num_cells; i++) {
        for (int j = 0; j < max_channels; j++) {
            rx_config[i].uplink_channel[j] = -1;
        }
    }
}

