    // Check if the specified cell ID is valid
    if (cell_id < 0 || cell_id >= num_cells) {
        printf("Invalid cell ID: %d\n", cell_id);
        return;
    }

    // Check if the specified uplink channel is valid
    if (uplink_channel < 0 || uplink_channel >= max_channels) {
        printf("Invalid uplink channel: %d\n", uplink_channel);
        return;
    }

    // Update the RX configuration for the specified cell
    rx_config[cell_id].uplink_channel[uplink_channel] = 1;
}

