// Define the structure for an LTE UE context
typedef struct {
    int ue_id;
    char *active_s1_mme_associations;
    time_t last_update;
} lte_ue_context_t;

// Define a dynamic list of LTE UE contexts
lte_ue_context_t **lte_ue_contexts = NULL;
size_t num_lte_ue_contexts = 0;
pthread_mutex_t lte_ue_contexts_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new LTE UE context
void add_lte_ue_context(int ue_id, char *active_s1_mme_associations) {
    // Lock the mutex to prevent concurrent access to the list of LTE UE contexts
    pthread_mutex_lock(&lte_ue_contexts_lock);

    // Allocate memory for the new LTE UE context
    lte_ue_context_t *new_context = malloc(sizeof(lte_ue_context_t));
    if (new_context == NULL) {
        perror("malloc");
        exit(1);
    }

    // Initialize the new LTE UE context
    new_context->ue_id = ue_id;
    new_context->active_s1_mme_associations = active_s1_mme_associations;
    new_context->last_update = time(NULL);

    // Add the new LTE UE context to the list of LTE UE contexts
    lte_ue_contexts = realloc(lte_ue_contexts, (num_lte_ue_contexts + 1) * sizeof(lte_ue_context_t *));
    if (lte_ue_contexts == NULL) {
        perror("realloc");
        exit(1);
    }
    lte_ue_contexts[num_lte_ue_contexts] = new_context;
    num_lte_ue_contexts++;

    // Unlock the mutex
    pthread_mutex_unlock(&lte_ue_contexts_lock);
}

// Function to update an existing LTE UE context's associations
void update_lte_ue_context(int ue_id, char *active_s1_mme_associations) {
    // Lock the mutex to prevent concurrent access to the list of LTE UE contexts
    pthread_mutex_lock(&lte_ue_contexts_lock);

    // Find the LTE UE context with the specified UE ID
    int i;
    for (i = 0; i < num_lte_ue_contexts; i++) {
        if (lte_ue_contexts[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the LTE UE context was found, update its associations and timestamp
    if (i < num_lte_ue_contexts) {
        free(lte_ue_contexts[i]->active_s1_mme_associations);
        lte_ue_contexts[i]->active_s1_mme_associations = active_s1_mme_associations;
        lte_ue_contexts[i]->last_update = time(NULL);
    } else {
        // If the LTE UE context was not found, add a new one
        add_lte_ue_context(ue_id, active_s1_mme_associations);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lte_ue_contexts_lock);
}

// Function to remove a LTE UE context based on its UE ID
void remove_lte_ue_context(int ue_id) {
    // Lock the mutex to prevent concurrent access to the list of LTE UE contexts
    pthread_mutex_lock(&lte_ue_contexts_lock);

    // Find the LTE UE context with the specified UE ID
    int i;
    for (i = 0; i < num_lte_ue_contexts; i++) {
        if (lte_ue_contexts[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the LTE UE context was found, remove it from the list of LTE UE contexts
    if (i < num_lte_ue_contexts) {
        free(lte_ue_contexts[i]->active_s1_mme_associations);
        free(lte_ue_contexts[i]);
        lte_ue_contexts = realloc(lte_ue_contexts, (num_lte_ue_contexts - 1) * sizeof(lte_ue_context_t *));
        if (lte_ue_contexts == NULL) {
            perror("realloc");
            exit(1);
        }
        num_lte_ue_contexts--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lte_ue_contexts_lock);
}

