// Define the structure to store the data
typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

// Define the linked list head structure
typedef struct LinkedListHead {
    LinkedListNode* first;
    LinkedListNode* last;
    size_t count;
    pthread_mutex_t mutex;
} LinkedListHead;

// Define the cleanup mechanism for the linked list
void cleanupLinkedList(LinkedListHead* head, size_t M) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&head->mutex);

    // Remove the oldest entries first to minimize the risk of retaining outdated data
    while (head->count > M) {
        LinkedListNode* node = head->first;
        head->first = node->next;
        free(node);
        head->count--;
    }

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&head->mutex);
}

// Define the memory pressure monitoring system
void monitorMemoryPressure() {
    // Check if the memory usage exceeds the predefined threshold
    if (getMemoryUsage() > MEMORY_THRESHOLD) {
        // Trigger additional cleanup of the linked list
        cleanupLinkedList(head, M);
    }
}

// Define the function to manage the dynamically resizable and thread-safe linked list
void manageLinkedList(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&head->mutex);

    // Insert a new node into the linked list
    LinkedListNode* node = malloc(sizeof(LinkedListNode));
    node->data = *data;
    node->next = NULL;

    if (head->first == NULL) {
        head->first = node;
        head->last = node;
    } else {
        head->last->next = node;
        head->last = node;
    }

    head->count++;

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&head->mutex);
}

// Define the function to adjust the value of M at runtime
void adjustM(size_t new_value) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&head->mutex);

    // Update the value of M
    head->M = new_value;

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&head->mutex);
}
