void generateNFADeviceStatusReports() {
    // Declare variables
    std::vector<NFAPI_DEVICE_STATUS_PDU_T> deviceStatusList;
    int bufferSize = 0;
    float averageRSSI = 0.0f;

    // Loop indefinitely to generate and populate the list of NFAPI_DEVICE_STATUS_PDU_T structures
    while (true) {
        // Try to retrieve data from the external sensor API
        try {
            // Get the current RSSI measurement from the sensor service
            float rssi = getRSSI();

            // Create a new NFAPI_DEVICE_STATUS_PDU_T structure and populate it with the retrieved data
            NFAPI_DEVICE_STATUS_PDU_T deviceStatus;
            deviceStatus.deviceId = getDeviceId();
            deviceStatus.txPowerLevel = getTXPowerLevel();
            deviceStatus.rssi = rssi;

            // Add the structure to the list of device statuses
            deviceStatusList.push_back(deviceStatus);

            // Increment the buffer size and calculate the average RSSI value over the last 10 measurements
            bufferSize++;
            averageRSSI = (averageRSSI * 9 + rssi) / 10;
        } catch (const std::exception& e) {
            // If there is an error retrieving data from the sensor service, log it and continue
            std::cout << "Error retrieving data from sensor service: " << e.what() << std::endl;
            continue;
        }

        // Sleep for 1 second to simulate network latency
        std::this_thread::sleep_for(std::chrono::seconds(1));

        // Check if the cooldown period has elapsed and flush the buffer if necessary
        if (bufferSize > 0 && (std::chrono::steady_clock::now() - lastFlushTime) >= std::chrono::seconds(15)) {
            // Log the buffer size and average RSSI value to the console every 5 seconds
            if ((std::chrono::steady_clock::now() - lastLogTime) >= std::chrono::seconds(5)) {
                std::cout << "Buffer size: " << bufferSize << ", Average RSSI: " << averageRSSI << std::endl;
                lastLogTime = std::chrono::steady_clock::now();
            }

            // Flush the buffer and reset the cooldown period
            flushBuffer(deviceStatusList);
            bufferSize = 0;
            averageRSSI = 0.0f;
            lastFlushTime = std::chrono::steady_clock::now();
        }
    }
}
