// Define a struct to represent a user session event
typedef struct {
    int session_id;
    char* user_agent;
    char* requested_url;
    char* http_method;
    int response_status_code;
    double request_duration;
} SessionEvent;

// Define a hash table to store the session events
typedef struct {
    int size;
    int count;
    SessionEvent** events;
} SessionHashTable;

// Initialize a new session hash table with a given size
SessionHashTable* init_session_hash_table(int size) {
    SessionHashTable* table = malloc(sizeof(SessionHashTable));
    assert(table != NULL);

    table->size = size;
    table->count = 0;
    table->events = calloc(size, sizeof(SessionEvent*));
    assert(table->events != NULL);

    return table;
}

// Add a new session event to the hash table
void add_session_event(SessionHashTable* table, SessionEvent* event) {
    int index = event->session_id % table->size;
    if (table->events[index] == NULL) {
        table->count++;
    }
    table->events[index] = event;
}

// Update an existing session event in the hash table
void update_session_event(SessionHashTable* table, SessionEvent* event) {
    int index = event->session_id % table->size;
    if (table->events[index] != NULL && table->events[index]->session_id == event->session_id) {
        free(table->events[index]);
        table->count--;
    }
    add_session_event(table, event);
}

// Search for session events based on specific criteria
SessionEvent* search_session_events(SessionHashTable* table, int user_agent_type, char* http_method, int response_status_code) {
    SessionEvent* result = NULL;
    for (int i = 0; i < table->size; i++) {
        if (table->events[i] != NULL && table->events[i]->user_agent == user_agent_type && table->events[i]->http_method == http_method && table->events[i]->response_status_code == response_status_code) {
            result = table->events[i];
        }
    }
    return result;
}

// Free the memory allocated for a session hash table
void free_session_hash_table(SessionHashTable* table) {
    for (int i = 0; i < table->size; i++) {
        if (table->events[i] != NULL) {
            free(table->events[i]);
        }
    }
    free(table);
}
