typedef struct {
    long offset;
    int key;
} Record;

// Function to dynamically allocate memory for a collection of records under resource-constrained conditions
Record* createRecords(int numOffsets, int numKeys, Record** existingRecords) {
    // Check if the input parameters are valid
    if (numOffsets < 0 || numKeys < 0) {
        return NULL;
    }

    // Allocate memory for an array of long integers named offsets with a size determined by numOffsets
    long* offsets = malloc(sizeof(long) * numOffsets);
    if (offsets == NULL) {
        return NULL;
    }

    // Initialize the offsets array with sequential values starting from 0
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = i * sizeof(long);
    }

    // Allocate memory for an array of int integers named keys with a size determined by numKeys
    int* keys = malloc(sizeof(int) * numKeys);
    if (keys == NULL) {
        free(offsets);
        return NULL;
    }

    // Populate the keys array with unique random values within the range of 0 to 1000
    srand(time(NULL));
    for (int i = 0; i < numKeys; i++) {
        int key = rand() % 1000;
        while (keyExists(existingRecords, key)) {
            key = rand() % 1000;
        }
        keys[i] = key;
    }

    // Allocate memory for an array of record structures, where each record contains a long integer from the offsets array and an int integer from the keys array
    Record* records = malloc(sizeof(Record) * (numOffsets < numKeys ? numOffsets : numKeys));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the records array with the offsets and keys arrays
    for (int i = 0; i < (numOffsets < numKeys ? numOffsets : numKeys); i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Free the memory allocated for the offsets and keys arrays
    free(offsets);
    free(keys);

    return records;
}

// Function to check if a key exists in an array of records
int keyExists(Record** existingRecords, int key) {
    // Check if the input parameters are valid
    if (existingRecords == NULL || key < 0) {
        return 0;
    }

    // Iterate through the existing records and check if any of them have the same key as the input key
    for (int i = 0; i < numRecords(existingRecords); i++) {
        if (existingRecords[i]->key == key) {
            return 1;
        }
    }

    // If no record with the same key is found, return 0
    return 0;
}

// Function to get the number of records in an array of records
int numRecords(Record** existingRecords) {
    // Check if the input parameter is valid
    if (existingRecords == NULL) {
        return -1;
    }

    // Return the number of records in the existingRecords array
    return sizeof(existingRecords) / sizeof(Record*);
}
