// Function to initialize a dynamically allocated array of LTE_RRC_UECONTEXT_T structures
int init_uecontext_array(LTE_RRC_UECONTEXT_T **uecontext_array, int num_ues) {
    // Check if the number of UEs exceeds the maximum size of the array
    if (num_ues > MAX_ARRAY_SIZE) {
        printf("Error: Number of UEs exceeds maximum size of the array\n");
        return -1;
    }

    // Allocate memory for the array of LTE_RRC_UECONTEXT_T structures
    *uecontext_array = (LTE_RRC_UECONTEXT_T *)malloc(num_ues * sizeof(LTE_RRC_UECONTEXT_T));
    if (*uecontext_array == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    // Initialize each structure in the array with a valid UE ID, RRC state, and empty list of LTE_RRC_MSG_T objects
    for (int i = 0; i < num_ues; i++) {
        (*uecontext_array)[i].UE_ID = i + 1;
        (*uecontext_array)[i].RRC_STATE = 0;
        (*uecontext_array)[i].LTE_RRC_MSG_T = NULL;
    }

    return 0;
}

// Function to populate the list of LTE_RRC_MSG_T objects for each UE in the array
int populate_msg_list(LTE_RRC_UECONTEXT_T *uecontext, int num_msgs) {
