        printf("Error: Number of messages exceeds maximum size of the list\n");
        return -1;
    }

    // Allocate memory for the list of LTE_RRC_MSG_T objects
    uecontext->LTE_RRC_MSG_T = (List *)malloc(num_msgs * sizeof(LTE_RRC_MSG_T));
    if (uecontext->LTE_RRC_MSG_T == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    // Populate the list with a mix of CHANNEL_REQUEST, RECONFIGURATION, and SOME_OTHER_MESSAGE types
    for (int i = 0; i < num_msgs; i++) {
