        uecontext->LTE_RRC_MSG_T[i].timestamp = time(NULL);
        if (i % 3 == 0) {
            strcpy(uecontext->LTE_RRC_MSG_T[i].message_type, "CHANNEL_REQUEST");
        } else if (i % 3 == 1) {
