void createAndPopulateList(vector<NFAPI_CRC_INDICATION_PDU_T>& list, int numStructures) {
    for (int i = 0; i < numStructures; i++) {
        NFAPI_CRC_INDICATION_PDU_T structure;
        structure.RX_UE_INFORMATION_TAG = rand() % 65536;
