// Define the structure for LTE_NAS_Message
typedef struct {
    int id;
    char* data;
} LTE_NAS_Message;

// Define the dynamic array of LTE_NAS_Message structures
struct DynamicArray {
    LTE_NAS_Message** elements;
    size_t capacity;
    size_t size;
};

// Function to create a new dynamic array
struct DynamicArray* createDynamicArray() {
    struct DynamicArray* arr = malloc(sizeof(struct DynamicArray));
    if (arr == NULL) {
        return NULL;
    }
    arr->elements = malloc(sizeof(LTE_NAS_Message*) * 10);
    if (arr->elements == NULL) {
        free(arr);
        return NULL;
    }
    arr->capacity = 10;
    arr->size = 0;
    return arr;
}

// Function to add a new element to the dynamic array
int addElement(struct DynamicArray* arr, LTE_NAS_Message* elem) {
    if (arr == NULL || elem == NULL) {
        return -1;
    }
    // Check if the array is full and needs to be resized
    if (arr->size >= arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        LTE_NAS_Message** newElements = realloc(arr->elements, sizeof(LTE_NAS_Message*) * newCapacity);
        if (newElements == NULL) {
            return -1;
        }
        arr->elements = newElements;
        arr->capacity = newCapacity;
    }
    // Add the element to the array
    arr->elements[arr->size++] = elem;
    return 0;
}

// Function to remove an element from the dynamic array
int removeElement(struct DynamicArray* arr, int index) {
    if (arr == NULL || index < 0 || index >= arr->size) {
        return -1;
    }
    // Shift all elements after the removed element to the left
    for (int i = index + 1; i < arr->size; i++) {
        arr->elements[i - 1] = arr->elements[i];
    }
    // Decrease the size of the array
    arr->size--;
    return 0;
}

// Function to update an element in the dynamic array
int updateElement(struct DynamicArray* arr, int index, LTE_NAS_Message* elem) {
    if (arr == NULL || index < 0 || index >= arr->size || elem == NULL) {
        return -1;
    }
    // Update the element at the specified index
    arr->elements[index] = elem;
    return 0;
}

// Function to get an element from the dynamic array
LTE_NAS_Message* getElement(struct DynamicArray* arr, int index) {
    if (arr == NULL || index < 0 || index >= arr->size) {
        return NULL;
    }
    // Return the element at the specified index
    return arr->elements[index];
}

// Function to destroy a dynamic array
void destroyDynamicArray(struct DynamicArray* arr) {
    if (arr == NULL) {
        return;
    }
    for (int i = 0; i < arr->size; i++) {
        free(arr->elements[i]);
    }
    free(arr->elements);
    free(arr);
}
