        (*list)[i].port = rand() % 65536;
        (*list)[i].server_socket = -1;

        // Add the current element to the Union-Find data structure
        uf[i].parent = i;
        uf[i].rank = 0;
    }

    // Iterate over each element in the list and check for disjoint pairs
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (!strcmp((*list)[i].client_ip, (*list)[j].client_ip) && (*list)[i].port == (*list)[j].port) {
