// Define the structure for NetworkConnectionEvent
typedef struct {
    uint64_t device_identifier;
    uint64_t timestamp;
    bool connection_status;
} NetworkConnectionEvent;

// Define a dynamic array to store the events
struct EventArray {
    size_t capacity;
    size_t count;
    NetworkConnectionEvent* events;
};

// Define a lock for synchronizing access to the event array
pthread_mutex_t event_array_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the event array with a given capacity
void init_event_array(struct EventArray* arr, size_t capacity) {
    arr->capacity = capacity;
    arr->count = 0;
    arr->events = (NetworkConnectionEvent*)malloc(sizeof(NetworkConnectionEvent) * capacity);
}

// Add a new event to the event array
void add_event(struct EventArray* arr, NetworkConnectionEvent event) {
    pthread_mutex_lock(&event_array_lock);
    if (arr->count == arr->capacity) {
        // Resize the array if it's full
        size_t new_capacity = arr->capacity * 2;
        NetworkConnectionEvent* new_events = (NetworkConnectionEvent*)realloc(arr->events, sizeof(NetworkConnectionEvent) * new_capacity);
        if (!new_events) {
            // Reallocation failed, abort
            pthread_mutex_unlock(&event_array_lock);
            return;
        }
        arr->events = new_events;
        arr->capacity = new_capacity;
    }
    arr->events[arr->count++] = event;
    pthread_mutex_unlock(&event_array_lock);
}

// Retrieve the latest event based on timestamp
NetworkConnectionEvent get_latest_event(struct EventArray* arr) {
    NetworkConnectionEvent latest_event = {0};
    if (arr->count == 0) {
        return latest_event;
    }
    pthread_mutex_lock(&event_array_lock);
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->events[i].timestamp > latest_event.timestamp) {
            latest_event = arr->events[i];
        }
    }
    pthread_mutex_unlock(&event_array_lock);
    return latest_event;
}

// Clear all events in the event array
void clear_all_events(struct EventArray* arr) {
    pthread_mutex_lock(&event_array_lock);
    arr->count = 0;
    pthread_mutex_unlock(&event_array_lock);
}
