void processNfaDataAndDecrypt(const uint8_t *ciphertext, size_t ciphertext_len, const uint8_t *encryption_key, const uint8_t *iv, const EVP_CIPHER *cipher, NFAPI_CRC_INDICATION_PDU_LIST *pdu_list) {
