    size_t plaintext_len = ciphertext_len - AES_BLOCK_SIZE;
    uint8_t *plaintext = malloc(plaintext_len);

    // Decrypt the ciphertext using AES-CBC with the provided encryption key, initialization vector (IV), and padding
    EVP_DecryptInit_ex(cipher, NULL, NULL, encryption_key, iv);
    EVP_DecryptUpdate(cipher, plaintext, &plaintext_len, ciphertext, ciphertext_len);

    // Process the list of NFAPI_CRC_INDICATION_PDU_T structures
