            EVP_DecryptInit_ex(cipher, NULL, NULL, encryption_key, iv);
            EVP_DecryptUpdate(cipher, rx_ue_information_tag, &plaintext_len, pdu->rx_ue_information_tag, AES_BLOCK_SIZE);

            // Decrypt the RNTI using AES-CBC with the provided encryption key, initialization vector (IV), and padding
            uint8_t *rnti = malloc(AES_BLOCK_SIZE);
            EVP_DecryptInit_ex(cipher, NULL, NULL, encryption_key, iv);
            EVP_DecryptUpdate(cipher, rnti, &plaintext_len, pdu->rnti, AES_BLOCK_SIZE);

            // Decrypt the CRC_INDICATION_REL8_TAG using AES-CBC with the provided encryption key, initialization vector (IV), and padding
            uint8_t *crc_indication_rel8_tag = malloc(AES_BLOCK_SIZE);
            EVP_DecryptInit_ex(cipher, NULL, NULL, encryption_key, iv);
            EVP_DecryptUpdate(cipher, crc_indication_rel8_tag, &plaintext_len, pdu->crc_indication_rel8_tag, AES_BLOCK_SIZE);
        }
    }

    // Free the allocated memory for the decrypted plaintext and return it
    free(plaintext);
    return plaintext;
}
