int processFiles(char *jpegFilePaths[], int numJPEGFiles, char *pdfDirectory) {
    // Initialize variables
    int i, j;
    FILE *file;
    struct stat fileStat;
    size_t fileSize;
    char pdfFileName[256];
    char logMessage[256];
