        // Check if the file size exceeds the maximum size limit
        if (fileSize > MAX_PDF_SIZE) {
            log4cplus::Logger logger = log4cplus::Logger::getInstance(LOGGING_FRAMEWORK);
            logger.logError("File size of JPEG file: " + jpegFilePaths[i] + " exceeds maximum size limit");
            numFailedFiles++;
            continue;
