        // Convert the current JPEG file to a PDF file using the third-party tool
        sprintf(pdfFileName, "%s/%03d.pdf", pdfDirectory, i);
        if (convertJPEGToPDF(jpegFilePaths[i], pdfFileName) != 0) {
