        log4cplus::Logger logger = log4cplus::Logger::getInstance(LOGGING_FRAMEWORK);
        sprintf(logMessage, "Converted JPEG file: %s to PDF file: %s", jpegFilePaths[i], pdfFileName);
        logger.logInfo(logMessage);
    }

    // Return the number of failed files
    return numFailedFiles;
}

