        log4cplus::Logger logger = log4cplus::Logger::getInstance(LOGGING_FRAMEWORK);
        logger.logError("File size of JPEG file: " + jpegFilePath + " exceeds maximum size limit");
        fclose(file);
        return 1;
    }

    // Open the PDF file for writing
    if ((file = fopen(pdfFilePath, "wb")) == NULL) {
        log4cplus::Logger logger = log4cplus::Logger::getInstance(LOGGING_FRAMEWORK);
        logger.logError("Failed to open PDF file: " + pdfFilePath);
        fclose(file);
        return 1;
    }

    // Convert the current JPEG file to a PDF file using the third-party tool
    if (jpeg2pdf(file, jpegFilePath) != 0) {
        log4cplus::Logger logger = log4cplus::Logger::getInstance(LOGGING_FRAMEWORK);
        logger.logError("Failed to convert JPEG file: " + jpegFilePath + " to PDF file: " + pdfFilePath);
        fclose(file);
