    sprintf(logMessage, "Converted JPEG file: %s to PDF file: %s", jpegFilePath, pdfFilePath);
    logger.logInfo(logMessage);

    // Close the JPEG and PDF files
    fclose(file);

    // Return 0 if all files are successfully processed within the size constraints
    return 0;
}

