int handle_failure(char *input_file, char *output_file) {
    // Check if the input and output files are valid
    if (input_file == NULL || output_file == NULL) {
        return -1;
    }

    // Open the input and output files in append mode to resume processing
    FILE *in = fopen(input_file, "ab");
    FILE *out = fopen(output_file, "ab");
    if (in == NULL || out == NULL) {
        return -2;
    }

    // Resume processing from the last successfully processed file
    int ret = convert_jpeg_to_pdf(in, out);
    if (ret != 0) {
        return -3;
    }

    // Close the input and output files
    fclose(in);
    fclose(out);

    // Return success
    return 0;
