#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the union-find data structure for tracking disjoint pairs
typedef struct {
    uint32_t RNTI;
    uint16_t RX_UE_INFORMATION_TAG;
} UF_NODE;

// Define the function to dynamically manage and process a flexible list of NFAPI_CRC_INDICATION_PDU_T structures
int process_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int num_pdus) {
    // Initialize the union-find data structure and the count of disjoint pairs
    UF_NODE *uf = (UF_NODE *)malloc(sizeof(UF_NODE) * num_pdus);
    int count = 0;

    // Iterate over each PDU in the list
    for (int i = 0; i < num_pdus; i++) {
        // Check if the current PDU is a valid one
        if (!pdu[i].RX_UE_INFORMATION_TAG || !pdu[i].RNTI) continue;

        // Find the representative node for the current PDU's RNTI and RX_UE_INFORMATION_TAG
        UF_NODE *rep = find(uf, pdu[i].RNTI, pdu[i].RX_UE_INFORMATION_TAG);

        // If the representative node is not the current PDU's RNTI and RX_UE_INFORMATION_TAG, it means they are disjoint
        if (rep != &uf[i]) {
            count++;
            rep->RNTI = pdu[i].RNTI;
            rep->RX_UE_INFORMATION_TAG = pdu[i].RX_UE_INFORMATION_TAG;
        }
    }

    // Free the union-find data structure and return the count of disjoint pairs
    free(uf);
    return count;
}

// Define the function to find the representative node for a given RNTI and RX_UE_INFORMATION_TAG
UF_NODE *find(UF_NODE *uf, uint32_t rnti, uint16_t rx_ue_information_tag) {
    // Initialize the representative node to itself
    UF_NODE *rep = &uf[rnti];

    // Iterate over each PDU in the list until we find a representative node for the given RNTI and RX_UE_INFORMATION_TAG
    while (rep->RNTI != rnti || rep->RX_UE_INFORMATION_TAG != rx_ue_information_tag) {
        // If the current PDU is a valid one, update the representative node to its parent
        if (rep->RX_UE_INFORMATION_TAG && rep->RNTI) rep = find(uf, rep->RNTI, rep->RX_UE_INFORMATION_TAG);
        // If the current PDU is not a valid one or we have reached the root node, return the representative node
        else break;
    }

    // Return the representative node
    return rep;
