        array->capacity *= 2;
        // Reallocate memory for the array
        array->data = realloc(array->data, sizeof(NFAPI_MESSAGE_T) * array->capacity);
    }
    // Add the new message to the end of the array
    array->data[array->count].header = header;
    array->data[array->count].payload = payload;
    array->count++;
}

