void nfapi_remove_message(NFAPI_MESSAGE_ARRAY* array, size_t index) {
    // Check if the index is valid
    if (index >= array->count) {
        return;
    }
    // Shift all messages after the specified index to fill the gap
    for (size_t i = index + 1; i < array->count; i++) {
        array->data[i - 1] = array->data[i];
    }
    // Decrement the count of elements in the array
    array->count--;
}

