// PHP function to authenticate users and manage session tokens securely
function authenticate_user($username, $password) {
  // Check if the user is already logged in
  if (isset($_SESSION['token'])) {
    // If the token has expired, refresh it
    if ($_SESSION['token']['expires'] < time()) {
      refresh_token();
    }
    return $_SESSION['token'];
  }

  // Authenticate the user using OAuth 2.0
  $client = new GuzzleHttp\Client();
  $response = $client->post('https://auth.example.com/oauth/token', [
    'form_params' => [
      'grant_type' => 'password',
      'username' => $username,
      'password' => $password,
    ],
  ]);

  // Check if the authentication was successful
  if ($response->getStatusCode() !== 200) {
    return false;
  }

  // Store the token in the session and set its expiration time
  $_SESSION['token'] = json_decode($response->getBody(), true);
  $_SESSION['token']['expires'] = time() + $_SESSION['token']['expires_in'];

  return $_SESSION['token'];
}

// Function to refresh the token if it has expired
function refresh_token() {
  $client = new GuzzleHttp\Client();
  $response = $client->post('https://auth.example.com/oauth/token', [
    'form_params' => [
      'grant_type' => 'refresh_token',
      'refresh_token' => $_SESSION['token']['refresh_token'],
    ],
  ]);

  // Check if the refresh was successful
  if ($response->getStatusCode() !== 200) {
    return false;
  }

  // Update the token in the session and set its expiration time
  $_SESSION['token'] = json_decode($response->getBody(), true);
  $_SESSION['token']['expires'] = time() + $_SESSION['token']['expires_in'];

  return true;
}
