// Define the structure to hold the uplink transmission records
typedef struct UplinkTransmissionRecord {
    UEIdentifier ue_id;
    time_t timestamp;
    void* payload;
} UplinkTransmissionRecord;

// Define a pool allocator for efficient memory management
#define POOL_SIZE 1024 // adjust this value based on available memory
static UplinkTransmissionRecord* pool[POOL_SIZE];
static int pool_index = 0;

// Initialize the dynamic array of uplink transmission records
void init_uplink_transmission_records() {
    for (int i = 0; i < POOL_SIZE; i++) {
        pool[i] = NULL;
    }
}

// Add a new record to the dynamic array
UplinkTransmissionRecord* add_uplink_transmission_record(UEIdentifier ue_id, time_t timestamp, void* payload) {
    // Check if there is space in the pool for a new record
    if (pool_index >= POOL_SIZE) {
        return NULL;
    }

    // Allocate memory for the new record
    UplinkTransmissionRecord* record = malloc(sizeof(UplinkTransmissionRecord));
    if (!record) {
        return NULL;
    }

    // Initialize the record fields
    record->ue_id = ue_id;
    record->timestamp = timestamp;
    record->payload = payload;

    // Add the new record to the pool
    pool[pool_index++] = record;

    return record;
}

// Remove a record from the dynamic array
void remove_uplink_transmission_record(UplinkTransmissionRecord* record) {
    // Find the index of the record in the pool
    int index = 0;
    while (index < POOL_SIZE && pool[index] != record) {
        index++;
    }

    // If the record was found, remove it from the pool
    if (index < POOL_SIZE) {
        pool[index] = NULL;
        free(record);
    }
}

// Serialize the dynamic array of uplink transmission records to a binary format
void serialize_uplink_transmission_records(FILE* file) {
    // Write the number of records in the pool to the file
    fwrite(&pool_index, sizeof(int), 1, file);

    // Write each record in the pool to the file
    for (int i = 0; i < pool_index; i++) {
        UplinkTransmissionRecord* record = pool[i];
        fwrite(&record->ue_id, sizeof(UEIdentifier), 1, file);
        fwrite(&record->timestamp, sizeof(time_t), 1, file);
        fwrite(&record->payload, sizeof(void*), 1, file);
    }
}

// Deserialize the dynamic array of uplink transmission records from a binary format
void deserialize_uplink_transmission_records(FILE* file) {
    // Read the number of records in the pool from the file
    int num_records;
    fread(&num_records, sizeof(int), 1, file);

    // Allocate memory for the deserialized records
    UplinkTransmissionRecord* records = malloc(sizeof(UplinkTransmissionRecord) * num_records);

    // Read each record from the file and add it to the pool
    for (int i = 0; i < num_records; i++) {
        UplinkTransmissionRecord* record = &records[i];
        fread(&record->ue_id, sizeof(UEIdentifier), 1, file);
        fread(&record->timestamp, sizeof(time_t), 1, file);
        fread(&record->payload, sizeof(void*), 1, file);
        add_uplink_transmission_record(record->ue_id, record->timestamp, record->payload);
    }
}

// Implement a mechanism to handle dynamic scaling of the array
void scale_uplink_transmission_records() {
    // Check if there is space in the pool for more records
    if (pool_index >= POOL_SIZE) {
        return;
    }

    // Allocate memory for a new record
    UplinkTransmissionRecord* record = malloc(sizeof(UplinkTransmissionRecord));
    if (!record) {
        return;
    }

    // Add the new record to the pool
    pool[pool_index++] = record;
}
