class LogManager {
public:
    // Constructor
    LogManager() : logs_(), capacity_(0), size_(0) {}

    // Destructor
    ~LogManager() { clear(); }

    // Add a new log entry to the collection
    void add(const std::string& message, const LogLevel level = LogLevel::INFO) {
        if (size_ >= capacity_) {
            resize();
        }
        logs_.push_back({std::chrono::system_clock::now(), level, new std::string(message)});
        size_++;
    }

    // Remove a log entry from the collection by its index
    void remove(size_t index) {
        if (index >= size_) {
            throw std::out_of_range("Index out of range");
        }
        delete logs_[index].message;
        logs_.erase(logs_.begin() + index);
        size_--;
    }

    // Iterate over the log entries in chronological order
    void iterate(const std::function<void(const LogEntry&)>& callback) const {
        for (auto it = logs_.cbegin(); it != logs_.cend(); ++it) {
            callback(*it);
        }
    }

private:
    // Resize the internal storage to accommodate more log entries
    void resize() {
        capacity_ *= 2;
        std::vector<LogEntry> new_logs(capacity_);
        for (size_t i = 0; i < size_; ++i) {
            new_logs[i] = logs_[i];
        }
        delete[] logs_;
        logs_ = new_logs;
    }

    // Clear the internal storage and release all log entries
    void clear() {
        for (size_t i = 0; i < size_; ++i) {
            delete logs_[i].message;
        }
        logs_.clear();
        capacity_ = 0;
        size_ = 0;
    }

    // Internal storage for the log entries
    std::vector<LogEntry> logs_;

    // Capacity of the internal storage in number of log entries
    size_t capacity_;

    // Size of the internal storage in number of log entries
    size_t size_;
};
```
