// Define the structure for holding RX frame information
typedef struct LTE_PHY_RX_FRAME_INFO_T {
    int UE_ID;
    float SNR;
    void* buffer;
} LTE_PHY_RX_FRAME_INFO_T;

// Define the maximum number of symbols to allocate for each RX frame
#define MAX_NUM_SYMBOLS 1024

// Define the size of each symbol in bytes
#define SYMBOL_SIZE 16

// Define the total memory usage limit for the array in bytes
#define MEMORY_LIMIT (MAX_NUM_UE * MAX_NUM_SYMBOLS * SYMBOL_SIZE)

// Function to initialize and configure a dynamic array of LTE_PHY_RX_FRAME_INFO_T structures
void init_rx_frame_info(LTE_PHY_RX_FRAME_INFO_T** rx_frame_info, int num_ue) {
    // Allocate memory for the array of RX frame information structures
    *rx_frame_info = (LTE_PHY_RX_FRAME_INFO_T*)malloc(num_ue * sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (*rx_frame_info == NULL) {
        printf("Error: Failed to allocate memory for RX frame information array\n");
        return;
    }

    // Initialize the UE ID and SNR fields of each structure
    for (int i = 0; i < num_ue; i++) {
        (*rx_frame_info)[i].UE_ID = i + 1;
        (*rx_frame_info)[i].SNR = 0.0f;
    }

    // Allocate memory for the buffer field of each structure
    for (int i = 0; i < num_ue; i++) {
        int num_symbols = MAX_NUM_SYMBOLS;
        if (num_symbols > MEMORY_LIMIT / SYMBOL_SIZE) {
            num_symbols = MEMORY_LIMIT / SYMBOL_SIZE;
        }
        (*rx_frame_info)[i].buffer = malloc(num_symbols * SYMBOL_SIZE);
        if ((*rx_frame_info)[i].buffer == NULL) {
            printf("Error: Failed to allocate memory for RX frame buffer\n");
            return;
        }
    }
}

// Function to handle memory allocation errors gracefully
void handle_memory_error(LTE_PHY_RX_FRAME_INFO_T** rx_frame_info, int num_ue) {
    // Free any allocated memory for the RX frame information array and its elements
    if (*rx_frame_info != NULL) {
        for (int i = 0; i < num_ue; i++) {
            free((*rx_frame_info)[i].buffer);
        }
        free(*rx_frame_info);
    }
}

// Function to monitor and limit the total memory usage of the array
void limit_memory_usage(LTE_PHY_RX_FRAME_INFO_T** rx_frame_info, int num_ue) {
    // Calculate the current total memory usage of the array
    size_t total_mem = 0;
    for (int i = 0; i < num_ue; i++) {
        total_mem += (*rx_frame_info)[i].buffer != NULL ? MEMORY_LIMIT : 0;
    }

    // If the current total memory usage exceeds the limit, free any excess memory
    if (total_mem > MEMORY_LIMIT) {
        for (int i = 0; i < num_ue; i++) {
            int num_symbols = MAX_NUM_SYMBOLS;
            if (num_symbols > total_mem / SYMBOL_SIZE) {
                num_symbols = total_mem / SYMBOL_SIZE;
            }
            free((*rx_frame_info)[i].buffer);
            (*rx_frame_info)[i].buffer = malloc(num_symbols * SYMBOL_SIZE);
        }
    }
}

// Function to adapt the array to different UE IDs efficiently
void adapt_to_new_ue_id(LTE_PHY_RX_FRAME_INFO_T** rx_frame_info, int num_ue) {
    // If a new UE ID is encountered, allocate memory for its buffer and initialize it to NULL
    if (num_ue > (*rx_frame_info)[0].UE_ID) {
        LTE_PHY_RX_FRAME_INFO_T* new_rx_frame_info = realloc(*rx_frame_info, num_ue * sizeof(LTE_PHY_RX_FRAME_INFO_T));
        if (new_rx_frame_info == NULL) {
            printf("Error: Failed to allocate memory for new UE ID\n");
            return;
        }
        (*rx_frame_info) = new_rx_frame_info;
        for (int i = 0; i < num_ue; i++) {
            if ((*rx_frame_info)[i].UE_ID == i + 1) {
                continue;
            } else {
                (*rx_frame_info)[i].buffer = NULL;
            }
        }
    }
}
