#define MAX_LIST_SIZE 1024

// Define the mutex for synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to insert a new element in the list
void insert(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (list_size == MAX_LIST_SIZE) {
        printf("List overflow\n");
        return;
    }

    // Create a new element and assign the values
    NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    new_element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Add the new element to the list
    list[list_size++] = new_element;

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&mutex);
}

// Define the function to delete an element from the list
void delete(int RNTI) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&mutex);

    // Find the index of the element to be deleted
    int index = -1;
    for (int i = 0; i < list_size; i++) {
        if (list[i]->RNTI == RNTI) {
            index = i;
            break;
        }
    }

    // Check if the element was found
    if (index != -1) {
        // Remove the element from the list
        NFAPI_CRC_INDICATION_PDU_T *element = list[index];
        free(element);
        list[index] = NULL;

        // Shift all elements after the deleted element to fill the gap
        for (int i = index + 1; i < list_size; i++) {
            list[i - 1] = list[i];
        }

        // Decrement the size of the list
        list_size--;
    } else {
        printf("Element not found\n");
    }

    // Unlock the mutex after modifying the list
