```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

// Define the structure to hold the HTTP request data
typedef struct {
  char *url;
  char *method;
  char *headers;
  char *body;
} http_request_t;

// Define the structure to hold the HTTP response data
typedef struct {
  int status_code;
  char *status_message;
  char *headers;
  char *body;
} http_response_t;

// Define the function to make an HTTP request
int make_http_request(http_request_t *request, http_response_t *response) {
  CURL *curl = curl_easy_init();
  if (!curl) {
    return -1;
  }

  // Set the URL and method for the request
  curl_easy_setopt(curl, CURLOPT_URL, request->url);
  curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, request->method);

  // Set the headers for the request
  struct curl_slist *headers = NULL;
  if (request->headers) {
    headers = curl_slist_append(headers, request->headers);
  }
  curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

  // Set the body for the request
  if (request->body) {
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, request->body);
  }

  // Perform the request and get the response
  CURLcode res = curl_easy_perform(curl);
  if (res != CURLE_OK) {
    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    return -1;
  }

  // Get the response status code and message
  long http_code = 0;
  curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
  char *status_message = NULL;
  curl_easy_getinfo(curl, CURLINFO_RESPONSE_MESSAGE, &status_message);

  // Get the response headers and body
  struct curl_slist *header_list = NULL;
  curl_easy_getinfo(curl, CURLINFO_HEADER_LIST, &header_list);
  char *body = NULL;
  curl_easy_getinfo(curl, CURLINFO_CONTENT_STRING, &body);

  // Clean up the response data
  if (headers) {
    curl_slist_free_all(headers);
  }
  if (header_list) {
    curl_slist_free_all(header_list);
  }
  if (body) {
    free(body);
  }

  // Set the response data
  response->status_code = http_code;
  response->status_message = status_message;
  response->headers = headers;
  response->body = body;

  // Clean up the request data
  if (request->url) {
    free(request->url);
  }
  if (request->method) {
    free(request->method);
  }
  if (request->headers) {
    free(request->headers);
  }
  if (request->body) {
    free(request->body);
  }

  // Clean up the curl handle
  curl_easy_cleanup(curl);

  return 0;
}

// Define the function to make an HTTP request with authentication
int make_http_request_with_auth(http_request_t *request, http_response_t *response) {
  // Set the username and password for the request
  curl_easy_setopt(curl, CURLOPT_USERNAME, "username");
  curl_easy_setopt(curl, CURLOPT_PASSWORD, "password");

  return make_http_request(request, response);
}

// Define the function to make an HTTP request with a custom timeout
int make_http_request_with_timeout(http_request_t *request, http_response_t *response) {
  // Set the timeout for the request
  curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10);

  return make_http_request(request, response);
}

// Define the function to handle redirects
int handle_redirects(http_response_t *response) {
  // Check if the response is a redirect
  if (response->status_code == 301 || response->status_code == 302) {
    // Get the location header from the response
    char *location = NULL;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_HEADER, &location);

    // Make a new request to the redirect URL
    http_request_t new_request = {
      .url = location,
      .method = "GET",
      .headers = NULL,
      .body = NULL
    };
    http_response_t new_response;
    make_http_request(&new_request, &new_response);

    // Set the response data to the new response
    response->status_code = new_response.status_code;
    response->status_message = new_response.status_message;
    response->headers = new_response.headers;
    response->body = new_response.body;
  }

  return 0;
}

// Define the function to handle error responses
int handle_errors(http_response_t *response) {
  // Check if the response is an error
  if (response->status_code >= 400 && response->status_code < 600) {
    // Handle the error response
    fprintf(stderr, "Error: %s\n", response->status_message);
    return -1;
  }

  return 0;
}
```
