// Define the structure for a single PDU in the dynamic array
typedef struct {
    RRC_PDU rrc_pdu; // The RRC message type
} RRC_PDU_STRUCT;

// Define the structure for the dynamic array of frames
typedef struct {
    int num_frames; // Number of frames in the array
    DL_FRAME_STRUCT *frames; // Array of frames
} DYNAMIC_ARRAY_STRUCT;

// Define the function to initialize the dynamic array of frames
void init_dynamic_array(DYNAMIC_ARRAY_STRUCT *array, int max_num_frames, int max_num_pdus) {
    // Allocate memory for the array of frames
    array->frames = (DL_FRAME_STRUCT *)malloc(max_num_frames * sizeof(DL_FRAME_STRUCT));
    if (!array->frames) {
        printf("Error: Failed to allocate memory for the dynamic array\n");
        return;
    }

    // Initialize each frame in the array with a valid number of PDUs
    for (int i = 0; i < max_num_frames; i++) {
        array->frames[i].num_pdus = rand() % max_num_pdus + 1;
        array->frames[i].pdus = (RRC_PDU_STRUCT *)malloc(array->frames[i].num_pdus * sizeof(RRC_PDU_STRUCT));
        if (!array->frames[i].pdus) {
            printf("Error: Failed to allocate memory for the PDUs in frame %d\n", i);
            return;
        }
    }

    // Initialize each PDU in the array with a randomly generated RRC message type
    for (int i = 0; i < max_num_frames; i++) {
        for (int j = 0; j < array->frames[i].num_pdus; j++) {
            array->frames[i].pdus[j].rrc_pdu.message_type = rand() % NUM_RRC_MESSAGE_TYPES + 1;
        }
    }
}

// Define the function to deallocate the dynamic array of frames
void deallocate_dynamic_array(DYNAMIC_ARRAY_STRUCT *array) {
    // Deallocate memory for each frame in the array
    for (int i = 0; i < array->num_frames; i++) {
        free(array->frames[i].pdus);
    }

    // Deallocate memory for the array of frames
    free(array->frames);
}

// Define the function to validate a single frame in the dynamic array
void validate_frame(DL_FRAME_STRUCT *frame) {
    // Validate each PDU in the frame against the predefined set of rules
    for (int i = 0; i < frame->num_pdus; i++) {
        RRC_PDU_STRUCT *pdu = &(frame->pdus[i]);
        if (!validate_rrc_message(pdu)) {
            printf("Error: PDU %d in frame %d is invalid\n", i, frame - array->frames);
            return;
        }
    }
}

// Define the function to validate all frames in the dynamic array asynchronously
void validate_all_frames(DYNAMIC_ARRAY_STRUCT *array) {
    // Validate each frame in the array asynchronously
    for (int i = 0; i < array->num_frames; i++) {
        DL_FRAME_STRUCT *frame = &(array->frames[i]);
        validate_frame(frame);
    }
}

// Define the function to provide a callback mechanism for external modules to hook into the frame initialization process
void init_callback(DYNAMIC_ARRAY_STRUCT *array, void (*callback)(DL_FRAME_STRUCT *)) {
    // Set the callback function pointer
    array->callback = callback;
}

// Define the function to handle asynchronous frame initialization with a callback mechanism
void init_async(DYNAMIC_ARRAY_STRUCT *array, int max_num_frames, int max_num_pdus) {
    // Initialize the dynamic array of frames
    init_dynamic_array(array, max_num_frames, max_num_pdus);

    // Set the callback function pointer to NULL initially
    array->callback = NULL;
}

// Define the function to handle synchronous frame initialization with a callback mechanism
void init_sync(DYNAMIC_ARRAY_STRUCT *array, int max_num_frames, int max_num_pdus) {
    // Initialize the dynamic array of frames
    init_dynamic_array(array, max_num_frames, max_num_pdus);

    // Set the callback function pointer to NULL initially
    array->callback = NULL;
}
