// Function to allocate memory for Offset structures
void* allocate_offsets(int num_blocks, int block_size) {
    // Calculate the total size of memory needed
    int total_size = num_blocks * block_size;

    // Allocate memory using malloc()
    void* mem = malloc(total_size);

    // Initialize each offset based on the block size and number of blocks
    for (int i = 0; i < num_blocks; i++) {
        struct Offset* offset = (struct Offset*)mem + i * sizeof(struct Offset);
        offset->offset = i * block_size;
    }

    return mem;
}

// Function to allocate memory for Key structures
void* allocate_keys(int num_keys, int seed) {
    // Allocate memory using malloc()
    void* mem = malloc(num_keys * sizeof(struct Key));

    // Initialize each key based on the provided seed
    for (int i = 0; i < num_keys; i++) {
        struct Key* key = (struct Key*)mem + i * sizeof(struct Key);
        key->key = seed + i;
    }

    return mem;
}

// Function to allocate memory for Record structures
void* allocate_records(int num_records, int range) {
    // Allocate memory using malloc()
    void* mem = malloc(num_records * sizeof(struct Record));

    // Initialize each record with a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        struct Record* record = (struct Record*)mem + i * sizeof(struct Record);
        record->record = rand() % range;
    }

    return mem;
}

