#include <libxml/tree.h>

// Define the structure to hold the LTE PHY test configuration
typedef struct {
    int frequency_band;
    int bandwidth;
    int cell_id;
} LTE_PHY_TEST_CONFIG_T;

// Function to initialize and populate an array of LTE_PHY_TEST_CONFIG_T structures
int init_lte_phy_test_config(LTE_PHY_TEST_CONFIG_T **configs, int num_configs) {
    // Check if the input parameters are valid
    if (configs == NULL || num_configs <= 0) {
        return -1;
    }

    // Initialize the array of structures to hold the configurations
    *configs = malloc(num_configs * sizeof(LTE_PHY_TEST_CONFIG_T));
    if (*configs == NULL) {
        return -2;
    }

    // Load the XML configuration file and parse it
    int fd = open("lte_phy_test_config.xml", O_RDONLY);
    if (fd < 0) {
        perror("Failed to open XML configuration file");
        return -3;
    }

    // Create an XML parser context and set the parsing options
    xmlParserCtxtPtr ctxt = xmlNewParserCtxt();
    if (ctxt == NULL) {
        fprintf(stderr, "Failed to create XML parser context\n");
        return -4;
    }

    // Set the parsing options to validate the XML document and handle errors
    int options = XML_PARSE_NOBLANKS | XML_PARSE_NOCDATA | XML_PARSE_NOENT | XML_PARSE_NONET | XML_PARSE_NOWARNING;
    xmlSetGenericErrorFunc(ctxt, &xml_error_handler);

    // Parse the XML document and extract the configurations
    int ret = xmlParseDocument(ctxt);
    if (ret != 0) {
        fprintf(stderr, "Failed to parse XML document\n");
        return -5;
    }

    // Get the root element of the XML document
    xmlNodePtr root = ctxt->myDoc->children;
    if (root == NULL) {
        fprintf(stderr, "Failed to get root element of XML document\n");
        return -6;
    }

    // Iterate over the child elements of the root element and extract the configurations
    int i = 0;
    for (xmlNodePtr cur = root->children; cur != NULL; cur = cur->next) {
        if (cur->type == XML_ELEMENT_NODE && strcmp(cur->name, "configuration") == 0) {
            // Extract the frequency band, bandwidth, and cell ID from the current element
            int frequency_band = xmlGetProp(cur, "frequency-band");
            int bandwidth = xmlGetProp(cur, "bandwidth");
            int cell_id = xmlGetProp(cur, "cell-id");

            // Check if the extracted values are valid and add them to the array of structures
            if (frequency_band < 0 || frequency_band > 100 || bandwidth < 0 || bandwidth > 100 || cell_id < 0) {
                fprintf(stderr, "Invalid configuration values\n");
                return -7;
            }

            (*configs)[i].frequency_band = frequency_band;
            (*configs)[i].bandwidth = bandwidth;
            (*configs)[i].cell_id = cell_id;
            i++;
        }
    }

    // Close the XML parser context and file descriptor
    xmlFreeParserCtxt(ctxt);
    close(fd);

    return 0;
}

// Function to handle errors during XML parsing
void xml_error_handler(void *ctx, const char *msg, ...) {
    va_list args;
    va_start(args, msg);
    vfprintf(stderr, msg, args);
    va_end(args);
}
