        pdus[i].rnti = rand(); // Generate a random RNTI for each structure
        pdus[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INIT;
        pdus[i].crcFlag = (rand() % 2) ? 1 : 0; // Set the CRCFLAG randomly
    }

