        return false;
    }

    // Check that the CRC_INDICATION_REL8_TAG is valid
    if (pdu->crcIndicationRel8Tag != CRC_INDICATION_REL8_TAG_INIT) {
        return false;
    }

    // Check that the CRCFLAG is valid
    if (pdu->crcFlag > 1) {
        return false;
    }

    // If all checks pass, return true
    return true;
}
