int init_wifi_network_configs(const char *filepath, CACHE_T *cache) {
    // Load the configuration data from the JSON file or database
    json_object *root = json_object_from_file(filepath);
    if (!root) {
        fprintf(stderr, "Failed to load WiFi network configurations from %s\n", filepath);
        return -1;
    }

    // Validate the configuration data and populate the cache structure
    json_object *configs = json_object_get_array(root);
    size_t num_configs = json_object_array_length(configs);
    WIFI_NETWORK_CONFIG_T **wifi_network_configs = malloc(num_configs * sizeof(WIFI_NETWORK_CONFIG_T));
