    // Update the cache structure with the validated configurations
    cache->configs = wifi_network_configs;
    cache->num_configs = num_configs;

    return 0;
}

// Function to retrieve a WiFi network configuration from the cache by its index
WIFI_NETWORK_CONFIG_T *get_wifi_network_config(CACHE_T *cache, size_t index) {
