    long* offsets = (long*)allocate(sizeof(long) * size);
    if (offsets == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    memset(offsets, 0, sizeof(long) * size);
    return offsets;
}

int* allocate_keys(size_t size) {
    int* keys = (int*)allocate(sizeof(int) * size);
    if (keys == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    memset(keys, 0, sizeof(int) * size);
    return keys;
}

record_t* allocate_records(size_t size) {
    record_t* records = (record_t*)allocate(sizeof(record_t) * size);
    if (records == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    memset(records, 0, sizeof(record_t) * size);
    return records;
}

void deallocate_offsets(long* offsets) {
    deallocate((void*)offsets);
}

void deallocate_keys(int* keys) {
    deallocate((void*)keys);
}

void deallocate_records(record_t* records) {
    deallocate((void*)records);
}

// Define the synchronization functions
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void lock() {
    pthread_mutex_lock(&mutex);
}

void unlock() {
    pthread_mutex_unlock(&mutex);
}

// Define the memory management functions for the arrays
long* offsets = NULL;
int* keys = NULL;
record_t* records = NULL;
size_t capacity = 0;
size_t size = 0;

void initialize_arrays(size_t initial_capacity) {
    lock();
    if (offsets != NULL || keys != NULL || records != NULL) {
        // Handle initialization failure
        unlock();
        return;
    }
    offsets = allocate_offsets(initial_capacity);
    keys = allocate_keys(initial_capacity);
    records = allocate_records(initial_capacity);
    capacity = initial_capacity;
    size = 0;
    unlock();
}

void resize_arrays(size_t new_capacity) {
    lock();
    if (new_capacity <= capacity) {
        // Handle invalid resizing request
        unlock();
        return;
    }
    long* new_offsets = allocate_offsets(new_capacity);
    int* new_keys = allocate_keys(new_capacity);
    record_t* new_records = allocate_records(new_capacity);
    if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
        // Handle memory allocation failure
        deallocate_offsets(offsets);
        deallocate_keys(keys);
        deallocate_records(records);
        offsets = NULL;
        keys = NULL;
        records = NULL;
        capacity = 0;
        size = 0;
        unlock();
        return;
    }
    memcpy(new_offsets, offsets, sizeof(long) * size);
    memcpy(new_keys, keys, sizeof(int) * size);
    memcpy(new_records, records, sizeof(record_t) * size);
    deallocate_offsets(offsets);
    deallocate_keys(keys);
    deallocate_records(records);
    offsets = new_offsets;
    keys = new_keys;
    records = new_records;
    capacity = new_capacity;
    unlock();
}

void add_record(int key, int value) {
    lock();
    if (size == capacity) {
        // Handle overflow
        resize_arrays(2 * capacity);
    }
    offsets[size] = 0;
    keys[size] = key;
    records[size].value = value;
    size++;
    unlock();
}

void remove_record(int key) {
    lock();
    int index = -1;
    for (int i = 0; i < size; i++) {
        if (keys[i] == key) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        // Handle non-existent record
        unlock();
        return;
    }
    for (int i = index + 1; i < size; i++) {
        offsets[i - 1] = offsets[i];
        keys[i - 1] = keys[i];
        records[i - 1].value = records[i].value;
    }
    size--;
    unlock();
}

void clear_arrays() {
    lock();
    deallocate_offsets(offsets);
    deallocate_keys(keys);
    deallocate_records(records);
    offsets = NULL;
    keys = NULL;
    records = NULL;
    capacity = 0;
    size = 0;
    unlock();
}

