    struct PacketListNode *next;
    struct PacketListNode *prev;
} PacketListNode;

// Function to process a stream of network packet timestamps and validate each timestamp before storing it in a dynamically allocated, doubly linked list
void processPackets(PacketListNode **list) {
    // Initialize the list head pointer
    *list = NULL;

    // Loop through the packets and validate each timestamp
    while (1) {
        // Read the next packet from the network interface
        PacketMetadata metadata;
        if (!readPacket(&metadata)) {
            break;
        }

        // Validate the timestamp
