        newNode->next = NULL;
        newNode->prev = *list;

        // Update the list head pointer if necessary
        if (*list == NULL) {
            *list = newNode;
        } else {
            (*list)->next = newNode;
        }
    }
}

// Function to calculate and print the average inter-packet interval (APII)
void calculateAPII(PacketListNode *list) {
    // Initialize variables for APII calculation
    double apii = 0.0;
    int count = 0;

    // Loop through the packets and calculate the APII
    while (list != NULL) {
        // Calculate the inter-packet interval
        time_t delta = list->metadata->timestamp - list->prev->metadata->timestamp;

        // Update the APII and count variables
        apii += delta;
        count++;

        // Move to the next packet in the list
        list = list->next;
    }

    // Print the average APII
    printf("Average inter-packet interval: %f\n", apii / count);
}

