#define HASH_TABLE_SIZE 1024
USER_PROFILE_RECORD *hash_table[HASH_TABLE_SIZE];

// Define the linked list to maintain insertion order
typedef struct {
    USER_PROFILE_RECORD *record;
    struct node *next;
} NODE;
NODE *head = NULL;

// Define the mutex for thread safety
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the function to manage the cache of user profiles
void manage_cache(USER_PROFILE_RECORD *record, bool update) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&cache_lock);

    // Check if the record already exists in the hash table
    int index = hash_table[record->username];
    if (index != -1 && !update) {
        // If it does, update the last active timestamp and return
        hash_table[record->username]->last_active_timestamp = time(NULL);
        pthread_mutex_unlock(&cache_lock);
        return;
    }

    // Check if the record already exists in the linked list
    NODE *node = head;
    while (node != NULL) {
        if (strcmp(record->username, node->record->username) == 0) {
            // If it does, update the last active timestamp and return
            node->record->last_active_timestamp = time(NULL);
            pthread_mutex_unlock(&cache_lock);
            return;
        }
        node = node->next;
    }

    // If the record does not exist, insert it into the hash table and linked list
    index = hash_table[record->username];
    if (index == -1) {
        // Insert the record into the hash table
        hash_table[record->username] = record;

        // Insert the record into the linked list
        NODE *new_node = malloc(sizeof(NODE));
        new_node->record = record;
        new_node->next = head;
        head = new_node;
    } else {
        // Update the last active timestamp in the hash table
        hash_table[record->username]->last_active_timestamp = time(NULL);
    }

    // Release the lock for thread safety
    pthread_mutex_unlock(&cache_lock);
}

// Define the function to retrieve a user profile from the cache
USER_PROFILE_RECORD *retrieve_profile(char *username) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&cache_lock);

    // Check if the record exists in the hash table
    int index = hash_table[username];
    if (index == -1) {
        // If it does not, return NULL
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    // Return the record from the hash table
    USER_PROFILE_RECORD *record = hash_table[username];
    pthread_mutex_unlock(&cache_lock);
    return record;
}

// Define the function to update a user profile in the cache
void update_profile(USER_PROFILE_RECORD *record) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&cache_lock);

    // Check if the record exists in the hash table
