// TCPPACKET structure definition
struct TCPPACKET {
    struct iphdr ip_header;
    struct tcphdr tcp_header;
    char payload[1024];
};

// Flow array data structure
struct FLOW {
    int id;
    struct TCPPACKET *packet;
};

// Global variables
int flow_count = 0;
struct FLOW *flows = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a TCPPACKET structure instance
struct TCPPACKET* create_packet() {
    struct TCPPACKET *packet = malloc(sizeof(struct TCPPACKET));
    if (packet == NULL) {
        perror("malloc");
        exit(1);
    }
    memset(packet, 0, sizeof(struct TCPPACKET));
    packet->ip_header.version = 4;
    packet->ip_header.ihl = 5;
    packet->ip_header.tot_len = htons(sizeof(struct iphdr) + sizeof(struct tcphdr) + 1024);
    packet->ip_header.id = htonl(flow_count++);
    packet->ip_header.ttl = 64;
    packet->ip_header.protocol = IPPROTO_TCP;
    packet->tcp_header.source = htons(1025);
    packet->tcp_header.dest = htons(80);
    packet->tcp_header.seq = htonl(flow_count++);
    packet->tcp_header.ack_seq = htonl(flow_count++);
    packet->tcp_header.doff = 5;
    packet->tcp_header.syn = 1;
    packet->tcp_header.window = htons(1024);
    packet->tcp_header.check = 0;
    packet->tcp_header.urg_ptr = 0;
    memset(packet->payload, 'A', 1024);
    return packet;
}

// Function to create and populate a flow instance
struct FLOW* create_flow() {
    struct FLOW *flow = malloc(sizeof(struct FLOW));
    if (flow == NULL) {
        perror("malloc");
        exit(1);
    }
    memset(flow, 0, sizeof(struct FLOW));
    flow->id = flow_count++;
    flow->packet = create_packet();
    return flow;
}

// Function to add a new flow to the array
void add_flow(struct FLOW *flow) {
    pthread_mutex_lock(&mutex);
    flows = realloc(flows, (flow_count + 1) * sizeof(struct FLOW));
    if (flows == NULL) {
        perror("realloc");
        exit(1);
    }
    flows[flow_count - 1] = flow;
    pthread_mutex_unlock(&mutex);
}

// Function to update a flow in the array
void update_flow(int id, struct TCPPACKET *packet) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < flow_count; i++) {
        if (flows[i].id == id) {
            flows[i].packet = packet;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to delete a flow from the array
void delete_flow(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < flow_count; i++) {
        if (flows[i].id == id) {
            free(flows[i].packet);
            flows[i] = flows[--flow_count];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to initialize a new flow with default values
void init_flow(struct FLOW *flow) {
    flow->id = flow_count++;
    flow->packet = create_packet();
}

// Main function for the API service
int main() {
    // Initialize the flows array and the mutex
    flows = malloc(sizeof(struct FLOW));
    if (flows == NULL) {
        perror("malloc");
        exit(1);
    }
    memset(flows, 0, sizeof(struct FLOW));
    pthread_mutex_init(&mutex, NULL);

    // Create a socket for the API service
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    // Bind the socket to a specific IP address and port
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(struct sockaddr_in));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    if (bind(sock, (struct sockaddr *)&addr, sizeof(struct sockaddr_in)) < 0) {
        perror("bind");
        exit(1);
    }

    // Listen for incoming connections on the socket
    if (listen(sock, 3) < 0) {
        perror("listen");
        exit(1);
    }

    // Accept incoming connections and handle them in separate threads
    while (1) {
        struct sockaddr_in client;
        int client_len = sizeof(struct sockaddr_in);
        int client_sock = accept(sock, (struct sockaddr *)&client, &client_len);
        if (client_sock < 0) {
            perror("accept");
            exit(1);
        }
        pthread_t thread;
        pthread_create(&thread, NULL, handle_connection, (void *)client_sock);
    }

    // Clean up the socket and mutex
    close(sock);
    pthread_mutex_destroy(&mutex);
    free(flows);
    return 0;
}

// Function to handle incoming connections in separate threads
void *handle_connection(void *arg) {
    int client_sock = (int)arg;
    char buffer[1024];
    while (1) {
        // Read the request from the client
        memset(buffer, 0, sizeof(char) * 1024);
        read(client_sock, buffer, 1024);

        // Parse the JSON request body and extract the flow ID and updated data
        json_object *json = json_tokener_parse(buffer);
        int id = json_object_get_int(json_object_object_get(json, "id"));
        char *data = json_object_get_string(json_object_object_get(json, "data"));

        // Update the flow in the array
        update_flow(id, data);

        // Send a response back to the client
        write(client_sock, buffer, 1024);
    }
