    // Initialize the Union-Find data structure for disjoint pair tracking
    UF_TREE_NODE_T *uf_tree = (UF_TREE_NODE_T *)malloc(sizeof(UF_TREE_NODE_T) * num_elements);
    memset(uf_tree, 0, sizeof(UF_TREE_NODE_T) * num_elements);

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
