        // Add the current element to the Union-Find data structure for disjoint pair tracking
        uf_tree[i].parent = i;
        uf_tree[i].rank = 0;
    }

    // Ensure that no two elements in the list share the same RNTI or RX_UE_INFORMATION_TAG
    for (int i = 0; i < num_elements - 1; i++) {
        for (int j = i + 1; j < num_elements; j++) {
