                int root1 = find_root(uf_tree, i);
                int root2 = find_root(uf_tree, j);
                if (root1 != root2) {
                    uf_tree[root1].parent = root2;
                    uf_tree[root1].rank += uf_tree[root2].rank;
                }
            }
        }
    }

    // Return the count of disjoint pairs identified
    int num_disjoint_pairs = 0;
    for (int i = 0; i < num_elements; i++) {
        if (uf_tree[i].parent == i) {
            num_disjoint_pairs++;
        }
    }
    return num_disjoint_pairs;
}

// Function to find the root node of a Union-Find tree
int find_root(UF_TREE_NODE_T *uf_tree, int node) {
    if (uf_tree[node].parent != node) {
        uf_tree[node].parent = find_root(uf_tree, uf_tree[node].parent);
    }
    return uf_tree[node].parent;
}

