void add_element(int rx_ue_information_tag, int rnti, int crc_indication_rel8_tag) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Check if the list is full
    if (list == NULL || list->size >= MAX_LIST_SIZE) {
        // If the list is full, resize it by a factor of 2
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size + 1));
        if (new_list == NULL) {
