// Define the function to manage the doubly linked list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list, RX_UE_INFORMATION_TAG *rx_ue_information, RNTI rnti) {
    // Check if the list is empty
    if (list->head == NULL) {
        // Create a new node and add it to the head of the list
        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->rx_ue_information = rx_ue_information;
        new_node->rnti = rnti;
        new_node->crc_indication_rel8.CRCFLAG = (rnti % 2 == 0) ? true : false;
        list->head = new_node;
        list->tail = new_node;
    } else {
        // Create a new node and add it to the tail of the list
        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->rx_ue_information = rx_ue_information;
        new_node->rnti = rnti;
        new_node->crc_indication_rel8.CRCFLAG = (rnti % 2 == 0) ? true : false;
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
}

// Define the function to compress the linked list data when the number of nodes exceeds 20,000
void compress_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list) {
    // Check if the list is empty or has less than 20,000 nodes
    if (list->head == NULL || list->tail->next == NULL) {
        return;
    }

    // Define a temporary linked list to store the compressed data
    NFAPI_CRC_INDICATION_LIST *compressed_list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    compressed_list->head = NULL;
    compressed_list->tail = NULL;

    // Iterate through the list and compress the data
    NFAPI_CRC_INDICATION_PDU_T *current_node = list->head;
    while (current_node != NULL) {
        // Check if the current node is the last node in the list
        if (current_node->next == NULL) {
            // Add the current node to the compressed list and break the loop
            add_to_compressed_list(compressed_list, current_node);
            break;
        } else {
            // Check if the next node is the same as the previous node
            NFAPI_CRC_INDICATION_PDU_T *next_node = current_node->next;
            while (next_node != NULL && next_node->rx_ue_information == current_node->rx_ue_information) {
                // Add the next node to the compressed list and remove it from the original list
                add_to_compressed_list(compressed_list, next_node);
                remove_from_original_list(current_node);
                current_node = next_node;
            }
        }
    }

    // Free the memory of the original list and assign the compressed list to it
    free(list->head);
    list->head = compressed_list->head;
    list->tail = compressed_list->tail;
}

// Define the function to add a node to the compressed linked list
void add_to_compressed_list(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    // Check if the list is empty
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        // Add the node to the tail of the list
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
}

// Define the function to remove a node from the original linked list
void remove_from_original_list(NFAPI_CRC_INDICATION_PDU_T *node) {
    // Check if the node is the head of the list
    if (node->prev == NULL) {
        node->next->prev = NULL;
        free(node);
    } else {
        // Remove the node from the middle or end of the list
        node->prev->next = node->next;
        node->next->prev = node->prev;
        free(node);
    }
}

