void export_compressed_data(NFAPI_CRC_INDICATION_LIST *list, FILE *file) {
    // Check if the list is empty
    if (list->head == NULL) {
        return;
    }

    // Iterate through the list and export the data to the file
    NFAPI_CRC_INDICATION_PDU_T *current_node = list->head;
    while (current_node != NULL) {
        // Export the node data to the file
