} MemoryPool;

// Define the logging mechanism for tracking allocation failures and performance bottlenecks
typedef struct {
    FILE* logFile; // File handle for writing logs
    size_t maxLogSize; // Maximum number of bytes to write to the log file
    size_t currentLogSize; // Current number of bytes written to the log file
} LoggingMechanism;

// Define the function to initialize and populate a dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* initAndPopulateArray(size_t numElements, float probabilityThreshold) {
    // Validate that the array can hold at least `numElements` elements before proceeding
    if (numElements > 0 && numElements <= MAX_NUM_ELEMENTS) {
        // Initialize the memory pool for efficient allocation and deallocation
        MemoryPool* memPool = malloc(sizeof(MemoryPool));
        memPool->capacity = numElements;
        memPool->count = 0;
        memPool->elements = calloc(numElements, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Initialize the logging mechanism for tracking allocation failures and performance bottlenecks
        LoggingMechanism* log = malloc(sizeof(LoggingMechanism));
        log->logFile = fopen("log.txt", "w");
        log->maxLogSize = 1024 * 1024; // 1 MB
        log->currentLogSize = 0;

        // Populate the array with unique `RX_UE_INFORMATION_TAG` and `RNTI` values, setting `CRCFLAG` randomly based on the probability threshold
        for (size_t i = 0; i < numElements; i++) {
            NFAPI_CRC_INDICATION_PDU_T* element = &memPool->elements[i];
            element->RX_UE_INFORMATION_TAG = rand() % MAX_NUM_ELEMENTS;
            element->RNTI = rand() % MAX_NUM_ELEMENTS;
            if (rand() / (float) RAND_MAX < probabilityThreshold) {
                element->CRCFLAG = true;
            } else {
                element->CRCFLAG = false;
            }
        }

        // Track allocation failures and performance bottlenecks through the logging mechanism
        if (log->currentLogSize > log->maxLogSize) {
            fprintf(stderr, "Log file size exceeded maximum limit of %zu bytes\n", log->maxLogSize);
        } else {
            fwrite(log->logFile, log->currentLogSize, 1, log->logFile);
        }

        // Clean up the memory pool and logging mechanism
        free(memPool);
        free(log);
    } else {
        return NULL;
    }
}
