} LTE_TransportChannelConfig;

LTE_TransportChannelConfig** initialize_transport_channels(int cellID, int numTransportChannels, int systemState) {
    // Validate input parameters
    if (cellID < 0 || cellID > 65535 || numTransportChannels < 0 || numTransportChannels > 1024 || systemState < 0 || systemState > 100) {
        return NULL;
    }

    // Allocate memory for the array of configurations
    LTE_TransportChannelConfig** configs = (LTE_TransportChannelConfig**)malloc(sizeof(LTE_TransportChannelConfig*) * numTransportChannels);
    if (!configs) {
        return NULL;
    }

    // Allocate memory for each configuration structure
    for (int i = 0; i < numTransportChannels; i++) {
        configs[i] = (LTE_TransportChannelConfig*)malloc(sizeof(LTE_TransportChannelConfig));
        if (!configs[i]) {
            free(configs);
            return NULL;
        }
    }

    // Populate each configuration with data
    for (int i = 0; i < numTransportChannels; i++) {
        configs[i]->cellID = cellID;
        configs[i]->transportChannelIdentifier = i + 1;
        if (systemState == 1) {
            // Set up nested configuration for high-speed data transmission
            configs[i]->nestedConfiguration = (void*)malloc(sizeof(LTE_TransportChannelConfig));
            if (!configs[i]->nestedConfiguration) {
                free(configs);
                return NULL;
            }
        } else {
            // Set up nested configuration for low-speed data transmission
            configs[i]->nestedConfiguration = (void*)malloc(sizeof(LTE_TransportChannelConfig));
            if (!configs[i]->nestedConfiguration) {
                free(configs);
                return NULL;
            }
        }
    }

    // Implement logging mechanism to record detailed information about each configuration
    for (int i = 0; i < numTransportChannels; i++) {
        printf("Cell ID: %d, Transport Channel Identifier: %d\n", configs[i]->cellID, configs[i]->transportChannelIdentifier);
        if (configs[i]->nestedConfiguration) {
            printf("Nested Configuration: %p\n", configs[i]->nestedConfiguration);
        } else {
            printf("No nested configuration\n");
        }
    }

    // Return a pointer to the first element of the array if successful, or NULL if an error occurs
    return configs;
}
