void collect_matching_elements(node *root, const char *selector, record **records) {
    // Initialize the offset array and key array
    long *offset = (long *)malloc(sizeof(long) * 10);
    memset(offset, 0, sizeof(long) * 10);
    int *key = (int *)malloc(sizeof(int) * 10);
    memset(key, 0, sizeof(int) * 10);

