    for (int i = 0; i < 10; i++) {
        records[i] = (record *)malloc(sizeof(record));
        memset(records[i], 0, sizeof(record));
    }

    // Recursively traverse the DOM tree and collect matching elements
    collect_matching_elements_helper(root, selector, offset, key, records);

    // Free the memory allocated for the offset array and key array
    free(offset);
    free(key);

    // Return the list of matching elements
    return records;
}

// Helper function to recursively traverse the DOM tree and collect matching elements
void collect_matching_elements_helper(node *root, const char *selector, long *offset, int *key, record **records) {
    // Check if the current node matches the specified CSS selector
