}

// Define the function to delete a single UE context
void delete_ue_context(UECtx **ue_contexts, int num_ue, int ue_idx) {
    // Delete the specified UE context from the list
    free((*ue_contexts)[ue_idx].guti);
    (*ue_contexts)[ue_idx].guti = NULL;
}

// Define the function to handle concurrent updates of UE contexts
void update_ue_contexts(UECtx **ue_contexts, int num_ue) {
    // Use a mutex to synchronize access to the list of UE contexts
    pthread_mutex_t ue_contexts_lock;
    pthread_mutex_init(&ue_contexts_lock, NULL);

    // Update the specified UE context with new data
    for (int i = 0; i < num_ue; i++) {
        pthread_mutex_lock(&ue_contexts_lock);
        update_ue_context(ue_contexts, num_ue, i);
        pthread_mutex_unlock(&ue_contexts_lock);
    }
}

