    memcpy(&(connections[num_connections].remote_addr), &remote_addr, sizeof(struct sockaddr_in));
    connections[num_connections].state = "ESTABLISHED";

    // Increment the number of connections
    num_connections++;

    return 0;
}

// Function to update an existing connection record
