void iterate_connections(void (*callback)(connection_record_t *)) {
    // Iterate over all connection records and call the callback function for each one
    for (int i = 0; i < num_connections; i++) {
        callback(&(connections[i]));
    }
}

// Function to handle connection timeouts
void handle_timeouts() {
    // Iterate over all active connections and check if any have timed out
