Here is an example implementation of the C function to manage a dynamic list of TCP connection records:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

// Define the structure to hold a TCP connection record
typedef struct {
    int socket; // valid socket descriptor
    struct sockaddr_in remote_addr; // remote address
    enum ConnectionState state; // connection state
} ConnectionRecord;

// Define an array to store all active connections
ConnectionRecord *connections = NULL;
size_t num_connections = 0;

// Function to add a new connection record
void add_connection(int socket, struct sockaddr_in remote_addr) {
    // Allocate memory for the new connection record
    ConnectionRecord *new_record = malloc(sizeof(ConnectionRecord));
    if (!new_record) {
        perror("Failed to allocate memory for new connection record");
        return;
    }

    // Initialize the new connection record
    new_record->socket = socket;
    memcpy(&new_record->remote_addr, &remote_addr, sizeof(struct sockaddr_in));
    new_record->state = CONNECTION_STATE_NEW;

    // Add the new connection record to the list of active connections
    if (num_connections == 0) {
        connections = malloc(sizeof(ConnectionRecord));
        if (!connections) {
            perror("Failed to allocate memory for connection array");
            return;
        }
    } else {
        connections = realloc(connections, sizeof(ConnectionRecord) * (num_connections + 1));
        if (!connections) {
            perror("Failed to reallocate memory for connection array");
            return;
        }
    }
    connections[num_connections++] = new_record;
}

// Function to update an existing connection record
void update_connection(int socket, struct sockaddr_in remote_addr) {
    // Find the connection record with the given socket descriptor
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i]->socket == socket) {
            connections[i]->remote_addr = remote_addr;
            return;
        }
    }
}

// Function to iterate over all active connections
void iterate_connections(void (*callback)(ConnectionRecord *)) {
    for (size_t i = 0; i < num_connections; i++) {
        callback(connections[i]);
    }
}

// Function to handle connection timeouts
void handle_timeouts() {
    // Iterate over all active connections and check if any have timed out
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i]->state == CONNECTION_STATE_TIMED_OUT) {
            // Close the connection and remove it from the list of active connections
            close(connections[i]->socket);
            free(connections[i]);
            memmove(&connections[i], &connections[i + 1], sizeof(ConnectionRecord) * (num_connections - i));
            num_connections--;
        }
    }
}

// Function to handle memory efficiency under high load
void handle_memory_efficiency() {
    // Check if the number of active connections exceeds a certain threshold
    if (num_connections > 100) {
        // Reallocate memory for the connection array to reduce its size
        connections = realloc(connections, sizeof(ConnectionRecord) * num_connections / 2);
        if (!connections) {
            perror("Failed to reallocate memory for connection array");
            return;
        }
    }
}
```
This implementation uses a dynamic array to store all active connections. The `add_connection` function adds a new connection record to the list, while the `update_connection` function updates an existing connection record. The `iterate_connections` function iterates over all active connections and calls a callback function for each one. The `handle_timeouts` function checks if any connections have timed out and closes them. Finally, the `handle_memory_efficiency` function reduces the size of the connection array when the number of active connections exceeds a certain threshold.

