// Structure to store network interface statistics
typedef struct NetworkInterfaceStats {
    int index;
    char name[IFNAMSIZ];
    unsigned long rx_bytes;
    unsigned long tx_bytes;
} NetworkInterfaceStats;

// Function to initialize and populate a dynamic array of NetworkInterfaceStats structures for a subset of active network interfaces within a given range
int init_network_interface_stats(NetworkInterfaceStats **stats, int *num_interfaces) {
    // Read the list of network interface indices from an external configuration file
    FILE *config = fopen("config.txt", "r");
    if (config == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), config)) {
        // Trim whitespace from the end of the line
        int len = strlen(line);
        while (len > 0 && isspace(line[len - 1])) {
            line[len - 1] = '\0';
            --len;
        }

        // Check if the line contains a valid network interface index
        int index = atoi(line);
        if (index < 0 || index >= *num_interfaces) {
            fprintf(stderr, "Invalid network interface index: %d\n", index);
            continue;
        }

        // Add the network interface to the list of active interfaces
        NetworkInterfaceStats *new_stats = realloc(*stats, (*num_interfaces + 1) * sizeof(NetworkInterfaceStats));
        if (new_stats == NULL) {
            perror("Error allocating memory for network interface statistics");
            return -1;
        }
        *stats = new_stats;
        (*stats)[*num_interfaces].index = index;
        strcpy((*stats)[*num_interfaces].name, if_indextoname(index));
        ++(*num_interfaces);
    }

    // Close the configuration file
    fclose(config);

    return 0;
}

// Function to update the network interface statistics for a given range of interfaces
int update_network_interface_stats(NetworkInterfaceStats *stats, int num_interfaces) {
    // Iterate over each network interface in the list
    for (int i = 0; i < num_interfaces; ++i) {
        // Get the current statistics for the interface
        struct ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, stats[i].name, IFNAMSIZ);
        if (ioctl(sockfd, SIOCGIFSTATS, &ifr) < 0) {
            perror("Error getting interface statistics");
            return -1;
        }

        // Update the rx_bytes and tx_bytes fields in the NetworkInterfaceStats structure
        stats[i].rx_bytes = ifr.ifr_data.ifi_ibytes;
        stats[i].tx_bytes = ifr.ifr_data.ifi_obytes;
    }

    return 0;
}

// Function to print the network interface statistics for a given range of interfaces
void print_network_interface_stats(NetworkInterfaceStats *stats, int num_interfaces) {
    // Iterate over each network interface in the list
    for (int i = 0; i < num_interfaces; ++i) {
        printf("Index: %d\n", stats[i].index);
        printf("Name: %s\n", stats[i].name);
        printf("RX Bytes: %lu\n", stats[i].rx_bytes);
        printf("TX Bytes: %lu\n", stats[i].tx_bytes);
    }
}

// Main function to demonstrate the use of the init_network_interface_stats and update_network_interface_stats functions
int main() {
    // Initialize a dynamic array of NetworkInterfaceStats structures for a subset of active network interfaces within a given range
    int num_interfaces = 0;
    NetworkInterfaceStats *stats = NULL;
    if (init_network_interface_stats(&stats, &num_interfaces) < 0) {
        perror("Error initializing network interface statistics");
        return -1;
    }

    // Update the network interface statistics for a given range of interfaces
    if (update_network_interface_stats(stats, num_interfaces) < 0) {
        perror("Error updating network interface statistics");
        return -1;
    }

    // Print the network interface statistics for a given range of interfaces
    print_network_interface_stats(stats, num_interfaces);

    // Clean up memory allocated for the NetworkInterfaceStats structures
    free(stats);

    return 0;
}
```
