    while (count < array->capacity) {
        DataPacket packet;
        int result = fetchDataPacketTemplate(source, &packet);
        if (result == -1) { // Error occurred during fetching
            break;
        } else if (result == 0) { // No more templates available
            break;
        }
        addDataPacket(array, packet);
        count++;
    }

    // Release the mutex for thread safety
    pthread_mutex_unlock(&array->mutex);

    return 0; // Success
}

// Minimize memory fragmentation while ensuring that the dynamic array can grow efficiently as more packets are added
int minimizeMemoryFragmentation(DataPacketArray* array) {
    if (array == NULL) {
        return -1; // Invalid arguments
    }

    // Acquire the mutex for thread safety
    pthread_mutex_lock(&array->mutex);

    // Reallocate memory for the dynamic array to minimize fragmentation
