#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Define the structure for a resource pool
typedef struct {
    int VM_INSTANCE_ID;
    char* RESOURCE_ALLOCATION_TAG;
    float CPU_USAGE_PERCENTAGE;
} NFVI_RESOURCE_POOL_T;

// Define a linked list to store the resource pools
typedef struct {
    NFVI_RESOURCE_POOL_T* pool;
    struct node* next;
} node;

// Function to allocate memory for a new resource pool
NFVI_RESOURCE_POOL_T* create_resource_pool(int VM_INSTANCE_ID, char* RESOURCE_ALLOCATION_TAG, float CPU_USAGE_PERCENTAGE) {
    NFVI_RESOURCE_POOL_T* pool = malloc(sizeof(NFVI_RESOURCE_POOL_T));
    if (pool == NULL) {
        return NULL;
    }
    pool->VM_INSTANCE_ID = VM_INSTANCE_ID;
    pool->RESOURCE_ALLOCATION_TAG = RESOURCE_ALLOCATION_TAG;
    pool->CPU_USAGE_PERCENTAGE = CPU_USAGE_PERCENTAGE;
    return pool;
}

// Function to add a new resource pool to the linked list
void add_resource_pool(node* head, NFVI_RESOURCE_POOL_T* pool) {
    node* current = head;
    while (current->next != NULL) {
        if (current->pool->VM_INSTANCE_ID == pool->VM_INSTANCE_ID) {
            // Prevent consecutive structures from having the same VM_INSTANCE_ID value
            return;
        }
        current = current->next;
    }
    current->next = malloc(sizeof(node));
    if (current->next == NULL) {
        return;
    }
    current->next->pool = pool;
    current->next->next = NULL;
}

// Function to remove a resource pool from the linked list
void remove_resource_pool(node* head, int VM_INSTANCE_ID) {
    node* current = head;
    while (current != NULL) {
        if (current->pool->VM_INSTANCE_ID == VM_INSTANCE_ID) {
            // Remove the resource pool from the linked list
            node* temp = current;
            current = current->next;
            free(temp);
            return;
        }
        current = current->next;
    }
}

// Function to update a resource pool in the linked list
void update_resource_pool(node* head, int VM_INSTANCE_ID, char* RESOURCE_ALLOCATION_TAG, float CPU_USAGE_PERCENTAGE) {
    node* current = head;
    while (current != NULL) {
        if (current->pool->VM_INSTANCE_ID == VM_INSTANCE_ID) {
            // Update the resource pool in the linked list
            current->pool->RESOURCE_ALLOCATION_TAG = RESOURCE_ALLOCATION_TAG;
            current->pool->CPU_USAGE_PERCENTAGE = CPU_USAGE_PERCENTAGE;
            return;
        }
        current = current->next;
    }
}

// Function to print the linked list of resource pools
void print_resource_pools(node* head) {
    node* current = head;
    while (current != NULL) {
        printf("VM Instance ID: %d\n", current->pool->VM_INSTANCE_ID);
        printf("Resource Allocation Tag: %s\n", current->pool->RESOURCE_ALLOCATION_TAG);
        printf("CPU Usage Percentage: %.2f\n", current->pool->CPU_USAGE_PERCENTAGE);
        current = current->next;
    }
}
