#define POOL_SIZE 1024 // Size of the memory pool in bytes
static char pool[POOL_SIZE];
static int pool_used = 0; // Keep track of used memory in the pool

// Define a function to allocate memory from the pool
void* alloc(size_t size) {
    if (pool_used + size > POOL_SIZE) {
        return NULL;
    }
    void* ptr = &pool[pool_used];
    pool_used += size;
    return ptr;
}

// Define a function to free memory from the pool
void free(void* ptr) {
    if (ptr < &pool[0] || ptr > &pool[POOL_SIZE - 1]) {
        return;
    }
    int offset = (int)(ptr - &pool[0]);
    pool_used -= offset;
}

