// Function to find the largest integer in a stream of integers and populate a list of CRC indications
void findLargestAndPopulateCRCIndications(int *stream, size_t length, CRCIndication **crc_indications) {
    // Initialize variables
    int largest = INT_MIN;
    bool crc_valid = false;
    size_t i = 0;
    CRCIndication *crc_list = NULL;

    // Iterate through the stream of integers and find the largest value
    while (i < length) {
        if (stream[i] > largest) {
            largest = stream[i];
        }
        i++;
    }

    // Allocate memory for the CRC indication list
    crc_list = malloc(length * sizeof(CRCIndication));
    if (!crc_list) {
        printf("Error: Failed to allocate memory for CRC indications\n");
        return;
    }

    // Populate the CRC indication list with the values from the stream and their corresponding CRC flags
    i = 0;
    while (i < length) {
        crc_list[i].value = stream[i];
        if (stream[i] == largest) {
            crc_list[i].crc_valid = true;
        } else {
            crc_list[i].crc_valid = false;
        }
        i++;
    }

    // Return the largest integer and the CRC indication list
