void manage_lte_phy_configs(lte_phy_config_t** configs, int num_configs) {
    // Validate input parameters for consistency and completeness
    if (configs == NULL || num_configs <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the array of configurations
    lte_phy_config_t* new_configs = malloc(num_configs * sizeof(lte_phy_config_t));
    if (new_configs == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Copy the input configurations to the new array
    for (int i = 0; i < num_configs; i++) {
        new_configs[i] = configs[i];
    }

    // Validate the configurations for consistency and completeness
    for (int i = 0; i < num_configs; i++) {
        if (new_configs[i].bandwidth <= 0 || new_configs[i].center_frequency <= 0) {
            printf("Invalid configuration: bandwidth and center frequency must be positive\n");
            free(new_configs);
            return;
        }
        if (strlen(new_configs[i].antenna_config) == 0) {
            printf("Invalid configuration: antenna configuration must not be empty\n");
            free(new_configs);
            return;
