// Define a linked list node to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define a global variable to keep track of the head node of the linked list
Node* head = NULL;

// Define a semaphore to synchronize access to the linked list
sem_t sem;

// Function to dynamically manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void manageLinkedList(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Acquire the semaphore to prevent race conditions and contention between threads
    sem_wait(&sem);

    // Check if the linked list is empty
    if (head == NULL) {
        head = malloc(sizeof(Node));
        head->data = *data;
        head->next = NULL;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(Node));
        current->next->data = *data;
        current->next->next = NULL;
    }

    // Release the semaphore to allow other threads to access the linked list
    sem_post(&sem);
}

// Function to insert a new node into the linked list
void insertNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = malloc(sizeof(Node));
    newNode->data = *data;
    newNode->next = NULL;

    // Acquire the semaphore to prevent race conditions and contention between threads
    sem_wait(&sem);

    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Release the semaphore to allow other threads to access the linked list
    sem_post(&sem);
}

// Function to delete a node from the linked list
void deleteNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* current = head;
    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != data->RX_UE_INFORMATION_TAG) {
        current = current->next;
    }

    // Acquire the semaphore to prevent race conditions and contention between threads
    sem_wait(&sem);

    if (current == NULL) {
        // Node not found, do nothing
    } else if (current == head) {
        head = current->next;
    } else {
        Node* previous = head;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }

    // Release the semaphore to allow other threads to access the linked list
    sem_post(&sem);
}

// Function to traverse the linked list and process each node
void traverseLinkedList(void (*processNode)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* current = head;
    while (current != NULL) {
        // Acquire the semaphore to prevent race conditions and contention between threads
        sem_wait(&sem);

        processNode(&(current->data));

        // Release the semaphore to allow other threads to access the linked list
        sem_post(&sem);

        current = current->next;
    }
}
