// Define a structure to represent an NFAPI_MESSAGE_T
typedef struct {
    int tag; // Valid TX UE CONTROL INFORMATION tag
    char *rrc_message; // Pointer to dynamically allocated buffer for encoded RRC messages
} nfapi_message_t;

// Define a dynamic array of NFAPI_MESSAGE_T structures
typedef struct {
    int size; // Current number of elements in the array
    int capacity; // Maximum number of elements that can be stored in the array
    nfapi_message_t *messages; // Pointer to an array of NFAPI_MESSAGE_T structures
} nfapi_message_array_t;

// Initialize a new dynamic array of NFAPI_MESSAGE_T structures
nfapi_message_array_t* init_nfapi_message_array(int capacity) {
    // Allocate memory for the array and its elements
    nfapi_message_array_t *array = malloc(sizeof(nfapi_message_array_t));
    array->messages = malloc(capacity * sizeof(nfapi_message_t));
    array->size = 0;
    array->capacity = capacity;

    // Initialize each element in the array with a NULL pointer for the RRC message buffer
    for (int i = 0; i < capacity; i++) {
        array->messages[i].rrc_message = NULL;
    }

    return array;
}

// Add a new NFAPI_MESSAGE_T structure to the dynamic array, handling memory allocation and buffer overflows
void add_nfapi_message(nfapi_message_array_t *array, int tag, char *rrc_message) {
    // Check if the array needs to be resized
    if (array->size == array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;
        array->messages = realloc(array->messages, array->capacity * sizeof(nfapi_message_t));

        // Initialize each new element in the array with a NULL pointer for the RRC message buffer
        for (int i = array->size; i < array->capacity; i++) {
            array->messages[i].rrc_message = NULL;
        }
    }

    // Add the new NFAPI_MESSAGE_T structure to the end of the array
    array->messages[array->size].tag = tag;
    array->messages[array->size].rrc_message = rrc_message;
    array->size++;
}

// Serialize the entire dynamic array into a binary file for offline analysis, ensuring compatibility with the tool's input format
void serialize_nfapi_message_array(nfapi_message_array_t *array, char *filename) {
    // Open the output file in binary mode
    FILE *output = fopen(filename, "wb");
    if (output == NULL) {
        printf("Error: unable to open output file %s\n", filename);
        return;
    }

    // Write the size of the array to the beginning of the file
    int32_t size = htonl(array->size);
    fwrite(&size, sizeof(int32_t), 1, output);

    // Serialize each element in the array and write it to the file
    for (int i = 0; i < array->size; i++) {
        nfapi_message_t *message = &array->messages[i];

        // Write the tag of the message to the file
        int32_t tag = htonl(message->tag);
        fwrite(&tag, sizeof(int32_t), 1, output);

        // Write the length of the RRC message buffer to the file
        int32_t length = htonl(strlen(message->rrc_message));
        fwrite(&length, sizeof(int32_t), 1, output);

        // Write the contents of the RRC message buffer to the file
        char *buffer = message->rrc_message;
        fwrite(buffer, length, 1, output);
    }

    // Close the output file
    fclose(output);
}

// Free the memory allocated by the dynamic array
void free_nfapi_message_array(nfapi_message_array_t *array) {
    for (int i = 0; i < array->size; i++) {
        nfapi_message_t *message = &array->messages[i];
        if (message->rrc_message != NULL) {
            free(message->rrc_message);
        }
    }
    free(array->messages);
    free(array);
}
