void nfapi_message_array_init(nfapi_message_array_t *array, size_t capacity) {
    array->messages = malloc(capacity * sizeof(nfapi_message_t));
    if (array->messages == NULL) {
        perror("Failed to allocate memory for NFAPI message array");
        exit(EXIT_FAILURE);
    }
    array->capacity = capacity;
    array->count = 0;
}

// Add a new element to the dynamic array
void nfapi_message_array_add(nfapi_message_array_t *array, int tag, int rrc_tag, char *buffer, size_t buffer_size) {
    if (array->count == array->capacity) {
        // Resize the array if it is full
        nfapi_message_array_resize(array);
    }
    array->messages[array->count].tag = tag;
    array->messages[array->count].rrc_tag = rrc_tag;
    array->messages[array->count].buffer = buffer;
    array->messages[array->count].buffer_size = buffer_size;
    array->count++;
}

// Resize the dynamic array to accommodate more elements
void nfapi_message_array_resize(nfapi_message_array_t *array) {
    // Double the capacity of the array
    size_t new_capacity = array->capacity * 2;
    nfapi_message_t *new_messages = realloc(array->messages, new_capacity * sizeof(nfapi_message_t));
    if (new_messages == NULL) {
        perror("Failed to resize NFAPI message array");
        exit(EXIT_FAILURE);
    }
    array->messages = new_messages;
    array->capacity = new_capacity;
}

// Serialize the dynamic array into a binary file
void nfapi_message_array_serialize(nfapi_message_array_t *array, const char *filename) {
    // Open the file for writing in binary mode
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for serialization");
        exit(EXIT_FAILURE);
    }
    // Write the number of elements in the array to the file
    size_t count = fwrite(&array->count, sizeof(size_t), 1, file);
    if (count != 1) {
        perror("Failed to write element count");
        exit(EXIT_FAILURE);
    }
    // Write each element of the array to the file
    for (size_t i = 0; i < array->count; i++) {
        nfapi_message_t *message = &array->messages[i];
        count = fwrite(message, sizeof(nfapi_message_t), 1, file);
        if (count != 1) {
            perror("Failed to write element");
            exit(EXIT_FAILURE);
        }
    }
    // Close the file
    fclose(file);
}

// Deserialize a binary file into the dynamic array
void nfapi_message_array_deserialize(nfapi_message_array_t *array, const char *filename) {
    // Open the file for reading in binary mode
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for deserialization");
        exit(EXIT_FAILURE);
    }
    // Read the number of elements from the file
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (ferror(file)) {
        perror("Failed to read element count");
        exit(EXIT_FAILURE);
    }
    // Resize the array to accommodate the number of elements
    nfapi_message_array_resize(array, count);
    // Read each element from the file and add it to the array
    for (size_t i = 0; i < count; i++) {
        nfapi_message_t *message = &array->messages[i];
        size_t read = fread(message, sizeof(nfapi_message_t), 1, file);
        if (ferror(file) || read != 1) {
            perror("Failed to read element");
            exit(EXIT_FAILURE);
        }
    }
    // Close the file
    fclose(file);
}

// Free all dynamically allocated resources in the dynamic array
void nfapi_message_array_free(nfapi_message_array_t *array) {
    for (size_t i = 0; i < array->count; i++) {
        free(array->messages[i].buffer);
    }
    free(array->messages);
}
