typedef struct {
    NFAPI_MESSAGE_T *elements; // Array of NFAPI_MESSAGE_T elements
    size_t capacity; // Capacity of the array in number of elements
    size_t count; // Number of elements currently stored in the array
} NFAPI_MESSAGE_ARRAY_T;

// Define a mutex for thread-safe access to the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the dynamic array of NFAPI_MESSAGE_T elements
void nfapi_message_array_init(NFAPI_MESSAGE_ARRAY_T *array) {
    // Allocate memory for the array and its elements
    array->elements = malloc(sizeof(NFAPI_MESSAGE_T) * 10);
    array->capacity = 10;
    array->count = 0;
}

// Function to add a new NFAPI_MESSAGE_T element to the dynamic array
void nfapi_message_array_add(NFAPI_MESSAGE_ARRAY_T *array, uint8_t *buffer, size_t size, uint32_t tag, uint32_t rrc_tag) {
    // Acquire the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Check if the array needs to be resized
    if (array->count == array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;
        array->elements = realloc(array->elements, sizeof(NFAPI_MESSAGE_T) * array->capacity);
    }

    // Add a new element to the array
    array->elements[array->count].buffer = buffer;
    array->elements[array->count].size = size;
    array->elements[array->count].tag = tag;
    array->elements[array->count].rrc_tag = rrc_tag;
    array->count++;

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

// Function to remove a NFAPI_MESSAGE_T element from the dynamic array
void nfapi_message_array_remove(NFAPI_MESSAGE_ARRAY_T *array, size_t index) {
    // Acquire the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index < array->count) {
        // Remove the element from the array
        memmove(array->elements + index, array->elements + index + 1, sizeof(NFAPI_MESSAGE_T) * (array->count - index));
        array->count--;
    }

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

// Function to serialize the entire dynamic array of NFAPI_MESSAGE_T elements into a binary file
void nfapi_message_array_serialize(NFAPI_MESSAGE_ARRAY_T *array, FILE *file) {
    // Acquire the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Write the number of elements in the array to the file
    fwrite(&array->count, sizeof(size_t), 1, file);

    // Iterate over each element in the array and serialize it
    for (size_t i = 0; i < array->count; i++) {
        NFAPI_MESSAGE_T *element = &array->elements[i];
        fwrite(&element->tag, sizeof(uint32_t), 1, file);
        fwrite(&element->rrc_tag, sizeof(uint32_t), 1, file);
        fwrite(element->buffer, element->size, 1, file);
    }

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

// Function to deserialize a binary file containing an array of NFAPI_MESSAGE_T elements and add them to the dynamic array
void nfapi_message_array_deserialize(NFAPI_MESSAGE_ARRAY_T *array, FILE *file) {
    // Acquire the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Read the number of elements in the file from the beginning of the file
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    // Iterate over each element in the file and deserialize it
    for (size_t i = 0; i < count; i++) {
        NFAPI_MESSAGE_T *element = malloc(sizeof(NFAPI_MESSAGE_T));
        fread(&element->tag, sizeof(uint32_t), 1, file);
        fread(&element->rrc_tag, sizeof(uint32_t), 1, file);
        element->size = fread(element->buffer, 1, sizeof(NFAPI_MESSAGE_T), file);
        nfapi_message_array_add(array, element->buffer, element->size, element->tag, element->rrc_tag);
    }

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

// Function to verify the integrity of the serialized data after deserialization by recalculating the checksums and comparing them to those stored in the binary file
void nfapi_message_array_verify(NFAPI_MESSAGE_ARRAY_T *array, FILE *file) {
    // Acquire the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Read the number of elements in the file from the beginning of the file
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    // Iterate over each element in the file and verify its integrity
    for (size_t i = 0; i < count; i++) {
        NFAPI_MESSAGE_T *element = &array->elements[i];
        uint32_t checksum = calculate_checksum(element->buffer, element->size);
        fseek(file, sizeof(uint32_t) * 2 + i * sizeof(NFAPI_MESSAGE_T), SEEK_SET);
        uint32_t stored_checksum;
        fread(&stored_checksum, sizeof(uint32_t), 1, file);
        if (checksum != stored_checksum) {
            printf("Checksum mismatch for element %zu\n", i);
        }
    }

    // Release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}
