} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(int numOffsets, int numKeys, NFAPI_CRC_INDICATION_PDU_T** existingRecords, void (*log_error)(const char*)) {
    // Allocate memory for the offsets array
    long* offsets = NULL;
    if (numOffsets > 0) {
        offsets = malloc(sizeof(long) * numOffsets);
        if (!offsets) {
            log_error("Failed to allocate memory for offsets");
            return NULL;
        }
        // Initialize the offsets array with sequential values starting from 0
        for (int i = 0; i < numOffsets; i++) {
            offsets[i] = i * sizeof(long);
        }
    }

    // Allocate memory for the keys array
    int* keys = NULL;
    if (numKeys > 0) {
        keys = malloc(sizeof(int) * numKeys);
        if (!keys) {
            log_error("Failed to allocate memory for keys");
            free(offsets);
            return NULL;
        }
        // Populate the keys array with unique random values within the range of 0 to 1000
        srand(time(NULL));
        for (int i = 0; i < numKeys; i++) {
            int key = rand() % 1000;
            while (key == keys[i]) {
                key = rand() % 1000;
            }
            keys[i] = key;
        }
    }

    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structures
    int numRecords = (numOffsets > numKeys) ? numOffsets : numKeys;
    NFAPI_CRC_INDICATION_PDU_T* records = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numRecords);
    if (!records) {
        log_error("Failed to allocate memory for CRC indication PDUs");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the CRCFLAG field of each structure randomly
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].CRCFLAG = rand() % 2;
    }

    // Integrate the newly allocated structures into the existingRecords array
    if (existingRecords && *existingRecords) {
        int existingSize = (*existingRecords)->numRecords;
        NFAPI_CRC_INDICATION_PDU_T* newRecords = realloc(*existingRecords, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (existingSize + numRecords));
        if (!newRecords) {
            log_error("Failed to reallocate memory for existing records");
            free(records);
            return NULL;
        }
        memcpy(&newRecords[existingSize], records, sizeof(NFAPI_CRC_INDICATION_PDU_T) * numRecords);
        *existingRecords = newRecords;
    } else {
        *existingRecords = records;
    }

    // Free the memory allocated for the offsets and keys arrays if they were not integrated into existingRecords
    if (numOffsets > numKeys) {
        free(offsets);
    }
    if (numKeys == 0) {
        free(keys);
    }

    return *existingRecords;
}
