        fwrite(struct_ptr, 1, sizeof(NFAPI_CRC_INDICATION_PDU_T), file);
    }

    // Close the file
    fclose(file);

    // Return success
    return true;
}

bool deserialize_crc_indication_list(const char *filename, NFAPI_CRC_INDICATION_LIST_T **list) {
    // Open the file for reading
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return false;
    }

    // Read the list size from the file
    size_t list_size;
    fread(&list_size, 1, sizeof(size_t), file);

    // Allocate memory for the list structure
    *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!*list) {
        return false;
    }

    // Initialize the list structure
    (*list)->data = malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*list)->data) {
        free(*list);
        return false;
    }
    (*list)->capacity = list_size;
    (*list)->count = 0;

    // Read the list data from the file
    for (size_t i = 0; i < list_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *struct_ptr = &(*list)->data[i];
        fread(struct_ptr, 1, sizeof(NFAPI_CRC_INDICATION_PDU_T), file);
    }

    // Close the file
    fclose(file);

    // Return success
    return true;
}
