LTEPHY_TransportChannelConfig* initTransportChannels(int numChannels) {
    // Allocate memory for the array of transport channel configurations
    LTEPHY_TransportChannelConfig* channels = (LTEPHY_TransportChannelConfig*)malloc(numChannels * sizeof(LTEPHY_TransportChannelConfig));
    if (!channels) {
        printf("Error: Failed to allocate memory for transport channel configurations\n");
        return NULL;
    }

    // Initialize the array of transport channel configurations
    for (int i = 0; i < numChannels; i++) {
        channels[i].id = i + 1;
        channels[i].bandwidthPartIdx = 0;
        channels[i].mcs = 0;
    }

    // Allocate memory for the corresponding physical layer buffers
    int bufferSize = 0;
    for (int i = 0; i < numChannels; i++) {
        bufferSize += getBufferSize(channels[i].bandwidthPartIdx);
    }
    void* buffers = malloc(bufferSize);
    if (!buffers) {
        printf("Error: Failed to allocate memory for physical layer buffers\n");
        free(channels);
        return NULL;
    }

    // Populate the array of transport channel configurations with the corresponding physical layer buffers
    int bufferIdx = 0;
    for (int i = 0; i < numChannels; i++) {
        channels[i].buffer = buffers + bufferIdx;
        bufferIdx += getBufferSize(channels[i].bandwidthPartIdx);
    }

    return channels;
}

// Function to release all allocated resources upon function completion
void releaseTransportChannels(LTEPHY_TransportChannelConfig* channels) {
    if (channels) {
        free(channels->buffer);
        free(channels);
    }
}

