#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the data structure for LTE_MME_MESSAGE_T
typedef struct {
    int eps_bearer_id;
    int mme_ue_s1ap_id;
    char* nas_message;
} LTE_MME_MESSAGE_T;

// Define the data structure for the in-memory data structure
typedef struct {
    LTE_MME_MESSAGE_T** messages;
    int size;
    pthread_mutex_t mutex;
} IN_MEMORY_DATA_STRUCTURE;

// Define the function to add a new message to the data structure
void add_message(IN_MEMORY_DATA_STRUCTURE* data, LTE_MME_MESSAGE_T* message) {
    // Acquire the mutex lock
    pthread_mutex_lock(&data->mutex);

    // Check if the message already exists in the data structure
    for (int i = 0; i < data->size; i++) {
        if (data->messages[i]->eps_bearer_id == message->eps_bearer_id &&
            data->messages[i]->mme_ue_s1ap_id == message->mme_ue_s1ap_id) {
            // If the message already exists, update it and release the mutex lock
            data->messages[i] = message;
            pthread_mutex_unlock(&data->mutex);
            return;
        }
    }

    // If the message does not exist, add it to the end of the data structure
    data->messages = realloc(data->messages, (data->size + 1) * sizeof(LTE_MME_MESSAGE_T*));
    data->messages[data->size] = message;
    data->size++;

    // Release the mutex lock
    pthread_mutex_unlock(&data->mutex);
}

// Define the function to update an existing message in the data structure
void update_message(IN_MEMORY_DATA_STRUCTURE* data, LTE_MME_MESSAGE_T* message) {
    // Acquire the mutex lock
    pthread_mutex_lock(&data->mutex);

    // Check if the message exists in the data structure
    for (int i = 0; i < data->size; i++) {
        if (data->messages[i]->eps_bearer_id == message->eps_bearer_id &&
            data->messages[i]->mme_ue_s1ap_id == message->mme_ue_s1ap_id) {
            // If the message exists, update it and release the mutex lock
            data->messages[i] = message;
            pthread_mutex_unlock(&data->mutex);
            return;
        }
    }

    // If the message does not exist, add it to the end of the data structure
    add_message(data, message);
}

// Define the function to remove a message from the data structure
void remove_message(IN_MEMORY_DATA_STRUCTURE* data, int eps_bearer_id, int mme_ue_s1ap_id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&data->mutex);

    // Check if the message exists in the data structure
    for (int i = 0; i < data->size; i++) {
        if (data->messages[i]->eps_bearer_id == eps_bearer_id &&
            data->messages[i]->mme_ue_s1ap_id == mme_ue_s1ap_id) {
            // If the message exists, remove it and release the mutex lock
            free(data->messages[i]);
            for (int j = i; j < data->size - 1; j++) {
                data->messages[j] = data->messages[j + 1];
            }
            data->size--;
            pthread_mutex_unlock(&data->mutex);
            return;
        }
    }

    // If the message does not exist, release the mutex lock
    pthread_mutex_unlock(&data->mutex);
}

// Define the function to retrieve a message from the data structure
LTE_MME_MESSAGE_T* get_message(IN_MEMORY_DATA_STRUCTURE* data, int eps_bearer_id, int mme_ue_s1ap_id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&data->mutex);

    // Check if the message exists in the data structure
    for (int i = 0; i < data->size; i++) {
        if (data->messages[i]->eps_bearer_id == eps_bearer_id &&
            data->messages[i]->mme_ue_s1ap_id == mme_ue_s1ap_id) {
            // If the message exists, return it and release the mutex lock
            LTE_MME_MESSAGE_T* message = data->messages[i];
            pthread_mutex_unlock(&data->mutex);
            return message;
        }
    }

    // If the message does not exist, release the mutex lock and return NULL
    pthread_mutex_unlock(&data->mutex);
    return NULL;
}

// Define the function to integrate with an external message broker
void integrate_with_message_broker(IN_MEMORY_DATA_STRUCTURE* data, char* message) {
    // Acquire the mutex lock
    pthread_mutex_lock(&data->mutex);

    // Check if the message exists in the data structure
    for (int i = 0; i < data->size; i++) {
        if (strcmp(data->messages[i]->nas_message, message) == 0) {
            // If the message exists, update it and release the mutex lock
            data->messages[i] = realloc(data->messages[i], sizeof(LTE_MME_MESSAGE_T));
            strcpy(data->messages[i]->nas_message, message);
            pthread_mutex_unlock(&data->mutex);
            return;
        }
    }

    // If the message does not exist, add it to the end of the data structure
    LTE_MME_MESSAGE_T* new_message = malloc(sizeof(LTE_MME_MESSAGE_T));
    strcpy(new_message->nas_message, message);
    add_message(data, new_message);

    // Release the mutex lock
    pthread_mutex_unlock(&data->mutex);
}
