import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class Hasher {
    private static final Logger LOGGER = Logger.getLogger(Hasher.class.getName());
    private static final int CACHE_SIZE = 15; // minutes
    private static final long CACHE_EXPIRATION = 60 * 1000L; // milliseconds
    private static final String DEFAULT_ALGORITHM = "MD5";
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public static String hash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance(DEFAULT_ALGORITHM);
            byte[] bytes = digest.digest(input.getBytes());
            return bytesToHex(bytes);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error hashing input: " + input, e);
            return null;
        }
    }

    public static String hashWithCache(String input) {
        String cachedHash = cache.get(input);
        if (cachedHash != null && isValid(cachedHash)) {
            LOGGER.info("Using cached hash for input: " + input);
            return cachedHash;
        } else {
            String newHash = hash(input);
            cache.put(input, newHash);
            return newHash;
        }
    }

    public static void clearCache() {
        cache.clear();
    }

    private static boolean isValid(String hash) {
        // Check if the hash is valid by comparing it to a known good hash
        // of an empty string, for example.
        return true;
    }

    public static void setLoggingEnabled(boolean enabled) {
        LOGGER.setLevel(enabled ? Level.INFO : Level.OFF);
    }
}
```
