// Structure to store frame processing statistics
typedef struct FrameProcessingStats {
    uint64_t timestamp; // Timestamp of the frame
    uint32_t frame_id; // Unique identifier for the frame
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu; // List of CRC indication PDUs
} FrameProcessingStats;

// Structure to store packet processing statistics
typedef struct PacketProcessingStats {
    uint64_t timestamp; // Timestamp of the packet
    uint32_t sequence_number; // Sequence number of the packet
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu; // CRC indication PDU for the packet
} PacketProcessingStats;

// Function to initialize and populate a linked list of FrameProcessingStats structures
void init_frame_processing_stats(FrameProcessingStats **head) {
    *head = NULL;
}

// Function to add a new frame processing statistics structure to the linked list
void add_frame_processing_stats(FrameProcessingStats **head, uint64_t timestamp, uint32_t frame_id) {
    FrameProcessingStats *new_frame = (FrameProcessingStats *)malloc(sizeof(FrameProcessingStats));
    new_frame->timestamp = timestamp;
    new_frame->frame_id = frame_id;
    new_frame->crc_indication_pdu = NULL;

    // Add the new frame to the linked list
    if (*head == NULL) {
        *head = new_frame;
    } else {
        FrameProcessingStats *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_frame;
    }
}

// Function to add a new packet processing statistics structure to the linked list of CRC indication PDUs
void add_packet_processing_stats(FrameProcessingStats *head, uint64_t timestamp, uint32_t sequence_number) {
    // Check if the frame exists in the linked list
    FrameProcessingStats *current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

    // If the frame does not exist, create a new one
    if (current == NULL) {
        add_frame_processing_stats(&head, timestamp, 0);
        current = head;
    }

    // Add the new packet to the linked list of CRC indication PDUs for the frame
    NFAPI_CRC_INDICATION_PDU_T *new_packet = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_packet->RX_UE_INFORMATION_TAG.rnti = 0; // Randomly set RNTI
    new_packet->CRC_INDICATION_REL8_TAG.crcFlag = 1; // Set CRCFlag to 1
    new_packet->sequenceNumber = sequence_number;

    if (current->crc_indication_pdu == NULL) {
        current->crc_indication_pdu = new_packet;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current_packet = current->crc_indication_pdu;
        while (current_packet->next != NULL) {
            current_packet = current_packet->next;
        }
        current_packet->next = new_packet;
    }
}

// Function to handle packet processing errors and log them appropriately
void handle_packet_processing_errors(FrameProcessingStats *head, uint64_t timestamp) {
    // Check if the frame exists in the linked list
    FrameProcessingStats *current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

    // If the frame does not exist, log an error message
    if (current == NULL) {
        printf("Error: Frame with timestamp %lu does not exist\n", timestamp);
    } else {
        // Log a message indicating that there was an error processing the packet
        printf("Error: Packet with sequence number %u in frame with timestamp %lu could not be processed\n", current->crc_indication_pdu->sequenceNumber, timestamp);
    }
}

// Function to handle successful packet processing and log it appropriately
void handle_successful_packet_processing(FrameProcessingStats *head, uint64_t timestamp) {
    // Check if the frame exists in the linked list
    FrameProcessingStats *current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

    // If the frame does not exist, log an error message
    if (current == NULL) {
        printf("Error: Frame with timestamp %lu does not exist\n", timestamp);
    } else {
        // Log a message indicating that the packet was processed successfully
        printf("Success: Packet with sequence number %u in frame with timestamp %lu was processed successfully\n", current->crc_indication_pdu->sequenceNumber, timestamp);
    }
}

// Function to handle frame start and log it appropriately
void handle_frame_start(FrameProcessingStats *head, uint64_t timestamp) {
    // Check if the frame exists in the linked list
    FrameProcessingStats *current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

    // If the frame does not exist, log an error message
    if (current == NULL) {
        printf("Error: Frame with timestamp %lu does not exist\n", timestamp);
    } else {
        // Log a message indicating that the frame has started
        printf("Frame start: Frame with timestamp %lu has started\n", timestamp);
    }
}

// Function to handle frame end and log it appropriately
void handle_frame_end(FrameProcessingStats *head, uint64_t timestamp) {
    // Check if the frame exists in the linked list
    FrameProcessingStats *current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

