    } else {
        // Log a message indicating that the frame has ended
        printf("Frame end: Frame with timestamp %lu has ended\n", timestamp);
    }
}

// Function to handle packet processing and update the linked list accordingly
void process_packet(FrameProcessingStats *head, uint64_t timestamp, uint32_t sequence_number) {
    // Check if the frame exists in the linked list
    FrameProcessingStats *current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

    // If the frame does not exist, log an error message and return
    if (current == NULL) {
        handle_packet_processing_errors(head, timestamp);
        return;
    }

    // Check if the packet exists in the linked list of CRC indication PDUs for the frame
    NFAPI_CRC_INDICATION_PDU_T *current_packet = current->crc_indication_pdu;
    while (current_packet != NULL) {
        if (current_packet->sequenceNumber == sequence_number) {
            break;
        }
        current_packet = current_packet->next;
    }

    // If the packet does not exist, log an error message and return
    if (current_packet == NULL) {
        handle_packet_processing_errors(head, timestamp);
        return;
    }

    // Update the linked list of CRC indication PDUs for the frame
    current->crc_indication_pdu = current_packet;

    // Log a message indicating that the packet was processed successfully
    handle_successful_packet_processing(head, timestamp);
}

// Function to handle frame processing and update the linked list accordingly
void process_frame(FrameProcessingStats *head, uint64_t timestamp) {
    // Check if the frame exists in the linked list
    FrameProcessingStats *current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

    // If the frame does not exist, log an error message and return
    if (current == NULL) {
        handle_frame_start(head, timestamp);
        return;
    }

    // Log a message indicating that the frame has started
    handle_frame_start(head, timestamp);

    // Process all packets in the linked list of CRC indication PDUs for the frame
    NFAPI_CRC_INDICATION_PDU_T *current_packet = current->crc_indication_pdu;
    while (current_packet != NULL) {
        process_packet(head, timestamp, current_packet->sequenceNumber);
        current_packet = current_packet->next;
    }

    // Log a message indicating that the frame has ended
    handle_frame_end(head, timestamp);
}

// Function to integrate with an external packet processing service and process packets asynchronously
void process_packets(FrameProcessingStats *head) {
    // Initialize the linked list of FrameProcessingStats structures
    init_frame_processing_stats(&head);

