    sem_t *sem = sem_open("/packet_processing_sem", O_CREAT, 0644, 1);

    // Create a thread to handle packet processing and update the linked list accordingly
    pthread_t thread;
    pthread_create(&thread, NULL, process_frame, head);

    // Loop indefinitely to receive packets from an external packet processing service
    while (1) {
