        uint64_t timestamp = 0;
        uint32_t sequence_number = 0;
        NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = NULL;

        // Handle the received packet and update the linked list accordingly
        process_packet(head, timestamp, sequence_number);

        // Signal the semaphore to release access to the linked list
        sem_post(sem);
    }
}
