// Function to dynamically manage a pool of MAC frames
void mac_frame_pool(MAC_FRAME *frame) {
    // Acquire the semaphore for accessing the pool
    if (sem_wait(&sem) == -1) {
        perror("Error waiting for semaphore");
        return;
    }

    // Check if the frame is valid
    if (!frame || !frame->header.valid || !frame->payload.valid || !frame->trailer.valid) {
