        return NULL;
    }

    // create a socket and connect to the server
    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (connect(sock, res->ai_addr, res->ai_addrlen) == -1) {
        printf("Error: DNS query failed with error %s\n", strerror(errno));
        return NULL;
    }

    // send a DNS query and receive the response
    char *query = "example.com";
    if (send(sock, query, strlen(query), 0) == -1) {
        printf("Error: DNS query failed with error %s\n", strerror(errno));
        return NULL;
    }

    char response[4096];
    int bytes = recv(sock, response, sizeof(response), 0);
    if (bytes == -1) {
        printf("Error: DNS query failed with error %s\n", strerror(errno));
        return NULL;
    }

    // parse the DNS response and extract the IP address
    struct addrinfo *result;
    err = getaddrinfo(response, NULL, &hints, &result);
    if (err != 0) {
        printf("Error: DNS query failed with error %s\n", gai_strerror(err));
        return NULL;
    }

    // store the IP address in the cache
    pthread_mutex_lock(&cache_mutex);
    if (cache_size < DNS_CACHE_MAX_ENTRIES) {
        cache[cache_size].hostname = hostname;
        cache[cache_size].ip = result->ai_addr->sa_data;
        cache_size++;
    } else {
        // purge the oldest entry from the cache if it is older than DNS_CACHE_TTL seconds
        time_t now = time(NULL);
        for (int i = 0; i < DNS_CACHE_MAX_ENTRIES; i++) {
            if (now - cache[i].timestamp > DNS_CACHE_TTL) {
                freeaddrinfo(cache[i].result);
                cache[i] = cache[DNS_CACHE_MAX_ENTRIES - 1];
                cache_size--;
                break;
            }
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // free the memory allocated by getaddrinfo()
    freeaddrinfo(result);

    return NULL;
}

