// Define the hash function for generating CRC indications
unsigned int crc_hash(const char *rx_ue_information_tag, const char *rnti) {
    unsigned int hash = 0;
    while (*rx_ue_information_tag != '\0') {
        hash = (hash << 5) - hash + *rx_ue_information_tag++;
    }
    while (*rnti != '\0') {
        hash = (hash << 5) - hash + *rnti++;
    }
    return hash;
}

