    int qos_params[3]; // QoS parameters for this session
    void* session_buffers; // Pointer to session-specific buffers
} USER_PLANE_SESSION_CONTEXT;

// Define the transport protocols supported by the function
#define TRANSPORT_PROTOCOL_TCP 1
#define TRANSPORT_PROTOCOL_UDP 2

// Define the error codes for the function
#define ERROR_CODE_SUCCESS 0
#define ERROR_CODE_FAILURE -1
#define ERROR_CODE_TRANSPORT_PROTOCOL_NOT_SUPPORTED -2
#define ERROR_CODE_SESSION_ID_ALREADY_EXISTS -3
#define ERROR_CODE_USER_IDENTITY_NOT_FOUND -4
#define ERROR_CODE_QOS_PARAMS_INVALID -5
#define ERROR_CODE_MEMORY_ALLOCATION_FAILED -6
#define ERROR_CODE_CONNECTION_ESTABLISHMENT_FAILED -7

// Define the logging mechanism for the function
void log_error(int error_code, char* message) {
    printf("[ERROR] %d: %s\n", error_code, message);
}

// Initialize a network session context and establish connections to remote peers
int initialize_network_session(USER_PLANE_SESSION_CONTEXT* session_context, int transport_protocol, char* user_identity, int qos_params[3]) {
    // Check if the transport protocol is supported
    if (transport_protocol != TRANSPORT_PROTOCOL_TCP && transport_protocol != TRANSPORT_PROTOCOL_UDP) {
        log_error(ERROR_CODE_TRANSPORT_PROTOCOL_NOT_SUPPORTED, "Unsupported transport protocol");
        return ERROR_CODE_FAILURE;
    }

    // Check if the session ID already exists
    int session_id = 0;
    while (session_id < MAX_SESSION_ID) {
        if (session_context[session_id].user_identity == NULL) {
            break;
        }
        session_id++;
    }
    if (session_id >= MAX_SESSION_ID) {
        log_error(ERROR_CODE_SESSION_ID_ALREADY_EXISTS, "Maximum number of sessions reached");
        return ERROR_CODE_FAILURE;
    }

    // Check if the user identity exists in the system
    char* user_identity_ptr = NULL;
    for (int i = 0; i < MAX_USERS; i++) {
        if (strcmp(user_identity, users[i].username) == 0) {
            user_identity_ptr = users[i].username;
            break;
        }
    }
    if (user_identity_ptr == NULL) {
        log_error(ERROR_CODE_USER_IDENTITY_NOT_FOUND, "User identity not found");
        return ERROR_CODE_FAILURE;
    }

    // Check if the QoS parameters are valid
    for (int i = 0; i < 3; i++) {
        if (qos_params[i] < MIN_QOS_PARAM || qos_params[i] > MAX_QOS_PARAM) {
            log_error(ERROR_CODE_QOS_PARAMS_INVALID, "Invalid QoS parameters");
            return ERROR_CODE_FAILURE;
        }
    }

    // Allocate memory for session-specific buffers
    void* session_buffers = malloc(sizeof(void*) * MAX_BUFFERS);
    if (session_buffers == NULL) {
        log_error(ERROR_CODE_MEMORY_ALLOCATION_FAILED, "Memory allocation failed");
        return ERROR_CODE_FAILURE;
    }

    // Establish connections to remote peers using the specified transport protocol
    int connection_established = 0;
    for (int i = 0; i < MAX_REMOTE_PEERS; i++) {
        if (strcmp(remote_peers[i].ip_address, "0.0.0.0") == 0) {
            continue;
        }
        int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (socket_fd < 0) {
            log_error(ERROR_CODE_CONNECTION_ESTABLISHMENT_FAILED, "Connection establishment failed");
            return ERROR_CODE_FAILURE;
        }
        struct sockaddr_in remote_peer_address = {
            .sin_family = AF_INET,
            .sin_port = htons(remote_peers[i].port),
            .sin_addr.s_addr = inet_addr(remote_peers[i].ip_address)
        };
        if (connect(socket_fd, (struct sockaddr*)&remote_peer_address, sizeof(struct sockaddr_in)) < 0) {
            log_error(ERROR_CODE_CONNECTION_ESTABLISHMENT_FAILED, "Connection establishment failed");
            return ERROR_CODE_FAILURE;
        }
        connection_established = 1;
    }

    // Initialize the USER_PLANE_SESSION_CONTEXT structure
    session_context[session_id].session_id = session_id;
    session_context[session_id].user_identity = user_identity_ptr;
    memcpy(session_context[session_id].qos_params, qos_params, sizeof(int) * 3);
    session_context[session_id].session_buffers = session_buffers;

    // Return success
    return ERROR_CODE_SUCCESS;
}
