        return NULL;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        return NULL;
    }

    // Initialize the array with random values for the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    srand(time(NULL));
    for (uint32_t i = 0; i < n; i++) {
