#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

// Define the structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the pool of structures to manage
#define MAX_STRUCTURES 1000
#define INITIAL_ALLOCATION 500
NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the pool of structures
void init_pool() {
    // Allocate memory for the initial allocation
    pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * INITIAL_ALLOCATION);
    if (!pool) {
        printf("Error: Failed to allocate memory for the pool\n");
        return;
    }

    // Initialize each structure in the pool
    for (int i = 0; i < INITIAL_ALLOCATION; i++) {
        pool[i].rx_ue_information.valid = false;
        pool[i].rnti = 0;
        pool[i].crc_indication_rel8.crflag = rand() % 2; // Randomly set CRCFLAG
    }
}

// Function to allocate a new structure in the pool
NFAPI_CRC_INDICATION_PDU_T *allocate_structure() {
    pthread_mutex_lock(&mutex);

    // Check if there are any free structures in the pool
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (!pool[i].rx_ue_information.valid) {
            pool[i].rx_ue_information.valid = true;
            pthread_mutex_unlock(&mutex);
            return &pool[i];
        }
    }

    // If no free structures are found, allocate more memory for the pool
    int new_allocation = MAX_STRUCTURES - INITIAL_ALLOCATION;
    NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_allocation);
    if (!new_pool) {
        printf("Error: Failed to allocate more memory for the pool\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize each structure in the newly allocated memory
    for (int i = INITIAL_ALLOCATION; i < new_allocation; i++) {
        new_pool[i].rx_ue_information.valid = false;
        new_pool[i].rnti = 0;
        new_pool[i].crc_indication_rel8.crflag = rand() % 2; // Randomly set CRCFLAG
    }

    pool = new_pool;
    pthread_mutex_unlock(&mutex);

    return &pool[INITIAL_ALLOCATION];
}

// Function to free a structure in the pool
void free_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&mutex);

    // Mark the structure as invalid
    structure->rx_ue_information.valid = false;

    pthread_mutex_unlock(&mutex);
}

// Function to periodically verify the integrity of the allocated structures
void verify_integrity() {
    pthread_mutex_lock(&mutex);

    // Check each structure in the pool for validity and correctness
    for (int i = 0; i < MAX_STRUCTURES; i++) {
