// Structure to represent a custom network event
typedef struct {
    time_t timestamp;
    int type;
    char* identifier;
} Event;

// Dynamic list of events
struct EventList {
    Event** events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

// Initialize the dynamic list of events
void event_list_init(EventList* list) {
    list->events = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new event to the dynamic list of events
void event_list_add(EventList* list, Event* event) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Check if the list needs to be resized
    if (list->count == list->capacity) {
        // Double the capacity of the list
        list->capacity *= 2;
        Event** new_events = realloc(list->events, list->capacity * sizeof(Event*));
        if (!new_events) {
            // Reallocation failed, free the old events and return
            for (size_t i = 0; i < list->count; ++i) {
                event_free(list->events[i]);
            }
            free(list->events);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->events = new_events;
    }

    // Add the new event to the list
    list->events[list->count++] = event;

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Remove an event from the dynamic list of events
void event_list_remove(EventList* list, Event* event) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Find the index of the event to remove
    size_t i = 0;
    for (; i < list->count && list->events[i] != event; ++i) {}

    // Check if the event was found in the list
    if (i == list->count) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Remove the event from the list
    --list->count;
    for (size_t j = i; j < list->count; ++j) {
        list->events[j] = list->events[j + 1];
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Prune old events based on a specified retention policy
void event_list_prune(EventList* list, int retention) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Iterate over the events and remove those that are older than the retention period
    for (size_t i = 0; i < list->count; ++i) {
        Event* event = list->events[i];
        if (difftime(time(NULL), event->timestamp) > retention) {
            // Remove the event from the list
            --list->count;
            for (size_t j = i; j < list->count; ++j) {
                list->events[j] = list->events[j + 1];
            }
        }
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}
