            num_concurrent_allocations++;
        }
    }
    if (num_concurrent_allocations > concurrency_limit) {
        printf("Error: Maximum number of concurrent allocations exceeded\n");
        return NULL;
    }

    // Monitor memory usage to avoid excessive consumption and trigger alerts if thresholds are exceeded
    size_t total_memory_usage = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements_to_allocate;
    if (total_memory_usage > 1024 * 1024 * 1024) { // 1 GB
        printf("Warning: Memory usage exceeds 1 GB\n");
