// Define the function to resolve a hostname using DNS resolution and handle errors gracefully
int resolve_hostname(const char* hostname, u_char* ip_address) {
    // Initialize variables for DNS resolution
    struct addrinfo hints, *res;
    int error;

    // Set up the hints for DNS resolution
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    // Perform DNS resolution with a timeout mechanism to prevent infinite requests during periods of high network latency
    error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error != 0) {
        printf("Error: %s\n", gai_strerror(error));
        return -1;
    }

    // Handle DNS resolution errors gracefully by logging an error message and returning an appropriate error code
    if (res == NULL) {
        printf("Error: No IP address found for hostname %s\n", hostname);
        freeaddrinfo(res);
        return -1;
    }

    // Copy the resolved IP address to the output parameter
    memcpy(ip_address, res->ai_addr, res->ai_addrlen);

    // Free the memory allocated for DNS resolution
    freeaddrinfo(res);

    return 0;
}

