        crc_indication_pdu[i].RNTI = min_rnti + (uint16_t)(rand() % (max_rnti - min_rnti));
    }

    // Set the CRCFLAG based on the configurable probability p
    for (size_t i = 0; i < num_elements; ++i) {
        if (p > ((double)rand() / RAND_MAX)) {
            crc_indication_pdu[i].CRCFLAG = true;
        }
    }

    // Validate the RNTIs to ensure they fall within the specified valid range
    for (size_t i = 0; i < num_elements; ++i) {
        if (crc_indication_pdu[i].RNTI < min_rnti || crc_indication_pdu[i].RNTI > max_rnti) {
            // Handle out-of-bounds RNTIs gracefully by logging an error message and setting the corresponding CRCFLAG to false
            printf("Error: RNTI %d is out of bounds (%d - %d)\n", crc_indication_pdu[i].RNTI, min_rnti, max_rnti);
            crc_indication_pdu[i].CRCFLAG = false;
        }
    }

