// Custom packet structure
struct Packet {
    int id;
    struct timeval timestamp;
    char* source_ip;
    char* dest_ip;
    int payload_len;
};

// List of packets
struct PacketList {
    struct Packet* packets[1024];
    int count;
    pthread_mutex_t mutex;
};

// Initialize and manage the list of packets
void initPackets(struct PacketList* list) {
    // Initialize the mutex
    pthread_mutex_init(&list->mutex, NULL);

    // Initialize the packet count
    list->count = 0;
}

// Add a new packet to the list
void addPacket(struct PacketList* list, struct Packet* packet) {
    // Acquire the mutex
    pthread_mutex_lock(&list->mutex);

    // Validate the payload length and IP addresses
    if (packet->payload_len < 0 || packet->source_ip == NULL || packet->dest_ip == NULL) {
        printf("Invalid packet: %d, %s, %s\n", packet->id, packet->source_ip, packet->dest_ip);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Add the packet to the list
    list->packets[list->count++] = packet;

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Remove a packet from the list
void removePacket(struct PacketList* list, int id) {
    // Acquire the mutex
    pthread_mutex_lock(&list->mutex);

    // Find the packet with the given ID
    struct Packet* packet = NULL;
    for (int i = 0; i < list->count; i++) {
        if (list->packets[i]->id == id) {
            packet = list->packets[i];
            break;
        }
    }

    // Remove the packet from the list
    if (packet != NULL) {
        for (int i = 0; i < list->count - 1; i++) {
            if (list->packets[i] == packet) {
                memmove(&list->packets[i], &list->packets[i + 1], sizeof(struct Packet*) * (list->count - i - 1));
                list->count--;
                break;
            }
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Get a packet from the list by ID
struct Packet* getPacket(struct PacketList* list, int id) {
    // Acquire the mutex
    pthread_mutex_lock(&list->mutex);

    // Find the packet with the given ID
    struct Packet* packet = NULL;
    for (int i = 0; i < list->count; i++) {
        if (list->packets[i]->id == id) {
            packet = list->packets[i];
            break;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);

    return packet;
}

// Free the memory allocated for the packets in the list
void freePackets(struct PacketList* list) {
    // Acquire the mutex
    pthread_mutex_lock(&list->mutex);

    // Free the memory allocated for each packet
    for (int i = 0; i < list->count; i++) {
        free(list->packets[i]);
    }

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}
