// Function to initialize a dynamic array of MAC_RX_FRAME structures
MAC_RX_FRAME* init_mac_frames(size_t num_frames, size_t max_frame_size) {
    // Allocate memory for the array of frames
    MAC_RX_FRAME** frames = malloc(num_frames * sizeof(MAC_RX_FRAME*));
    if (!frames) {
        return NULL;
    }

    // Initialize each frame with a valid header and payload
    for (size_t i = 0; i < num_frames; i++) {
        frames[i] = malloc(sizeof(MAC_RX_FRAME));
        if (!frames[i]) {
            free(frames);
            return NULL;
        }

        // Generate a random header for the frame
        MAC_HEADER* header = &frames[i]->header;
        header->src_addr = rand() % 256;
        header->dst_addr = rand() % 256;
        header->type = rand() % 256;

        // Generate a random payload for the frame
        MAC_PAYLOAD* payload = frames[i]->payload;
        size_t payload_size = rand() % max_frame_size;
        for (size_t j = 0; j < payload_size; j++) {
            payload[j] = rand() % 256;
        }
    }

    // Validate each frame by reconstructing it from its header and payload
    for (size_t i = 0; i < num_frames; i++) {
        MAC_RX_FRAME* frame = frames[i];
        MAC_HEADER* header = &frame->header;
        MAC_PAYLOAD* payload = frame->payload;
        size_t payload_size = sizeof(MAC_PAYLOAD) * (payload - frame->payload);
        if (!validate_mac_frame(header, payload, payload_size)) {
            free(frames[i]);
            frames[i] = NULL;
        }
    }

    // Handle potential race conditions when multiple threads access the shared resource simultaneously
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_frames; i++) {
        if (!frames[i]) {
            continue;
        }
        // Add the frame to the array of frames
        mac_frames = realloc(mac_frames, sizeof(MAC_RX_FRAME*) * (num_frames + 1));
        if (!mac_frames) {
            free(frames);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        mac_frames[num_frames] = frames[i];
        num_frames++;
    }
    pthread_mutex_unlock(&mutex);

    // Return the initialized array of frames
    return mac_frames;
}

// Function to validate a MAC frame by reconstructing it from its header and payload
bool validate_mac_frame(MAC_HEADER* header, MAC_PAYLOAD* payload, size_t payload_size) {
    // Reconstruct the frame from its header and payload
    MAC_RX_FRAME frame;
    memcpy(&frame.header, header, sizeof(MAC_HEADER));
    memcpy(frame.payload, payload, payload_size);

    // Validate the reconstructed frame by comparing it to its original representation
    if (memcmp(&frame, header, sizeof(MAC_RX_FRAME)) != 0) {
        return false;
    }

    // Return true if the frame is valid
    return true;
}
