// Define constants for supported bits per sample values
#define BITS_PER_SAMPLE_1 1
#define BITS_PER_SAMPLE_2 2
#define BITS_PER_SAMPLE_4 4
#define BITS_PER_SAMPLE_8 8
#define BITS_PER_SAMPLE_16 16

// Define constants for supported compression types
#define COMPRESSION_NONE 0
#define COMPRESSION_CCITT_RLE 32771
#define COMPRESSION_LZW 5
#define COMPRESSION_JPEG 6
#define COMPRESSION_DEFLATE 8
#define COMPRESSION_PACKBITS 32773
#define COMPRESSION_ADOBE_DEFLATE 10

// Define constants for supported byte orders
#define BYTE_ORDER_BIG_ENDIAN 0x4d4d
#define BYTE_ORDER_LITTLE_ENDIAN 0x4949

// Define structure to hold metadata information
typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int compressionType;
    int imageWidth;
    int imageHeight;
    int extraSamplesCount;
    char* extraSamples[10];
    int embeddedProfilesCount;
    char* embeddedProfiles[10];
} metadata_t;

// Define function to parse TIFF file and extract metadata
int parseTIFFMetadata(const char* filename, metadata_t* metadata) {
    // Open TIFF file for reading
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: unable to open TIFF file %s\n", filename);
        return 1;
    }

    // Read metadata from TIFF file
    uint32 width, height;
    uint16 samplesPerPixel, bitsPerSample;
    uint16 compressionType;
    uint32 extraSamplesCount = 0;
    char* extraSamples[10];
    uint32 embeddedProfilesCount = 0;
    char* embeddedProfiles[10];

    // Read image width and height
    if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width) == 0) {
        fprintf(stderr, "Error: unable to read image width\n");
        return 1;
    }
    if (TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height) == 0) {
        fprintf(stderr, "Error: unable to read image height\n");
        return 1;
    }

    // Read samples per pixel and bits per sample
    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) == 0) {
        fprintf(stderr, "Error: unable to read samples per pixel\n");
        return 1;
    }
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) == 0) {
        fprintf(stderr, "Error: unable to read bits per sample\n");
        return 1;
    }

    // Read compression type
    if (TIFFGetField(tif, TIFFTAG_COMPRESSION, &compressionType) == 0) {
        fprintf(stderr, "Error: unable to read compression type\n");
        return 1;
    }

    // Read extra samples
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamplesCount, extraSamples) == 0) {
        fprintf(stderr, "Error: unable to read extra samples\n");
        return 1;
    }

    // Read embedded profiles and ICC color spaces
    if (TIFFGetField(tif, TIFFTAG_EMBEDDEDPROFILES, &embeddedProfilesCount, embeddedProfiles) == 0) {
        fprintf(stderr, "Error: unable to read embedded profiles\n");
        return 1;
    }

    // Close TIFF file
    TIFFClose(tif);

    // Validate bits per sample value
    if (bitsPerSample != BITS_PER_SAMPLE_1 && bitsPerSample != BITS_PER_SAMPLE_2 && bitsPerSample != BITS_PER_SAMPLE_4 && bitsPerSample != BITS_PER_SAMPLE_8 && bitsPerSample != BITS_PER_SAMPLE_16) {
        fprintf(stderr, "Error: unsupported bits per sample value\n");
        return 1;
    }

    // Validate compression type
    if (compressionType != COMPRESSION_NONE && compressionType != COMPRESSION_CCITT_RLE && compressionType != COMPRESSION_LZW && compressionType != COMPRESSION_JPEG && compressionType != COMPRESSION_DEFLATE && compressionType != COMPRESSION_PACKBITS && compressionType != COMPRESSION_ADOBE_DEFLATE) {
        fprintf(stderr, "Error: unsupported compression type\n");
        return 1;
    }

    // Validate byte order
    uint16 byteOrder = TIFFGetByteOrder(tif);
    if (byteOrder != BYTE_ORDER_BIG_ENDIAN && byteOrder != BYTE_ORDER_LITTLE_ENDIAN) {
        fprintf(stderr, "Error: unsupported byte order\n");
        return 1;
    }

    // Fill metadata structure with extracted information
    metadata->bitsPerSample = bitsPerSample;
    metadata->samplesPerPixel = samplesPerPixel;
    metadata->compressionType = compressionType;
    metadata->imageWidth = width;
    metadata->imageHeight = height;
    metadata->extraSamplesCount = extraSamplesCount;
    for (int i = 0; i < extraSamplesCount; i++) {
        metadata->extraSamples[i] = extraSamples[i];
    }
    metadata->embeddedProfilesCount = embeddedProfilesCount;
    for (int i = 0; i < embeddedProfilesCount; i++) {
        metadata->embeddedProfiles[i] = embeddedProfiles[i];
    }

    return 0;
}
```
This code block defines a function `parseTIFFMetadata` that takes a filename as input and returns a structure of type `metadata_t` containing detailed information about the TIFF image's metadata. The function uses the `TIFFOpen`, `TIFFGetField`, and `TIFFClose` functions from the `libtiff` library to read the metadata from the TIFF file. It also validates the bits per sample value, compression type, and byte order to ensure that they are supported by the function.

The function returns an error code if any of these values are not supported or if there is an issue reading the metadata from the file. If the validation passes, the function fills the `metadata_t` structure with the extracted information and returns 0.

This code block also defines constants for the supported bits per sample values, compression types, and byte orders to ensure that they are used consistently throughout the function.']

