    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_crc_indication_pdu_list(int N, int RNTI_min, int RNTI_max) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!crc_indication_pdu_list) {
        printf("Error: Failed to allocate memory for crc_indication_pdu_list\n");
        return;
    }

    // Initialize the random number generator with a seed value
    srand(time(NULL));

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < N; i++) {
        // Generate a random RNTI value within the acceptable range
        int rnti = rand() % (RNTI_max - RNTI_min + 1) + RNTI_min;

        // Check if the generated RNTI value is already in the list
        bool duplicate = false;
        for (int j = 0; j < i; j++) {
            if (crc_indication_pdu_list[j].RNTI == rnti) {
                duplicate = true;
                break;
            }
        }

        // If the generated RNTI value is not a duplicate, add it to the list
        if (!duplicate) {
            crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG = 0;
            crc_indication_pdu_list[i].RNTI = rnti;
            crc_indication_pdu_list[i].CRCFLAG = rand() % 2;
        } else {
            // If the generated RNTI value is a duplicate, generate a new one and try again
            i--;
        }
    }

    // Sort the list of NFAPI_CRC_INDICATION_PDU_T structures by RNTI in ascending order
    qsort(crc_indication_pdu_list, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    // Free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(crc_indication_pdu_list);
}

// Define a comparison function to sort the list of NFAPI_CRC_INDICATION_PDU_T structures by RNTI in ascending order
int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *p1 = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *p2 = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return p1->RNTI - p2->RNTI;
