// Function to get the memory usage in bytes
size_t get_memory_usage() {
    // Get the current process ID
    pid_t pid = getpid();

    // Open the /proc/<PID>/status file
    FILE *fp = fopen("/proc/self/status", "r");
    if (!fp) {
        printf("Error opening /proc/self/status. Aborting.\n");
