    }

    // Set the IP address
    if (set_ip_address(interface_name, default_gateway->s_addr) < 0) {
        return -1;
    }

    // Set the subnet mask
    if (set_subnet_mask(interface_name, default_gateway->s_addr) < 0) {
        return -1;
    }

    // Set the default gateway
    if (set_default_gateway(interface_name, default_gateway->s_addr) < 0) {
        return -1;
    }

    return 0;
}

// Function to get the IP address of a network interface
struct in_addr get_ip_address(char *interface_name) {
    // Get the IP address from the system
    struct ifreq ifr;
    strcpy(ifr.ifr_name, interface_name);
    ioctl(sockfd, SIOCGIFADDR, &ifr);

    return ifr.ifr_addr;
}

// Function to get the subnet mask of a network interface
struct in_addr get_subnet_mask(char *interface_name) {
    // Get the subnet mask from the system
    struct ifreq ifr;
    strcpy(ifr.ifr_name, interface_name);
    ioctl(sockfd, SIOCGIFNETMASK, &ifr);

    return ifr.ifr_addr;
}

// Function to get the default gateway of a network interface
struct in_addr get_default_gateway() {
    // Get the default gateway from the system
    struct rtentry rt;
    ioctl(sockfd, SIOCGRT, &rt);

    return rt.rt_gateway;
}

// Function to set the interface type of a network interface
int set_interface_type(char *interface_name, int interface_type) {
    // Set the interface type on the system
    struct ifreq ifr;
    strcpy(ifr.ifr_name, interface_name);
    ifr.ifr_flags = interface_type;
    ioctl(sockfd, SIOCSIFFLAGS, &ifr);
}

// Function to set the IP address of a network interface
int set_ip_address(char *interface_name, struct in_addr ip_address) {
    // Set the IP address on the system
    struct ifreq ifr;
    strcpy(ifr.ifr_name, interface_name);
    ifr.ifr_addr = ip_address;
    ioctl(sockfd, SIOCSIFADDR, &ifr);
}

// Function to set the subnet mask of a network interface
int set_subnet_mask(char *interface_name, struct in_addr subnet_mask) {
    // Set the subnet mask on the system
    struct ifreq ifr;
    strcpy(ifr.ifr_name, interface_name);
    ifr.ifr_netmask = subnet_mask;
    ioctl(sockfd, SIOCSIFNETMASK, &ifr);
}

// Function to set the default gateway of a network interface
int set_default_gateway(char *interface_name, struct in_addr default_gateway) {
    // Set the default gateway on the system
    struct rtentry rt;
    strcpy(rt.rt_dev, interface_name);
    rt.rt_dst = 0;
    rt.rt_gateway = default_gateway;
    ioctl(sockfd, SIOCADDRT, &rt);
}

// Function to validate a network interface configuration
int validate_network_interface_config(struct NetworkInterfaceConfig *config) {
    // Check if the interface type is valid
    if (config->interface_type != INTERFACE_TYPE_ETHERNET && config->interface_type != INTERFACE_TYPE_WIFI) {
        return -1;
    }

    // Check if the IP address is valid
    if (!is_valid_ip_address(config->ip_address)) {
        return -1;
    }

    // Check if the subnet mask is valid
    if (!is_valid_subnet_mask(config->subnet_mask)) {
        return -1;
    }

    // Check if the default gateway is valid
    if (!is_valid_default_gateway(config->default_gateway)) {
        return -1;
    }

    return 0;
}

// Function to validate an IP address
int is_valid_ip_address(struct in_addr ip_address) {
    // Check if the IP address is valid
    if (inet_pton(AF_INET, "192.168.1.1", &ip_address) != 1) {
        return -1;
    }

    return 0;
}

// Function to validate a subnet mask
int is_valid_subnet_mask(struct in_addr subnet_mask) {
    // Check if the subnet mask is valid
    if (inet_pton(AF_INET, "255.255.255.0", &subnet_mask) != 1) {
        return -1;
    }

    return 0;
}

// Function to validate a default gateway
int is_valid_default_gateway(struct in_addr default_gateway) {
    // Check if the default gateway is valid
    if (inet_pton(AF_INET, "192.168.1.1", &default_gateway) != 1) {
        return -1;
    }

    return 0;
}
