    int num_interfaces;
    struct in_addr ips[MAX_IPS];
    int num_ips;
    struct in_addr subnets[MAX_SUBNETS];
    int num_subnets;
};

struct configuration config;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_configuration() {
    // Initialize the configuration structure with default values
    for (int i = 0; i < MAX_INTERFACES; i++) {
        config.interfaces[i].name[0] = '\0';
        config.interfaces[i].ip.s_addr = INADDR_ANY;
        config.interfaces[i].subnet = 0;
    }
    config.num_interfaces = 0;
    for (int i = 0; i < MAX_IPS; i++) {
        config.ips[i].s_addr = INADDR_ANY;
    }
    config.num_ips = 0;
    for (int i = 0; i < MAX_SUBNETS; i++) {
        config.subnets[i].s_addr = INADDR_ANY;
    }
    config.num_subnets = 0;
}

void apply_configuration() {
    // Apply the configuration to all interfaces
    for (int i = 0; i < config.num_interfaces; i++) {
        struct interface *interface = &config.interfaces[i];
        if (interface->name[0] != '\0') {
            // Set the IP address and subnet mask on the interface
            int ret = set_ip_address(interface->name, interface->ip);
            if (ret < 0) {
                printf("Error setting IP address for interface %s: %s\n", interface->name, strerror(errno));
            }
            ret = set_subnet_mask(interface->name, interface->subnet);
            if (ret < 0) {
                printf("Error setting subnet mask for interface %s: %s\n", interface->name, strerror(errno));
            }
        }
    }
}

void detect_conflicts() {
    // Detect conflicts between interfaces sharing the same subnet
    for (int i = 0; i < config.num_interfaces - 1; i++) {
        struct interface *interface1 = &config.interfaces[i];
        if (interface1->subnet != 0) {
            for (int j = i + 1; j < config.num_interfaces; j++) {
                struct interface *interface2 = &config.interfaces[j];
                if (interface2->subnet == interface1->subnet) {
                    // Detect conflict and reallocate addresses if necessary
                    printf("Conflict detected between interfaces %s and %s on subnet %d\n", interface1->name, interface2->name, interface1->subnet);
                    int ret = reallocate_addresses(interface1, interface2);
                    if (ret < 0) {
                        printf("Error reallocating addresses for interfaces %s and %s: %s\n", interface1->name, interface2->name, strerror(errno));
                    }
                }
            }
        }
    }
}

void allocate_addresses() {
    // Allocate IP addresses to interfaces based on availability of public and private subnets
    for (int i = 0; i < config.num_interfaces; i++) {
        struct interface *interface = &config.interfaces[i];
        if (interface->subnet == 0) {
            // Allocate IP address from public subnet
            int ret = allocate_public_address(interface);
            if (ret < 0) {
                printf("Error allocating public IP address for interface %s: %s\n", interface->name, strerror(errno));
            }
        } else {
            // Allocate IP address from private subnet
            int ret = allocate_private_address(interface);
            if (ret < 0) {
                printf("Error allocating private IP address for interface %s: %s\n", interface->name, strerror(errno));
            }
        }
    }
}

void apply_configurations() {
    // Apply configurations to all interfaces
    for (int i = 0; i < config.num_interfaces; i++) {
        struct interface *interface = &config.interfaces[i];
        if (interface->name[0] != '\0') {
            // Set the IP address and subnet mask on the interface
            int ret = set_ip_address(interface->name, interface->ip);
            if (ret < 0) {
                printf("Error setting IP address for interface %s: %s\n", interface->name, strerror(errno));
            }
            ret = set_subnet_mask(interface->name, interface->subnet);
            if (ret < 0) {
                printf("Error setting subnet mask for interface %s: %s\n", interface->name, strerror(errno));
            }
        }
    }
}

void monitor_configurations() {
    // Monitor configuration success rates and error occurrences
    for (int i = 0; i < config.num_interfaces; i++) {
        struct interface *interface = &config.interfaces[i];
        if (interface->name[0] != '\0') {
            // Check the status of the interface and log any errors
            int ret = check_interface(interface->name);
            if (ret < 0) {
                printf("Error checking interface %s: %s\n", interface->name, strerror(errno));
            }
        }
    }
}

int main() {
    // Initialize the configuration structure and apply configurations to all interfaces
    initialize_configuration();
    apply_configurations();

    // Detect conflicts between interfaces sharing the same subnet and reallocate addresses if necessary
    detect_conflicts();

    // Allocate IP addresses to interfaces based on availability of public and private subnets
    allocate_addresses();

    // Apply configurations to all interfaces
    apply_configurations();

    // Monitor configuration success rates and error occurrences
    monitor_configurations();

    return 0;
}
