#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the session structure
struct Session {
    int user_id;
    char* session_token;
    time_t expiration_time;
    time_t last_activity_timestamp;
};

// Define the session cache structure
struct SessionCache {
    struct Session* sessions[1024]; // 1024 is a reasonable size for most use cases
    int num_sessions;
    pthread_mutex_t mutex;
};

// Initialize the session cache
void init_session_cache(struct SessionCache* cache) {
    cache->num_sessions = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add a new session to the cache
int add_session(struct SessionCache* cache, struct Session* session) {
    int ret = -1;
    pthread_mutex_lock(&cache->mutex);
    if (cache->num_sessions < 1024) {
        cache->sessions[cache->num_sessions++] = session;
        ret = 0;
    }
    pthread_mutex_unlock(&cache->mutex);
    return ret;
}

// Remove an expired session from the cache
int remove_expired_session(struct SessionCache* cache) {
    int ret = -1;
    struct Session* session = NULL;
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->num_sessions; i++) {
        if (cache->sessions[i]->expiration_time <= time(NULL)) {
            session = cache->sessions[i];
            break;
        }
    }
    if (session != NULL) {
        for (int i = 0; i < cache->num_sessions - 1; i++) {
            if (cache->sessions[i] == session) {
                memmove(&cache->sessions[i], &cache->sessions[i + 1], sizeof(struct Session*) * (cache->num_sessions - i - 1));
                cache->num_sessions--;
                ret = 0;
            }
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return ret;
}

// Get a session from the cache by user ID
struct Session* get_session(struct SessionCache* cache, int user_id) {
    struct Session* session = NULL;
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->num_sessions; i++) {
        if (cache->sessions[i]->user_id == user_id) {
            session = cache->sessions[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return session;
}

// Update the last activity timestamp of a session in the cache
int update_last_activity(struct SessionCache* cache, struct Session* session) {
    int ret = -1;
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->num_sessions; i++) {
        if (cache->sessions[i] == session) {
            cache->sessions[i]->last_activity_timestamp = time(NULL);
            ret = 0;
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return ret;
}

// Persist a session to disk
int persist_session(struct Session* session) {
    int fd = open("sessions.dat", O_CREAT | O_RDWR, 0644);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    struct stat st;
    fstat(fd, &st);
    off_t offset = lseek(fd, 0, SEEK_END);
    if (offset < 0) {
        perror("lseek");
        return -1;
    }
    size_t bytes_written = write(fd, session, sizeof(struct Session));
    if (bytes_written != sizeof(struct Session)) {
        perror("write");
        return -1;
    }
    close(fd);
    return 0;
}

// Load a session from disk
int load_session(struct Session* session) {
    int fd = open("sessions.dat", O_RDONLY, 0644);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    struct stat st;
    fstat(fd, &st);
    off_t offset = lseek(fd, 0, SEEK_SET);
    if (offset < 0) {
        perror("lseek");
        return -1;
    }
    size_t bytes_read = read(fd, session, sizeof(struct Session));
    if (bytes_read != sizeof(struct Session)) {
        perror("read");
        return -1;
    }
    close(fd);
    return 0;
}

// Evict expired sessions from the cache and persist them to disk
void evict_expired_sessions() {
    struct SessionCache* cache = get_session_cache();
    while (remove_expired_session(cache) == 0) {}
    for (int i = 0; i < cache->num_sessions; i++) {
        persist_session(cache->sessions[i]);
    }
}

// Load all sessions from disk and add them to the cache
void load_all_sessions() {
    struct SessionCache* cache = get_session_cache();
    for (int i = 0; i < 1024; i++) {
        struct Session session;
        if (load_session(&session) == 0) {
            add_session(cache, &session);
        }
    }
}

// Initialize the session cache and load all sessions from disk
void init_sessions() {
    struct SessionCache* cache = get_session_cache();
    init_session_cache(cache);
    load_all_sessions();
}

// Clean up the session cache and persist all sessions to disk
void cleanup_sessions() {
    struct SessionCache* cache = get_session_cache();
    for (int i = 0; i < cache->num_sessions; i++) {
        persist_session(cache->sessions[i]);
    }
}
```
