#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

#define MAX_NFAPI_INTERFACES 10
#define NFAPI_CRC_INDICATION_PDU_T struct { \
    uint32_t rx_ue_information_tag; \
    uint32_t rnti; \
    uint32_t crc_indication_rel8_tag; \
}

struct nfapi_interface_manager {
    int num_interfaces;
    struct nfapi_interface *interfaces[MAX_NFAPI_INTERFACES];
};

struct nfapi_interface {
    char ip_address[INET6_ADDRSTRLEN];
    uint32_t subnet_mask;
    uint32_t gateway;
    struct in_addr *ipv4_addr;
    struct in6_addr *ipv6_addr;
};

struct nfapi_interface_manager *nfapi_interface_manager_init(int num_interfaces) {
    if (num_interfaces > MAX_NFAPI_INTERFACES) {
        return NULL;
    }
    struct nfapi_interface_manager *manager = malloc(sizeof(struct nfapi_interface_manager));
    manager->num_interfaces = num_interfaces;
    for (int i = 0; i < num_interfaces; i++) {
        manager->interfaces[i] = malloc(sizeof(struct nfapi_interface));
    }
    return manager;
}

void nfapi_interface_manager_destroy(struct nfapi_interface_manager *manager) {
    for (int i = 0; i < manager->num_interfaces; i++) {
        free(manager->interfaces[i]);
    }
    free(manager);
}

void nfapi_interface_manager_configure(struct nfapi_interface_manager *manager, int interface_index, char *ip_address, uint32_t subnet_mask, uint32_t gateway) {
    struct in_addr ipv4_addr;
    struct in6_addr ipv6_addr;
    if (inet_pton(AF_INET, ip_address, &ipv4_addr) == 1) {
        manager->interfaces[interface_index]->ipv4_addr = malloc(sizeof(struct in_addr));
        memcpy(manager->interfaces[interface_index]->ipv4_addr, &ipv4_addr, sizeof(struct in_addr));
    } else if (inet_pton(AF_INET6, ip_address, &ipv6_addr) == 1) {
        manager->interfaces[interface_index]->ipv6_addr = malloc(sizeof(struct in6_addr));
        memcpy(manager->interfaces[interface_index]->ipv6_addr, &ipv6_addr, sizeof(struct in6_addr));
    } else {
        return;
    }
    manager->interfaces[interface_index]->subnet_mask = subnet_mask;
    manager->interfaces[interface_index]->gateway = gateway;
}

void nfapi_interface_manager_start(struct nfapi_interface_manager *manager) {
    for (int i = 0; i < manager->num_interfaces; i++) {
        if (manager->interfaces[i]->ipv4_addr != NULL) {
            struct sockaddr_in server_address;
            memset(&server_address, 0, sizeof(struct sockaddr_in));
            server_address.sin_family = AF_INET;
            server_address.sin_port = htons(5000);
            inet_pton(AF_INET, manager->interfaces[i]->ipv4_addr, &server_address.sin_addr);
            int sockfd = socket(AF_INET, SOCK_STREAM, 0);
            if (sockfd < 0) {
                perror("socket");
                return;
            }
            if (bind(sockfd, (struct sockaddr *)&server_address, sizeof(struct sockaddr)) < 0) {
                perror("bind");
                close(sockfd);
                return;
            }
            if (listen(sockfd, 3) < 0) {
                perror("listen");
                close(sockfd);
                return;
            }
        } else if (manager->interfaces[i]->ipv6_addr != NULL) {
            struct sockaddr_in6 server_address;
            memset(&server_address, 0, sizeof(struct sockaddr_in6));
            server_address.sin6_family = AF_INET6;
            server_address.sin6_port = htons(5000);
            inet_pton(AF_INET6, manager->interfaces[i]->ipv6_addr, &server_address.sin6_addr);
            int sockfd = socket(AF_INET6, SOCK_STREAM, 0);
            if (sockfd < 0) {
                perror("socket");
                return;
            }
            if (bind(sockfd, (struct sockaddr *)&server_address, sizeof(struct sockaddr)) < 0) {
                perror("bind");
                close(sockfd);
                return;
            }
            if (listen(sockfd, 3) < 0) {
                perror("listen");
                close(sockfd);
                return;
            }
        } else {
            continue;
        }
    }
}

void nfapi_interface_manager_stop(struct nfapi_interface_manager *manager) {
    for (int i = 0; i < manager->num_interfaces; i++) {
        if (manager->interfaces[i]->ipv4_addr != NULL) {
            close(manager->interfaces[i]->sockfd);
        } else if (manager->interfaces[i]->ipv6_addr != NULL) {
            close(manager->interfaces[i]->sockfd);
        } else {
            continue;
        }
    }
}

void nfapi_interface_manager_update(struct nfapi_interface_manager *manager, int interface_index, char *ip_address, uint32_t subnet_mask, uint32_t gateway) {
    if (interface_index >= manager->num_interfaces || interface_index < 0) {
        return;
    }
    nfapi_interface_manager_stop(manager);
    nfapi_interface_manager_configure(manager, interface_index, ip_address, subnet_mask, gateway);
    nfapi_interface_manager_start(manager);
}

void nfapi_interface_manager_add(struct nfapi_interface_manager *manager, char *ip_address, uint32_t subnet_mask, uint32_t gateway) {
    if (manager->num_interfaces >= MAX_NFAPI_INTERFACES) {
        return;
    }
    manager->num_interfaces++;
    nfapi_interface_manager_configure(manager, manager->num_interfaces - 1, ip_address, subnet_mask, gateway);
    nfapi_interface_manager_start(manager);
}

void nfapi_interface_manager_remove(struct nfapi_interface_manager *manager, int interface_index) {
    if (interface_index >= manager->num_interfaces || interface_index < 0) {
        return;
    }
    nfapi_interface_manager_stop(manager);
    for (int i = interface_index; i < manager->num_interfaces - 1; i++) {
        memcpy(&manager->interfaces[i], &manager->interfaces[i + 1], sizeof(struct nfapi_interface));
    }
    manager->num_interfaces--;
}
