const WebSocket = require('ws');
const http = require('http');
const express = require('express');
const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Caching strategy
const cache = {};

// Memory management
const maxCacheSize = 1000; // Maximum number of cached data points
let currentCacheSize = 0;

// Concurrent client connections
const concurrentClients = [];

// Persistent storage and retrieval operations
const db = require('./db');

// Handle incoming WebSocket messages
wss.on('connection', (ws) => {
  // Add the new client to the list of concurrent clients
  concurrentClients.push(ws);

  // Handle incoming data from the client
  ws.on('message', (data) => {
    const sensorData = JSON.parse(data);
    const cacheKey = `${sensorData.id}-${sensorData.timestamp}`;

    // Check if the data point is already in the cache
    if (cache[cacheKey]) {
      // If it's in the cache, update its value and return it
      cache[cacheKey].value = sensorData.value;
      ws.send(JSON.stringify({ type: 'update', data: cache[cacheKey] }));
    } else {
      // If it's not in the cache, add it to the cache and return it
      const newCacheEntry = { id: sensorData.id, timestamp: sensorData.timestamp, value: sensorData.value };
      cache[cacheKey] = newCacheEntry;
      ws.send(JSON.stringify({ type: 'new', data: newCacheEntry }));
    }
  });

  // Handle client disconnections
  ws.on('close', () => {
    // Remove the client from the list of concurrent clients
    const index = concurrentClients.indexOf(ws);
    if (index > -1) {
      concurrentClients.splice(index, 1);
    }
  });
});

// Handle network interruptions gracefully
wss.on('error', (err) => {
  console.log(`WebSocket error: ${err}`);
});

// Optimize for both initial load times and sustained performance under heavy load conditions
app.use(express.json());
server.listen(3000, () => {
  console.log('Server started on port 3000');
});
```
This code creates a WebSocket server using the `ws` module, and sets up a caching strategy to optimize data retrieval and processing. It also manages memory usage efficiently by keeping track of the number of cached data points and removing old entries when necessary. The system can handle network interruptions gracefully by logging any errors that occur during WebSocket communication. Additionally, it optimizes for both initial load times and sustained performance under heavy load conditions by using `express.json()` to parse incoming JSON data and `server.listen()` to start the server on port 3000."]

