    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

// Define a function to initialize the list with a given initial size
void nfapi_crc_indication_pdu_list_init(NFAPI_CRC_INDICATION_PDU_LIST_T* list, int N) {
    // Validate input
    if (N < 0) {
        printf("Error: Invalid initial size for CRC indication PDU list\n");
        return;
    }

    // Allocate memory for the list and its data
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (list->data == NULL) {
        printf("Error: Failed to allocate memory for CRC indication PDU list\n");
        return;
    }

    // Initialize the size and capacity of the list
    list->size = 0;
    list->capacity = N;
}

// Define a function to insert a new CRC flag into the list
void nfapi_crc_indication_pdu_list_insert(NFAPI_CRC_INDICATION_PDU_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T crc) {
    // Validate input
    if (list == NULL || crc.length < 0) {
        printf("Error: Invalid CRC flag for insertion into CRC indication PDU list\n");
        return;
    }

    // Check if the list needs to be resized
    if (list->size == list->capacity) {
        // Double the capacity of the list
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_data == NULL) {
            printf("Error: Failed to resize CRC indication PDU list\n");
            return;
        }

        // Update the size and capacity of the list
        list->size = list->size + 1;
        list->capacity = new_capacity;
        list->data = new_data;
    } else {
        // Insert the new CRC flag into the list
        list->data[list->size] = crc;
        list->size = list->size + 1;
    }
}

// Define a function to remove a CRC flag from the list
void nfapi_crc_indication_pdu_list_remove(NFAPI_CRC_INDICATION_PDU_LIST_T* list, int index) {
    // Validate input
    if (list == NULL || index < 0 || index >= list->size) {
        printf("Error: Invalid index for removal from CRC indication PDU list\n");
        return;
    }

    // Shift the elements after the removed element to the left
    for (int i = index + 1; i < list->size; i++) {
        list->data[i - 1] = list->data[i];
    }

    // Decrement the size of the list
    list->size--;
}

// Define a function to retrieve a CRC flag from the list by index
NFAPI_CRC_INDICATION_PDU_T nfapi_crc_indication_pdu_list_get(NFAPI_CRC_INDICATION_PDU_LIST_T* list, int index) {
