#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the maximum number of ciphers that can be initialized concurrently
#define MAX_CIPHERS 1024

// Define the size of the key and IV for each cipher instance
#define KEY_SIZE 32
#define IV_SIZE 16

// Define the maximum number of iterations for PBKDF2
#define MAX_ITERATIONS 20000

// Define the PRF used in PBKDF2
#define PRF SHA256

// Define the error codes for the function
#define ERR_INVALID_ID -1
#define ERR_INVALID_PASSWORD -2
#define ERR_INVALID_SALT -3
#define ERR_MEMORY_ALLOCATION -4
#define ERR_KEY_DERIVATION -5
#define ERR_IV_GENERATION -6
#define ERR_CIPHER_INITIALIZATION -7
#define ERR_RESOURCE_CLEANUP -8

// Define the structure for storing the cipher contexts and keys
typedef struct {
    AES_KEY key;
    unsigned char iv[IV_SIZE];
} CipherContext;

// Define the function to initialize a new cipher instance
int initCipher(unsigned int id, const char* password, const char* salt) {
    // Validate the input parameters
    if (id >= MAX_CIPHERS || strlen(password) < 1 || strlen(salt) < 1) {
        return ERR_INVALID_ID;
    }

    // Derive the key and IV for the cipher instance
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
    if (PBKDF2(key, sizeof(key), iv, sizeof(iv), password, strlen(password), salt, strlen(salt), PRF, MAX_ITERATIONS) != 1) {
        return ERR_KEY_DERIVATION;
    }

    // Initialize the AES-256-CBC cipher for encryption and decryption
    CipherContext* ctx = malloc(sizeof(CipherContext));
    if (ctx == NULL) {
        return ERR_MEMORY_ALLOCATION;
    }
    if (AES_set_encrypt_key(key, 256, &ctx->key) != 1 || AES_set_decrypt_key(key, 256, &ctx->key) != 1) {
        return ERR_CIPHER_INITIALIZATION;
    }
    memcpy(ctx->iv, iv, IV_SIZE);

    // Store the cipher context and key in a global array
    CipherContext* ctxs[MAX_CIPHERS];
    if (ctxs[id] != NULL) {
        return ERR_RESOURCE_CLEANUP;
    }
    ctxs[id] = ctx;

    // Return success
    return 0;
}

// Define the function to encrypt a data stream using a specific cipher instance
int encrypt(unsigned int id, const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext) {
    // Validate the input parameters
    if (id >= MAX_CIPHERS || plaintext == NULL || plaintext_len < 1 || ciphertext == NULL) {
        return ERR_INVALID_ID;
    }

    // Retrieve the cipher context and key for the specified cipher instance
    CipherContext* ctx = ctxs[id];
    if (ctx == NULL) {
        return ERR_RESOURCE_CLEANUP;
    }

    // Encrypt the data stream using AES-256-CBC
    size_t ciphertext_len = 0;
    if (AES_cbc_encrypt(plaintext, ciphertext, plaintext_len, &ctx->key, ctx->iv, &ciphertext_len, NULL) != 1) {
        return ERR_CIPHER_INITIALIZATION;
    }

    // Return the length of the encrypted data stream
    return ciphertext_len;
}

// Define the function to decrypt a data stream using a specific cipher instance
int decrypt(unsigned int id, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
    // Validate the input parameters
    if (id >= MAX_CIPHERS || ciphertext == NULL || ciphertext_len < 1 || plaintext == NULL) {
        return ERR_INVALID_ID;
    }

    // Retrieve the cipher context and key for the specified cipher instance
    CipherContext* ctx = ctxs[id];
    if (ctx == NULL) {
        return ERR_RESOURCE_CLEANUP;
    }

    // Decrypt the data stream using AES-256-CBC
    size_t plaintext_len = 0;
    if (AES_cbc_decrypt(ciphertext, plaintext, ciphertext_len, &ctx->key, ctx->iv, &plaintext_len, NULL) != 1) {
        return ERR_CIPHER_INITIALIZATION;
    }

    // Return the length of the decrypted data stream
    return plaintext_len;
}

// Define the function to disable and clean up a specific cipher instance
int disableCipher(unsigned int id) {
    // Validate the input parameter
    if (id >= MAX_CIPHERS) {
        return ERR_INVALID_ID;
    }

    // Retrieve the cipher context and key for the specified cipher instance
    CipherContext* ctx = ctxs[id];
    if (ctx == NULL) {
        return ERR_RESOURCE_CLEANUP;
    }

    // Clean up the AES-256-CBC cipher and free the memory for the cipher context and key
    AES_cbc_cleanup(&ctx->key);
    free(ctx);
    ctxs[id] = NULL;

    // Return success
    return 0;
}
