void process_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu, CRC_LIST_T *list) {
    // Check if the RNTI is unique in the list
    int i;
    for (i = 0; i < list->list_size; i++) {
        if (!strcmp(list->list[i].rnti, pdu->rnti)) {
            return;
        }
    }

    // Add the PDU to the list
    if (list->list_size < list->max_list_size) {
        memcpy(&list->list[list->list_size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->list_size++;
    } else {
        // List is full, drop the PDU
        return;
    }
}

void convert_jpeg_to_pdf(char *input_filename, char *output_filename) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *infile = fopen(input_filename, "rb");
    FILE *outfile = fopen(output_filename, "wb");
    if (!infile || !outfile) {
        // Handle error
        return;
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, infile);
    (void)jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    int row_stride = cinfo.output_width * cinfo.output_components;
    JSAMPARRAY buffer = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, row_stride, 1);

    while (cinfo.output_scanline < cinfo.output_height) {
        jpeg_read_scanlines(&cinfo, buffer, 1);
        fwrite(buffer[0], 1, row_stride, outfile);
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(infile);
    fclose(outfile);
}

int main() {
    CRC_LIST_T list;
    list.max_list_size = MAX_LIST_SIZE;
    list.list_size = 0;
    list.list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list.max_list_size);
    if (!list.list) {
        // Handle error
        return 1;
    }

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Read the PDU from the network
        read(fd, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        process_crc_indication(&pdu, &list);

        if (list.list_size >= list.max_list_size) {
            // List is full, convert to PDF and reset the list
            char input_filename[MAX_FILENAME_LEN];
            char output_filename[MAX_FILENAME_LEN];
            sprintf(input_filename, "crc_indication_%d.jpg", getpid());
            sprintf(output_filename, "crc_indication_%d.pdf", getpid());
            convert_jpeg_to_pdf(input_filename, output_filename);
            list.list_size = 0;
        }
    }

    return 0;
}
