void manageSessions(SessionData **sessions, int *count, const char *csvFilePath, int threshold, const char *validationServiceURL) {
    // Initialize the array of sessions
    if (*sessions == NULL) {
        *sessions = malloc(sizeof(SessionData) * 10);
        assert(*sessions != NULL);
        *count = 0;
    }

