        stats.totalBytesSent = atoi(strtok(NULL, ","));

        // Add the session to the array if it meets the traffic threshold
        if (stats.totalBytesReceived >= threshold || stats.totalBytesSent >= threshold) {
            SessionData *session = malloc(sizeof(SessionData));
            assert(session != NULL);
            session->subscriptionID = subscriptionID;
            strncpy(session->imsi, imsi, 15);
            session->stats = stats;
            (*sessions)[*count] = session;
            *count += 1;
        }
    }
    fclose(file);

    // Filter the sessions based on traffic thresholds
    for (int i = 0; i < *count; i++) {
        if ((*sessions)[i]->stats.totalBytesReceived < threshold && (*sessions)[i]->stats.totalBytesSent < threshold) {
            free((*sessions)[i]);
            (*sessions)[i] = NULL;
        }
    }

    // Integrate with an external data validation service to ensure data integrity
    CURL *curl = curl_easy_init();
    if (curl) {
        char url[1024];
        snprintf(url, sizeof(url), "%s?subscriptionID=%d&IMSI=%s", validationServiceURL, (*sessions)[i]->subscriptionID, (*sessions)[i]->imsi);
