            // Check if there is a gap in the sequence numbers
            if (trafficFlowList[i].PacketSequenceNumber != 0 && trafficFlowList[i].PacketSequenceNumber < i) {
                // Handle the gap by incrementing the packet sequence number
                trafficFlowList[i].PacketSequenceNumber++;
            }
        }
    }
