// Define the dynamic list of TrafficFlow structures
typedef struct {
    TrafficFlow **flows;
    int numFlows;
    pthread_mutex_t lock; // mutex for thread-safe operations
} DynamicList;

// Function to initialize and populate a dynamic list of TrafficFlow structures
void initAndPopulateDynamicList(DynamicList *list, int numFlows) {
    // Allocate memory for the flows array
    list->flows = (TrafficFlow **)malloc(numFlows * sizeof(TrafficFlow *));
    if (!list->flows) {
        printf("Error: Failed to allocate memory for flows\n");
        return;
    }

    // Initialize the lock for thread-safe operations
    pthread_mutex_init(&list->lock, NULL);

    // Populate the dynamic list with TrafficFlow structures
    for (int i = 0; i < numFlows; i++) {
        // Allocate memory for the current flow
        list->flows[i] = (TrafficFlow *)malloc(sizeof(TrafficFlow));
        if (!list->flows[i]) {
            printf("Error: Failed to allocate memory for flow %d\n", i);
            return;
        }

        // Initialize the current flow with a unique source and destination address
        list->flows[i]->sourceAddress = (char *)malloc(16 * sizeof(char));
        if (!list->flows[i]->sourceAddress) {
            printf("Error: Failed to allocate memory for source address\n");
            return;
        }
        list->flows[i]->destinationAddress = (char *)malloc(16 * sizeof(char));
        if (!list->flows[i]->destinationAddress) {
