    }

    // Set the number of flows in the dynamic list
    list->numFlows = numFlows;
}

// Function to handle duplicate packets and efficiently detect and handle duplicate packets
void handleDuplicatePackets(DynamicList *list, TrafficFlow *flow) {
    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&list->lock);

    // Check if the current flow has a duplicate packet
    int i;
    for (i = 0; i < list->numFlows; i++) {
        if (flow == list->flows[i]) {
            break;
        }
    }

    // If the current flow is not a duplicate, add it to the dynamic list
    if (i == list->numFlows) {
        list->flows = (TrafficFlow **)realloc(list->flows, (list->numFlows + 1) * sizeof(TrafficFlow *));
        if (!list->flows) {
            printf("Error: Failed to reallocate memory for flows\n");
            return;
        }
        list->flows[list->numFlows] = flow;
        list->numFlows++;
    }

    // Unlock the mutex for thread-safe operations
    pthread_mutex_unlock(&list->lock);
}

// Function to efficiently detect and handle duplicate packets
