void manageMemory(DynamicList *list) {
    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&list->lock);

    // Check if any flows in the dynamic list are no longer needed
    int i;
    for (i = 0; i < list->numFlows; i++) {
        if (!list->flows[i]) {
            break;
        }
