#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

// Define the structure for TCP_NODE_STATS
typedef struct {
    int connection_id;
    time_t timestamp;
    int outstanding_packets[10];
} TCP_NODE_STATS;

// Define the maximum number of structures to create
#define MAX_STRUCTURES 1000

// Define the maximum count per structure
#define MAX_COUNT_PER_STRUCTURE 100

// Define the predefined maximum count per structure
#define PREDEFINED_MAX_COUNT_PER_STRUCTURE 50

// Define the thread-safe mutex for accessing the array of structures
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to initialize and manage the dynamic array of TCP_NODE_STATS structures
void init_tcp_node_stats(int num_structures, int max_count_per_structure) {
    // Validate the configuration parameters
    if (num_structures <= 0 || num_structures > MAX_STRUCTURES) {
        printf("Invalid number of structures specified. Using default value.\n");
        num_structures = PREDEFINED_MAX_COUNT_PER_STRUCTURE;
    }
    if (max_count_per_structure <= 0 || max_count_per_structure > MAX_COUNT_PER_STRUCTURE) {
        printf("Invalid maximum count per structure specified. Using default value.\n");
        max_count_per_structure = PREDEFINED_MAX_COUNT_PER_STRUCTURE;
    }

    // Dynamically allocate memory for the array of structures
    TCP_NODE_STATS *tcp_node_stats = (TCP_NODE_STATS *)malloc(num_structures * sizeof(TCP_NODE_STATS));
    if (!tcp_node_stats) {
        printf("Failed to allocate memory for the array of structures. Using default value.\n");
        num_structures = PREDEFINED_MAX_COUNT_PER_STRUCTURE;
    }

    // Initialize the array of structures
    for (int i = 0; i < num_structures; i++) {
        tcp_node_stats[i].connection_id = -1;
        tcp_node_stats[i].timestamp = 0;
        memset(tcp_node_stats[i].outstanding_packets, 0, sizeof(int) * max_count_per_structure);
    }

    // Set the number of structures and maximum count per structure
    int num_structures_set = num_structures;
    int max_count_per_structure_set = max_count_per_structure;

    // Acquire the mutex for accessing the array of structures
    pthread_mutex_lock(&mutex);

    // Update the number of structures and maximum count per structure if necessary
    if (num_structures_set != num_structures || max_count_per_structure_set != max_count_per_structure) {
        for (int i = 0; i < num_structures; i++) {
            tcp_node_stats[i].connection_id = -1;
            tcp_node_stats[i].timestamp = 0;
            memset(tcp_node_stats[i].outstanding_packets, 0, sizeof(int) * max_count_per_structure);
        }
    }

    // Release the mutex for accessing the array of structures
    pthread_mutex_unlock(&mutex);
}

// Define the function to add a new TCP_NODE_STATS structure to the dynamic array
void add_tcp_node_stats(int connection_id, time_t timestamp) {
    // Acquire the mutex for accessing the array of structures
    pthread_mutex_lock(&mutex);

    // Find an empty slot in the array of structures
    int i;
    for (i = 0; i < num_structures && tcp_node_stats[i].connection_id != -1; i++) {}

    // If no empty slots are found, increase the number of structures and reallocate memory
    if (i == num_structures) {
        num_structures++;
        TCP_NODE_STATS *new_tcp_node_stats = (TCP_NODE_STATS *)realloc(tcp_node_stats, num_structures * sizeof(TCP_NODE_STATS));
        if (!new_tcp_node_stats) {
            printf("Failed to reallocate memory for the array of structures. Using default value.\n");
            num_structures--;
        } else {
            tcp_node_stats = new_tcp_node_stats;
        }
    }

    // Initialize the new structure with the given connection ID and timestamp
    tcp_node_stats[i].connection_id = connection_id;
    tcp_node_stats[i].timestamp = timestamp;
    memset(tcp_node_stats[i].outstanding_packets, 0, sizeof(int) * max_count_per_structure);

    // Release the mutex for accessing the array of structures
    pthread_mutex_unlock(&mutex);
}

// Define the function to update a TCP_NODE_STATS structure in the dynamic array
void update_tcp_node_stats(int connection_id, time_t timestamp) {
    // Acquire the mutex for accessing the array of structures
    pthread_mutex_lock(&mutex);

    // Find the structure with the given connection ID
    int i;
    for (i = 0; i < num_structures && tcp_node_stats[i].connection_id != connection_id; i++) {}

    // If the structure is found, update its timestamp and release the mutex
    if (i < num_structures) {
        tcp_node_stats[i].timestamp = timestamp;
        pthread_mutex_unlock(&mutex);
    } else {
        // If the structure is not found, add a new one with the given connection ID and timestamp
        add_tcp_node_stats(connection_id, timestamp);
    }
}

// Define the function to remove a TCP_NODE_STATS structure from the dynamic array
void remove_tcp_node_stats(int connection_id) {
    // Acquire the mutex for accessing the array of structures
    pthread_mutex_lock(&mutex);

    // Find the structure with the given connection ID
    int i;
    for (i = 0; i < num_structures && tcp_node_stats[i].connection_id != connection_id; i++) {}

    // If the structure is found, remove it and update the number of structures if necessary
    if (i < num_structures) {
        for (int j = i + 1; j < num_structures; j++) {
            tcp_node_stats[j - 1] = tcp_node_stats[j];
        }
        num_structures--;
    }

    // Release the mutex for accessing the array of structures
    pthread_mutex_unlock(&mutex);
}

// Define the function to get the number of TCP_NODE_STATS structures in the dynamic array
int get_num_tcp_node_stats() {
    // Acquire the mutex for accessing the array of structures
    pthread_mutex_lock(&mutex);

    // Return the number of structures
    int num_structures = this->num_structures;

    // Release the mutex for accessing the array of structures
    pthread_mutex_unlock(&mutex);

    return num_structures;
}

// Define the function to get a TCP_NODE_STATS structure from the dynamic array by index
TCP_NODE_STATS *get_tcp_node_stats(int index) {
    // Acquire the mutex for accessing the array of structures
    pthread_mutex_lock(&mutex);

    // Return the structure at the given index
    TCP_NODE_STATS *tcp_node_stats = this->tcp_node_stats[index];

    // Release the mutex for accessing the array of structures
    pthread_mutex_unlock(&mutex);

    return tcp_node_stats;
}

// Define the function to get a TCP_NODE_STATS structure from the dynamic array by connection ID
TCP_NODE_STATS *get_tcp_node_stats(int connection_id) {
    // Acquire the mutex for accessing the array of structures
    pthread_mutex_lock(&mutex);

    // Find the structure with the given connection ID
    int i;
    for (i = 0; i < num_structures && tcp_node_stats[i].connection_id != connection_id; i++) {}

    // Return the structure at the found index, or NULL if not found
    TCP_NODE_STATS *tcp_node_stats = (i < num_structures) ? this->tcp_node_stats[i] : NULL;

    // Release the mutex for accessing the array of structures
    pthread_mutex_unlock(&mutex);

    return tcp_node_stats;
}
