// Function to read a text file and print the contents of each line in a comma-separated format
void processTextFile(char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");

    // Check if the file was successfully opened
    if (fp == NULL) {
        printf("Error: Unable to open file %s\n", filename);
        return;
    }

    // Read each line of the file and print it in a comma-separated format
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Split the line into fields using commas as delimiters
        char** fields = strtok(line, ",");

        // Print each field in a comma-separated format
        for (int i = 0; i < 3; i++) {
            printf("%s", fields[i]);
            if (i != 2) {
                printf(",");
            }
        }

        // Calculate the average of the last two numerical fields and print it
        int num1 = atoi(fields[2]);
        int num2 = atoi(fields[3]);
        float average = (num1 + num2) / 2.0;
        printf(",%f", average);

        // Free the memory allocated for the line
        free(line);
    }

    // Close the file
    fclose(fp);
}

// Function to manage theme caching for a mobile application while processing a large text file line by line
void processTextFileWithThemeCaching(char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");

    // Check if the file was successfully opened
    if (fp == NULL) {
        printf("Error: Unable to open file %s\n", filename);
        return;
    }

    // Read each line of the file and process it
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Split the line into fields using commas as delimiters
        char** fields = strtok(line, ",");

        // Check if a default theme directory is set and initialize it with a specified default value if not
        if (strlen(fields[0]) == 0) {
            printf("Default theme directory not set. Using default value: %s\n", DEFAULT_THEME_DIRECTORY);
            fields[0] = DEFAULT_THEME_DIRECTORY;
        }

        // Parse a PNG file from the cache root directory and add it to the theme cache, considering potential issues with file parsing and integration
        char* pngFilePath = malloc(strlen(fields[0]) + strlen(PNG_FILE_EXTENSION) + 1);
        sprintf(pngFilePath, "%s%s", fields[0], PNG_FILE_EXTENSION);
        if (parsePNGFile(pngFilePath)) {
            addToThemeCache(pngFilePath);
        } else {
            printf("Error: Unable to parse PNG file %s\n", pngFilePath);
        }

        // Free the memory allocated for the line
        free(line);
    }

    // Close the file
    fclose(fp);
}
