    }
    mempool = malloc(capacity * sizeof(DataPacket));
    mempool_size = capacity;
    pthread_mutex_unlock(&mempool_lock);
}

// Allocate a new DataPacket from the memory pool
DataPacket* allocate_packet() {
    pthread_mutex_lock(&mempool_lock);
    if (mempool == NULL || mempool_size == 0) {
        pthread_mutex_unlock(&mempool_lock);
        return NULL;
    }
    DataPacket* packet = mempool;
    mempool += sizeof(DataPacket);
    mempool_size--;
    pthread_mutex_unlock(&mempool_lock);
    return packet;
}

// Free a DataPacket from the memory pool
void free_packet(DataPacket* packet) {
    pthread_mutex_lock(&mempool_lock);
    mempool -= sizeof(DataPacket);
    mempool_size++;
    pthread_mutex_unlock(&mempool_lock);
}

// Initialize and populate a dynamically allocated array of DataPackets
void init_packets(int num_packets, size_t data_size) {
    // Allocate memory for the array of DataPackets
    DataPacket** packets = malloc(num_packets * sizeof(DataPacket*));
    if (packets == NULL) {
        return;
    }

    // Initialize each DataPacket in the array
    for (int i = 0; i < num_packets; i++) {
        packets[i] = allocate_packet();
        if (packets[i] == NULL) {
            break;
        }
        packets[i]->packet_id = i;
        packets[i]->data = malloc(data_size);
        if (packets[i]->data == NULL) {
            free_packet(packets[i]);
            break;
        }
        packets[i]->length = data_size;
    }

    // If any DataPackets were not initialized, free the entire array
    if (i < num_packets) {
        for (int j = 0; j < i; j++) {
            free(packets[j]->data);
            free_packet(packets[j]);
        }
        free(packets);
    }
}
```
This code defines a `DataPacket` structure that contains a unique `packet_id`, a pointer to a buffer containing encoded data, and a length field indicating the size of the data buffer. It also defines a thread-safe memory pool for allocating and freeing `DataPacket` structures. The `init_mempool()` function initializes the memory pool with a given capacity, while the `allocate_packet()` function allocates a new `DataPacket` from the memory pool. The `free_packet()` function frees a `DataPacket` from the memory pool.

The `init_packets()` function initializes and populates a dynamically allocated array of `DataPacket` structures. It first allocates memory for the array of `DataPacket` pointers, then initializes each `DataPacket` in the array by allocating memory for its data buffer and setting its `packet_id`, `data`, and `length` fields. If any `DataPacket` is not initialized successfully, the entire array is freed.

