// Define the structure to hold the LTE radio resource management data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
} DynamicArray;

// Function to allocate memory for a new entry in the dynamic array
DynamicArray* createEntry(size_t index) {
    // Allocate memory for the structure
    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        // Handle memory allocation failure gracefully by returning an error status
        printf("Error: Failed to allocate memory for new entry in dynamic array\n");
        return NULL;
    }

    // Initialize the structure with valid values
    data->RX_UE_INFORMATION_TAG = 0x1234;
    data->RNTI = 0x5678;
    data->CRC_INDICATION_REL8_TAG = 0x9ABC;

    // Generate a unique timestamp and sequence number for the entry
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    sprintf(data->timestamp, "%d-%02d-%02d %02d:%02d:%02d", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);
    data->sequenceNumber = index;

    // Create a new dynamic array entry with the allocated memory
    DynamicArray *entry = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!entry) {
        printf("Error: Failed to allocate memory for new dynamic array entry\n");
        free(data);
        return NULL;
    }
    entry->data = data;
    entry->capacity = 1;
    entry->count = 1;

    return entry;
}

// Function to add a new entry at runtime, expanding the allocated memory if necessary
void addEntry(DynamicArray *array, size_t index) {
    // Check if the array needs to be expanded
    if (array->count == array->capacity) {
        // Expand the allocated memory by 25%
        array->capacity += array->capacity / 4;
        NFAPI_CRC_INDICATION_PDU_T *newData = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->capacity);
        if (!newData) {
            // Handle memory allocation failure gracefully by returning an error status
            printf("Error: Failed to expand allocated memory for dynamic array\n");
            return;
        }
        array->data = newData;
    }

    // Create a new entry at the specified index
    DynamicArray *entry = createEntry(index);
    if (!entry) {
        printf("Error: Failed to create new dynamic array entry\n");
        return;
    }
    array->data[array->count] = entry->data;
    array->count++;
}

// Function to handle memory allocation failures gracefully by returning an error status and providing detailed failure information for debugging purposes
void handleMemoryAllocationFailure(const char *message) {
    printf("Error: %s\n", message);
    // Provide detailed failure information for debugging purposes
    printf("Last error code: %d\n", errno);
}

// Main function to manage the dynamic array of LTE radio resource management data
int main() {
    // Initialize a new dynamic array with an initial capacity of 10 entries
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        handleMemoryAllocationFailure("Failed to allocate memory for dynamic array");
        return -1;
    }
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10);
    if (!array->data) {
        handleMemoryAllocationFailure("Failed to allocate memory for dynamic array entries");
        return -1;
    }
    array->capacity = 10;
    array->count = 0;

    // Add new entries at runtime, expanding the allocated memory if necessary
    addEntry(array, 0);
    addEntry(array, 1);
    addEntry(array, 2);

    // Handle memory allocation failures gracefully by returning an error status and providing detailed failure information for debugging purposes
    if (errno != 0) {
        handleMemoryAllocationFailure("Failed to allocate memory for dynamic array");
        return -1;
    }

    // Process the LTE radio resource management data in the dynamic array
    for (size_t i = 0; i < array->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *data = array->data[i];
        printf("RX_UE_INFORMATION_TAG: %d\n", data->RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", data->RNTI);
        printf("CRC_INDICATION_REL8_TAG: %d\n", data->CRC_INDICATION_REL8_TAG);
        printf("Timestamp: %s\n", data->timestamp);
        printf("Sequence number: %d\n", data->sequenceNumber);
    }

    // Free the allocated memory for the dynamic array and its entries
    free(array->data);
    free(array);

    return 0;
}
