#define MAX_PACKET_SIZE 1024 // maximum size of a packet in bytes
#define FRAGMENTATION_THRESHOLD 512 // maximum size of a fragmented packet in bytes
#define PRIORITY_QUEUE_SIZE 10000 // maximum number of packets to be stored in the priority queue
#define MAX_FRAMES_PER_SECOND 1000000 // maximum number of frames per second
