int add_job_to_queue(JobQueue* q, EncodingJob* job) {
    int ret = -1;
    sem_wait(&q->mutex);
    if (q->rear < 100) {
        q->jobs[q->rear++] = job;
        ret = 0;
    }
    sem_post(&q->mutex);
    return ret;
}

// Remove a job from the queue
EncodingJob* remove_job_from_queue(JobQueue* q) {
    EncodingJob* job = NULL;
    sem_wait(&q->mutex);
    if (q->front < q->rear) {
        job = q->jobs[q->front++];
    }
    sem_post(&q->mutex);
    return job;
}

