    int ret = 1;
    sem_wait(&q->mutex);
    if (q->front < q->rear) {
        ret = 0;
    }
    sem_post(&q->mutex);
    return ret;
}

// Get the number of jobs in the queue
int get_queue_size(JobQueue* q) {
    int size = 0;
    sem_wait(&q->mutex);
    size = q->rear - q->front;
    sem_post(&q->mutex);
    return size;
}

