// Define the function to handle CRC indication data
void handle_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Validate the RNTI value falls within the valid range
    if (pdu->rnti < 0 || pdu->rnti > MAX_RNTI) {
        printf("Invalid RNTI value: %d\n", pdu->rnti);
        return;
    }

    // Acquire the semaphore to access shared resources
    sem_wait(sem);

    // Add the CRC indication data to the pool
    crc_indication_t *new_entry = malloc(sizeof(crc_indication_t));
    new_entry->pdu = *pdu;
    new_entry->rnti = pdu->rnti;
    // Add the entry to the pool
