    // Release the semaphore
    sem_post(sem);
}

// Define the function to handle CRC indication data in batch mode
void handle_crc_indications_batch(NFAPI_CRC_INDICATION_PDU_T *pdu, int num_pdus) {
    // Acquire the semaphore to access shared resources
    sem_wait(sem);

    // Add the CRC indication data to the pool
    for (int i = 0; i < num_pdus; i++) {
        crc_indication_t *new_entry = malloc(sizeof(crc_indication_t));
        new_entry->pdu = pdu[i];
        new_entry->rnti = pdu[i].rnti;
        // Add the entry to the pool
        pool_add(&pool, new_entry);
