// Define the linked list to hold the data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} LinkedList;

// Function to initialize and populate the linked list
void initAndPopulateLinkedList(int numElements) {
    // Allocate memory for the linked list
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!list) {
        printf("Error: Failed to allocate memory for linked list\n");
        return;
    }

    // Initialize the head node of the linked list
    list->data = NULL;
    list->next = NULL;

    // Populate the linked list with random data
    for (int i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            printf("Error: Failed to allocate memory for linked list node\n");
            return;
        }

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG randomly
        node->RX_UE_INFORMATION_TAG = rand() % 1000;
        node->RNTI = rand() % 1000;
        node->CRC_INDICATION_REL8_TAG = rand() % 1000;

        // Add the node to the linked list
        LinkedList *current = list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (LinkedList *)malloc(sizeof(LinkedList));
        if (!current->next) {
            printf("Error: Failed to allocate memory for linked list node\n");
            return;
        }
        current->next->data = node;
        current->next->next = NULL;
    }

    // Print the linked list
    LinkedList *current = list;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", current->data->RX_UE_INFORMATION_TAG, current->data->RNTI, current->data->CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

// Function to free the linked list
void freeLinkedList(LinkedList *list) {
    LinkedList *current = list;
    while (current != NULL) {
        LinkedList *temp = current;
        current = current->next;
        free(temp);
    }
}
