typedef struct {
    RRCConnectionInfo rrc_info;
    NASMessage nas_msg;
    SecurityContext sec_ctx;
} UEContext;

// Define the function to initialize and populate an array of UEContext structures
void init_ue_contexts(UEContext **ue_contexts, int num_ues) {
    // Allocate memory for the array of UEContext structures
    *ue_contexts = (UEContext *)malloc(num_ues * sizeof(UEContext));
    if (*ue_contexts == NULL) {
        perror("Failed to allocate memory for UE contexts");
        exit(1);
    }

    // Initialize the RRCConnectionInfo and NASMessage structures for each UE
    for (int i = 0; i < num_ues; i++) {
        (*ue_contexts)[i].rrc_info.state = INITIALIZED;
        (*ue_contexts)[i].nas_msg.type = NONE;
        (*ue_contexts)[i].nas_msg.length = 0;
    }

    // Dynamically allocate memory for the SecurityContext structures
    for (int i = 0; i < num_ues; i++) {
        (*ue_contexts)[i].sec_ctx = (SecurityContext *)malloc(sizeof(SecurityContext));
        if ((*ue_contexts)[i].sec_ctx == NULL) {
            perror("Failed to allocate memory for SecurityContext");
            exit(1);
        }
    }

    // Validate the integrity of the SecurityContext structures
    for (int i = 0; i < num_ues; i++) {
        if (!validate_security_context(&(*ue_contexts)[i].sec_ctx)) {
            perror("Failed to validate SecurityContext");
            exit(1);
        }
    }
}

// Define the function to validate the integrity of a SecurityContext structure
bool validate_security_context(SecurityContext *sec_ctx) {
    // Check if all security parameters are correctly configured for the given UE context
    if (sec_ctx->integrity_algorithm == INVALID || sec_ctx->ciphering_algorithm == INVALID) {
        return false;
    }

    // Check if the security keys are properly initialized and validated
    if (!validate_security_keys(sec_ctx)) {
        return false;
    }

    return true;
}

// Define the function to validate the integrity of a SecurityContext structure's security keys
bool validate_security_keys(SecurityContext *sec_ctx) {
    // Check if the security keys are properly initialized and validated
    if (sec_ctx->integrity_key == NULL || sec_ctx->ciphering_key == NULL) {
        return false;
    }

    // Check if the security keys are properly aligned for optimal processing within the network stack
    if (!is_aligned(sec_ctx->integrity_key, 16) || !is_aligned(sec_ctx->ciphering_key, 16)) {
        return false;
    }

    return true;
}

// Define the function to check if a pointer is properly aligned for optimal processing within the network stack
bool is_aligned(void *ptr, int alignment) {
    // Check if the pointer is properly aligned for the given alignment value
    if ((uintptr_t)ptr % alignment != 0) {
        return false;
    }

    return true;
}
