// Define function to dynamically allocate memory for array of NFAPI_CRC_INDICATION_PDU_T structures
void *allocate_memory(int n) {
    // Calculate size of array based on user input n
    int size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;

    // Dynamically allocate memory for array using malloc() function
    void *array = malloc(size);

    // Check if memory allocation was successful
    if (array == NULL) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize each structure in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = array + i;
        pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG_INIT;
        pdu->rnti = rand() % 10000; // Randomly set RNTI value within valid range
        pdu->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG_INIT;
    }

    return array;
}

// Define function to sort structures in array based on RNTI values in ascending order using optimized sorting algorithm suitable for large datasets
void sort_array(NFAPI_CRC_INDICATION_PDU_T *array, int n) {
    // Use quicksort algorithm with median-of-three pivot selection to sort structures in array based on RNTI values
    int left = 0;
    int right = n - 1;

    while (left < right) {
        // Partition the array into two subarrays, one containing elements less than or equal to the median and one containing elements greater than the median
        int pivot = partition(array, left, right);

        // Recursively sort the subarrays
        if (pivot > 0) {
            sort_array(array, pivot);
        }
        if (pivot < n - 1) {
            sort_array(array + pivot + 1, n - pivot - 1);
        }
    }
}

// Define function to manage memory usage and prevent memory leaks after printing sorted list to console
void free_memory(void *array) {
    // Check if array is NULL before attempting to free memory
    if (array != NULL) {
        free(array);
    }
}

