// Custom random number generator using Xorshift* algorithm
uint32_t xorshift128(uint64_t *state) {
    uint32_t x = (uint32_t)(*state >> 1);
    uint32_t y = (uint32_t)(*state >> 7);
    uint32_t z = (uint32_t)(*state >> 12);
    *state = x ^ y ^ z;
    return *state;
}

// Allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(uint32_t n, uint64_t seed, const NFAPI_CONFIGURATION_STRUCT *config) {
    // Validate input parameters
    if (n < 1 || n > 1000) {
        printf("Error: Invalid number of CRC indications (%u).\n", n);
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (crc_indications == NULL) {
        printf("Error: Failed to allocate memory for CRC indications.\n");
        return NULL;
