size_t array_size = 0;

// Define the lock for concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
void populate_array(size_t num_elements) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array is already allocated and has enough space for the new elements
    if (array == NULL || array_size < num_elements) {
        // If not, allocate a new array with twice the size of the current one
        array = realloc(array, 2 * num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array == NULL) {
            perror("realloc failed");
            return;
        }
        // Initialize the new elements to zero
        memset(array + array_size, 0, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array_size = 2 * num_elements;
    }

    // Set the RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG for each element in the array
    for (size_t i = 0; i < num_elements; i++) {
        array[i].rx_ue_information_tag = i + 1;
        array[i].rnti = i + 2;
        array[i].crc_indication_rel8_tag = (uint8_t)rand() % 256;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to free the array of NFAPI_CRC_INDICATION_PDU_T structures
