// Define the function to initialize and configure a dynamic array of NICP settings
void initNICPSettings(NICPSettings* nicpSettings, int minMacAddress, int maxMacAddress, int vlanIdRangeStart, int vlanIdRangeEnd) {
    // Validate input parameters
    if (nicpSettings == NULL || minMacAddress < 0 || maxMacAddress < 0 || vlanIdRangeStart < 0 || vlanIdRangeEnd < 0) {
        return;
    }

    // Initialize the dynamic array of NICP settings
    nicpSettings->settings = (NICPSetting*)malloc(sizeof(NICPSetting));
    if (nicpSettings->settings == NULL) {
        return;
    }
    nicpSettings->count = 0;
    nicpSettings->capacity = 1;

    // Generate unique MAC addresses and VLAN IDs within the specified range
