        NICPSetting* setting = &nicpSettings->settings[i];
        if (strcmp(setting->macAddress, macAddress) == 0 && setting->vlanId == vlanId) {
            return; // Return early if the MAC address and VLAN ID are already in use
        }
    }

    // Add a new NICP setting to the dynamic array
    nicpSettings->settings = (NICPSetting*)realloc(nicpSettings->settings, sizeof(NICPSetting) * (nicpSettings->count + 1));
    if (nicpSettings->settings == NULL) {
        return;
