    for (int i = 0; i < nicpSettings->count; i++) {
        NICPSetting* setting = &nicpSettings->settings[i];
        if (strcmp(setting->macAddress, macAddress) == 0 && setting->vlanId == vlanId) {
            index = i;
            break;
        }
    }

    // Remove the NICP setting from the dynamic array
    if (index != -1) {
        for (int i = index; i < nicpSettings->count - 1; i++) {
            nicpSettings->settings[i] = nicpSettings->settings[i + 1];
        }
        nicpSettings->count--;
    }
