void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t rx_ue_information_tag, uint32_t rnti, bool crcflag) {
    // Check if the list is full
    if (list->pdu_count == SIZE_MAX) {
        return;
    }

    // Allocate memory for a new PDU structure
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
