    new_pdu->rx_ue_information_tag = rx_ue_information_tag;
    new_pdu->rnti = rnti;
    new_pdu->crc_indication_rel8_tag = crcflag;

    // Add the new PDU structure to the list
    list->pdu_list[list->pdu_count++] = new_pdu;
