    // Check if the input is valid
    if (n == 0) {
        return NULL;
    }

    // Calculate the size of each structure in bytes
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * struct_size);
    if (pdu_array == NULL) {
        // Log an error message if memory allocation fails
        printf("Error: Failed to allocate memory for CRC indication PDU array\n");
