        pdu_array[i].RNTI = 5678;
        pdu_array[i].CRC_INDICATION_REL8_TAG = 9012;
        pdu_array[i].CRCFLAG = true;
    }

    // Return the pointer to the first element of the array
    return pdu_array;
}

// Define a function to deallocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
