// Define the function to parse a TIFF image file and extract detailed information about the image's header, including the bits per sample, samples per pixel, compression type, image dimensions, and color space information
void* parse_tiff_image(const char* filename) {
    // Open the file in binary mode
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        return NULL;
    }

    // Read the header of the TIFF image
    uint8_t header[12];
    size_t bytes_read = fread(header, 1, sizeof(header), fp);
    if (bytes_read != sizeof(header)) {
        fclose(fp);
        return NULL;
    }

    // Check the magic number of the TIFF image
    uint32_t magic_number = header[0] | (header[1] << 8) | (header[2] << 16) | (header[3] << 24);
    if (magic_number != 0x49492A00 && magic_number != 0x4D4D002A) {
        fclose(fp);
        return NULL;
    }

    // Read the image dimensions and bits per sample
    uint16_t width = header[4] | (header[5] << 8);
    uint16_t height = header[6] | (header[7] << 8);
    uint16_t bits_per_sample = header[8] | (header[9] << 8);

    // Read the compression type and samples per pixel
    uint16_t compression_type = header[10] | (header[11] << 8);
    uint16_t samples_per_pixel = header[12] | (header[13] << 8);

    // Read the color space information
    uint16_t color_space = header[14] | (header[15] << 8);

    // Close the file
    fclose(fp);

    // Allocate memory for the image metadata structure
    size_t size = sizeof(TIFF_IMAGE_METADATA) + width * height * bits_per_sample / 8;
    void* metadata = malloc(size);

    // Check if memory allocation failed
    if (metadata == NULL) {
        return NULL;
    }

    // Initialize the image metadata structure
    TIFF_IMAGE_METADATA* metadata_ptr = (TIFF_IMAGE_METADATA*)metadata;
    metadata_ptr->width = width;
    metadata_ptr->height = height;
    metadata_ptr->bits_per_sample = bits_per_sample;
    metadata_ptr->compression_type = compression_type;
    metadata_ptr->samples_per_pixel = samples_per_pixel;
    metadata_ptr->color_space = color_space;

    // Read the image data and store it in the image metadata structure
    fp = fopen(filename, "rb");
    if (fp == NULL) {
        free(metadata);
        return NULL;
    }
    size_t bytes_read = fread((uint8_t*)metadata + sizeof(TIFF_IMAGE_METADATA), 1, width * height * bits_per_sample / 8, fp);
    if (bytes_read != width * height * bits_per_sample / 8) {
        free(metadata);
        return NULL;
    }
    fclose(fp);

    return metadata;
}
```
