void add_config(LinkedList* ll, RadioFrequencyConfiguration config) {
    Node* node = malloc(sizeof(Node));
    node->config = config;
    node->next = NULL;

    if (ll->head == NULL) {
        ll->head = node;
    } else {
        Node* current = ll->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    ll->size++;
}

