    // Iterate over the frames and validate the frequency hopping sequence
    for (int i = 0; i < list_size(frameMetadata); i++) {
        FrameMetadata* metadata = list_get(frameMetadata, i);
        int frequencyChannel = metadata->frequencyChannel;
        int timeSlot = metadata->timeSlot;
        SRSConfig srsConfig = metadata->srsConfig;
        // Check if the frequency hopping sequence is consistent across all time slots within the same frequency channel
        for (int j = 0; j < numChannels; j++) {
