    {
        _backgroundService = backgroundService;
    }

    public async Task HandleRequestAsync(HttpContext context)
    {
        var sessionToken = context.Request.Headers["Session-Token"];
        var pageId = context.Request.QueryString["pageId"];
        var updates = context.Request.Form["updates"];

        if (!_sessions.ContainsKey(sessionToken))
        {
            _sessions[sessionToken] = new Session();
        }

        var session = _sessions[sessionToken];

        // Validate the session token and apply updates asynchronously using a background service
        await _backgroundService.ApplyUpdatesAsync(session, pageId, updates);

        // Optimize repeated operations on popular pages by implementing a caching mechanism
        if (pageId == "popularPage")
        {
            var cachedData = GetCachedData(pageId);
            if (cachedData != null)
            {
                context.Response.Write(cachedData);
                return;
            }
