        // Handle potential race conditions and ensure data consistency across concurrent requests
        lock (session)
        {
            var page = session.Pages[pageId];
            if (page == null)
            {
                page = new Page();
                session.Pages[pageId] = page;
            }

            foreach (var update in updates)
