function testSuite(label, f, config) {
  // Initialize blueslip instance for logging
  const blueslip = new Blueslip();

  // Validate module path against whitelist of allowed directories
  if (!config.modulePath || !isValidModulePath(config.modulePath)) {
    throw new Error(`Invalid module path: ${config.modulePath}`);
  }

  // Dynamically construct module path using configuration object
  const modulePath = config.modulePath;

  // Implement mechanism to handle external dependencies that may affect test execution
  const dependencyManager = new DependencyManager();

  // Wrap each test in a transaction-like context to ensure state consistency
  try {
    // Execute test function and log results using blueslip
    f(blueslip);
  } catch (e) {
    // Handle errors thrown by test function gracefully
    console.error(`Error executing test: ${label}`);
    console.error(e);
  } finally {
    // Reset blueslip instance to its initial state after each test
    blueslip.reset();
  }

  // Implement mechanism to track total number of tests executed and pass/fail status
  const testResults = [];
  for (const test of f) {
    try {
      // Execute test function and log results using blueslip
      test(blueslip);
      testResults.push({ label, result: 'pass' });
    } catch (e) {
      // Handle errors thrown by test function gracefully
      console.error(`Error executing test: ${label}`);
      console.error(e);
      testResults.push({ label, result: 'fail' });
    } finally {
      // Reset blueslip instance to its initial state after each test
      blueslip.reset();
    }
  }

  return testResults;
}
```
