// Structure to store RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to execute a specified command in the background using fork and wait system calls
int execute_command(char* command) {
    // Fork a child process to run the command
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: run the command and exit
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(127);
    } else if (pid < 0) {
        // Error: failed to fork child process
        perror("fork");
        return 0;
    }

    // Parent process: wait for the child process to finish and check its status
    int status;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 1;
    } else {
        // Error: child process exited with a non-zero status
        fprintf(stderr, "Child process exited with status %d\n", WEXITSTATUS(status));
        return 0;
    }
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_crc_indication_pdu_list(char* command, int num_elements) {
    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        perror("malloc");
        return 0;
    }

    // Populate the list with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        pdu_list[i].rx_ue_information_tag = rand() % 1000;
        pdu_list[i].rnti = rand() % 1000;
        pdu_list[i].crc_indication_rel8_tag = rand() % 1000;
    }

    // Serialize the list of structures into a binary file
    FILE* fp = fopen("crc_indication_pdu_list.bin", "wb");
    if (fp == NULL) {
        perror("fopen");
        return 0;
    }
    for (int i = 0; i < num_elements; i++) {
        fwrite(&pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
    fclose(fp);

    // Free the list of structures
    free(pdu_list);

    return 1;
}
