typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the sliding window size
#define WINDOW_SIZE 5

// Define the mutex for protecting the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the array of CRC indication data structures
NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;

// Define the function for dynamically managing the array
void manage_crc_indications(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRCFLAG) {
    // Lock the mutex to protect the array
    pthread_mutex_lock(&mutex);

    // Check if the array is NULL and allocate memory for it if necessary
    if (crc_indications == NULL) {
        crc_indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * WINDOW_SIZE);
        if (crc_indications == NULL) {
            // Log an error message and return
            printf("Error: Failed to allocate memory for CRC indication array\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Check if the array is full and needs to be resized
    if (crc_indications->length == WINDOW_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (WINDOW_SIZE + 1));
        if (new_array == NULL) {
            // Log an error message and return
            printf("Error: Failed to resize CRC indication array\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        crc_indications = new_array;
    }

    // Add the new CRC indication data structure to the end of the array
    crc_indications[crc_indications->length].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    crc_indications[crc_indications->length].RNTI = RNTI;
    crc_indications[crc_indications->length].CRCFLAG = CRCFLAG;
    crc_indications->length++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

