typedef struct {
    char *session_id;
    void *connection;
    void (*callback)(void);
} SessionInfo;

// Define a linked list node for storing session information
typedef struct Node {
    SessionInfo *data;
    struct Node *next;
} Node;

// Define a linked list to store all session information
Node *head = NULL;

// Define a mutex to protect the linked list from concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a log buffer to record insertion operations
