    SessionInfo *new_session = malloc(sizeof(SessionInfo));
    if (new_session == NULL) {
        return NULL;
    }
    new_session->session_id = strdup(session_id);
    new_session->connection = connection;
    new_session->callback = callback;
    return new_session;
}

// Define a function to free memory for a session info structure
void free_session_info(SessionInfo *session) {
    if (session == NULL) {
        return;
    }
    free(session->session_id);
    free(session);
}

