int insert_session(const char *session_id, void *connection, void (*callback)(void)) {
    // Check if the session identifier is empty or NULL
    if (session_id == NULL || strlen(session_id) == 0) {
        return -1;
    }

    // Check if the connection has a valid endpoint
    if (connection == NULL) {
        return -2;
    }

    // Check if the callback function is not NULL
    if (callback == NULL) {
        return -3;
