    pthread_mutex_lock(&mutex);

    // Create a new node for the session information
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&mutex);
        return -4;
    }

    // Allocate memory for the session info structure
    SessionInfo *new_session = allocate_session_info(session_id, connection, callback);
    if (new_session == NULL) {
        free(new_node);
        pthread_mutex_unlock(&mutex);
        return -5;
    }

    // Set the data field of the new node to the session info structure
    new_node->data = new_session;

    // Check if the linked list is empty
    if (head == NULL) {
        head = new_node;
    } else {
        // Find the last node in the linked list
        Node *last_node = head;
        while (last_node->next != NULL) {
            last_node = last_node->next;
        }

        // Set the next field of the last node to the new node
        last_node->next = new_node;
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define a function to remove a session from the linked list
int remove_session(const char *session_id) {
    // Acquire the mutex to protect the linked list from concurrent access
    pthread_mutex_lock(&mutex);

    // Find the node in the linked list that contains the specified session ID
    Node *node = head;
    while (node != NULL && strcmp(session_id, node->data->session_id) != 0) {
        node = node->next;
    }

    // Check if the node was found
    if (node == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Remove the node from the linked list
    Node *prev_node = head;
    while (prev_node->next != node) {
        prev_node = prev_node->next;
    }
    prev_node->next = node->next;

    // Free the memory for the session info structure and the node
    free_session_info(node->data);
    free(node);

    // Release the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define a function to update a session in the linked list
int update_session(const char *session_id, void *connection, void (*callback)(void)) {
    // Acquire the mutex to protect the linked list from concurrent access
    pthread_mutex_lock(&mutex);

