    if (node == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Update the connection and callback function for the session info structure
    node->data->connection = connection;
    node->data->callback = callback;

    // Release the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define a function to retrieve a session from the linked list
SessionInfo *get_session(const char *session_id) {
    // Acquire the mutex to protect the linked list from concurrent access
    pthread_mutex_lock(&mutex);

