// Define the synchronization mechanism for thread-safe access to the linked list
semaphore_t semaphore;

// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU structures
void create_and_populate_linked_list(int num_entries) {
    // Initialize the synchronization mechanism for thread-safe access to the linked list
    semaphore = semaphore_create();

    // Iterate over the number of entries provided as input
    for (int i = 1; i <= num_entries; i++) {
        // Allocate memory for the new node in the linked list
        NFAPI_CRC_INDICATION_PDU_NODE_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_NODE_T));

        // Check if allocation failed
