        new_node->data->crc_indication_rel8_tag.crflag = rand() % 2;

        // Acquire the semaphore to ensure thread-safe access to the linked list
        semaphore_acquire(semaphore);

        // Add the new node to the end of the linked list
        if (head == NULL) {
            head = new_node;
        } else {
            NFAPI_CRC_INDICATION_PDU_NODE_T *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }

        // Release the semaphore to release access to the linked list
        semaphore_release(semaphore);
    }
}

// Function to traverse the linked list and perform necessary operations on each node
void traverse_linked_list() {
    // Acquire the semaphore to ensure thread-safe access to the linked list
    semaphore_acquire(semaphore);

    // Iterate over the nodes in the linked list
    NFAPI_CRC_INDICATION_PDU_NODE_T *current = head;
    while (current != NULL) {
