        printf("CRC_INDICATION_REL8_TAG: %d\n", current->data->crc_indication_rel8_tag.crflag);

        // Move to the next node in the linked list
        current = current->next;
    }

    // Release the semaphore to release access to the linked list
    semaphore_release(semaphore);
}

// Function to delete a node from the linked list and free its memory
void delete_node(int sequence_number) {
    // Acquire the semaphore to ensure thread-safe access to the linked list
    semaphore_acquire(semaphore);

    // Iterate over the nodes in the linked list until the node with the specified sequence number is found
    NFAPI_CRC_INDICATION_PDU_NODE_T *current = head;
    while (current != NULL) {
        if (current->data->sequence_number == sequence_number) {
            // If the node is found, delete it from the linked list and free its memory
            NFAPI_CRC_INDICATION_PDU_NODE_T *previous = current;
            current = current->next;
            previous->next = NULL;
            free(previous);
            break;
        } else {
            // Move to the next node in the linked list
            current = current->next;
        }
    }

    // Release the semaphore to release access to the linked list
    semaphore_release(semaphore);
}

// Function to free all memory allocated for the linked list and its nodes
void free_linked_list() {
    // Acquire the semaphore to ensure thread-safe access to the linked list
    semaphore_acquire(semaphore);

    // Iterate over the nodes in the linked list and free their memory
    NFAPI_CRC_INDICATION_PDU_NODE_T *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_NODE_T *previous = current;
        current = current->next;
        free(previous);
    }

    // Release the semaphore to release access to the linked list
    semaphore_release(semaphore);
}
