void nfapi_crc_indication_list_add(nfapi_crc_indication_list_t *list, uint16_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag, bool crcflag) {
    // Check if the list is full
    if (list->count == list->capacity) {
        // If the list is full, double its capacity and reallocate memory for the elements array
        size_t new_capacity = list->capacity * 2;
        nfapi_crc_indication_pdu_t *new_elements = realloc(list->elements, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
