        printf("Error: Invalid index for NFAPI CRC indication list\n");
        return;
    }

    // Shift all elements after the specified index to fill the gap
    size_t i;
    for (i = index + 1; i < list->count; i++) {
        list->elements[i - 1] = list->elements[i];
    }

    // Decrement the count of elements in the list
