int create_process(Process *process, const char *directory) {
    // Create a new process and set its working directory to the specified directory
    if (process == NULL || directory == NULL) {
        printf("Invalid process or directory\n");
        return -1;
    }
    process->pid = fork();
    if (process->pid < 0) {
        printf("Failed to create process: %s\n", strerror(errno));
        return -1;
    } else if (process->pid == 0) {
        // Child process
        chdir(directory);
        execl("/bin/sh", "sh", "-c", "./start_website.sh", NULL);
        printf("Failed to start website: %s\n", strerror(errno));
        return -1;
    } else {
        // Parent process
        return 0;
    }
}

