    // Start the process and handle any errors that may occur
    if (process == NULL) {
        printf("Invalid process\n");
        return -1;
    }
    int ret = 0;
    for (int i = 0; i < MAX_PROCESS_RETRIES; i++) {
        ret = kill(process->pid, SIGCONT);
        if (ret == 0) {
            break;
        } else {
