// Define the maximum queue size and logging level as configurable parameters
#define MAX_QUEUE_SIZE 1024
#define LOGGING_LEVEL 3

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint8_t valid;
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the queue data structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} QUEUE_DATA_STRUCTURE;

// Define the logging function
void log(int level, const char *format, ...) {
    if (level <= LOGGING_LEVEL) {
        va_list args;
        va_start(args, format);
        vprintf(format, args);
        va_end(args);
    }
}

// Define the queue management functions
QUEUE_DATA_STRUCTURE *queue_create(size_t capacity) {
    QUEUE_DATA_STRUCTURE *queue = malloc(sizeof(QUEUE_DATA_STRUCTURE));
    if (queue == NULL) {
        log(1, "Error: Failed to allocate memory for queue\n");
        return NULL;
    }
    queue->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (queue->data == NULL) {
        log(1, "Error: Failed to allocate memory for queue data\n");
        free(queue);
        return NULL;
    }
    queue->size = 0;
    queue->capacity = capacity;
    return queue;
}

void queue_destroy(QUEUE_DATA_STRUCTURE *queue) {
    if (queue == NULL) {
        log(1, "Error: Queue is null\n");
        return;
    }
    free(queue->data);
    free(queue);
}

bool queue_push(QUEUE_DATA_STRUCTURE *queue, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (queue == NULL || element == NULL) {
        log(1, "Error: Queue or element is null\n");
        return false;
    }
    if (queue->size >= queue->capacity) {
        log(2, "Warning: Queue is full\n");
        return false;
    }
    memcpy(&queue->data[queue->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->size++;
    return true;
}

bool queue_pop(QUEUE_DATA_STRUCTURE *queue, NFAPI_CRC_INDICATION_PDU_T **element) {
    if (queue == NULL || element == NULL) {
        log(1, "Error: Queue or element is null\n");
        return false;
    }
    if (queue->size <= 0) {
        log(2, "Warning: Queue is empty\n");
        return false;
    }
    *element = &queue->data[queue->size - 1];
    queue->size--;
    return true;
}

// Define the C function that manages the dynamically sized queue of up to M elements
void manage_queue(QUEUE_DATA_STRUCTURE *queue, size_t max_queue_size) {
    // Check if the queue is full and needs to be resized
    if (queue->size >= max_queue_size) {
        log(2, "Warning: Queue is full\n");
        QUEUE_DATA_STRUCTURE *new_queue = queue_create(max_queue_size * 2);
        if (new_queue == NULL) {
            log(1, "Error: Failed to create new queue\n");
            return;
        }
        // Copy the elements from the old queue to the new one
        for (size_t i = 0; i < queue->size; i++) {
            NFAPI_CRC_INDICATION_PDU_T *element = &queue->data[i];
            if (!queue_push(new_queue, element)) {
                log(1, "Error: Failed to push element to new queue\n");
                return;
            }
        }
        // Destroy the old queue and replace it with the new one
        queue_destroy(queue);
        *queue = *new_queue;
    }
}

// Define the thread-safe version of the C function that manages the dynamically sized queue of up to M elements
void manage_queue_thread_safe(QUEUE_DATA_STRUCTURE *queue, size_t max_queue_size) {
    // Check if the queue is full and needs to be resized
    pthread_mutex_lock(&queue->mutex);
    if (queue->size >= max_queue_size) {
        log(2, "Warning: Queue is full\n");
        QUEUE_DATA_STRUCTURE *new_queue = queue_create(max_queue_size * 2);
        if (new_queue == NULL) {
            log(1, "Error: Failed to create new queue\n");
            pthread_mutex_unlock(&queue->mutex);
            return;
        }
        // Copy the elements from the old queue to the new one
        for (size_t i = 0; i < queue->size; i++) {
            NFAPI_CRC_INDICATION_PDU_T *element = &queue->data[i];
            if (!queue_push(new_queue, element)) {
                log(1, "Error: Failed to push element to new queue\n");
                pthread_mutex_unlock(&queue->mutex);
                return;
            }
        }
        // Destroy the old queue and replace it with the new one
        queue_destroy(queue);
        *queue = *new_queue;
    }
    pthread_mutex_unlock(&queue->mutex);
}
