import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import org.json.JSONObject;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonParser;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.concurrent.TimeoutException;

public class ProcessRemoteData {
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_MILLIS = 500L;
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public Map<String, Object> processRemoteData(String jsonPayload) throws IOException, TimeoutException {
        HttpClient client = HttpClient.newHttpClient();
        URI endpoint = URI.create("https://example.com/api/data");
        HttpRequest request = HttpRequest.newBuilder()
                .uri(endpoint)
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(jsonPayload))
                .build();

        Future<HttpResponse<String>> responseFuture = executor.submit(() -> client.send(request, HttpResponse.BodyHandlers.ofString()));

        int retries = 0;
        while (true) {
            try {
                HttpResponse<String> response = responseFuture.get(10, TimeUnit.SECONDS);
                if (response.statusCode() == 200) {
                    return parseResponse(response.body());
                } else {
                    throw new IOException("Received non-success status code: " + response.statusCode());
                }
            } catch (TimeoutException e) {
                if (retries >= MAX_RETRIES) {
                    throw new TimeoutException("Exceeded maximum retries");
                } else {
                    System.err.println("Retrying request due to timeout...");
                    responseFuture = executor.submit(() -> client.send(request, HttpResponse.BodyHandlers.ofString()));
                    retries++;
                    try {
                        Thread.sleep(BACKOFF_MILLIS * retries);
                    } catch (InterruptedException ex) {
                        // ignore
                    }
                }
            }
        }
    }

    private Map<String, Object> parseResponse(String responseBody) throws IOException {
        JsonReader reader = new JsonReader(new StringReader(responseBody));
        Gson gson = new Gson();
        JsonElement jsonElement = gson.fromJson(reader, JsonElement.class);
        return gson.fromJson(jsonElement, Map.class);
    }
}
