// Define structure for UE connection record
typedef struct {
    int node_id;
    long last_seen_timestamp;
    float current_bandwidth;
    bool active_flag;
    unsigned short dependency_flags;
} UE_CONNECTION_RECORD;

// Define function to manage array of UE connection records
void manage_ue_connection_records(int num_nodes) {
    // Allocate memory for the array of UE connection records
    UE_CONNECTION_RECORD *records = (UE_CONNECTION_RECORD *)malloc(num_nodes * sizeof(UE_CONNECTION_RECORD));

    // Initialize each record with default values
    for (int i = 0; i < num_nodes; i++) {
        records[i].node_id = i + 1;
        records[i].last_seen_timestamp = 0;
        records[i].current_bandwidth = 0.0f;
        records[i].active_flag = false;
        records[i].dependency_flags = 0;
    }

    // Dynamically allocate and populate the array with unique node IDs
    for (int i = 0; i < num_nodes; i++) {
        bool found_unique_id = false;
        while (!found_unique_id) {
            int random_node_id = rand() % num_nodes + 1;
            if (records[random_node_id].node_id != random_node_id) {
                records[random_node_id].node_id = random_node_id;
                found_unique_id = true;
            }
        }
    }

    // Validate each record's bandwidth and active flag consistency
    for (int i = 0; i < num_nodes; i++) {
        if (!records[i].active_flag) {
            continue;
        }
        float current_bandwidth = records[i].current_bandwidth;
        bool valid_bandwidth = true;
        for (int j = 0; j < num_nodes; j++) {
            if (records[j].node_id == i) {
                continue;
            }
            float dependency_bandwidth = records[j].current_bandwidth * records[i].dependency_flags;
            if (current_bandwidth < dependency_bandwidth) {
                valid_bandwidth = false;
                break;
            }
        }
        if (!valid_bandwidth) {
            // Reallocate memory for the array to accommodate a new record with updated bandwidth and active flag
            UE_CONNECTION_RECORD *new_records = (UE_CONNECTION_RECORD *)realloc(records, (num_nodes + 1) * sizeof(UE_CONNECTION_RECORD));
            if (new_records == NULL) {
                // Handle error gracefully by returning an appropriate error status without causing a system crash
                printf("Error: Failed to reallocate memory for UE connection records\n");
                return;
            }
            records = new_records;
            records[num_nodes].node_id = i + 1;
            records[num_nodes].last_seen_timestamp = 0;
            records[num_nodes].current_bandwidth = current_bandwidth - dependency_bandwidth;
            records[num_nodes].active_flag = true;
            records[num_nodes].dependency_flags = 0;
            num_nodes++;
        }
    }
}
