// Define the mutex for synchronizing access to the list
static pthread_mutex_t crc_indication_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a new NFAPI_CRC_INDICATION_PDU_T structure with a random RNTI and CRCFLAG
NFAPI_CRC_INDICATION_PDU_T *generate_crc_indication(void) {
    // Allocate memory for the new structure
    NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_struct == NULL) {
        return NULL;
    }

    // Generate a random RNTI and CRCFLAG
    new_struct->RX_UE_INFORMATION_TAG = 0x1234;
    new_struct->RNTI = rand() % 65536;
    new_struct->CRCFLAG = rand() % 256;

    // Add the new structure to the list, ensuring no duplicates
    pthread_mutex_lock(&crc_indication_list_mutex);
    if (crc_indication_list == NULL) {
        crc_indication_list = new_struct;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list;
        while (current->next != NULL) {
            if (current->RNTI == new_struct->RNTI) {
                // Duplicate RNTI found, generate a new one
                new_struct->RNTI = rand() % 65536;
            }
            current = current->next;
        }
        current->next = new_struct;
    }
    pthread_mutex_unlock(&crc_indication_list_mutex);

    return new_struct;
}

// Function to validate the integrity of the generated list
bool validate_crc_indication_list(void) {
    // Check for duplicate RNTIs in the list
    pthread_mutex_lock(&crc_indication_list_mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = crc_indication_list;
    while (current != NULL) {
        if (current->next != NULL && current->RNTI == current->next->RNTI) {
            // Duplicate RNTI found, return false
            pthread_mutex_unlock(&crc_indication_list_mutex);
            return false;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&crc_indication_list_mutex);

    // Check that all CRCFLAGS fall within the specified valid range
    pthread_mutex_lock(&crc_indication_list_mutex);
    current = crc_indication_list;
    while (current != NULL) {
        if (current->CRCFLAG < 0 || current->CRCFLAG > 255) {
            // CRCFLAG out of range, return false
            pthread_mutex_unlock(&crc_indication_list_mutex);
            return false;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&crc_indication_list_mutex);

    // List is valid, return true
    return true;
}
