    struct MAC_HEADER macHeader;
    struct LLC_HEADER llcHeader;
    struct ERROR_CORRECTION_TAG errorCorrectionTag;
};

// Define the MAC_HEADER structure
struct MAC_HEADER {
    unsigned char destinationAddress[6];
    unsigned char sourceAddress[6];
    unsigned short frameControl;
};

// Define the LLC_HEADER structure
