// Structure to represent a node in the linked list
struct Node {
    int data;
    struct Node* next;
};

// Function to read integers from a file and store them in a linked list
void readIntegersFromFile(char* filename, int max_size) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Create a linked list to store the integers
    struct Node* head = NULL;
    int count = 0;

    // Read each integer from the file and add it to the linked list
    while (fscanf(fp, "%d", &data) == 1 && count < max_size) {
        // Check if the integer is valid
        if (!isValidInteger(data)) {
            printf("Error: invalid integer %d\n", data);
            continue;
        }

        // Create a new node and add it to the linked list
        struct Node* new_node = malloc(sizeof(struct Node));
        new_node->data = data;
        new_node->next = head;
        head = new_node;

        count++;
    }

    // Close the file
    fclose(fp);

    // Print the largest integer in the list
    printf("Largest integer: %d\n", getLargestInteger(head));
}

// Function to check if an integer is valid
int isValidInteger(int data) {
    return (data >= INT_MIN && data <= INT_MAX);
}

// Function to get the largest integer in a linked list
int getLargestInteger(struct Node* head) {
    int largest = INT_MIN;
    while (head != NULL) {
        if (head->data > largest) {
            largest = head->data;
        }
        head = head->next;
    }
    return largest;
}

// Function to limit the maximum number of integers stored in the list
void limitMaxSize(struct Node* head, int max_size) {
    // If the linked list is already at its maximum size, remove the first node
    if (count >= max_size) {
        struct Node* temp = head;
        head = head->next;
        free(temp);
    }
}

// Function to handle memory allocation failures
void handleMemoryAllocationFailure() {
    printf("Error: unable to allocate memory\n");
}

// Function to handle malformed input data
void handleMalformedInputData() {
    printf("Error: invalid integer found in file\n");
}

// Main function to demonstrate the use of the readIntegersFromFile function
int main(int argc, char* argv[]) {
    if (argc != 3) {
        printf("Usage: %s <filename> <max_size>\n", argv[0]);
        return 1;
    }

    readIntegersFromFile(argv[1], atoi(argv[2]));

    return 0;
}
