// Define the mutex for protecting concurrent access to the configuration data
pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and populate an array of LTE PHY test configurations
int init_lte_phy_test_configs(int num_configs) {
    // Validate input parameters
    if (num_configs <= 0) {
        return -1;
    }

    // Allocate memory for the array of LTE PHY test configurations
    lte_phy_test_configs = malloc(sizeof(LTE_PHY_TEST_CONFIG_T) * num_configs);
    if (lte_phy_test_configs == NULL) {
        return -1;
    }

    // Initialize each configuration structure with a unique frequency band, bandwidth, and cell ID
    for (int i = 0; i < num_configs; i++) {
        lte_phy_test_configs[i].frequency_band = i + 1;
        lte_phy_test_configs[i].bandwidth = i * 2 + 1;
        lte_phy_test_configs[i].cell_id = i + 100;
    }

    // Initialize each CRC indication PDU structure with a randomly set CRCFLAG
    for (int i = 0; i < num_configs; i++) {
        lte_phy_test_configs[i].crc_indication_pdu.rx_ue_information_tag = rand() % 10 + 1;
        lte_phy_test_configs[i].crc_indication_pdu.rnti = rand() % 1000 + 1;
        lte_phy_test_configs[i].crc_indication_pdu.crc_indication_rel8_tag = rand() % 2 == 0 ? 1 : 0;
    }

    return num_configs;
}

// Function to add a new configuration to the array of LTE PHY test configurations
int add_lte_phy_test_config(LTE_PHY_TEST_CONFIG_T *new_config) {
    // Validate input parameters
    if (new_config == NULL) {
        return -1;
    }

    // Acquire the mutex for protecting concurrent access to the configuration data
    pthread_mutex_lock(&config_mutex);

    // Allocate memory for the new configuration structure
    LTE_PHY_TEST_CONFIG_T *new_config_ptr = malloc(sizeof(LTE_PHY_TEST_CONFIG_T));
    if (new_config_ptr == NULL) {
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }

    // Copy the new configuration structure to the allocated memory
    memcpy(new_config_ptr, new_config, sizeof(LTE_PHY_TEST_CONFIG_T));

    // Add the new configuration structure to the array of LTE PHY test configurations
    lte_phy_test_configs = realloc(lte_phy_test_configs, (num_configs + 1) * sizeof(LTE_PHY_TEST_CONFIG_T));
    if (lte_phy_test_configs == NULL) {
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }
    lte_phy_test_configs[num_configs] = *new_config_ptr;

    // Release the mutex for protecting concurrent access to the configuration data
    pthread_mutex_unlock(&config_mutex);

    return num_configs + 1;
}

// Function to remove a configuration from the array of LTE PHY test configurations
int remove_lte_phy_test_config(int config_index) {
    // Validate input parameters
    if (config_index < 0 || config_index >= num_configs) {
        return -1;
    }

    // Acquire the mutex for protecting concurrent access to the configuration data
    pthread_mutex_lock(&config_mutex);

    // Remove the specified configuration structure from the array of LTE PHY test configurations
    lte_phy_test_configs = realloc(lte_phy_test_configs, (num_configs - 1) * sizeof(LTE_PHY_TEST_CONFIG_T));
    if (lte_phy_test_configs == NULL) {
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }
    for (int i = config_index; i < num_configs - 1; i++) {
        lte_phy_test_configs[i] = lte_phy_test_configs[i + 1];
    }

    // Release the mutex for protecting concurrent access to the configuration data
    pthread_mutex_unlock(&config_mutex);

    return num_configs - 1;
}

// Function to modify a configuration in the array of LTE PHY test configurations
int modify_lte_phy_test_config(int config_index, LTE_PHY_TEST_CONFIG_T *new_config) {
    // Validate input parameters
    if (config_index < 0 || config_index >= num_configs || new_config == NULL) {
        return -1;
    }

    // Acquire the mutex for protecting concurrent access to the configuration data
    pthread_mutex_lock(&config_mutex);

    // Copy the new configuration structure to the specified configuration structure in the array of LTE PHY test configurations
    memcpy(&lte_phy_test_configs[config_index], new_config, sizeof(LTE_PHY_TEST_CONFIG_T));

    // Release the mutex for protecting concurrent access to the configuration data
    pthread_mutex_unlock(&config_mutex);

    return 0;
}

// Function to serialize the configuration data to disk for persistence across application restarts
int serialize_lte_phy_test_configs(char *filename) {
    // Validate input parameters
