        return -1;
    }

    // Initialize a union-find data structure for tracking disjoint pairs of RNTI and RX_UE_INFORMATION_TAG
    UnionFind *uf = (UnionFind *)malloc(sizeof(UnionFind) * N);
    if (!uf) {
        printf("Memory allocation failed\n");
        free(list);
        return -1;
