    clock_t start = clock();
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (uf[i].RNTI == uf[j].RNTI && uf[i].RX_UE_INFORMATION_TAG == uf[j].RX_UE_INFORMATION_TAG) {
                count++;
            } else {
                UnionFind *tmp = (UnionFind *)realloc(uf, sizeof(UnionFind) * (N + 1));
                if (!tmp) {
                    printf("Memory reallocation failed\n");
                    free(list);
                    free(uf);
                    return -1;
                } else {
                    uf = tmp;
                }
                uf[N].RNTI = RNTI[i];
                uf[N].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG[i];
            }
        }
    }

    // Print the number of milliseconds taken to perform the disjointness check for each pair
    clock_t end = clock();
    double time_spent = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Time spent: %f\n", time_spent);

    // Return the count of disjoint pairs identified
    return count;
}
