        return NULL;
    }

    // Copy the input string to the output string
    strcpy(outputStr, str);

    // Append a newline character to the end of the output string if it does not exceed the size limit
    if (strLen < sizeLimit) {
        outputStr[strLen] = '\n';
        outputStr[strLen + 1] = '\0';
