// Function to initialize the list data structure
void init_list(LIST_DATA_STRUCTURE *list) {
    // Allocate memory for the list and set the initial size to 0
    list->pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1);
    list->num_pdus = 0;
}

// Function to add a new PDU to the list
void add_pdu(LIST_DATA_STRUCTURE *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Acquire the mutex to protect the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Check if there is enough memory allocated for the new PDU
    if (list->num_pdus >= list->pdu_list) {
        // Reallocate the memory to accommodate the new PDU
        list->pdu_list = realloc(list->pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->num_pdus + 1));
    }

    // Copy the new PDU to the end of the list
    memcpy(&list->pdu_list[list->num_pdus], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->num_pdus++;

    // Release the mutex
    pthread_mutex_unlock(&list_mutex);
}

// Function to remove a PDU from the list
void remove_pdu(LIST_DATA_STRUCTURE *list, size_t index) {
    // Acquire the mutex to protect the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Check if the index is valid
    if (index >= list->num_pdus) {
        // Release the mutex and return
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // Shift all the PDUs after the specified index to fill the gap
    memmove(&list->pdu_list[index], &list->pdu_list[index + 1], (list->num_pdus - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Decrement the number of PDUs by 1
    list->num_pdus--;

    // Release the mutex
    pthread_mutex_unlock(&list_mutex);
}

// Function to retrieve a PDU from the list
NFAPI_CRC_INDICATION_PDU_T *get_pdu(LIST_DATA_STRUCTURE *list, size_t index) {
    // Acquire the mutex to protect the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Check if the index is valid
    if (index >= list->num_pdus) {
        // Release the mutex and return NULL
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    // Return a pointer to the PDU at the specified index
