    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_STRUCTURE {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct NFAPI_CRC_INDICATION_STRUCTURE *next;
} NFAPI_CRC_INDICATION_STRUCTURE;

static NFAPI_CRC_INDICATION_STRUCTURE *head = NULL;
static size_t num_structures = 0;

void add_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    assert(num_structures < MAX_STRUCTURES);
    NFAPI_CRC_INDICATION_STRUCTURE *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_STRUCTURE));
    new_node->pdu = pdu;
    new_node->next = head;
    head = new_node;
    num_structures++;
}

void remove_structure(size_t index) {
    assert(index < num_structures);
    NFAPI_CRC_INDICATION_STRUCTURE *current = head;
    for (size_t i = 0; i < index - 1; i++) {
        current = current->next;
    }
    NFAPI_CRC_INDICATION_STRUCTURE *to_remove = current->next;
    current->next = to_remove->next;
    free(to_remove);
    num_structures--;
}

void update_structure(size_t index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    assert(index < num_structures);
    NFAPI_CRC_INDICATION_STRUCTURE *current = head;
    for (size_t i = 0; i < index - 1; i++) {
        current = current->next;
    }
    current->pdu = pdu;
}

void iterate_structures(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    NFAPI_CRC_INDICATION_STRUCTURE *current = head;
    while (current != NULL) {
        callback(current->pdu);
        current = current->next;
    }
}

void free_structures() {
    NFAPI_CRC_INDICATION_STRUCTURE *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_STRUCTURE *to_free = current;
        current = current->next;
        free(to_free);
    }
}
