        $backoff = 100; // initial backoff time in milliseconds
        while ($backoff < 60000) { // maximum backoff time in milliseconds
            try {
                // Retry the database operation with an exponential backoff strategy
                sleep($backoff);
                $dao = new UserAccountDao();
                $connection = $dao->getConnection();
                $statement = $connection->prepare("UPDATE users SET password = ?, email = ?, notification_preferences = ? WHERE id = ?");
                $statement->bindValue(1, $password);
