                $statement->bindValue(3, json_encode($notificationPreferences));
                $statement->bindValue(4, $userId);
                $statement->execute();
                break; // exit the retry loop on success
            } catch (PDOException $e) {
                $backoff *= 2; // exponential backoff strategy
            }
        }
    }
}
