// Define the structure to hold the cellular base station configuration
typedef struct {
    char* bssid;
    int frequency_band;
    int channel_map[N]; // N is the maximum number of concurrent channels
} CELLULAR_BASE_STATION_CONFIG_T;

// Define a function to initialize and manage the dynamic array of base station configurations
void init_base_station_configs(CELLULAR_BASE_STATION_CONFIG_T** configs, int num_bssids) {
    // Allocate memory for the array of base station configurations
    *configs = (CELLULAR_BASE_STATION_CONFIG_T*)malloc(num_bssids * sizeof(CELLULAR_BASE_STATION_CONFIG_T));
    if (*configs == NULL) {
        printf("Error: Failed to allocate memory for base station configurations\n");
        return;
    }

    // Initialize each base station configuration structure
    for (int i = 0; i < num_bssids; i++) {
        (*configs)[i].bssid = NULL;
        (*configs)[i].frequency_band = -1;
        memset((*configs)[i].channel_map, 0, N * sizeof(int));
    }
}

// Define a function to add a new base station configuration to the array
void add_base_station_config(CELLULAR_BASE_STATION_CONFIG_T** configs, int num_bssids, char* bssid, int frequency_band) {
    // Check if there is enough memory available for a new base station configuration
    if (num_bssids >= N) {
        printf("Error: Maximum number of base station configurations reached\n");
        return;
    }

    // Allocate memory for the new base station configuration structure
    CELLULAR_BASE_STATION_CONFIG_T* new_config = (CELLULAR_BASE_STATION_CONFIG_T*)malloc(sizeof(CELLULAR_BASE_STATION_CONFIG_T));
    if (new_config == NULL) {
        printf("Error: Failed to allocate memory for new base station configuration\n");
        return;
    }

    // Initialize the new base station configuration structure
    new_config->bssid = bssid;
    new_config->frequency_band = frequency_band;
    memset(new_config->channel_map, 0, N * sizeof(int));

    // Add the new base station configuration to the array
    (*configs)[num_bssids] = new_config;
    num_bssids++;
}

// Define a function to remove a base station configuration from the array
void remove_base_station_config(CELLULAR_BASE_STATION_CONFIG_T** configs, int* num_bssids, char* bssid) {
    // Find the index of the base station configuration to be removed
    int index = -1;
    for (int i = 0; i < *num_bssids; i++) {
        if (strcmp((*configs)[i].bssid, bssid) == 0) {
            index = i;
            break;
        }
    }

    // Check if the base station configuration was found in the array
    if (index < 0) {
        printf("Error: Base station configuration not found\n");
        return;
    }

    // Remove the base station configuration from the array
    for (int i = index; i < *num_bssids - 1; i++) {
        (*configs)[i] = (*configs)[i + 1];
    }
    *num_bssids -= 1;
}

// Define a function to update the channel map for a base station configuration in the array
void update_channel_map(CELLULAR_BASE_STATION_CONFIG_T** configs, int* num_bssids, char* bssid, int frequency_band) {
    // Find the index of the base station configuration to be updated
    int index = -1;
    for (int i = 0; i < *num_bssids; i++) {
        if (strcmp((*configs)[i].bssid, bssid) == 0 && (*configs)[i].frequency_band == frequency_band) {
            index = i;
            break;
        }
    }

    // Check if the base station configuration was found in the array
    if (index < 0) {
        printf("Error: Base station configuration not found\n");
        return;
    }

    // Update the channel map for the base station configuration
    (*configs)[index].channel_map = (int*)realloc((*configs)[index].channel_map, N * sizeof(int));
    if ((*configs)[index].channel_map == NULL) {
        printf("Error: Failed to update channel map for base station configuration\n");
        return;
    }
}
