    int i;
    for (i = 0; i < list->size; i++) {
        if (list->contexts[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the context was found, update its fields and set the last activity time to the current time
    if (i < list->size) {
        list->contexts[i]->cell_identity = cell_identity;
        list->contexts[i]->radio_resource_config = radio_resource_config;
        list->contexts[i]->last_activity = time(NULL);
    }
