    for (i = 0; i < list->size; i++) {
        if (list->contexts[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the context was found, return it
    if (i < list->size) {
        return list->contexts[i];
    } else {
        return NULL;
    }
}

// Function to evict LTE UE context records that have been inactive for more than 30 minutes
void evict_inactive_lte_ue_contexts(lte_ue_context_list* list) {
    // Get the current time
    time_t now = time(NULL);

    // Iterate over the contexts and evict those that have been inactive for more than 30 minutes
    int i;
    for (i = 0; i < list->size; i++) {
        if (difftime(now, list->contexts[i]->last_activity) > 30 * 60) {
            // Evict the context by removing it from the list and freeing its memory
            struct lte_ue_context* evicted_context = list->contexts[i];
            list->size--;
            list->contexts = realloc(list->contexts, sizeof(struct lte_ue_context*) * list->size);
            free(evicted_context);
        }
    }
}

