    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the array of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;

// Define the mutex for synchronizing access to the array
pthread_mutex_t crc_indications_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and populate an array of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_T *allocate_crc_indications(int num_elements) {
    // Check if the input is valid
    if (num_elements <= 0 || num_elements > 10000) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indications_mutex);

    // Allocate memory for the array of CRC indication PDUs
    crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        pthread_mutex_unlock(&crc_indications_mutex);
        return NULL;
    }

    // Initialize the array of CRC indication PDUs
    for (int i = 0; i < num_elements; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = i + 1;
        crc_indications[i].RNTI = rand() % 65536;
        crc_indications[i].CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indications_mutex);

    return crc_indications;
}

// Function to free the array of CRC indication PDUs
void free_crc_indications() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indications_mutex);

    // Free the memory for the array of CRC indication PDUs
    if (crc_indications) {
        free(crc_indications);
        crc_indications = NULL;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indications_mutex);
}
