// Define the function to fetch real-time network metrics for a given UE using an external service
NetworkResponseCache *fetchNetworkMetrics(int ueId) {
    // Fetch real-time network metrics for the given UE from an external service
    NetworkResponseCache *cache = malloc(sizeof(NetworkResponseCache));
    if (cache == NULL) {
        printf("Error: Failed to allocate memory for NetworkResponseCache\n");
        return NULL;
    }

    // Check if the external service is available and update the cache accordingly
    if (!isServiceAvailable()) {
        printf("Warning: External service is unavailable. Using cached metrics instead.\n");
