    if (signalStrength == -1) {
        printf("Error: Failed to fetch signal strength for UE %d\n", ueId);
        free(cache);
        return NULL;
    }

    cache->isCached = false;
    cache->ueId = ueId;
    cache->measurementInterval = measurementInterval;
    cache->signalStrength = signalStrength;

    return cache;
}

