    // Initialize each AP's security configuration
    for (int i = 0; i < num_aps; i++) {
        WIFI_AP_INFO_T* ap = &(*ap_info)[i];
        ap->ssid = NULL;
        ap->security_type = -1;
        ap->key = NULL;
