    // Validate configuration parameters and handle edge cases
    for (int i = 0; i < num_aps; i++) {
        WIFI_AP_INFO_T* ap = &(*ap_info)[i];
        if (ap->ssid == NULL || ap->security_type < 0) {
            printf("Invalid configuration for AP %d\n", i);
            return;
