    }

    // Generate random keys for each AP if not provided
    for (int i = 0; i < num_aps; i++) {
        WIFI_AP_INFO_T* ap = &(*ap_info)[i];
        if (ap->key == NULL) {
            char key[16];
            sprintf(key, "%08x", rand());
            ap->key = strdup(key);
        }
    }

    // Validate SSIDs for overlaps and adhere to maximum number of SSIDs per AP
    for (int i = 0; i < num_aps; i++) {
        WIFI_AP_INFO_T* ap = &(*ap_info)[i];
        for (int j = i + 1; j < num_aps; j++) {
