// Define the function to manage the dynamic array of NR_PHY_RX_CONFIG_T structures
void manage_slices(NR_PHY_RX_CONFIG_T **slices, int *num_slices) {
    // Check if there is enough memory available for a new slice
    if (*num_slices >= MAX_SLICES) {
        printf("Error: Maximum number of slices reached\n");
        return;
    }

    // Allocate memory for the new slice
    NR_PHY_RX_CONFIG_T *new_slice = (NR_PHY_RX_CONFIG_T *)malloc(sizeof(NR_PHY_RX_CONFIG_T));
    if (!new_slice) {
        printf("Error: Failed to allocate memory for new slice\n");
        return;
    }

    // Initialize the new slice and its associated set of downlink beams
    new_slice->slice_id = *num_slices;
    new_slice->num_beams = 0;
    new_slice->beamforming_report = (NFAPI_BEAMFORMING_REPORT_PDU_T *)malloc(sizeof(NFAPI_BEAMFORMING_REPORT_PDU_T) * MAX_BEAMS);
    if (!new_slice->beamforming_report) {
        printf("Error: Failed to allocate memory for new slice's beamforming report\n");
        free(new_slice);
        return;
    }

    // Add the new slice to the array of slices
    (*slices)[*num_slices] = new_slice;
    *num_slices += 1;
}

// Define the function to add a new downlink beam to an existing slice
void add_beam(NR_PHY_RX_CONFIG_T **slices, int num_slices, int slice_id) {
    // Check if the specified slice exists and has enough memory available for a new beam
    if (slice_id >= num_slices || (*slices)[slice_id]->num_beams >= MAX_BEAMS) {
        printf("Error: Invalid slice ID or maximum number of beams reached\n");
        return;
    }

    // Allocate memory for the new beam and initialize its signal strength measurement and direction vector
    NFAPI_BEAMFORMING_REPORT_PDU_T *new_beam = (NFAPI_BEAMFORMING_REPORT_PDU_T *)malloc(sizeof(NFAPI_BEAMFORMING_REPORT_PDU_T));
    if (!new_beam) {
        printf("Error: Failed to allocate memory for new beam\n");
        return;
    }
    (*slices)[slice_id]->beamforming_report[(*slices)[slice_id]->num_beams] = new_beam;
    (*slices)[slice_id]->num_beams += 1;
}

// Define the function to validate that no two slices overlap in their assigned downlink beams
void validate_overlap(NR_PHY_RX_CONFIG_T **slices, int num_slices) {
    // Iterate over all pairs of slices and check for overlapping downlink beams
    for (int i = 0; i < num_slices - 1; i++) {
        for (int j = i + 1; j < num_slices; j++) {
            // Check if the two slices share any common downlink beams
            for (int k = 0; k < (*slices)[i]->num_beams && k < (*slices)[j]->num_beams; k++) {
                if ((*slices)[i]->beamforming_report[k] == (*slices)[j]->beamforming_report[k]) {
                    printf("Error: Overlapping downlink beams between slices %d and %d\n", i, j);
                    return;
                }
            }
        }
    }
}

// Define the function to ensure that each slice adheres to a predefined maximum beam count
void validate_beam_count(NR_PHY_RX_CONFIG_T **slices, int num_slices) {
    // Iterate over all slices and check if they have exceeded their maximum allowed number of beams
    for (int i = 0; i < num_slices; i++) {
        if ((*slices)[i]->num_beams > MAX_BEAMS) {
            printf("Error: Slice %d has exceeded its maximum allowed number of beams\n", i);
            return;
        }
    }
}
