// Define a structure for storing connection information
typedef struct {
    int connection_id;
    long timestamp;
    int signal_strength;
} ConnectionInfo;

// Define a structure for storing device state information
typedef struct {
    ConnectionInfo *connections; // Array of connections
    size_t num_connections;      // Number of connections in the array
    pthread_mutex_t mutex;       // Mutex for thread-safe access
} DeviceState;

// Function to add a new connection to the device state
void addConnection(DeviceState *state, int connection_id, long timestamp, int signal_strength) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&state->mutex);

    // Check if there is enough space in the array for a new connection
    if (state->num_connections == state->connections.size()) {
        // If not, double the size of the array
        state->connections = realloc(state->connections, 2 * state->connections.size() * sizeof(ConnectionInfo));
    }

    // Add the new connection to the end of the array
    state->connections[state->num_connections].connection_id = connection_id;
    state->connections[state->num_connections].timestamp = timestamp;
    state->connections[state->num_connections].signal_strength = signal_strength;
    state->num_connections++;

    // Unlock the mutex
    pthread_mutex_unlock(&state->mutex);
}

// Function to update an existing connection in the device state
void updateConnection(DeviceState *state, int connection_id, long timestamp, int signal_strength) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&state->mutex);

    // Find the index of the connection in the array
    size_t i;
    for (i = 0; i < state->num_connections; i++) {
        if (state->connections[i].connection_id == connection_id) {
            break;
        }
    }

    // If the connection was found, update its information
    if (i < state->num_connections) {
        state->connections[i].timestamp = timestamp;
        state->connections[i].signal_strength = signal_strength;
    } else {
        // If not, add a new connection to the end of the array
        addConnection(state, connection_id, timestamp, signal_strength);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&state->mutex);
}

// Function to retrieve the latest signal strength for a given connection ID
int getSignalStrength(DeviceState *state, int connection_id) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&state->mutex);

    // Find the index of the connection in the array
    size_t i;
    for (i = 0; i < state->num_connections; i++) {
        if (state->connections[i].connection_id == connection_id) {
            break;
        }
    }

    // If the connection was found, return its signal strength
    int signal_strength = 0;
    if (i < state->num_connections) {
        signal_strength = state->connections[i].signal_strength;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&state->mutex);

    return signal_strength;
}

// Function to clean up old entries in the device state that have not been updated within a specified grace period
void cleanupDeviceState(DeviceState *state, long grace_period) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&state->mutex);

    // Find the index of the first entry that has not been updated within the grace period
    size_t i;
    for (i = 0; i < state->num_connections; i++) {
        if (state->connections[i].timestamp + grace_period <= time(NULL)) {
            break;
        }
    }

    // If there are any entries that have not been updated within the grace period, remove them from the array
    if (i < state->num_connections) {
        size_t num_removed = 0;
        for (size_t j = i; j < state->num_connections - num_removed; j++) {
            if (state->connections[j].timestamp + grace_period <= time(NULL)) {
                // Remove the entry from the array and decrement the number of connections
                free(state->connections[j]);
                state->num_connections--;
                num_removed++;
            } else {
                break;
            }
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&state->mutex);
}
