void init_mac_configs(int num_configs) {
    // Allocate memory for the dynamic array
    mac_configs = (mac_config_t *)malloc(num_configs * sizeof(mac_config_t));
    if (!mac_configs) {
        printf("Error: Failed to allocate memory for MAC entity configurations\n");
        return;
    }

    // Initialize the dynamic array with default values
    for (int i = 0; i < num_configs; i++) {
        mac_configs[i].lcid = -1;
        mac_configs[i].priority = -1;
    }
}

// Function to retrieve initial configuration templates from an external data source and apply them to the dynamic array
void populate_mac_configs(int num_templates) {
    // Retrieve the initial configuration templates from the external data source
    int *templates = (int *)malloc(num_templates * sizeof(int));
    if (!templates) {
        printf("Error: Failed to retrieve initial configuration templates\n");
        return;
    }

    // Apply the retrieved templates to the dynamic array of MAC entity configurations
    for (int i = 0; i < num_templates; i++) {
        int template = templates[i];
        if (template >= 0 && template < num_configs) {
            mac_configs[template].lcid = template;
            mac_configs[template].priority = i % 2 ? 1 : -1;
        } else {
            printf("Warning: Ignoring invalid configuration template (%d)\n", template);
        }
    }
}

// Function to handle memory allocation failures gracefully and provide detailed logging for debugging purposes
void handle_memory_allocation_failure(const char *message) {
    printf("Error: %s\n", message);
    free(mac_configs);
    mac_configs = NULL;
}

// Function to ensure that no two configurations have the same LCID and that priorities are within a specified range
void validate_mac_configs() {
    // Check for duplicate LCIDs
    for (int i = 0; i < num_configs - 1; i++) {
        for (int j = i + 1; j < num_configs; j++) {
            if (mac_configs[i].lcid == mac_configs[j].lcid) {
                printf("Error: Duplicate LCID found in MAC entity configurations\n");
                return;
            }
        }
    }

    // Check for priorities within the specified range
    for (int i = 0; i < num_configs; i++) {
        if (mac_configs[i].priority < -1 || mac_configs[i].priority > 1) {
            printf("Error: Priority setting out of range in MAC entity configuration %d\n", i);
            return;
        }
    }
}
