class MacEntityConfigManager {
private:
    std::vector<MacEntityConfig> configs_;
    std::map<int, int> lcid_to_index_;
    pthread_mutex_t mutex_;
    size_t threshold_;

public:
    MacEntityConfigManager(size_t threshold = 10) : threshold_(threshold) {
        pthread_mutex_init(&mutex_, NULL);
    }

    ~MacEntityConfigManager() {
        pthread_mutex_destroy(&mutex_);
    }

    void add(const MacEntityConfig& config) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (configs_.size() >= threshold_) {
            clear();
        }
        int index = configs_.size();
        configs_.push_back(config);
        lcid_to_index_[config.lcid] = index;
    }

    void remove(int lcid) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = lcid_to_index_.find(lcid);
        if (it != lcid_to_index_.end()) {
            int index = it->second;
            configs_.erase(configs_.begin() + index);
            lcid_to_index_.erase(it);
        }
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mutex_);
        configs_.clear();
        lcid_to_index_.clear();
    }

    MacEntityConfig get(int lcid) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = lcid_to_index_.find(lcid);
        if (it != lcid_to_index_.end()) {
            return configs_[it->second];
        } else {
            MacEntityConfig empty;
            return empty;
        }
