#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for a Network Interface Control Block (NICB)
typedef struct nicb {
    char mac_address[6]; // MAC address of the NICB
    int vlan_id; // VLAN ID of the NICB
    int num_ipv4_addrs; // Number of IPv4 addresses associated with the NICB
    struct ipv4_addr *ipv4_addrs; // Array of IPv4 addresses associated with the NICB
} nicb_t;

// Define the structure for an IPv4 address
typedef struct ipv4_addr {
    unsigned char addr[4]; // IPv4 address in dotted-decimal notation
} ipv4_addr_t;

// Define the structure for a flow entry
typedef struct flow_entry {
    nicb_t *nicb; // NICB associated with the flow entry
    int src_port; // Source port number
    int dst_port; // Destination port number
} flow_entry_t;

// Define the structure for a flow table
typedef struct flow_table {
    int num_flows; // Number of flow entries in the table
    flow_entry_t *flows; // Array of flow entries
} flow_table_t;

// Function to initialize a dynamic array of NICB structures
nicb_t **init_nicbs(int num_nicbs) {
    nicb_t **nicbs = (nicb_t **)malloc(num_nicbs * sizeof(nicb_t *));
    for (int i = 0; i < num_nicbs; i++) {
        nicbs[i] = (nicb_t *)malloc(sizeof(nicb_t));
        memset(nicbs[i], 0, sizeof(nicb_t));
    }
    return nicbs;
}

// Function to initialize a dynamic array of flow entries
flow_entry_t **init_flows(int num_flows) {
    flow_entry_t **flows = (flow_entry_t **)malloc(num_flows * sizeof(flow_entry_t *));
    for (int i = 0; i < num_flows; i++) {
        flows[i] = (flow_entry_t *)malloc(sizeof(flow_entry_t));
        memset(flows[i], 0, sizeof(flow_entry_t));
    }
    return flows;
}

// Function to add a flow entry to the flow table
void add_flow_entry(flow_table_t *flow_table, nicb_t *nicb, int src_port, int dst_port) {
    // Check if there is enough space in the flow table for another flow entry
    if (flow_table->num_flows >= 50000) {
        printf("Error: Flow table is full\n");
        return;
    }

    // Allocate memory for a new flow entry
    flow_entry_t *new_flow = (flow_entry_t *)malloc(sizeof(flow_entry_t));
    memset(new_flow, 0, sizeof(flow_entry_t));

    // Set the NICB and port numbers for the new flow entry
    new_flow->nicb = nicb;
    new_flow->src_port = src_port;
    new_flow->dst_port = dst_port;

    // Add the new flow entry to the flow table
    flow_table->flows[flow_table->num_flows++] = new_flow;
}

// Function to remove a flow entry from the flow table
void remove_flow_entry(flow_table_t *flow_table, int index) {
    // Check if the specified index is valid
    if (index < 0 || index >= flow_table->num_flows) {
        printf("Error: Invalid index\n");
        return;
    }

    // Free the memory for the removed flow entry
    free(flow_table->flows[index]);

    // Shift all subsequent flow entries down by one index
    for (int i = index + 1; i < flow_table->num_flows; i++) {
        flow_table->flows[i - 1] = flow_table->flows[i];
    }

    // Decrement the number of flow entries in the table
    flow_table->num_flows--;
}

// Function to lookup a flow entry in the flow table based on source and destination IP addresses and port numbers
int lookup_flow_entry(flow_table_t *flow_table, nicb_t *nicb, int src_port, int dst_port) {
    // Iterate over all flow entries in the table
    for (int i = 0; i < flow_table->num_flows; i++) {
        // Check if the current flow entry matches the specified source and destination IP addresses and port numbers
        if (flow_table->flows[i]->nicb == nicb && flow_table->flows[i]->src_port == src_port && flow_table->flows[i]->dst_port == dst_port) {
            return i; // Return the index of the matching flow entry
        }
    }

    // If no matching flow entry is found, return -1
    return -1;
}

// Function to add a NICB to the flow table and populate its flow entries
void add_nicb(flow_table_t *flow_table, nicb_t *nicb) {
    // Check if there is enough space in the flow table for another NICB
    if (flow_table->num_nicbs >= 10000) {
        printf("Error: Flow table is full\n");
        return;
    }

    // Allocate memory for a new NICB structure
    flow_table->nicbs[flow_table->num_nicbs++] = nicb;

    // Populate the flow entries for the new NICB
    for (int i = 0; i < nicb->num_ipv4_addrs; i++) {
        add_flow_entry(flow_table, nicb, i, i);
    }
}

// Function to remove a NICB from the flow table and delete its flow entries
void remove_nicb(flow_table_t *flow_table, int index) {
    // Check if the specified index is valid
    if (index < 0 || index >= flow_table->num_nicbs) {
        printf("Error: Invalid index\n");
        return;
    }

    // Remove all flow entries associated with the NICB at the specified index
    for (int i = 0; i < flow_table->flows[index]->num_ipv4_addrs; i++) {
        remove_flow_entry(flow_table, lookup_flow_entry(flow_table, flow_table->nicbs[index], i, i));
    }

    // Free the memory for the removed NICB structure
    free(flow_table->nicbs[index]);

    // Shift all subsequent NICBs down by one index
    for (int i = index + 1; i < flow_table->num_nicbs; i++) {
        flow_table->nicbs[i - 1] = flow_table->nicbs[i];
    }

    // Decrement the number of NICBs in the table
    flow_table->num_nicbs--;
}
```
This code defines a `flow_table_t` structure that contains an array of `flow_entry_t` structures and an array of `nicb_t` structures. The `add_flow_entry()` function adds a new flow entry to the table, while the `remove_flow_entry()` function removes a specific flow entry from the table. The `lookup_flow_entry()` function returns the index of a matching flow entry in the table, or -1 if no match is found.

The `add_nicb()` function adds a new NICB to the table and populates its flow entries using the `add_flow_entry()` function. The `remove_nicb()` function removes a specific NICB from the table and deletes its flow entries using the `remove_flow_entry()` function.

