// Define the mutex for protecting the list of user sessions
static pthread_mutex_t session_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to initialize and manage the dynamic list of user sessions
void init_user_sessions() {
    // Allocate memory for the list of user sessions
    user_sessions = (UserSession*)malloc(sizeof(UserSession) * 10);
    if (!user_sessions) {
        printf("Failed to allocate memory for user sessions\n");
        return;
    }

    // Initialize the list of user sessions
    for (int i = 0; i < 10; i++) {
        user_sessions[i].session_id = -1;
        user_sessions[i].user_name = NULL;
        user_sessions[i].last_activity_time = time(NULL);
    }
}

// Define the function to add a new user session
void add_user_session(int session_id, char* user_name) {
    // Acquire the mutex for protecting the list of user sessions
    pthread_mutex_lock(&session_list_mutex);

    // Check if the session ID is already in use
    for (int i = 0; i < 10; i++) {
        if (user_sessions[i].session_id == session_id) {
            printf("Session ID %d is already in use\n", session_id);
            pthread_mutex_unlock(&session_list_mutex);
            return;
        }
    }

    // Find an empty slot in the list of user sessions
    int index = -1;
    for (int i = 0; i < 10; i++) {
        if (user_sessions[i].session_id == -1) {
            index = i;
            break;
        }
    }

    // Add the new user session to the list
    if (index != -1) {
        user_sessions[index].session_id = session_id;
        user_sessions[index].user_name = strdup(user_name);
        user_sessions[index].last_activity_time = time(NULL);
    } else {
        printf("No more slots available for new user sessions\n");
    }

    // Release the mutex for protecting the list of user sessions
    pthread_mutex_unlock(&session_list_mutex);
}

