                update_timeout(sockets[i]->fd, -1);
            } else {
                // Check if the current time is greater than the timeout value
                struct timespec now;
                clock_gettime(CLOCK_REALTIME, &now);
                if (now.tv_sec > sockets[i]->timeout) {
