    int fd = connect_client(ip_addr, port);
    if (fd < 0) {
        perror("connect");
        return;
    }

    // Update the timeout value for the socket descriptor
    update_timeout(fd, -1);
}

// Function to handle a disconnection from a client
void handle_disconnection(const char *ip_addr, unsigned short port) {
    // Find the socket descriptor with the given IP address and port number
    int i;
    for (i = 0; i < num_sockets; i++) {
        if (strcmp(sockets[i]->ip_addr, ip_addr) == 0 && sockets[i]->port == port) {
            break;
        }
    }
    if (i == num_sockets) {
        // No socket descriptor found with the given IP address and port number
        return;
    }

    // Close the socket descriptor
    close(sockets[i]->fd);

    // Remove the socket descriptor from the array of socket descriptors
    sockets = realloc(sockets, (num_sockets - 1) * sizeof(socket_desc_t));
    if (!sockets) {
        perror("realloc");
        return;
    }
}
