#include <errno.h>

#define MAX_CONNECTIONS 5000
#define TIMEOUT_SEC 30

typedef enum {
    CONN_ESTABLISHED,
    CONN_CLOSED,
    CONN_TIMEDOUT
} conn_state_t;

typedef struct {
    int sockfd;
    conn_state_t state;
    time_t timeout;
} socket_desc_t;

socket_desc_t* socket_descs = NULL;
pthread_mutex_t socket_descs_lock = PTHREAD_MUTEX_INITIALIZER;

void init_sockets() {
    // Initialize the socket descriptor array
    socket_descs = (socket_desc_t*) malloc(MAX_CONNECTIONS * sizeof(socket_desc_t));
    if (!socket_descs) {
        perror("malloc");
        exit(1);
    }
    memset(socket_descs, 0, MAX_CONNECTIONS * sizeof(socket_desc_t));
}

void close_sockets() {
    // Close all open sockets and free the socket descriptor array
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (socket_descs[i].state != CONN_CLOSED) {
            close(socket_descs[i].sockfd);
            socket_descs[i].state = CONN_CLOSED;
        }
    }
    free(socket_descs);
}

void update_timeouts() {
    // Update the timeout values for each connection
    time_t current_time = time(NULL);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (socket_descs[i].state == CONN_ESTABLISHED && socket_descs[i].timeout <= current_time) {
            // Connection timed out, close the socket and update state
            close(socket_descs[i].sockfd);
            socket_descs[i].state = CONN_TIMEDOUT;
        } else if (socket_descs[i].state == CONN_ESTABLISHED) {
            // Update the timeout value for the connection
            socket_descs[i].timeout += TIMEOUT_SEC;
        }
    }
}

void handle_connection(int sockfd, struct sockaddr* addr, int addrlen) {
    // Handle a new incoming connection
    pthread_mutex_lock(&socket_descs_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (socket_descs[i].state == CONN_CLOSED) {
            // Found a free slot, assign the socket descriptor and update state
            socket_descs[i].sockfd = sockfd;
            socket_descs[i].state = CONN_ESTABLISHED;
            socket_descs[i].timeout = time(NULL) + TIMEOUT_SEC;
            break;
        }
    }
    pthread_mutex_unlock(&socket_descs_lock);
}

void handle_disconnection(int sockfd) {
    // Handle a disconnected socket
    pthread_mutex_lock(&socket_descs_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (socket_descs[i].sockfd == sockfd) {
            // Close the socket and update state
            close(socket_descs[i].sockfd);
            socket_descs[i].state = CONN_CLOSED;
            break;
        }
    }
    pthread_mutex_unlock(&socket_descs_lock);
}

void* handle_connections(void* arg) {
    // Handle incoming connections and disconnections
    int sockfd = (int)arg;
    while (1) {
        struct sockaddr addr;
        socklen_t addrlen = sizeof(addr);
        int newsockfd = accept(sockfd, &addr, &addrlen);
        if (newsockfd == -1) {
            perror("accept");
            continue;
        }
        handle_connection(newsockfd, &addr, addrlen);
    }
}

int main() {
    // Initialize the socket descriptor array and start listening for incoming connections
    init_sockets();
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        perror("socket");
        exit(1);
    }
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);
    if (bind(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) == -1) {
        perror("bind");
        exit(1);
    }
    listen(sockfd, 3);

    // Start a thread to handle incoming connections and disconnections
    pthread_t conn_handler;
    if (pthread_create(&conn_handler, NULL, handle_connections, (void*)sockfd) != 0) {
        perror("pthread_create");
        exit(1);
    }

    // Periodically check and update timeout values
    while (1) {
        update_timeouts();
        sleep(TIMEOUT_SEC);
    }

    return 0;
}
