```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

// Define the maximum number of socket descriptors to manage
#define MAX_SOCKETS 1024

// Define the timeout value for each socket descriptor
#define TIMEOUT_SECS 30

// Define the state values for each socket descriptor
typedef enum {
    ESTABLISHED,
    SYN_SENT,
    FIN_WAIT
} SocketState;

// Structure to represent a socket descriptor and its associated state
struct SocketDescriptor {
    int fd; // File descriptor for the socket
    SocketState state; // Current state of the socket
    time_t timeout; // Timeout value for the socket
};

// Array to store all socket descriptors
static struct SocketDescriptor sockets[MAX_SOCKETS];

// Function to create a new socket descriptor and add it to the array
int createSocket(void) {
    int i, fd;

    // Find an empty slot in the array for the new socket descriptor
    for (i = 0; i < MAX_SOCKETS; i++) {
        if (sockets[i].fd == -1) {
            break;
        }
    }

    // If no empty slots found, return an error
    if (i >= MAX_SOCKETS) {
        return -1;
    }

    // Create a new socket descriptor and set its state to ESTABLISHED
    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd == -1) {
        perror("socket");
        return -1;
    }
    sockets[i].fd = fd;
    sockets[i].state = ESTABLISHED;
    sockets[i].timeout = time(NULL) + TIMEOUT_SECS;

    // Return the file descriptor for the new socket descriptor
    return fd;
}

// Function to establish a connection with a remote server and add it to the array
int connectSocket(const char *host, const char *port) {
    int i, fd;
    struct sockaddr_in addr;

    // Find an empty slot in the array for the new socket descriptor
    for (i = 0; i < MAX_SOCKETS; i++) {
        if (sockets[i].fd == -1) {
            break;
        }
    }

    // If no empty slots found, return an error
    if (i >= MAX_SOCKETS) {
        return -1;
    }

    // Create a new socket descriptor and set its state to SYN_SENT
    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd == -1) {
        perror("socket");
        return -1;
    }
    sockets[i].fd = fd;
    sockets[i].state = SYN_SENT;
    sockets[i].timeout = time(NULL) + TIMEOUT_SECS;

    // Set up the socket address structure for the remote server
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(atoi(port));
    if (inet_pton(AF_INET, host, &addr.sin_addr) <= 0) {
        perror("inet_pton");
        return -1;
    }

    // Connect to the remote server and set the state to ESTABLISHED
    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(fd);
        return -1;
    }
    sockets[i].state = ESTABLISHED;

    // Return the file descriptor for the new socket descriptor
    return fd;
}

// Function to update the state of a socket descriptor based on its current state and timeout value
void updateSocketState(int fd) {
    int i, ret;

    // Find the socket descriptor in the array
    for (i = 0; i < MAX_SOCKETS; i++) {
        if (sockets[i].fd == fd) {
            break;
        }
    }

    // If the socket descriptor is not found, return an error
    if (i >= MAX_SOCKETS) {
        perror("updateSocketState");
        return -1;
    }

    // Check if the timeout value has been reached and update the state accordingly
    if (sockets[i].timeout <= time(NULL)) {
        switch (sockets[i].state) {
            case ESTABLISHED:
                sockets[i].state = FIN_WAIT;
                break;
            case SYN_SENT:
                close(fd);
                return -1;
            default:
                break;
        }
    }
}

// Function to check and update the timeout values for all socket descriptors in the array
void checkTimeouts(void) {
    int i, ret;

    // Iterate over all socket descriptors in the array
    for (i = 0; i < MAX_SOCKETS; i++) {
        if (sockets[i].fd != -1) {
            updateSocketState(sockets[i].fd);
        }
    }
}

// Function to close a socket descriptor and remove it from the array
void closeSocket(int fd) {
    int i;

    // Find the socket descriptor in the array
    for (i = 0; i < MAX_SOCKETS; i++) {
        if (sockets[i].fd == fd) {
            break;
        }
    }

    // If the socket descriptor is not found, return an error
    if (i >= MAX_SOCKETS) {
        perror("closeSocket");
        return -1;
    }

    // Close the socket and set its state to -1
    close(fd);
    sockets[i].state = -1;
}
