            element_t *element = allocate_memory(sizeof(element_t), allocation_strategy);
            if (element) {
                element->id = id;
                element->value = value;
                count++;
            } else {
                fprintf(stderr, "Error: failed to allocate memory for element\n");
                return -1;
            }
        }
    } else if (input_file_format == INPUT_FILE_FORMAT_TXT) {
        char *line = NULL;
        size_t line_len = 0;
        while (getline(&line, &line_len, file) != -1) {
            // Parse the TXT data and allocate memory for each structure type
            char **tokens = strtok(line, " ");
            if (!tokens) {
                continue;
            }
            int id = atoi(tokens[0]);
            float value = atof(tokens[1]);
            element_t *element = allocate_memory(sizeof(element_t), allocation_strategy);
            if (element) {
                element->id = id;
                element->value = value;
                count++;
            } else {
                fprintf(stderr, "Error: failed to allocate memory for element\n");
                return -1;
            }
        }
    }

    // Close the input file and return the data
    fclose(file);
    *data = count;
    return 0;
}

// Define the function to cache frequently accessed data
void cache_data(const char *filename, void *data) {
    size_t hash = 0;
    for (size_t i = 0; i < strlen(filename); i++) {
        hash += filename[i];
    }
    hash %= CACHE_SIZE;

    // Check if the data is already cached and return it if it is
    if (cache[hash].data && cache[hash].size == sizeof(element_t) * count) {
        memcpy(data, cache[hash].data, cache[hash].size);
        return;
    }

    // Cache the data and update the cache hit rate
    cache[hash].data = data;
    cache[hash].size = sizeof(element_t) * count;
    CACHE_HIT_RATE += 1.0 / CACHE_SIZE;
}

// Define the function to handle I/O errors and free allocated memory
void handle_io_error(const char *filename, void **data) {
    fprintf(stderr, "Error: failed to read file (%s)\n", strerror(errno));
    deallocate_memory(*data);
}

// Define the function to handle unexpected errors and free allocated memory
void handle_unexpected_error(const char *filename, void **data) {
    fprintf(stderr, "Error: unexpected error occurred\n");
    deallocate_memory(*data);
}

// Define the main function that reads data from multiple input files and allocates memory for each structure type
int main() {
    // Declare variables to store the data for each structure type
    array_double_t *array_double = NULL;
    array_char_t *array_char = NULL;
    array_element_t *array_element = NULL;

    // Read data from multiple input files and allocate memory for each structure type
    read_data("input1.csv", ALLOCATION_STRATEGY_CONTIGUOUS, (void **)&array_double);
    read_data("input2.txt", ALLOCATION_STRATEGY_LINKED, (void **)&array_char);
    read_data("input3.csv", ALLOCATION_STRATEGY_CONTIGUOUS, (void **)&array_element);

    // Cache frequently accessed data and update the cache hit rate
    cache_data("input1.csv", array_double);
    cache_data("input2.txt", array_char);
    cache_data("input3.csv", array_element);

    // Print the data for each structure type
    printf("Array of double precision floating-point numbers:\n");
    for (size_t i = 0; i < array_double->count; i++) {
        printf("%f\n", array_double->values[i]);
    }
    printf("\n");

    printf("Array of char byte values:\n");
    for (size_t i = 0; i < array_char->count; i++) {
        printf("%c\n", array_char->bytes[i]);
    }
    printf("\n");

    printf("Array of struct element pointers:\n");
    for (size_t i = 0; i < array_element->count; i++) {
        printf("ID: %d, Value: %f\n", array_element->elements[i]->id, array_element->elements[i]->value);
    }
    printf("\n");

    // Free the allocated memory for each structure type
    deallocate_memory(array_double);
    deallocate_memory(array_char);
    deallocate_memory(array_element);

    return 0;
}
