                // Reallocate memory to remove the duplicate entry and log the issue
                NFAPI_CRC_INDICATION_PDU_T *new_pdu = realloc(*pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_pdus - 1));
                if (new_pdu == NULL) {
                    // Log the error and exit the function
                    printf("Error: Failed to reallocate memory for PDUs\n");
                    return;
                }
                *pdu = new_pdu;
                num_pdus--;
            }
        }
    }

    // Manage memory allocation and deallocation efficiently
    int batch_size = DEFAULT_BATCH_SIZE;
    for (int i = 0; i < num_pdus; i += batch_size) {
        if (i + batch_size > num_pdus) {
            batch_size = num_pdus - i;
        }
        // Allocate memory for the current batch of PDUs
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * batch_size);
        if (current_pdu == NULL) {
            // Log the error and exit the function
            printf("Error: Failed to allocate memory for current PDUs\n");
            return;
        }
        memcpy(current_pdu, &(*pdu)[i], sizeof(NFAPI_CRC_INDICATION_PDU_T) * batch_size);

        // Add the current batch of PDUs to the queue
        pthread_mutex_lock(&queue->mutex);
        while (queue->size + batch_size > queue->capacity) {
