            int new_capacity = queue->capacity * BATCH_SIZE_MULTIPLIER;
            NFAPI_CRC_INDICATION_PDU_T **new_data = realloc(queue->data, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * new_capacity);
