                printf("Error: Failed to reallocate memory for queue\n");
                return;
            }
            queue->data = new_data;
            queue->capacity = new_capacity;
        }
        memcpy(&queue->data[queue->size], current_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * batch_size);
        queue->size += batch_size;
        pthread_mutex_unlock(&queue->mutex);
    }

    // Free the memory allocated for the PDUs
    free(*pdu);

    // Monitor the health of the system during execution
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    printf("Resident set size before: %ld\n", usage.ru_maxrss);

    // Process the PDUs in the queue asynchronously using a separate thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, process_pdus, queue) != 0) {
        // Log the error and exit the function
        printf("Error: Failed to create processing thread\n");
        return;
    }

    // Wait for the processing thread to complete
    pthread_join(thread, NULL);

    // Monitor the health of the system during execution
    getrusage(RUSAGE_SELF, &usage);
    printf("Resident set size after: %ld\n", usage.ru_maxrss);

    // Free the memory allocated for the queue
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

void *process_pdus(void *arg) {
    CRC_INDICATION_QUEUE_T *queue = (CRC_INDICATION_QUEUE_T *) arg;
    while (true) {
        // Acquire the lock on the queue
        pthread_mutex_lock(&queue->mutex);

        // Check if there are any PDUs to process
        if (queue->size == 0) {
            // Release the lock and exit the thread
            pthread_mutex_unlock(&queue->mutex);
            break;
        }

        // Process a batch of PDUs from the queue
        int batch_size = queue->size > DEFAULT_BATCH_SIZE ? DEFAULT_BATCH_SIZE : queue->size;
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * batch_size);
        memcpy(current_pdu, &queue->data[0], sizeof(NFAPI_CRC_INDICATION_PDU_T) * batch_size);
        for (int i = 0; i < batch_size; i++) {
            // Process the current PDU
            process_pdu(&current_pdu[i]);
        }

        // Remove the processed PDUs from the queue
        memmove(queue->data, &queue->data[batch_size], sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (queue->size - batch_size));
        queue->size -= batch_size;

        // Release the lock and signal the condition variable to wake up any waiting threads
        pthread_mutex_unlock(&queue->mutex);
        pthread_cond_signal(&queue->cond);
    }
}

void process_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Process the current PDU
    printf("Processing PDU with RNTI %d\n", pdu->rnti);
}
