// Define the mutex for thread safety
pthread_mutex_t crc_indications_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new CRC indication to the array
void add_crc_indication(uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI, uint8_t CRCFLAG) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&crc_indications_mutex);

    // Check if the array is full
    if (crc_indications == NULL || num_crc_indications >= 10000) {
        // If the array is full, reallocate it with a new size
        crc_indications = realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_crc_indications + 1));
    }

    // Add the new CRC indication to the array
    crc_indications[num_crc_indications].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    crc_indications[num_crc_indications].RNTI = RNTI;
    crc_indications[num_crc_indications].CRCFLAG = CRCFLAG;

    // Increment the number of CRC indications
    num_crc_indications++;

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indications_mutex);
}

// Function to remove a CRC indication from the array
void remove_crc_indication(uint32_t RNTI) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&crc_indications_mutex);

    // Find the index of the CRC indication with the specified RNTI
    int index = -1;
    for (int i = 0; i < num_crc_indications; i++) {
        if (crc_indications[i].RNTI == RNTI) {
            index = i;
            break;
        }
    }

    // If the CRC indication was found, remove it from the array
    if (index != -1) {
        // Shift all elements after the removed element to fill the gap
        for (int i = index; i < num_crc_indications - 1; i++) {
            crc_indications[i] = crc_indications[i + 1];
        }

        // Decrement the number of CRC indications
        num_crc_indications--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indications_mutex);
}

// Function to validate the uniqueness of RNTIs in the array
void validate_rntis() {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&crc_indications_mutex);

    // Create a set to store unique RNTIs
    uint32_t *unique_rntis = malloc(sizeof(uint32_t) * num_crc_indications);
    int num_unique_rntis = 0;

    // Iterate over the array and add each RNTI to the set
    for (int i = 0; i < num_crc_indications; i++) {
        uint32_t rnti = crc_indications[i].RNTI;
        if (!contains(unique_rntis, num_unique_rntis, rnti)) {
            unique_rntis[num_unique_rntis++] = rnti;
        }
    }

    // If there are any duplicates, attempt to resolve them by replacing the conflicting entry with a new one generated until uniqueness is achieved
    for (int i = 0; i < num_crc_indications; i++) {
        uint32_t rnti = crc_indications[i].RNTI;
        if (!contains(unique_rntis, num_unique_rntis, rnti)) {
            // Generate a new RNTI and replace the conflicting entry with it
            uint32_t new_rnti = generate_new_rnti();
            crc_indications[i].RNTI = new_rnti;
        }
    }

    // Free the set of unique RNTIs
    free(unique_rntis);

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indications_mutex);
}

// Function to generate a new RNTI
uint32_t generate_new_rnti() {
    // Generate a random number between 0 and 65535
    uint32_t rnti = rand() % 65536;

    // If the generated RNTI is already in use, try again until a unique one is found
    while (contains(crc_indications, num_crc_indications, rnti)) {
        rnti = rand() % 65536;
    }

    return rnti;
}

// Function to check if a given RNTI is in use
bool contains(uint32_t *rntis, int num_rntis, uint32_t rnti) {
    for (int i = 0; i < num_rntis; i++) {
        if (rntis[i] == rnti) {
            return true;
        }
    }
    return false;
}
