NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(int N) {
    // Allocate memory for the list of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the list of available hash functions and block ciphers
    char *hash_functions[] = {"SHA-256", "SHA-384", "SHA-512"};
    char *block_ciphers[] = {"AES-128", "AES-256", "DES"};

    // Loop through each CRC indication PDU and populate it with a random RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    for (int i = 0; i < N; i++) {
        pdu_list[i].rx_ue_information_tag = rand() % 10000;
        pdu_list[i].rnti = rand() % 10000;
        pdu_list[i].crc_indication_rel8.crcFlag = rand() % 2;
    }

    // Loop through each hash function and block cipher and check if it is available on the system
    for (int i = 0; i < sizeof(hash_functions) / sizeof(char *); i++) {
        bool available = false;
        for (int j = 0; j < N; j++) {
            if (strcmp(pdu_list[j].crc_indication_rel8.hashFunction, hash_functions[i]) == 0) {
                available = true;
                break;
            }
        }
        if (!available) {
            continue;
        }
        for (int j = 0; j < sizeof(block_ciphers) / sizeof(char *); j++) {
            bool compatible = false;
            for (int k = 0; k < N; k++) {
                if (strcmp(pdu_list[k].crc_indication_rel8.blockCipher, block_ciphers[j]) == 0) {
                    compatible = true;
                    break;
                }
            }
            if (!compatible) {
                continue;
            }
            // Select the hash function and block cipher for each CRC indication PDU
            for (int k = 0; k < N; k++) {
                pdu_list[k].crc_indication_rel8.hashFunction = hash_functions[i];
                pdu_list[k].crc_indication_rel8.blockCipher = block_ciphers[j];
            }
        }
    }

    return pdu_list;
}
