typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum limit for the number of elements in the array
#define MAX_N 10000

// Function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_array(int n) {
    // Validate the input n to ensure it does not exceed the maximum limit
    if (n > MAX_N) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);

    // Initialize each structure in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    for (int i = 0; i < n; i++) {
        arr[i].RX_UE_INFORMATION_TAG = 1;
        arr[i].RNTI = rand() % 1000000;
        arr[i].CRCFLAG = rand() % 2;
    }

    // Sort the array based on the RNTI values in ascending order
    qsort(arr, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    return arr;
}

// Function to deallocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void deallocate_array(NFAPI_CRC_INDICATION_PDU_T* arr) {
    free(arr);
}

// Comparison function for sorting the array based on RNTI values in ascending order
int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pa = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pb = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return pa->RNTI - pb->RNTI;
}
