    double value;
} LTE_PHY_MEASUREMENT;

// Function to initialize and populate an array of LTE_PHY_MEASUREMENT structures
LTE_PHY_MEASUREMENT* init_measurements(int num_tags, int num_meas) {
    // Allocate memory for the array of measurements
    LTE_PHY_MEASUREMENT* measurements = (LTE_PHY_MEASUREMENT*)malloc(num_tags * sizeof(LTE_PHY_MEASUREMENT));
    if (!measurements) {
        fprintf(stderr, "Error: Failed to allocate memory for measurements\n");
        return NULL;
    }

    // Initialize each measurement tag and value
    for (int i = 0; i < num_tags; i++) {
        measurements[i].tag = (LTE_PHY_MEASUREMENT_TAG)i;
        switch (measurements[i].tag) {
            case RX_POWER:
                // Simulate RX power measurement using a Gaussian distribution
                measurements[i].value = gaussian(0, 1);
                break;
            case SINR:
                // Simulate SINR measurement using a Gaussian distribution
                measurements[i].value = gaussian(5, 2);
                break;
            case RSSI:
                // Simulate RSSI measurement using a Gaussian distribution
                measurements[i].value = gaussian(-100, 5);
                break;
        }
    }

    // Handle potential overflow conditions and memory allocation issues
    if (num_meas > num_tags) {
        fprintf(stderr, "Warning: Number of measurements exceeds number of tags\n");
        num_meas = num_tags;
    }
    for (int i = 0; i < num_meas; i++) {
        if (!measurements[i].value) {
            fprintf(stderr, "Warning: Measurement value is zero\n");
            measurements[i].value = gaussian(0, 1);
        }
    }

    // Conditionally output detailed information about each measurement tag
    if (logging_level > 0) {
        for (int i = 0; i < num_tags; i++) {
            printf("Measurement tag %d: %s\n", i, get_measurement_tag_name(measurements[i].tag));
            printf("Value: %.2f\n", measurements[i].value);
        }
    }

    return measurements;
}

// Function to simulate a Gaussian distribution with mean and standard deviation
double gaussian(double mean, double stddev) {
    // Box-Muller transform for generating normally distributed random numbers
    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;
    double rand_std_normal = sqrt(-2 * log(u1)) * cos(2 * M_PI * u2);
    return mean + stddev * rand_std_normal;
}

// Function to get the name of a measurement tag
const char* get_measurement_tag_name(LTE_PHY_MEASUREMENT_TAG tag) {
    switch (tag) {
        case RX_POWER:
            return "RX Power";
        case SINR:
            return "SINR";
        case RSSI:
            return "RSSI";
        default:
            return "Unknown Measurement Tag";
    }
}
