// Define a structure to store RRC connection information
typedef struct {
    NR_RRC_CGI cgi;
    NR_RRC_CRS_INFO crs_info;
    NR_RRC_SRB1_MESSAGE *srb1_message;
    NR_RRC_DRB_MESSAGE *drb_message;
} NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE;

// Define a pool of RRC connection structures
NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE *rrc_connections = NULL;
size_t rrc_connection_count = 0;
pthread_mutex_t rrc_connection_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the RRC connection pool
void initializeRrcConnections(size_t count) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rrc_connection_lock);

    // If the pool is already initialized, do nothing
    if (rrc_connections != NULL) {
        pthread_mutex_unlock(&rrc_connection_lock);
        return;
    }

    // Allocate memory for the pool
    rrc_connections = malloc(count * sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE));
    if (rrc_connections == NULL) {
        pthread_mutex_unlock(&rrc_connection_lock);
        return;
    }

    // Initialize the pool with empty structures
    for (size_t i = 0; i < count; i++) {
        rrc_connections[i].cgi = NULL;
        rrc_connections[i].crs_info = NULL;
        rrc_connections[i].srb1_message = NULL;
        rrc_connections[i].drb_message = NULL;
    }

    // Set the size of the pool
    rrc_connection_count = count;

    // Unlock the mutex
    pthread_mutex_unlock(&rrc_connection_lock);
}

// Function to add a new RRC connection to the pool
void addRrcConnection(NR_RRC_CGI *cgi, NR_RRC_CRS_INFO *crs_info) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rrc_connection_lock);

    // If the pool is not initialized, do nothing
    if (rrc_connections == NULL) {
        pthread_mutex_unlock(&rrc_connection_lock);
        return;
    }

    // Find an empty slot in the pool
    size_t i = 0;
    while (i < rrc_connection_count && rrc_connections[i].cgi != NULL) {
        i++;
    }

    // If no empty slots are found, resize the pool
    if (i == rrc_connection_count) {
        size_t new_size = rrc_connection_count * 2;
        NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE *new_connections = realloc(rrc_connections, new_size * sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE));
        if (new_connections == NULL) {
            pthread_mutex_unlock(&rrc_connection_lock);
            return;
        }
        rrc_connections = new_connections;
        for (size_t j = rrc_connection_count; j < new_size; j++) {
            rrc_connections[j].cgi = NULL;
            rrc_connections[j].crs_info = NULL;
            rrc_connections[j].srb1_message = NULL;
            rrc_connections[j].drb_message = NULL;
        }
        rrc_connection_count = new_size;
    }

    // Add the new connection to the pool
    rrc_connections[i].cgi = cgi;
    rrc_connections[i].crs_info = crs_info;

    // Unlock the mutex
    pthread_mutex_unlock(&rrc_connection_lock);
}

// Function to remove an RRC connection from the pool
void removeRrcConnection(NR_RRC_CGI *cgi) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rrc_connection_lock);

    // If the pool is not initialized, do nothing
    if (rrc_connections == NULL) {
        pthread_mutex_unlock(&rrc_connection_lock);
        return;
    }

    // Find the connection in the pool
    size_t i = 0;
    while (i < rrc_connection_count && rrc_connections[i].cgi != cgi) {
        i++;
    }

    // If the connection is not found, do nothing
    if (i == rrc_connection_count) {
        pthread_mutex_unlock(&rrc_connection_lock);
        return;
    }

    // Remove the connection from the pool
    rrc_connections[i].cgi = NULL;
    rrc_connections[i].crs_info = NULL;
    rrc_connections[i].srb1_message = NULL;
    rrc_connections[i].drb_message = NULL;

    // If the pool is now empty, free the memory
    if (rrc_connection_count == 0) {
        free(rrc_connections);
        rrc_connections = NULL;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&rrc_connection_lock);
}
