#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

// Custom struct to store extracted information
struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    char* sample_format;
    char* photometric_interpretation;
    char* compression_method;
};

// Function to parse TIFF file and extract information
struct tiff_info parse_tiff(const char* filename) {
    struct tiff_info info = {0};

    // Open TIFF file using libtiff library
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        return info;
    }

    // Get image width and height
    uint32_t width = 0;
    uint32_t height = 0;
    if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width) &&
        TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height)) {
        info.width = width;
        info.height = height;
    } else {
        fprintf(stderr, "Error getting image dimensions\n");
        return info;
    }

    // Get bits per sample and samples per pixel
    uint16_t bps = 0;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bps)) {
        info.bits_per_sample = bps;
    } else {
        fprintf(stderr, "Error getting bits per sample\n");
        return info;
    }
    uint16_t spp = 0;
    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &spp)) {
        info.samples_per_pixel = spp;
    } else {
        fprintf(stderr, "Error getting samples per pixel\n");
        return info;
    }

    // Get extra samples
    uint16_t es = 0;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &es)) {
        info.extra_samples = es;
    } else {
        fprintf(stderr, "Error getting extra samples\n");
        return info;
    }

    // Get sample format and photometric interpretation
    uint16_t sf = 0;
    if (TIFFGetField(tif, TIFFTAG_SAMPLEFORMAT, &sf)) {
        info.sample_format = get_sample_format(sf);
    } else {
        fprintf(stderr, "Error getting sample format\n");
        return info;
    }
    uint16_t pi = 0;
    if (TIFFGetField(tif, TIFFTAG_PHOTOMETRICINTERPRETATION, &pi)) {
        info.photometric_interpretation = get_photometric_interpretation(pi);
    } else {
        fprintf(stderr, "Error getting photometric interpretation\n");
        return info;
    }

    // Get compression method
    uint16_t cm = 0;
    if (TIFFGetField(tif, TIFFTAG_COMPRESSION, &cm)) {
        info.compression_method = get_compression_method(cm);
    } else {
        fprintf(stderr, "Error getting compression method\n");
        return info;
    }

    // Close TIFF file
    TIFFClose(tif);

    return info;
}

// Function to get sample format string from libtiff library
char* get_sample_format(uint16_t sf) {
    switch (sf) {
        case SAMPLEFORMAT_UINT:
            return "unsigned integer";
        case SAMPLEFORMAT_INT:
            return "signed integer";
        case SAMPLEFORMAT_IEEEFP:
            return "IEEE floating point";
        default:
            return "unknown sample format";
    }
}

// Function to get photometric interpretation string from libtiff library
char* get_photometric_interpretation(uint16_t pi) {
    switch (pi) {
        case PHOTOMETRIC_MINISWHITE:
            return "min-is-white";
        case PHOTOMETRIC_MINISBLACK:
            return "min-is-black";
        case PHOTOMETRIC_RGB:
            return "RGB";
        case PHOTOMETRIC_PALETTE:
            return "palette";
        case PHOTOMETRIC_MASK:
            return "mask";
        case PHOTOMETRIC_SEPARATED:
            return "separated";
        case PHOTOMETRIC_YCBCR:
            return "YCbCr";
        case PHOTOMETRIC_CIELAB:
            return "CIE L*a*b*";
        default:
            return "unknown photometric interpretation";
    }
}

// Function to get compression method string from libtiff library
char* get_compression_method(uint16_t cm) {
    switch (cm) {
        case COMPRESSION_NONE:
            return "none";
        case COMPRESSION_CCITTRLE:
            return "CCITT RLE";
        case COMPRESSION_CCITTFAX3:
            return "CCITT Group 3 fax";
        case COMPRESSION_CCITTFAX4:
            return "CCITT Group 4 fax";
        case COMPRESSION_LZW:
            return "LZW";
        case COMPRESSION_JPEG:
            return "JPEG (old-style)";
        case COMPRESSION_JPEG2000:
            return "JPEG 2000";
        case COMPRESSION_ZSTD:
            return "ZSTD";
        case COMPRESSION_LZMA:
            return "LZMA";
        case COMPRESSION_WEBP:
            return "WebP";
        case COMPRESSION_JPEGLS:
            return "JPEG-LS";
        case COMPRESSION_PAM:
            return "PAM (portable anymap) format";
        case COMPRESSION_DEFLATE:
            return "deflate";
        case COMPRESSION_PKZIP:
            return "PKZIP";
        default:
            return "unknown compression method";
    }
}
```
