// Define the structure for an NFAPI_RX_FRAME
typedef struct {
    NFAPI_RX_FRAME_HEADER header;
    NFAPI_RX_FRAME_PAYLOAD_T payload;
} NFAPI_RX_FRAME;

// Define the linked list node for storing NFAPI_RX_FRAME structures
typedef struct {
    NFAPI_RX_FRAME *data;
    struct Node *next;
} Node;

// Define the linked list for storing NFAPI_RX_FRAME structures
typedef struct {
    Node *head;
    Node *tail;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

// Initialize and populate a linked list of NFAPI_RX_FRAME structures
void initAndPopulateLinkedList(LinkedList *list, void *buffer, size_t bufferSize) {
    // Check if the buffer is NULL or empty
    if (buffer == NULL || bufferSize == 0) {
        return;
    }

    // Initialize the linked list and mutex
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    // Iterate over the buffer and populate the linked list
    size_t offset = 0;
    while (offset < bufferSize) {
        // Allocate memory for the NFAPI_RX_FRAME structure
        NFAPI_RX_FRAME *frame = malloc(sizeof(NFAPI_RX_FRAME));
        if (frame == NULL) {
            printf("Error: Failed to allocate memory for NFAPI_RX_FRAME\n");
            return;
        }

        // Populate the NFAPI_RX_FRAME structure with the data from the buffer
        size_t frameSize = sizeof(NFAPI_RX_FRAME);
        if (offset + frameSize > bufferSize) {
            frameSize = bufferSize - offset;
        }
        memcpy(&frame->header, buffer + offset, frameSize);
        offset += frameSize;

        // Verify the integrity of the payload data by calculating a checksum and comparing it against an expected value
        uint32_t checksum = calculateChecksum(frame->payload.data, frame->payload.size);
        if (checksum != frame->header.checksum) {
            printf("Error: Checksum mismatch for NFAPI_RX_FRAME\n");
            free(frame);
            continue;
        }

        // Add the NFAPI_RX_FRAME structure to the linked list
        pthread_mutex_lock(&list->mutex);
        Node *node = malloc(sizeof(Node));
        if (node == NULL) {
            printf("Error: Failed to allocate memory for linked list node\n");
            free(frame);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        node->data = frame;
        node->next = NULL;
        if (list->head == NULL) {
            list->head = node;
        } else {
            list->tail->next = node;
        }
        list->tail = node;
        list->size++;
        pthread_mutex_unlock(&list->mutex);
    }
}

// Calculate the checksum of a buffer
uint32_t calculateChecksum(void *buffer, size_t bufferSize) {
    // Check if the buffer is NULL or empty
    if (buffer == NULL || bufferSize == 0) {
        return 0;
    }

    // Initialize the checksum to zero
    uint32_t checksum = 0;

    // Iterate over the buffer and calculate the checksum
    size_t offset = 0;
    while (offset < bufferSize) {
        checksum += *((uint8_t *)buffer + offset);
        offset++;
    }

    return checksum;
}
