    // Allocate memory for the linked list structure
    list->head = (NFAPI_RX_FRAME *)malloc(sizeof(NFAPI_RX_FRAME) * initial_size);
    if (!list->head) {
        printf("Error: Failed to allocate memory for NFAPI_RX_FRAME list\n");
        return;
    }
    list->tail = list->head + (initial_size - 1);
    list->count = initial_size;
}

