void populate_nfapi_rx_frame_list(NFAPI_RX_FRAME_LIST *list, void *buffer, size_t buffer_size) {
    // Calculate the number of frames that can be populated from the buffer
    size_t num_frames = buffer_size / sizeof(NFAPI_RX_FRAME);

    // Iterate over each frame in the buffer and populate the linked list
    for (size_t i = 0; i < num_frames; i++) {
        NFAPI_RX_FRAME *frame = &list->head[i];
        memcpy(&frame->header, buffer + (i * sizeof(NFAPI_RX_FRAME)), sizeof(NFAPI_RX_FRAME));
        frame->payload.data = buffer + (i * sizeof(NFAPI_RX_FRAME)) + sizeof(NFAPI_RX_FRAME_HEADER);
