    if (list->head == NULL) {
        list->head = frame;
        list->tail = frame;
    } else {
        list->tail->next = frame;
        frame->prev = list->tail;
        list->tail = frame;
    }

    // Release the lock for accessing the linked list
    pthread_mutex_unlock(&list_lock);
}

// Remove a NFAPI_RX_FRAME structure from the linked list
void remove_rx_frame(NFAPI_RX_FRAME_LIST *list, NFAPI_RX_FRAME *frame) {
    // Acquire the lock for accessing the linked list
    pthread_mutex_lock(&list_lock);

    // Remove the frame from the linked list
    if (frame == list->head) {
        list->head = frame->next;
    }
    if (frame == list->tail) {
        list->tail = frame->prev;
    }
    if (frame->prev != NULL) {
        frame->prev->next = frame->next;
    }
    if (frame->next != NULL) {
        frame->next->prev = frame->prev;
    }

    // Release the lock for accessing the linked list
    pthread_mutex_unlock(&list_lock);
}

