// Custom hash table implementation for storing and validating unique tags
#include "hash_table.h"

// Logging module to record statistics on duplicate tags encountered during the population process
#include "logging.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    bool valid;
} PDU_ENTRY_T;

// Global hash table for storing unique tags
static HASH_TABLE_T *tag_table = NULL;

// Lock for protecting access to the hash table and the PDU array
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Array of PDU entries, each containing a valid RX_UE_INFORMATION_TAG and RNTI, along with a CRC_INDICATION_REL8_TAG that reflects the integrity of the received packet
static PDU_ENTRY_T *pdu_array = NULL;

// Size of the PDU array
static size_t pdu_array_size = 0;

// Number of valid PDUs in the array
static size_t num_valid_pdus = 0;

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG and RNTI, along with a CRC_INDICATION_REL8_TAG that reflects the integrity of the received packet
void populate_pdu_array(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t num_pdus) {
    // Acquire lock to protect access to the hash table and the PDU array
    pthread_mutex_lock(&lock);

    // Iterate over each PDU in the input array
    for (size_t i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[i];

        // Check if the RX_UE_INFORMATION_TAG and RNTI are already present in the hash table
        bool is_duplicate = false;
        HASH_TABLE_ENTRY_T *entry = NULL;
        HASH_TABLE_LOOKUP(tag_table, pdu->rx_ue_information.rnti, entry);
        if (entry != NULL) {
            // If the RX_UE_INFORMATION_TAG and RNTI are already present in the hash table, mark the PDU as invalid
            is_duplicate = true;
            pdu->valid = false;
        } else {
            // If the RX_UE_INFORMATION_TAG and RNTI are not present in the hash table, add them to the hash table and mark the PDU as valid
            HASH_TABLE_ENTRY_T *entry = NULL;
            HASH_TABLE_INSERT(tag_table, pdu->rx_ue_information.rnti, entry);
            if (entry != NULL) {
                is_duplicate = false;
                pdu->valid = true;
            } else {
                // If the hash table insertion failed, mark the PDU as invalid and log an error
                is_duplicate = true;
                pdu->valid = false;
                LOG_ERROR("Failed to add RX_UE_INFORMATION_TAG and RNTI to hash table");
            }
        }

        // If the PDU is not a duplicate, add it to the PDU array
        if (!is_duplicate) {
            // Check if the PDU array needs to be reallocated to accommodate the new PDU
            if (num_valid_pdus >= pdu_array_size) {
                // Reallocate the PDU array with a larger size, doubling the current size
                size_t new_size = pdu_array_size * 2;
                PDU_ENTRY_T *new_pdu_array = realloc(pdu_array, new_size * sizeof(PDU_ENTRY_T));
                if (new_pdu_array == NULL) {
                    // If the reallocation failed, log an error and continue with the current PDU array size
                    LOG_ERROR("Failed to reallocate PDU array");
                } else {
                    pdu_array = new_pdu_array;
                    pdu_array_size = new_size;
                }
            }

            // Add the valid PDU to the PDU array
            pdu_array[num_valid_pdus].pdu = *pdu;
            pdu_array[num_valid_pdus].valid = true;
            num_valid_pdus++;
        }
    }

    // Release lock to allow other threads to access the hash table and the PDU array
    pthread_mutex_unlock(&lock);
}
