#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/time.h>
#include <hash_table.h> // external hash table library

// Define a struct to represent a PDCP PDU
struct pdcp_pdu {
    uint32_t sn;
    uint8_t sps;
};

// Define a struct to store the statistics of the population process
struct population_stats {
    uint64_t num_duplicate_pdus;
    uint64_t num_duplicate_sps;
};

// Define a function to populate the dynamic list of PDCP PDUs
void populate_pdcp_pdu_list(struct pdcp_pdu *pdcp_pdu_list, size_t num_pdus) {
    // Initialize the hash table for storing unique PDUs and SPS values
    struct hash_table *ht = hash_table_create();

    // Iterate over each PDCP PDU in the list
    for (size_t i = 0; i < num_pdus; i++) {
        struct pdcp_pdu *curr_pdu = &pdcp_pdu_list[i];

        // Check if the current PDU is already present in the hash table
        if (hash_table_contains(ht, curr_pdu->sn)) {
            // If it is, increment the number of duplicate PDUS and continue to the next PDU
            population_stats.num_duplicate_pdus++;
            continue;
        }

        // Check if the current SPS value is already present in the hash table
        if (hash_table_contains(ht, curr_pdu->sps)) {
            // If it is, increment the number of duplicate SPS values and continue to the next PDU
            population_stats.num_duplicate_sps++;
            continue;
        }

        // Add the current PDU to the hash table
        hash_table_insert(ht, curr_pdu->sn);
        hash_table_insert(ht, curr_pdu->sps);
    }

    // Destroy the hash table
    hash_table_destroy(ht);
}

// Define a function to handle concurrent access and modification of the data structure
void populate_pdcp_pdu_list_threadsafe(struct pdcp_pdu *pdcp_pdu_list, size_t num_pdus) {
    // Initialize a mutex for protecting the hash table
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Iterate over each PDCP PDU in the list
    for (size_t i = 0; i < num_pdus; i++) {
        struct pdcp_pdu *curr_pdu = &pdcp_pdu_list[i];

        // Lock the mutex before accessing the hash table
        pthread_mutex_lock(&mutex);

        // Check if the current PDU is already present in the hash table
        if (hash_table_contains(ht, curr_pdu->sn)) {
            // If it is, increment the number of duplicate PDUS and continue to the next PDU
            population_stats.num_duplicate_pdus++;
            pthread_mutex_unlock(&mutex);
            continue;
        }

        // Check if the current SPS value is already present in the hash table
        if (hash_table_contains(ht, curr_pdu->sps)) {
            // If it is, increment the number of duplicate SPS values and continue to the next PDU
            population_stats.num_duplicate_sps++;
            pthread_mutex_unlock(&mutex);
            continue;
        }

        // Add the current PDU to the hash table
        hash_table_insert(ht, curr_pdu->sn);
        hash_table_insert(ht, curr_pdu->sps);

        // Unlock the mutex after accessing the hash table
        pthread_mutex_unlock(&mutex);
    }
}
```
