// Structure to represent a node in the linked list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to dynamically create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndPopulateLinkedList(int N, int maxLimit) {
    // Initialize the head node as NULL
    Node* head = NULL;

    // Iterate over the given number of structures
    for (int i = 0; i < N; i++) {
        // Allocate memory for a new node
        Node* newNode = malloc(sizeof(Node));

        // Initialize the data field in the new node with a valid RX_UE_INFORMATION_TAG and RNTI
        newNode->data.rx_ue_information_tag = 0x1234;
        newNode->data.rnti = i + 1;

        // Initialize the CRC_INDICATION_REL8_TAG within the new node with a random CRCFLAG value
        newNode->data.crc_indication_rel8_tag.crcFlag = rand() % 2;

        // Add the new node to the linked list
        if (head == NULL) {
            head = newNode;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        }
    }

    // Serialize the linked list to a binary file for later retrieval
    FILE* fp = fopen("linked_list.bin", "wb");
    if (fp == NULL) {
        LOG_ERROR("Failed to open file for writing: %s\n", strerror(errno));
        return;
    }
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
        current = current->next;
    }
    fclose(fp);
}

// Function to handle concurrent access from multiple threads without causing race conditions or data corruption
void* createAndPopulateLinkedListThread(void* arg) {
    int N = *((int*)arg);
    createAndPopulateLinkedList(N, 1000);
    return NULL;
}

// Function to detect and handle duplicate RNTI entries efficiently to avoid data redundancy
bool isDuplicateRnti(Node* head, int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return true;
        }
        current = current->next;
    }
    return false;
}

// Function to handle edge cases where N is zero or negative, providing graceful error handling and logging to track the number of structures added, any errors encountered, and performance metrics like execution time and memory usage
void createAndPopulateLinkedList(int N) {
    if (N <= 0) {
        LOG_ERROR("Invalid input: N must be a positive integer\n");
        return;
    }
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    createAndPopulateLinkedList(N, 1000);
    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed = (double)(end.tv_sec - start.tv_sec) + (double)(end.tv_nsec - start.tv_nsec) / 1000000000;
    LOG_INFO("Execution time: %f seconds\n", elapsed);
}
