#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "custom_queue.h" // custom lock-free queue implementation
#include "statistical_analysis.h" // statistical analysis module for resource utilization monitoring

// NIC configuration structure
typedef struct {
    int id;
    char* ip_address;
    char* mac_address;
} NIC_CONFIG_T;

// NIC settings pool data structure
typedef struct {
    NIC_CONFIG_T** nic_configs; // array of pointers to NIC configurations
    size_t capacity; // current capacity of the pool
    size_t count; // number of NIC configurations in the pool
    pthread_mutex_t lock; // mutex for thread-safe access to the pool
} NIC_POOL_T;

// Initialize a new NIC settings pool with an initial capacity of 1000.
NIC_POOL_T* nic_pool_init(size_t initial_capacity) {
    NIC_POOL_T* pool = malloc(sizeof(NIC_POOL_T));
    if (!pool) {
        return NULL;
    }
    pool->nic_configs = calloc(initial_capacity, sizeof(NIC_CONFIG_T*));
    if (!pool->nic_configs) {
        free(pool);
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Add a new NIC configuration to the pool.
int nic_pool_add(NIC_POOL_T* pool, int id, char* ip_address, char* mac_address) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        // reallocate the array of pointers to NIC configurations
        size_t new_capacity = pool->capacity * 2;
        NIC_CONFIG_T** new_nic_configs = realloc(pool->nic_configs, new_capacity * sizeof(NIC_CONFIG_T*));
        if (!new_nic_configs) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        pool->nic_configs = new_nic_configs;
        pool->capacity = new_capacity;
    }
    // create a new NIC configuration structure and add it to the pool
    NIC_CONFIG_T* nic_config = malloc(sizeof(NIC_CONFIG_T));
    if (!nic_config) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }
    nic_config->id = id;
    nic_config->ip_address = ip_address;
    nic_config->mac_address = mac_address;
    pool->nic_configs[pool->count++] = nic_config;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Modify an existing NIC configuration in the pool.
int nic_pool_modify(NIC_POOL_T* pool, int id, char* ip_address, char* mac_address) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->nic_configs[i]->id == id) {
            // modify the NIC configuration structure in place
            free(pool->nic_configs[i]->ip_address);
            pool->nic_configs[i]->ip_address = ip_address;
            free(pool->nic_configs[i]->mac_address);
            pool->nic_configs[i]->mac_address = mac_address;
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return -1; // NIC configuration not found in the pool
}

// Delete an existing NIC configuration from the pool.
int nic_pool_delete(NIC_POOL_T* pool, int id) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->nic_configs[i]->id == id) {
            // delete the NIC configuration structure from the pool
            free(pool->nic_configs[i]);
            pool->nic_configs[i] = NULL;
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return -1; // NIC configuration not found in the pool
}

// Destroy a NIC settings pool.
void nic_pool_destroy(NIC_POOL_T* pool) {
    if (pool) {
        pthread_mutex_lock(&pool->lock);
        for (size_t i = 0; i < pool->count; i++) {
            free(pool->nic_configs[i]);
        }
        free(pool->nic_configs);
        pthread_mutex_unlock(&pool->lock);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}
