// Structure for NetworkResourceRequest
typedef struct {
    int resource_id;
    int request_priority;
    char metadata[500];
} NetworkResourceRequest;

// List of NetworkResourceRequests
struct NetworkResourceRequestList {
    NetworkResourceRequest* requests;
    size_t count;
    pthread_mutex_t mutex;
};

// Initialize a new list of NetworkResourceRequests
void init_network_resource_request_list(NetworkResourceRequestList* list) {
    list->requests = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new NetworkResourceRequest to the list
void add_network_resource_request(NetworkResourceRequestList* list, int resource_id, int request_priority, char* metadata) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);

    // Allocate memory for the new NetworkResourceRequest
    NetworkResourceRequest* new_request = malloc(sizeof(NetworkResourceRequest));
    if (new_request == NULL) {
        // Handle allocation failure gracefully
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Initialize the new NetworkResourceRequest
    new_request->resource_id = resource_id;
    new_request->request_priority = request_priority;
    strncpy(new_request->metadata, metadata, 500);

    // Add the new NetworkResourceRequest to the list
    list->requests = realloc(list->requests, (list->count + 1) * sizeof(NetworkResourceRequest));
    if (list->requests == NULL) {
        // Handle allocation failure gracefully
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->requests[list->count++] = new_request;

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&list->mutex);
}

// Remove a NetworkResourceRequest from the list by its index
void remove_network_resource_request(NetworkResourceRequestList* list, size_t index) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index >= list->count) {
        // Handle invalid index gracefully
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Remove the NetworkResourceRequest from the list
    NetworkResourceRequest* request = &list->requests[index];
    memmove(request, request + 1, (list->count - index - 1) * sizeof(NetworkResourceRequest));
    list->count--;

    // Free the memory allocated for the removed NetworkResourceRequest
    free(request);

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&list->mutex);
}

// Get a NetworkResourceRequest from the list by its index
NetworkResourceRequest* get_network_resource_request(NetworkResourceRequestList* list, size_t index) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index >= list->count) {
        // Handle invalid index gracefully
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Get the NetworkResourceRequest from the list
    NetworkResourceRequest* request = &list->requests[index];

    // Unlock the mutex after accessing the list
    pthread_mutex_unlock(&list->mutex);

    return request;
}
