// Define the maximum number of connections in the pool
#define MAX_CONNECTIONS 1024

// Define the minimum and maximum session IDs
#define MIN_SESSION_ID 1
#define MAX_SESSION_ID 65535

// Define the connection status flags
#define CONN_STATUS_OPEN 1
#define CONN_STATUS_CLOSED 0

// Define the connection object structure
struct conn {
    int socket; // TCP/IP socket
    int session_id; // unique session ID
    int status; // connection status flag
};

// Define the connection pool array
struct conn connections[MAX_CONNECTIONS];

// Initialize the connection pool
void init_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i].socket = -1;
        connections[i].session_id = -1;
        connections[i].status = CONN_STATUS_CLOSED;
    }
}

// Allocate a new connection object from the pool
struct conn* alloc_connection() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].socket == -1) {
            connections[i].status = CONN_STATUS_OPEN;
            return &connections[i];
        }
    }
    return NULL;
}

// Deallocate a connection object from the pool
void dealloc_connection(struct conn* conn) {
    if (conn->socket != -1) {
        close(conn->socket);
        conn->socket = -1;
        conn->session_id = -1;
        conn->status = CONN_STATUS_CLOSED;
    }
}

// Validate a session ID and allocate a new connection object if necessary
struct conn* validate_session(int session_id) {
    if (session_id < MIN_SESSION_ID || session_id > MAX_SESSION_ID) {
        return NULL;
    }
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].socket != -1 && connections[i].session_id == session_id) {
            return &connections[i];
        }
    }
    struct conn* new_conn = alloc_connection();
    if (new_conn != NULL) {
        new_conn->session_id = session_id;
        new_conn->status = CONN_STATUS_OPEN;
    }
    return new_conn;
}

// Close a connection object and deallocate it from the pool
void close_connection(struct conn* conn) {
    if (conn->socket != -1) {
        close(conn->socket);
        conn->socket = -1;
        conn->session_id = -1;
        conn->status = CONN_STATUS_CLOSED;
        dealloc_connection(conn);
    }
}

