// Define the function to initialize the RRC connection pool
void initializeRrcConnections(NR_RRC_CONNECTION_POOL *pool) {
    // Initialize the pool size and count
    pool->size = 100;
    pool->count = 0;

    // Allocate memory for the connections array
    pool->connections = (NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE **)malloc(pool->size * sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE *));

    // Initialize each connection in the pool
    for (int i = 0; i < pool->size; i++) {
        pool->connections[i] = (NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE *)malloc(sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE));
        memset(pool->connections[i], 0, sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE));
    }
}

// Define the function to add a new RRC connection to the pool
void addNewConnection(NR_RRC_CONNECTION_POOL *pool) {
