    if (pool->count == pool->size) {
        // Reallocate the connections array with a larger size
        int new_size = pool->size * 2;
        NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE **new_connections = (NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE **)realloc(pool->connections, new_size * sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE *));
        if (new_connections == NULL) {
            // Handle the error of reallocation failure
            return;
        }
        pool->connections = new_connections;
        pool->size = new_size;
    }

    // Add a new connection to the pool
    int index = pool->count++;
    pool->connections[index] = (NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE *)malloc(sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE));
    memset(pool->connections[index], 0, sizeof(NR_RRC_CONNECTION_RECONFIGURATION_MESSAGE));
}

// Define the function to remove an RRC connection from the pool
void removeConnection(NR_RRC_CONNECTION_POOL *pool, int index) {
