    // Remove the connection from the pool
    free(pool->connections[index]);
    pool->connections[index] = NULL;

    // Shift the connections in the pool to fill the gap
    for (int i = index; i < pool->count - 1; i++) {
        pool->connections[i] = pool->connections[i + 1];
    }
    pool->count--;
}

// Define the function to handle concurrent access to the RRC connection pool
void handleConcurrentAccess(NR_RRC_CONNECTION_POOL *pool) {
