#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the struct to hold the MAC entity configuration parameters
typedef struct {
    int uplink_scheduling;
    int downlink_scheduling;
    char* data_transmission_type;
} mac_entity_config_t;

// Define a dynamic array to store the MAC entity configurations
typedef struct {
    mac_entity_config_t** configs;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} mac_entity_config_array_t;

// Initialize a new dynamic array with the given capacity
mac_entity_config_array_t* init_mac_entity_config_array(size_t capacity) {
    mac_entity_config_array_t* arr = malloc(sizeof(mac_entity_config_array_t));
    if (!arr) {
        return NULL;
    }
    arr->configs = calloc(capacity, sizeof(mac_entity_config_t*));
    if (!arr->configs) {
        free(arr);
        return NULL;
    }
    arr->capacity = capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Add a new MAC entity configuration to the dynamic array
int add_mac_entity_config(mac_entity_config_array_t* arr, mac_entity_config_t* config) {
    if (!arr || !config) {
        return -1;
    }
    pthread_mutex_lock(&arr->lock);
    if (arr->count == arr->capacity) {
        // Reallocate the array with a new capacity
        size_t new_capacity = arr->capacity * 2;
        mac_entity_config_t** new_configs = realloc(arr->configs, sizeof(mac_entity_config_t*) * new_capacity);
        if (!new_configs) {
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }
        arr->configs = new_configs;
        arr->capacity = new_capacity;
    }
    // Copy the configuration to the array
    memcpy(arr->configs[arr->count], config, sizeof(mac_entity_config_t));
    arr->count++;
    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Remove a MAC entity configuration from the dynamic array
int remove_mac_entity_config(mac_entity_config_array_t* arr, size_t index) {
    if (!arr || index >= arr->count) {
        return -1;
    }
    pthread_mutex_lock(&arr->lock);
    // Shift the remaining configurations to fill the gap
    for (size_t i = index + 1; i < arr->count; i++) {
        memcpy(arr->configs[i - 1], arr->configs[i], sizeof(mac_entity_config_t));
    }
    // Decrement the count and free the removed configuration
    arr->count--;
    free(arr->configs[arr->count]);
    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Get a MAC entity configuration from the dynamic array by index
mac_entity_config_t* get_mac_entity_config(mac_entity_config_array_t* arr, size_t index) {
    if (!arr || index >= arr->count) {
        return NULL;
    }
    return arr->configs[index];
}

// Free the dynamic array and its contents
void free_mac_entity_config_array(mac_entity_config_array_t* arr) {
    if (!arr) {
        return;
    }
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->count; i++) {
        free(arr->configs[i]);
    }
    free(arr->configs);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}
