// Structure to represent a single packet
typedef struct {
    int rx_ue;
    int rnti;
    bool crc_indication;
} packet_t;

// Linked list node for storing packets
typedef struct node {
    packet_t *packet;
    struct node *next;
} node_t;

// Function to add a new packet to the linked list
void add_packet(node_t **head, int rx_ue, int rnti, bool crc_indication) {
    // Create a new node for the packet
    node_t *new_node = malloc(sizeof(node_t));
    new_node->packet = malloc(sizeof(packet_t));
    new_node->packet->rx_ue = rx_ue;
    new_node->packet->rnti = rnti;
    new_node->packet->crc_indication = crc_indication;
    new_node->next = NULL;

    // Add the new node to the linked list
    if (*head == NULL) {
        *head = new_node;
    } else {
        node_t *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to update a packet in the linked list
void update_packet(node_t **head, int rx_ue, int rnti, bool crc_indication) {
    // Find the node containing the packet to be updated
    node_t *current = *head;
    while (current != NULL && current->packet->rx_ue != rx_ue || current->packet->rnti != rnti) {
        current = current->next;
    }

    // Update the packet fields if found
    if (current != NULL) {
        current->packet->crc_indication = crc_indication;
    }
}

// Function to retrieve a packet from the linked list
packet_t *get_packet(node_t **head, int rx_ue, int rnti) {
    // Find the node containing the requested packet
    node_t *current = *head;
    while (current != NULL && current->packet->rx_ue != rx_ue || current->packet->rnti != rnti) {
        current = current->next;
    }

    // Return the packet if found, otherwise return NULL
    if (current != NULL) {
        return current->packet;
    } else {
        return NULL;
    }
}

// Function to delete a packet from the linked list
void delete_packet(node_t **head, int rx_ue, int rnti) {
    // Find the node containing the requested packet
    node_t *current = *head;
    while (current != NULL && current->next != NULL && current->next->packet->rx_ue != rx_ue || current->next->packet->rnti != rnti) {
        current = current->next;
    }

    // Delete the node if found
    if (current != NULL && current->next != NULL) {
        node_t *to_delete = current->next;
        current->next = to_delete->next;
        free(to_delete);
    }
}

// Function to render a footer section for a web application
void render_footer(int num_scripts) {
    // Create an HTML string with the requested number of scripts
    char *html = malloc(sizeof(char) * (num_scripts + 1));
    html[0] = '\0';
    for (int i = 0; i < num_scripts; i++) {
