// Function to initialize and populate an array of custom packet headers
PacketHeader* initPacketHeaders(size_t numHeaders) {
    // Allocate memory for the array of packet headers
    PacketHeader* headers = (PacketHeader*)malloc(numHeaders * sizeof(PacketHeader));
    if (!headers) {
        fprintf(stderr, "Failed to allocate memory for packet headers\n");
        return NULL;
    }

    // Initialize each header with default values
    for (size_t i = 0; i < numHeaders; i++) {
        headers[i].SourceIP = 0;
        headers[i].DestinationIP = 0;
        headers[i].Protocol = 0;
        headers[i].PayloadSize = 0;
        headers[i].Payload = NULL;
    }

    // Dynamically allocate memory for the payload of each header
    for (size_t i = 0; i < numHeaders; i++) {
        size_t payloadSize = headers[i].PayloadSize;
        void* payload = malloc(payloadSize);
        if (!payload) {
            fprintf(stderr, "Failed to allocate memory for packet header %zu\n", i);
            free(headers);
            return NULL;
        }
        headers[i].Payload = payload;
    }

    // Return the initialized array of packet headers
    return headers;
}

// Function to release resources allocated by initPacketHeaders()
void releasePacketHeaders(PacketHeader* headers, size_t numHeaders) {
    for (size_t i = 0; i < numHeaders; i++) {
        free(headers[i].Payload);
    }
    free(headers);
}
