    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&list_lock);

    // Initialize the head and tail pointers to NULL
    head = NULL;
    tail = NULL;

    // Unlock the mutex
    pthread_mutex_unlock(&list_lock);

    return 0;
}

// Function to add a new message to the linked list
int add_message(NAS_Message_t *nas_message, UE_ID_t ue_id) {
    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&list_lock);

    // Allocate memory for the new message structure
    LTE_RRCNASMessage_t *new_message = malloc(sizeof(LTE_RRCNASMessage_t));
    if (new_message == NULL) {
        // Log an error message and return an error code
        printf("Error: Failed to allocate memory for new message\n");
        pthread_mutex_unlock(&list_lock);
        return -1;
    }

    // Initialize the new message structure
    new_message->nas_message = nas_message;
    new_message->ue_id = ue_id;
    new_message->next = NULL;
    new_message->prev = NULL;

    // If the linked list is empty, set the head and tail pointers to the new message
    if (head == NULL) {
        head = new_message;
        tail = new_message;
    } else {
        // Otherwise, add the new message to the end of the linked list
        tail->next = new_message;
        new_message->prev = tail;
        tail = new_message;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list_lock);

    return 0;
}

// Function to remove an old message from the linked list
int remove_message(LTE_RRCNASMessage_t *message) {
    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&list_lock);

    // If the message is not in the linked list, return an error code
    if (message == NULL || message->next == NULL || message->prev == NULL) {
        printf("Error: Message not found in linked list\n");
        pthread_mutex_unlock(&list_lock);
        return -1;
    }

