// Define constants for the function
#define MAX_FILENAME_LENGTH 256
#define MAX_TEMPLATE_COUNT 1000
#define MAX_OUTPUT_DIRECTORY_LENGTH 256
#define DEFAULT_LOGGING_LEVEL "INFO"

// Define data structures for the function
typedef struct {
    char* template_file;
    char* output_directory;
} TemplateFileInfo;

typedef struct {
    char* filename;
    char* content;
} FileContent;

typedef struct {
    sem_t* semaphore;
    pthread_mutex_t* mutex;
    int thread_count;
    TemplateFileInfo* template_files;
    int template_file_count;
    char* output_directory;
} FunctionData;

// Define function prototypes
void* generate_html_files(void* data);
int process_template_file(TemplateFileInfo* file, FunctionData* func_data);
int write_output_file(char* filename, char* content, int overwrite);
int read_directory(char* directory, TemplateFileInfo** files, int* file_count);
void free_files(TemplateFileInfo* files, int file_count);
void log_message(char* message, char* level);

// Define function implementations
int generate_html_files(char* template_directory, char* output_directory) {
    // Initialize data structures for the function
    FunctionData func_data;
    TemplateFileInfo* template_files = NULL;
    int template_file_count = 0;
    int thread_count = 0;
    sem_t* semaphore = NULL;
    pthread_mutex_t* mutex = NULL;

    // Read the directory containing the template files
    if (read_directory(template_directory, &template_files, &template_file_count) != 0) {
        log_message("Error reading template directory", "ERROR");
        return 1;
    }

    // Initialize semaphore and mutex for thread synchronization
    if ((semaphore = sem_open("/html_generation_semaphore", O_CREAT, 0644, 0)) == SEM_FAILED) {
        log_message("Error creating semaphore", "ERROR");
        return 1;
    }
    if ((mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t))) == NULL) {
        log_message("Error allocating memory for mutex", "ERROR");
        return 1;
    }
    pthread_mutex_init(mutex, NULL);

    // Initialize thread data structure
    func_data.semaphore = semaphore;
    func_data.mutex = mutex;
    func_data.template_files = template_files;
    func_data.template_file_count = template_file_count;
    func_data.output_directory = output_directory;

    // Create threads for each template file
    thread_count = 0;
    for (int i = 0; i < template_file_count; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, generate_html_files, &func_data) != 0) {
            log_message("Error creating thread", "ERROR");
            return 1;
        }
        thread_count++;
    }

    // Wait for all threads to complete
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up semaphore and mutex
    if (sem_close(semaphore) != 0) {
        log_message("Error closing semaphore", "ERROR");
        return 1;
    }
    free(mutex);

    // Return success
    return 0;
}

void* generate_html_files(void* data) {
    FunctionData* func_data = (FunctionData*)data;
    TemplateFileInfo* file = &func_data->template_files[func_data->thread_count];
    int thread_count = func_data->thread_count;

    // Process the template file
    if (process_template_file(file, func_data) != 0) {
        log_message("Error processing template file", "ERROR");
        return NULL;
    }

    // Increment thread count and check for completion
    pthread_mutex_lock(func_data->mutex);
    func_data->thread_count++;
    if (func_data->thread_count == func_data->template_file_count) {
        sem_post(func_data->semaphore);
    }
    pthread_mutex_unlock(func_data->mutex);

    // Return success
    return NULL;
}

int process_template_file(TemplateFileInfo* file, FunctionData* func_data) {
    // Read the template file content
    char* filename = file->filename;
    char* content = read_file(filename);
    if (content == NULL) {
        log_message("Error reading template file", "ERROR");
        return 1;
    }

    // Apply the template to the data source
    char* output_directory = func_data->output_directory;
    char* output_filename = get_output_filename(filename, output_directory);
    if (apply_template(content, output_filename) != 0) {
        log_message("Error applying template", "ERROR");
        return 1;
    }

    // Write the output file
    if (write_output_file(output_filename, content, 1) != 0) {
        log_message("Error writing output file", "ERROR");
        return 1;
    }

    // Return success
    return 0;
}

int write_output_file(char* filename, char* content, int overwrite) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        log_message("Error opening output file", "ERROR");
        return 1;
    }

    // Write the content to the file
    int length = strlen(content);
    if (fwrite(content, sizeof(char), length, fp) != length) {
        log_message("Error writing output file", "ERROR");
        return 1;
    }

    // Close the file and return success
    fclose(fp);
    return 0;
}

int read_directory(char* directory, TemplateFileInfo** files, int* file_count) {
    // Open the directory for reading
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        log_message("Error opening template directory", "ERROR");
        return 1;
    }

    // Read the files in the directory
    int file_count = 0;
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        file_count++;
    }

    // Allocate memory for the files and read them in
    TemplateFileInfo* files = (TemplateFileInfo*)malloc(file_count * sizeof(TemplateFileInfo));
    rewinddir(dir);
    int i = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        files[i].filename = entry->d_name;
        i++;
    }

    // Close the directory and return success
    closedir(dir);
    *files = files;
    *file_count = file_count;
    return 0;
}

void free_files(TemplateFileInfo* files, int file_count) {
    for (int i = 0; i < file_count; i++) {
        free(files[i].filename);
    }
    free(files);
}

void log_message(char* message, char* level) {
    // Implement logging functionality here
}
