// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int generateAndPopulateList(char* filePath, char* outputDirPath, char* outputFileNamePrefix, int compressionLevel) {
    // Initialize variables
    int i;
    int j;
    int k;
    int numFiles = 0;
    int numPDUs = 0;
    int maxSize = 0;
    int currentSize = 0;
    int totalSize = 0;
    int fileIndex = 0;
    int PDUIndex = 0;
    char* fileName;
    char* outputFileName;
    FILE* inputFile;
    FILE* outputFile;
    NFAPI_CRC_INDICATION_PDU_T* PDUList;
    semaphore_t semaphore;
    pthread_t threadPool[100];
    bool isDeadlockDetected = false;

    // Open the input file and get the number of files to process
    inputFile = fopen(filePath, "r");
    if (inputFile == NULL) {
        printf("Error: Unable to open input file %s\n", filePath);
        return 1;
    }
    while (fscanf(inputFile, "%s", fileName) != EOF) {
        numFiles++;
    }
    fclose(inputFile);

    // Allocate memory for the list of PDUs and initialize it
    PDUList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numFiles);
    if (PDUList == NULL) {
        printf("Error: Unable to allocate memory for PDU list\n");
        return 1;
    }
    memset(PDUList, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * numFiles);

    // Create a semaphore to synchronize access to the PDU list
    if (semaphore_init(&semaphore, 1) != 0) {
        printf("Error: Unable to create semaphore\n");
        return 1;
    }

    // Create a thread pool for concurrent task management
    for (i = 0; i < 100; i++) {
        if (pthread_create(&threadPool[i], NULL, processFile, &fileIndex) != 0) {
            printf("Error: Unable to create thread %d\n", i);
            return 1;
        }
    }

    // Wait for all threads to complete
    for (i = 0; i < 100; i++) {
        if (pthread_join(threadPool[i], NULL) != 0) {
            printf("Error: Unable to join thread %d\n", i);
            return 1;
        }
    }

    // Check for deadlocks or race conditions
    if (isDeadlockDetected) {
        printf("Error: Deadlock detected\n");
        return 1;
    }

    // Close the input file and open the output file
    inputFile = fopen(filePath, "r");
    if (inputFile == NULL) {
        printf("Error: Unable to open input file %s\n", filePath);
        return 1;
    }
    outputFileName = malloc(strlen(outputDirPath) + strlen(outputFileNamePrefix) + 5);
    sprintf(outputFileName, "%s/%s_%d.pdf", outputDirPath, outputFileNamePrefix, compressionLevel);
    outputFile = fopen(outputFileName, "w");
    if (outputFile == NULL) {
        printf("Error: Unable to open output file %s\n", outputFileName);
        return 1;
    }

    // Write the header of the PDF file
    fprintf(outputFile, "%PDF-1.7\n");

    // Iterate over the list of PDUs and write each one to the PDF file
    for (i = 0; i < numPDUs; i++) {
        fprintf(outputFile, "<< /Type /XObject /Subtype /Image /Width %d /Height %d /BitsPerComponent %d /Filter /DCTDecode >>\n", PDUList[i].width, PDUList[i].height, PDUList[i].bitsPerComponent);
        fprintf(outputFile, "stream\n");
        for (j = 0; j < PDUList[i].numComponents; j++) {
            fwrite(PDUList[i].components[j], sizeof(unsigned char), PDUList[i].componentSizes[j], outputFile);
        }
        fprintf(outputFile, "endstream\n");
    }

    // Close the input and output files
    fclose(inputFile);
    fclose(outputFile);

    // Free memory for the list of PDUs and the semaphore
    free(PDUList);
    semaphore_destroy(&semaphore);

    return 0;
}

// Define the function to process a single file in parallel
void* processFile(void* arg) {
    int i;
    int j;
    int k;
    char* fileName;
    FILE* inputFile;
    NFAPI_CRC_INDICATION_PDU_T PDU;
    unsigned char* buffer;
    size_t bufferSize;
