    int fileIndex = *(int*)arg;
    fileName = malloc(strlen(filePath) + 5);
    sprintf(fileName, "%s_%d.jpg", filePath, fileIndex);
    inputFile = fopen(fileName, "r");
    if (inputFile == NULL) {
        printf("Error: Unable to open input file %s\n", fileName);
        return 1;
    }

    // Read the JPEG header and get the image dimensions
    fseek(inputFile, 0, SEEK_SET);
    if (fread(&buffer, sizeof(unsigned char), 2, inputFile) != 2) {
        printf("Error: Unable to read JPEG header\n");
        return 1;
    }
    if (buffer[0] != 0xFF || buffer[1] != 0xD8) {
        printf("Error: Invalid JPEG header\n");
        return 1;
    }
    fseek(inputFile, 4, SEEK_CUR);
    if (fread(&bufferSize, sizeof(size_t), 1, inputFile) != 1) {
        printf("Error: Unable to read image dimensions\n");
        return 1;
    }
    PDU.width = bufferSize >> 4;
    PDU.height = (bufferSize & 0xF) << 8;
    if (fread(&buffer, sizeof(unsigned char), 2, inputFile) != 2) {
        printf("Error: Unable to read image dimensions\n");
        return 1;
    }
    PDU.height |= buffer[0];

    // Read the JPEG data and get the number of components
    fseek(inputFile, 0, SEEK_SET);
    if (fread(&bufferSize, sizeof(size_t), 1, inputFile) != 1) {
        printf("Error: Unable to read image dimensions\n");
        return 1;
    }
    buffer = malloc(bufferSize);
    if (fread(buffer, sizeof(unsigned char), bufferSize, inputFile) != bufferSize) {
        printf("Error: Unable to read JPEG data\n");
        return 1;
    }
    PDU.numComponents = 3;
    for (i = 0; i < PDU.numComponents; i++) {
        if (fread(&bufferSize, sizeof(size_t), 1, inputFile) != 1) {
            printf("Error: Unable to read component size\n");
            return 1;
        }
        PDU.componentSizes[i] = bufferSize;
    }

    // Convert the JPEG data to a PDF file
    fprintf(outputFile, "<< /Type /XObject /Subtype /Image /Width %d /Height %d /BitsPerComponent %d /Filter /DCTDecode >>\n", PDU.width, PDU.height, PDU.bitsPerComponent);
    fprintf(outputFile, "stream\n");
    for (i = 0; i < PDU.numComponents; i++) {
        fwrite(buffer + PDU.componentSizes[i], sizeof(unsigned char), PDU.componentSizes[i], outputFile);
    }
    fprintf(outputFile, "endstream\n");

    // Close the input file and free memory for the buffer
    fclose(inputFile);
    free(buffer);

    return 0;
}
