int rename_files(const char* user_id, const char** source_file_paths, int num_source_files, const char* target_dir) {
    // Check if the required configuration files are present and valid
    if (!check_config_files()) {
        return 1;
    }

    // Initialize a lock for atomicity and concurrency control
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Iterate over the source files and rename them based on EXIF metadata
    for (int i = 0; i < num_source_files; i++) {
        const char* source_file_path = source_file_paths[i];
        FILE* source_file = fopen(source_file_path, "rb");
        if (!source_file) {
            // Log the error and continue with the next file
            log_error("Failed to open source file: %s", strerror(errno));
            continue;
        }

        // Extract EXIF metadata from the source file
        ExifData* exif_data = exif_data_new_from_file(source_file);
        if (!exif_data) {
            // Log the error and continue with the next file
            log_error("Failed to extract EXIF data: %s", strerror(errno));
            fclose(source_file);
            continue;
        }

        // Get the metadata attribute from the EXIF data
        const char* metadata = exif_data_get_metadata(exif_data, "MetadataAttribute");
        if (!metadata) {
            // Log the error and continue with the next file
            log_error("Failed to get metadata attribute: %s", strerror(errno));
            exif_data_free(exif_data);
            fclose(source_file);
            continue;
        }

        // Create a new target file path based on the metadata attribute
        char* target_file_path = create_target_file_path(metadata, target_dir);
        if (!target_file_path) {
            // Log the error and continue with the next file
            log_error("Failed to create target file path: %s", strerror(errno));
            exif_data_free(exif_data);
            fclose(source_file);
            continue;
        }

        // Rename the source file to the target file
        int result = rename(source_file_path, target_file_path);
        if (result != 0) {
            // Log the error and continue with the next file
            log_error("Failed to rename file: %s", strerror(errno));
            free(target_file_path);
            exif_data_free(exif_data);
            fclose(source_file);
            continue;
        }

        // Free resources and log success
        free(target_file_path);
        exif_data_free(exif_data);
        fclose(source_file);
        log_success("Renamed file: %s", source_file_path);
    }

    // Release the lock and return success
    pthread_mutex_unlock(&lock);
    return 0;
}

