// Define the concurrent insertion mechanism for handling high-throughput scenarios
void concurrent_insert(crc_packet_collection_t* collection, crc_packet_t packet) {
    // Acquire a lock on the collection to prevent concurrent access
    semaphore_wait(&collection->lock);

    // Add the new packet to the end of the collection
    collection->packets = realloc(collection->packets, (collection->num_packets + 1) * sizeof(crc_packet_t));
    collection->packets[collection->num_packets] = packet;
    collection->num_packets++;

    // Release the lock on the collection
    semaphore_post(&collection->lock);
}

// Define the function for retrieving a specific CRC indication packet from the collection
crc_packet_t* get_crc_packet(crc_packet_collection_t* collection, int index) {
    // Check if the index is within the bounds of the collection
    if (index < 0 || index >= collection->num_packets) {
        return NULL;
    }

    // Return the packet at the specified index
    return &collection->packets[index];
}

// Define the function for updating a specific CRC indication packet in the collection
void update_crc_packet(crc_packet_collection_t* collection, int index, crc_packet_t packet) {
    // Check if the index is within the bounds of the collection
    if (index < 0 || index >= collection->num_packets) {
        return;
    }

    // Update the packet at the specified index with the new values
    collection->packets[index] = packet;
}

// Define the function for deleting a specific CRC indication packet from the collection
void delete_crc_packet(crc_packet_collection_t* collection, int index) {
    // Check if the index is within the bounds of the collection
    if (index < 0 || index >= collection->num_packets) {
        return;
    }

    // Shift all packets after the specified index to fill the gap
    for (int i = index + 1; i < collection->num_packets; i++) {
        collection->packets[i - 1] = collection->packets[i];
    }

    // Decrement the number of packets in the collection
    collection->num_packets--;
}

// Define the function for bulk importing CRC indication packets into the collection
void import_crc_packets(crc_packet_collection_t* collection, crc_packet_t* packets, size_t num_packets) {
    // Acquire a lock on the collection to prevent concurrent access
    semaphore_wait(&collection->lock);

    // Reallocate the memory for the collection to fit the new number of packets
    collection->packets = realloc(collection->packets, (num_packets + collection->num_packets) * sizeof(crc_packet_t));

    // Copy the new packets into the collection
    memcpy(&collection->packets[collection->num_packets], packets, num_packets * sizeof(crc_packet_t));

    // Update the number of packets in the collection
    collection->num_packets += num_packets;

    // Release the lock on the collection
    semaphore_post(&collection->lock);
}

// Define the function for bulk exporting CRC indication packets from the collection
void export_crc_packets(crc_packet_collection_t* collection, crc_packet_t** packets) {
    // Acquire a lock on the collection to prevent concurrent access
    semaphore_wait(&collection->lock);

    // Copy the packets from the collection into the output array
    memcpy(packets, collection->packets, collection->num_packets * sizeof(crc_packet_t));

    // Release the lock on the collection
    semaphore_post(&collection->lock);
}

