```
class SessionManager {
public:
    // Constructor
    SessionManager() : sessions_(), analytics_service_(nullptr) {}

    // Destructor
    ~SessionManager() {
        for (auto& session : sessions_) {
            delete session.second;
        }
    }

    // Add a new media stream to an existing user session
    void addMediaStream(const std::string& user_id, const MediaStream& stream) {
        auto it = sessions_.find(user_id);
        if (it == sessions_.end()) {
            // Create a new session if one does not exist
            Session* session = new Session();
            session->media_streams.push_back(stream);
            sessions_.insert({user_id, session});
        } else {
            // Add the media stream to an existing session
            it->second->media_streams.push_back(stream);
        }
    }

    // Log an API call for a user session
    void logApiCall(const std::string& user_id, const ApiCall& call) {
        auto it = sessions_.find(user_id);
        if (it == sessions_.end()) {
            // Create a new session if one does not exist
            Session* session = new Session();
            session->api_calls.push_back(call);
            sessions_.insert({user_id, session});
        } else {
            // Add the API call to an existing session
            it->second->api_calls.push_back(call);
        }
    }

    // Update an existing user session with new media streams and API calls
    void updateSession(const std::string& user_id, const MediaStreams& media_streams, const ApiCalls& api_calls) {
        auto it = sessions_.find(user_id);
        if (it == sessions_.end()) {
            // Create a new session if one does not exist
            Session* session = new Session();
            session->media_streams = media_streams;
            session->api_calls = api_calls;
            sessions_.insert({user_id, session});
        } else {
            // Update the existing session with new media streams and API calls
            it->second->media_streams.insert(it->second->media_streams.end(), media_streams.begin(), media_streams.end());
            it->second->api_calls.insert(it->second->api_calls.end(), api_calls.begin(), api_calls.end());
        }
    }

    // Terminate a user session based on its ID
    void terminateSession(const std::string& user_id) {
        auto it = sessions_.find(user_id);
        if (it != sessions_.end()) {
            delete it->second;
            sessions_.erase(it);
        }
    }

private:
    // A session object stores information about a user's media streams and API calls
    struct Session {
        std::vector<MediaStream> media_streams;
        std::vector<ApiCall> api_calls;
    };

    // A map to store all active user sessions
    std::map<std::string, Session*> sessions_;

    // An external analytics service for tracking user behavior and optimizing content delivery
    AnalyticsService* analytics_service_;
};
