#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include "nfapi_crc_indication_pdu.h"
#include "external_crc_calculator.h"

// Define a hash table for storing RNTIs
typedef struct {
    int *rnti;
    bool used;
} rnti_hash_table_t;

// Define a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct nfapi_crc_indication_pdu_s *next;
} crc_indication_list_t;

// Define a mutex for synchronizing access to the list
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function for creating and populating a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_list(int num_pdu, int seed) {
    // Allocate memory for the list
    crc_indication_list_t *list = malloc(sizeof(crc_indication_list_t) * num_pdu);
    if (!list) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    // Initialize the hash table for storing RNTIs
    rnti_hash_table_t *rnti_ht = malloc(sizeof(rnti_hash_table_t) * num_pdu);
    if (!rnti_ht) {
        printf("Error: Failed to allocate memory for RNTI hash table\n");
        free(list);
        return NULL;
    }

    // Initialize the mutex for synchronizing access to the list
    pthread_mutex_init(&list_mutex, NULL);

    // Populate the list with random data
    for (int i = 0; i < num_pdu; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(list[i].pdu);
        pdu->rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        pdu->rx_ue_information.rnti = rand_r(&seed) % 10000;
        while (rnti_ht[pdu->rx_ue_information.rnti].used) {
            pdu->rx_ue_information.rnti = rand_r(&seed) % 10000;
        }
        rnti_ht[pdu->rx_ue_information.rnti].used = true;
        pdu->crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        pdu->crc_indication_rel8.crcFlag = rand_r(&seed) % 2;
    }

    // Serialize the list to a binary file for later reuse
    FILE *fp = fopen("crc_indication_list.bin", "wb");
    if (!fp) {
        printf("Error: Failed to open file for writing\n");
        free(list);
        free(rnti_ht);
        pthread_mutex_destroy(&list_mutex);
        return NULL;
    }
    fwrite(list, sizeof(crc_indication_list_t), num_pdu, fp);
    fclose(fp);

    // Clean up memory
    free(rnti_ht);
    pthread_mutex_destroy(&list_mutex);

    return list;
}

// Define a function for adding a new structure to the list
void add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&list_mutex);

    // Check if the RNTI is already in use
    rnti_hash_table_t *rnti_ht = malloc(sizeof(rnti_hash_table_t) * num_pdu);
    if (!rnti_ht) {
        printf("Error: Failed to allocate memory for RNTI hash table\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    bool rnti_in_use = false;
    for (int i = 0; i < num_pdu; i++) {
        if (rnti_ht[i].used && rnti_ht[i].rnti == pdu->rx_ue_information.rnti) {
            rnti_in_use = true;
            break;
        }
    }
    if (rnti_in_use) {
        printf("Error: RNTI %d is already in use\n", pdu->rx_ue_information.rnti);
        free(rnti_ht);
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // Add the new structure to the list
    crc_indication_list_t *new_node = malloc(sizeof(crc_indication_list_t));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new node\n");
        free(rnti_ht);
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    new_node->pdu = pdu;
    new_node->next = NULL;
    if (head == NULL) {
        head = new_node;
    } else {
        tail->next = new_node;
    }
    tail = new_node;

