// Initialize the session management module
void init_session_management() {
  // Initialize the mutex for protecting the session list
  pthread_mutex_init(&session_list_mutex, NULL);

  // Initialize the semaphore for waiting on the database write operation
  sem_init(&database_write_semaphore, 0, 1);

  // Initialize the session list
  memset(session_list, 0, sizeof(UserSession *) * MAX_ACTIVE_SESSIONS);
}

// Add a new user session to the list
void add_user_session(UserSession *session) {
  // Acquire the mutex for protecting the session list
  pthread_mutex_lock(&session_list_mutex);

  // Check if there is space in the session list
  if (num_active_sessions() >= MAX_ACTIVE_SESSIONS) {
    // Release the mutex and return
    pthread_mutex_unlock(&session_list_mutex);
    return;
  }

  // Add the new session to the list
  session_list[num_active_sessions()] = session;

  // Release the mutex
  pthread_mutex_unlock(&session_list_mutex);
}

// Remove a user session from the list
void remove_user_session(UserSession *session) {
  // Acquire the mutex for protecting the session list
  pthread_mutex_lock(&session_list_mutex);

  // Find the index of the session in the list
  int i;
  for (i = 0; i < num_active_sessions(); i++) {
    if (session == session_list[i]) {
      break;
    }
  }

  // Check if the session was found in the list
  if (i >= num_active_sessions()) {
    // Release the mutex and return
    pthread_mutex_unlock(&session_list_mutex);
    return;
  }

  // Remove the session from the list
  memmove(session_list + i, session_list + i + 1, sizeof(UserSession *) * (num_active_sessions() - i));

  // Release the mutex
  pthread_mutex_unlock(&session_list_mutex);
}

// Get the number of active sessions
int num_active_sessions() {
  int count = 0;

  // Acquire the mutex for protecting the session list
  pthread_mutex_lock(&session_list_mutex);

  // Count the number of active sessions
  for (int i = 0; i < MAX_ACTIVE_SESSIONS; i++) {
    if (session_list[i] != NULL) {
      count++;
    }
  }

  // Release the mutex
  pthread_mutex_unlock(&session_list_mutex);

  return count;
}

