  return (long)tv.tv_sec * 1000 + (long)tv.tv_usec / 1000;
}

// Check if a user session is expired
bool is_expired(UserSession *session) {
  // Calculate the difference between the current time and the last activity time
  long diff = get_current_timestamp() - session->last_activity_time;

  // Check if the session has been inactive for longer than the timeout period
  return diff >= SESSION_TIMEOUT;
}

