        rx_info->crc_indication_rel8_tag = crc_indication_rel8_tag;
        rx_info->crcflag = crcflag;
        rx_info_list = realloc(rx_info_list, (num_files + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        rx_info_list[num_files] = *rx_info;
        num_files++;

