        if (pdf_conversion_result != 0) {
            perror("pdf_convert");
            free(rx_info);
            rx_info_list[num_files] = NULL;
            num_files--;
            continue;
        }

        // Log the compression process and file operations to the log file
        time_t current_time = time(NULL);
        struct tm *current_tm = localtime(&current_time);
        char timestamp[64];
