    // Clean up the input file and log file
    fclose(input_file);
    fclose(log_file);

    // Destroy the compression library and custom memory pool
    int compression_destroy_result = compression_destroy();
    if (compression_destroy_result != 0) {
        perror("compression_destroy");
    }
    pdf_destroy(pdf_memory_pool);
    free(pdf_memory_pool);

    // Return 0 if all files are successfully processed within the size constraints; otherwise, return 1
    int result = 0;
    for (int i = 0; i < num_files; i++) {
        struct stat file_stat;
        if (fstat(fileno(fopen(rx_info_list[i].pdf_file_name, "r")), &file_stat) != 0) {
            perror("fstat");
            result = 1;
            break;
        }
        if (file_stat.st_size > MAX_FILE_SIZE) {
            fprintf(stderr, "File %s exceeds maximum size limit\n", rx_info_list[i].pdf_file_name);
            result = 1;
            break;
        }
    }
    return result;
}
