    char payload[]; // Variable length payload
    uint32_t checksum;
} NetworkPacket;

// Function to dynamically allocate memory for an array of custom network packets
NetworkPacket* alloc_network_packets(size_t N) {
    // Allocate memory for the array of packets
    NetworkPacket* packets = (NetworkPacket*)malloc(N * sizeof(NetworkPacket));
    if (!packets) {
        fprintf(stderr, "Error: Failed to allocate memory for network packets\n");
        return NULL;
    }

