    for (size_t i = 0; i < N; ++i) {
        packets[i].header = 0xDEADBEEF;
        packets[i].checksum = 0;
    }

    // Initialize the payload content and compute the checksum on-the-fly
    for (size_t i = 0; i < N; ++i) {
        char* payload = packets[i].payload;
        size_t payload_len = strlen(payload);
        for (size_t j = 0; j < payload_len; ++j) {
            payload[j] = 'A' + i % 26; // Update the payload content dynamically
            packets[i].checksum += payload[j];
        }
    }

    return packets;
}

// Function to free memory allocated for an array of custom network packets
void free_network_packets(NetworkPacket* packets) {
    if (packets) {
        free(packets);
    }
}
