// Custom memory allocator to minimize fragmentation and optimize memory usage
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle allocation failure
    }
    return ptr;
}

// Custom memory deallocator to free memory allocated by the custom allocator
void custom_free(void* ptr) {
