// Structure to represent a user session
typedef struct Session {
    int id;
    char* ip_address;
    long last_active_timestamp;
    int duration;
} Session;

// List of sessions with dynamic resizing capabilities
typedef struct SessionList {
    Session** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex; // Synchronization mechanism to manage shared resources
} SessionList;

// Initialize a new session list with the given capacity
SessionList* init_session_list(size_t capacity) {
    SessionList* list = (SessionList*)custom_alloc(sizeof(SessionList));
    if (list == NULL) {
        // Handle allocation failure
    }
    list->sessions = (Session**)custom_alloc(capacity * sizeof(Session*));
    if (list->sessions == NULL) {
        // Handle allocation failure
    }
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Insert a new session into the list
void insert_session(SessionList* list, Session* session) {
    // Acquire lock on the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Resize the list if it is full
        size_t new_capacity = list->capacity * 2;
        Session** new_sessions = (Session**)custom_alloc(new_capacity * sizeof(Session*));
        if (new_sessions == NULL) {
            // Handle allocation failure
        }
        memcpy(new_sessions, list->sessions, list->count * sizeof(Session*));
        custom_free(list->sessions);
        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }
    // Insert the session into the list
    list->sessions[list->count++] = session;
    pthread_mutex_unlock(&list->mutex);
}

// Delete a session from the list by its ID
void delete_session(SessionList* list, int id) {
    // Acquire lock on the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->sessions[i]->id == id) {
            // Remove the session from the list
            memmove(list->sessions + i, list->sessions + i + 1, (list->count - i - 1) * sizeof(Session*));
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Retrieve a session from the list by its ID
Session* get_session(SessionList* list, int id) {
    // Acquire lock on the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->sessions[i]->id == id) {
            // Return the session
            Session* session = list->sessions[i];
            pthread_mutex_unlock(&list->mutex);
            return session;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Retrieve a session from the list by its IP address
Session* get_session_by_ip(SessionList* list, char* ip_address) {
    // Acquire lock on the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->sessions[i]->ip_address, ip_address) == 0) {
            // Return the session
            Session* session = list->sessions[i];
            pthread_mutex_unlock(&list->mutex);
            return session;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

