#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure for LTE_PDCP_PDU
typedef struct {
    int pdcp_sn;
    int srb_id;
    char* user_data;
} LTE_PDCP_PDU;

// Define a dynamic array to store the PDCP PDUs
LTE_PDCP_PDU** pdu_array = NULL;
int num_pdu = 0;
int total_bytes = 0;

void init_and_configure_pdcp_pdu(int srb_id, char* user_data) {
    // Check if the SRB ID is valid
    if (srb_id < 0 || srb_id > 31) {
        printf("Invalid SRB ID: %d\n", srb_id);
        return;
    }

    // Allocate memory for the PDCP PDU
    LTE_PDCP_PDU* new_pdu = (LTE_PDCP_PDU*) malloc(sizeof(LTE_PDCP_PDU));
    if (!new_pdu) {
        printf("Failed to allocate memory for PDCP PDU\n");
        return;
    }

    // Initialize the PDCP SN and SRB ID
    new_pdu->pdcp_sn = num_pdu++;
    new_pdu->srb_id = srb_id;

    // Allocate memory for the user data
    int user_data_len = strlen(user_data);
    new_pdu->user_data = (char*) malloc(user_data_len + 1);
    if (!new_pdu->user_data) {
        printf("Failed to allocate memory for user data\n");
        free(new_pdu);
        return;
    }

    // Copy the user data into the PDCP PDU
    strcpy(new_pdu->user_data, user_data);

    // Add the new PDCP PDU to the array
    pdu_array = (LTE_PDCP_PDU**) realloc(pdu_array, num_pdu * sizeof(LTE_PDCP_PDU*));
    if (!pdu_array) {
        printf("Failed to allocate memory for PDCP PDU array\n");
        free(new_pdu->user_data);
        free(new_pdu);
        return;
    }
    pdu_array[num_pdu - 1] = new_pdu;

    // Update the total number of bytes allocated for all PDUs in the array
    total_bytes += user_data_len + 1;
}

void free_pdcp_pdu(int index) {
    if (index < 0 || index >= num_pdu) {
        printf("Invalid index: %d\n", index);
        return;
    }

    // Free the user data and PDCP PDU structure
    free(pdu_array[index]->user_data);
    free(pdu_array[index]);

    // Shift all subsequent PDUs in the array to fill the gap
    for (int i = index; i < num_pdu - 1; i++) {
        pdu_array[i] = pdu_array[i + 1];
    }

    // Decrement the number of PDUs and update the total number of bytes allocated
    num_pdu--;
    total_bytes -= strlen(pdu_array[index]->user_data) + 1;
}

void print_pdcp_pdu(int index) {
    if (index < 0 || index >= num_pdu) {
        printf("Invalid index: %d\n", index);
        return;
    }

    // Print the PDCP SN, SRB ID, and user data for the specified PDU
    printf("PDCP SN: %d\nSRB ID: %d\nUser Data: %s\n", pdu_array[index]->pdcp_sn, pdu_array[index]->srb_id, pdu_array[index]->user_data);
}
```
This implementation of the `init_and_configure_pdcp_pdu` function uses a dynamic array to store the PDCP PDUs. Each PDCP PDU is represented by a structure containing the PDCP SN, SRB ID, and a dynamically allocated buffer for user data. The function also tracks the total number of bytes currently allocated for all PDUs in the array.

The function first checks if the SRB ID is valid and allocates memory for the PDCP PDU structure using `malloc`. If allocation fails, it returns without modifying any state.

Next, the function initializes the PDCP SN and SRB ID of the new PDCP PDU and allocates memory for the user data using `malloc`. If allocation fails, it frees the previously allocated memory for the PDCP PDU structure and returns without modifying any state.

The function then copies the user data into the newly allocated buffer and adds the new PDCP PDU to the array using `realloc`. If reallocation fails, it frees the previously allocated memory for the PDCP PDU structure and returns without modifying any state.

Finally, the function updates the total number of bytes allocated for all PDUs in the array by adding the length of the user data plus one (for the null terminator).

The `free_pdcp_pdu` function frees the memory allocated for a specific PDCP PDU using `free`. It also shifts all subsequent PDUs in the array to fill the gap and decrements the number of PDUs.

The `print_pdcp_pdu` function prints the PDCP SN, SRB ID, and user data for a specific PDCP PDU using `printf`. It checks if the index is valid before accessing the PDCP PDU structure in the array.']

