typedef struct {
    PHY_RX_PDU_T rxFrameInfo;
    bool crcStatus;
} PHYSICAL_LAYER_RX_INDICATIONS;

// Define the array of PHY_RX_PDU_T structures
PHY_RX_PDU_T *rxPduArray = NULL;

// Define the total number of allocations made
int numAllocations = 0;

// Define the logging system
FILE *logFile = NULL;

// Define the mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void allocateRxPdu(PHYSICAL_LAYER_RX_INDICATIONS *rxIndications) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Increment the total number of allocations made
    numAllocations++;

    // Allocate memory for the PHY_RX_PDU_T structure
    rxPduArray = realloc(rxPduArray, sizeof(PHY_RX_PDU_T) * numAllocations);

    // Check if allocation failed
    if (rxPduArray == NULL) {
        printf("Error: Failed to allocate memory for PHY_RX_PDU_T structure\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize the new PHY_RX_PDU_T structure
    rxPduArray[numAllocations - 1].frameType = rxIndications->rxFrameInfo.frameType;
    rxPduArray[numAllocations - 1].syncFlag = rxIndications->rxFrameInfo.syncFlag;
    rxPduArray[numAllocations - 1].timestamp = rxIndications->rxFrameInfo.timestamp;

    // Check if the allocated memory is correctly aligned for the data structures involved
    if (!is_aligned(rxPduArray, sizeof(PHY_RX_PDU_T))) {
        printf("Error: Allocated memory is not correctly aligned\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Check if each RX_FRAME_INFO includes a valid frame type and synchronization flag
    if (rxPduArray[numAllocations - 1].frameType < 0 || rxPduArray[numAllocations - 1].syncFlag == false) {
        printf("Error: Invalid frame type or synchronization flag\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Log the allocation information
    logAllocation(rxPduArray[numAllocations - 1]);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void deallocateRxPdu(PHY_RX_PDU_T *rxPdu) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Decrement the total number of allocations made
    numAllocations--;

    // Deallocate memory for the PHY_RX_PDU_T structure
    rxPduArray = realloc(rxPduArray, sizeof(PHY_RX_PDU_T) * numAllocations);

    // Check if deallocation failed
    if (rxPduArray == NULL) {
        printf("Error: Failed to deallocate memory for PHY_RX_PDU_T structure\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Log the deallocation information
    logDeallocation(rxPdu);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void logAllocation(PHY_RX_PDU_T *rxPdu) {
    // Open the log file if it is not already open
    if (logFile == NULL) {
        logFile = fopen("allocation.log", "w");
    }

    // Write the allocation information to the log file
    fprintf(logFile, "%d: Allocated PHY_RX_PDU_T structure with frame type %d and synchronization flag %s\n", pthread_self(), rxPdu->frameType, rxPdu->syncFlag ? "true" : "false");
}

void logDeallocation(PHY_RX_PDU_T *rxPdu) {
    // Open the log file if it is not already open
    if (logFile == NULL) {
        logFile = fopen("deallocation.log", "w");
    }

    // Write the deallocation information to the log file
    fprintf(logFile, "%d: Deallocated PHY_RX_PDU_T structure with frame type %d and synchronization flag %s\n", pthread_self(), rxPdu->frameType, rxPdu->syncFlag ? "true" : "false");
}
