        return -1;
    }

    // Set the timeout for the connection
    struct timeval tv;
    tv.tv_sec = 5;
    tv.tv_usec = 0;
    if (setsockopt(socket_fd, SOL_SOCKET, SO_RCVTIMEO, (char *)&tv, sizeof(tv)) < 0) {
        perror("failed to set timeout");
        close(socket_fd);
        return -1;
    }

    // Check if the connection is still active after the timeout
    if (select(socket_fd + 1, NULL, NULL, NULL, &tv) <= 0) {
        perror("connection timed out");
        close(socket_fd);
        return -1;
    }

    // Check for any errors in the connection
    int error = 0;
    socklen_t len = sizeof(error);
    if (getsockopt(socket_fd, SOL_SOCKET, SO_ERROR, &error, &len) < 0) {
        perror("failed to get socket error");
        close(socket_fd);
        return -1;
    }

    // If there are any errors in the connection, reconnect
