    pthread_mutex_lock(&lock);

    // Allocate memory for a new node and populate it with the given data
    node_t *new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    new_node->data = data;
    new_node->next = head;
    head = new_node;

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

// Function to remove a node from the linked list with the given RNTI value
void remove_node(uint16_t rnti) {
    // Lock the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&lock);

    // Iterate over the nodes in the list and find the one with the given RNTI value
    node_t *current = head;
    while (current != NULL) {
        if (current->data->rnti == rnti) {
            // If the node is found, remove it from the list by updating the next pointer of the previous node
            node_t *previous = current->next;
            free(current);
            current = previous;
            break;
        } else {
            current = current->next;
        }
    }

    // If no node with the given RNTI value is found, do nothing
    if (current == NULL) {
        printf("Error: No node with RNTI %d found in the list\n", rnti);
