// Function to validate that all RNTIs in the linked list are unique
void validate_rntis(void) {
    // Lock the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&lock);

    // Iterate over the nodes in the list and check for duplicate RNTIs
    node_t *current = head;
    while (current != NULL) {
        node_t *next = current->next;
        while (next != NULL) {
            if (current->data->rnti == next->data->rnti) {
                printf("Error: Duplicate RNTI %d found in the list\n", current->data->rnti);
                break;
            }
            next = next->next;
        }
        current = current->next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

