void update_crcflag(uint16_t rnti, bool crcflag) {
    // Lock the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&lock);

    // Iterate over the nodes in the list and find the one with the given RNTI value
    node_t *current = head;
    while (current != NULL) {
        if (current->data->rnti == rnti) {
            current->data->crcflag = crcflag;
            break;
        } else {
            current = current->next;
        }
    }

    // If no node with the given RNTI value is found, do nothing
    if (current == NULL) {
        printf("Error: No node with RNTI %d found in the list\n", rnti);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

// Function to iterate over the nodes in the linked list and apply a given operation on each element
void iterate(void (*operation)(node_t *)) {
    // Lock the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&lock);

    // Iterate over the nodes in the list and apply the given operation on each element
    node_t *current = head;
    while (current != NULL) {
        operation(current);
        current = current->next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

// Function to enforce an LRU eviction policy on the linked list, removing the least recently used node if necessary
void lru_evict(void) {
    // Lock the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&lock);

    // If the number of nodes in the list exceeds the maximum allowed, remove the least recently used node
    if (head != NULL && head->next != NULL) {
        node_t *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        free(current);
        current = head;
        head = current->next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}
