// Structure to represent a NIC parameter
typedef struct nic_param {
    uint32_t ip_addr;
    uint32_t subnet_mask;
    uint64_t mac_addr;
    uint16_t mtu_size;
    bool status;
} nic_param_t;

// Structure to represent a pool of NIC parameters
typedef struct nic_pool {
    size_t capacity;
    size_t count;
    nic_param_t* params;
} nic_pool_t;

// Function to initialize the NIC parameter pool
void init_nic_pool(nic_pool_t* pool) {
    // Initialize the pool with a default capacity of 1024 NIC parameters
    pool->capacity = 1024;
    pool->count = 0;
    pool->params = (nic_param_t*)malloc(sizeof(nic_param_t) * pool->capacity);
}

// Function to add a new NIC parameter to the pool
void add_nic_param(nic_pool_t* pool, uint32_t ip_addr, uint32_t subnet_mask, uint64_t mac_addr, uint16_t mtu_size) {
    // Check if the pool is full and needs to be resized
    if (pool->count == pool->capacity) {
        resize_nic_pool(pool);
    }

    // Add the new NIC parameter to the pool
    nic_param_t* param = &pool->params[pool->count];
    param->ip_addr = ip_addr;
    param->subnet_mask = subnet_mask;
    param->mac_addr = mac_addr;
    param->mtu_size = mtu_size;
    param->status = true;
    pool->count++;
}

// Function to remove a NIC parameter from the pool
void remove_nic_param(nic_pool_t* pool, uint32_t ip_addr) {
    // Find the index of the NIC parameter with the given IP address
    size_t idx = 0;
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->params[i].ip_addr == ip_addr) {
            idx = i;
            break;
        }
    }

    // Remove the NIC parameter from the pool
    nic_param_t* param = &pool->params[idx];
    param->status = false;
    pool->count--;
}

// Function to resize the NIC parameter pool
void resize_nic_pool(nic_pool_t* pool) {
    // Double the capacity of the pool
    size_t new_capacity = pool->capacity * 2;
    nic_param_t* new_params = (nic_param_t*)malloc(sizeof(nic_param_t) * new_capacity);

    // Copy the existing NIC parameters to the new pool
    for (size_t i = 0; i < pool->count; i++) {
        nic_param_t* param = &pool->params[i];
        new_params[i] = *param;
    }

    // Free the old pool and update the new capacity and parameters
    free(pool->params);
    pool->capacity = new_capacity;
    pool->params = new_params;
}

// Function to retrieve a NIC parameter from the pool by IP address
nic_param_t* get_nic_param(nic_pool_t* pool, uint32_t ip_addr) {
    // Find the index of the NIC parameter with the given IP address
    size_t idx = 0;
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->params[i].ip_addr == ip_addr) {
            idx = i;
            break;
        }
    }

    // Return the NIC parameter at the given index
    return &pool->params[idx];
}

// Function to update a NIC parameter in the pool by IP address
void update_nic_param(nic_pool_t* pool, uint32_t ip_addr, uint32_t subnet_mask, uint64_t mac_addr, uint16_t mtu_size) {
    // Find the index of the NIC parameter with the given IP address
    size_t idx = 0;
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->params[i].ip_addr == ip_addr) {
            idx = i;
            break;
        }
    }

    // Update the NIC parameter at the given index
    nic_param_t* param = &pool->params[idx];
    param->subnet_mask = subnet_mask;
    param->mac_addr = mac_addr;
    param->mtu_size = mtu_size;
}

// Function to query the status of a NIC parameter in the pool by IP address
bool get_nic_status(nic_pool_t* pool, uint32_t ip_addr) {
    // Find the index of the NIC parameter with the given IP address
    size_t idx = 0;
    for (size_t i = 0; i < pool->count; i++) {
        if (pool->params[i].ip_addr == ip_addr) {
            idx = i;
            break;
        }
    }

    // Return the status of the NIC parameter at the given index
    return pool->params[idx].status;
}
