// Function to get the name of a network interface by its index
char *get_interface_name(int index) {
    // Get the list of all available network interfaces
    struct ifaddrs *ifaddr;
    if (getifaddrs(&ifaddr) == -1) {
        perror("Failed to get list of network interfaces");
        return NULL;
    }

    // Loop through each interface and find the one with the specified index
    for (struct ifaddrs *ifa = ifaddr; ifa != NULL; ifa = ifa->ifa_next) {
        if (index == 0) {
            break;
        }
        index--;
    }

    // Return the name of the interface with the specified index
    return ifa->ifa_name;
}

// Function to collect statistics for a single network interface
void collect_statistics(NetworkInterfaceStatistics *stats, char *interface_name) {
    // Get the socket file descriptor for the current interface
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("Failed to create socket");
        return;
    }

    // Bind the socket to the specified interface
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(0);
    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("Failed to bind socket");
        close(sock);
        return;
    }

    // Get the interface index for the specified interface name
    int ifindex = if_nametoindex(interface_name);
    if (ifindex == 0) {
        perror("Failed to get interface index");
        close(sock);
        return;
    }

    // Set the socket options to collect statistics for the specified interface
    struct packet_mreq mreq = {
        .mr_ifindex = ifindex,
        .mr_type = PACKET_MR_PROMISC,
        .mr_alen = 0,
        .mr_address = { 0 }
    };
    if (setsockopt(sock, SOL_PACKET, PACKET_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) == -1) {
        perror("Failed to set socket options");
        close(sock);
        return;
    }

    // Collect the statistics for the specified interface
    struct packet_statistics pstats;
    if (getsockopt(sock, SOL_PACKET, PACKET_STATISTICS, &pstats, sizeof(pstats)) == -1) {
        perror("Failed to get socket options");
        close(sock);
        return;
    }

    // Close the socket and return the statistics
    close(sock);
    stats->timestamp = time(NULL);
    stats->interface_name = interface_name;
    stats->packet_count = pstats.ps_ifdrop + pstats.ps_ifpackets;
}

// Function to add an entry to the list of network interface statistics
void add_to_list(NetworkInterfaceStatistics *list, NetworkInterfaceStatistics *entry) {
    // Check if the list is full and needs to be resized
    if (list->size == MAX_LIST_SIZE) {
        resize_list(list);
    }

    // Add the new entry to the end of the list
    list[list->size++] = *entry;
}

// Function to clear and resize the list of network interface statistics
void clear_and_resize_list(NetworkInterfaceStatistics *list) {
    // Clear the list by setting its size to 0
    list->size = 0;

    // Resize the list if necessary
    if (list->size == MAX_LIST_SIZE) {
        resize_list(list);
    }
}

// Function to resize the list of network interface statistics
void resize_list(NetworkInterfaceStatistics *list) {
    // Allocate a new array for the resized list
    NetworkInterfaceStatistics *new_list = malloc(sizeof(NetworkInterfaceStatistics) * (list->size + 1));
    if (new_list == NULL) {
        perror("Failed to allocate memory for resized list");
        return;
    }

    // Copy the existing entries from the old list to the new one
    memcpy(new_list, list, sizeof(NetworkInterfaceStatistics) * list->size);

    // Free the old list and set the new one as the current one
    free(list);
    list = new_list;
}
```
