#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>

// Define the maximum size of the network interface statistics list
#define MAX_INTERFACE_STATS 1024

// Define the structure to store network interface statistics
typedef struct {
    time_t timestamp; // Timestamp of the statistics
    char *interface_name; // Name of the network interface
    uint32_t packet_count; // Number of packets received on the interface
} interface_stats_t;

// Define the structure to store a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag; // Valid RX_UE_INFORMATION_TAG
    uint16_t rnti; // Random Network Transmission Identifier (RNTI)
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag; // CRC indication tag
} nfapi_crc_indication_pdu_t;

// Define the function to manage the dynamic list of network interface statistics
void manage_interface_stats(int num_interfaces, char **interface_names) {
    // Initialize the list of interface statistics
    interface_stats_t *interface_stats = (interface_stats_t *)malloc(sizeof(interface_stats_t) * MAX_INTERFACE_STATS);
    memset(interface_stats, 0, sizeof(interface_stats_t) * MAX_INTERFACE_STATS);

    // Loop through each network interface and collect statistics
    for (int i = 0; i < num_interfaces; i++) {
        char *interface_name = interface_names[i];
        int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
        if (sockfd == -1) {
            perror("socket");
            continue;
        }

        struct ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, interface_name, IFNAMSIZ - 1);
        ifr.ifr_name[IFNAMSIZ - 1] = '\0';

        if (ioctl(sockfd, SIOCGIFFLAGS, &ifr) < 0) {
            perror("SIOCGIFFLAGS");
            close(sockfd);
            continue;
        }

        // Check if the interface is up and running
        if (!(ifr.ifr_flags & IFF_UP) || !(ifr.ifr_flags & IFF_RUNNING)) {
            printf("Interface %s is not up or running\n", interface_name);
            close(sockfd);
            continue;
        }

        // Collect statistics for the current interface
        struct ifreq ifr2;
        memset(&ifr2, 0, sizeof(ifr2));
        strncpy(ifr2.ifr_name, interface_name, IFNAMSIZ - 1);
        ifr2.ifr_name[IFNAMSIZ - 1] = '\0';

        struct rtnl_link_stats64 *stats = (struct rtnl_link_stats64 *)malloc(sizeof(struct rtnl_link_stats64));
        memset(stats, 0, sizeof(struct rtnl_link_stats64));

        if (ioctl(sockfd, SIOCGIFSTATS, &ifr2) < 0) {
            perror("SIOCGIFSTATS");
            close(sockfd);
            continue;
        }

        // Update the interface statistics in the list
        interface_stats[i].timestamp = time(NULL);
        interface_stats[i].interface_name = strdup(interface_name);
        interface_stats[i].packet_count = stats->rx_packets;

        free(stats);
        close(sockfd);
    }

    // Clear the list of NFAPI_CRC_INDICATION_PDU_T structures if necessary
    if (interface_stats == NULL) {
        return;
    }

