// Define a structure to store UE statistics
typedef struct {
    int rnti;
    time_t lastUpdatedTime;
    float signalStrength;
} UEStats;

// Define a dynamic array to store the UE statistics
UEStats* ueStatsArray = NULL;
size_t ueStatsCount = 0;
size_t ueStatsCapacity = 0;

// Function to add a new UE statistic entry
void addUeStat(int rnti, time_t lastUpdatedTime, float signalStrength) {
    // Check if the array needs to be resized
    if (ueStatsCount == ueStatsCapacity) {
        ueStatsCapacity = ueStatsCapacity ? ueStatsCapacity * 2 : 16;
        UEStats* newArray = realloc(ueStatsArray, sizeof(UEStats) * ueStatsCapacity);
        if (newArray == NULL) {
            // Handle memory allocation error
            return;
        }
        ueStatsArray = newArray;
    }

    // Add the new UE statistic entry
    ueStatsArray[ueStatsCount].rnti = rnti;
    ueStatsArray[ueStatsCount].lastUpdatedTime = lastUpdatedTime;
    ueStatsArray[ueStatsCount].signalStrength = signalStrength;
    ++ueStatsCount;
}

// Function to update an existing UE statistic entry
void updateUeStat(int rnti, time_t lastUpdatedTime, float signalStrength) {
    // Find the index of the UE statistic entry to be updated
    size_t i = 0;
    for (; i < ueStatsCount; ++i) {
        if (ueStatsArray[i].rnti == rnti) {
            break;
        }
    }

    // Update the UE statistic entry if found
    if (i < ueStatsCount) {
        ueStatsArray[i].lastUpdatedTime = lastUpdatedTime;
        ueStatsArray[i].signalStrength = signalStrength;
    } else {
        // Handle the case where the UE statistic entry is not found
    }
}

// Function to remove an existing UE statistic entry
void removeUeStat(int rnti) {
    // Find the index of the UE statistic entry to be removed
    size_t i = 0;
    for (; i < ueStatsCount; ++i) {
        if (ueStatsArray[i].rnti == rnti) {
            break;
        }
    }

    // Remove the UE statistic entry if found
    if (i < ueStatsCount) {
        --ueStatsCount;
        memmove(&ueStatsArray[i], &ueStatsArray[i + 1], sizeof(UEStats) * (ueStatsCount - i));
    } else {
        // Handle the case where the UE statistic entry is not found
    }
}

// Function to iterate over all UE statistics and perform a callback function on each one
void iterateUeStats(void (*callback)(UEStats*)) {
    for (size_t i = 0; i < ueStatsCount; ++i) {
        callback(&ueStatsArray[i]);
    }
}

// Function to clean up stale entries based on a configurable timeout duration
void cleanUpStaleEntries(time_t timeoutDuration) {
    // Iterate over all UE statistics and remove any that are older than the specified timeout duration
    iterateUeStats((UEStats* ueStat) => {
        if (difftime(ueStat->lastUpdatedTime, time(NULL)) > timeoutDuration) {
            removeUeStat(ueStat->rnti);
        }
    });
}
