void* allocate_memory(size_t size) {
    void* ptr = NULL;
    if (size <= POOL_SIZE) {
        pthread_mutex_lock(&mutex);
        while (ptr == NULL && !pthread_cond_wait(&cond, &mutex)) {
            ptr = malloc(size);
        }
        pthread_mutex_unlock(&mutex);
    } else {
        ptr = malloc(size);
    }
    return ptr;
}

