// Define the function to initialize a TCP connection record
void init_tcp_connection_record(tcp_connection_record_t* record) {
    // Initialize the source and destination IP addresses
    record->source_ip = 0;
    record->destination_ip = 0;

    // Initialize the SYN and ACK timestamps
    record->syn_timestamp = 0;
    record->ack_timestamp = 0;

    // Initialize the data size to 0
    record->data_size = 0;
}

// Define the function to allocate a TCP connection record from the memory pool
tcp_connection_record_t* allocate_tcp_connection_record() {
    // Acquire the lock on the memory pool mutex
    pthread_mutex_lock(&memory_pool_mutex);

    // Check if there is enough free memory in the memory pool to allocate a new record
    if (memory_pool.free_memory < sizeof(tcp_connection_record_t)) {
        // Release the lock on the memory pool mutex and return NULL
        pthread_mutex_unlock(&memory_pool_mutex);
        return NULL;
    }

    // Allocate a new record from the memory pool
    tcp_connection_record_t* record = (tcp_connection_record_t*)memory_pool.memory_pool;
    memory_pool.memory_pool += sizeof(tcp_connection_record_t);
    memory_pool.used_memory += sizeof(tcp_connection_record_t);
    memory_pool.free_memory -= sizeof(tcp_connection_record_t);

    // Initialize the record
    init_tcp_connection_record(record);

    // Release the lock on the memory pool mutex
    pthread_mutex_unlock(&memory_pool_mutex);

    return record;
}

// Define the function to free a TCP connection record from the memory pool
void free_tcp_connection_record(tcp_connection_record_t* record) {
    // Acquire the lock on the memory pool mutex
    pthread_mutex_lock(&memory_pool_mutex);

    // Check if the record is valid
    if (record == NULL || record->source_ip == 0 || record->destination_ip == 0) {
        // Release the lock on the memory pool mutex and return
        pthread_mutex_unlock(&memory_pool_mutex);
        return;
    }

    // Free the record from the memory pool
    size_t record_size = sizeof(tcp_connection_record_t);
    void* memory_pool_ptr = (void*)&memory_pool.memory_pool;
    if ((uint64_t)record >= (uint64_t)memory_pool_ptr &&
        (uint64_t)record < (uint64_t)memory_pool_ptr + memory_pool.used_memory - record_size) {
        // Update the used and free memory in the memory pool
        memory_pool.used_memory -= record_size;
        memory_pool.free_memory += record_size;
    } else {
        // Release the lock on the memory pool mutex and return
        pthread_mutex_unlock(&memory_pool_mutex);
        return;
    }

    // Release the lock on the memory pool mutex
    pthread_mutex_unlock(&memory_pool_mutex);
}

