    if (list->num_records == list->max_records) {
        // If the list is full, double its size
        list->max_records *= 2;
        UE_CONNECTION_RECORD_T** new_records = realloc(list->records, list->max_records * sizeof(UE_CONNECTION_RECORD_T*));
        if (new_records == NULL) {
            // If the allocation fails, handle it gracefully
            printf("Failed to allocate memory for UE connection records\n");
            return;
        }
        list->records = new_records;
    }

    // Allocate a buffer for the new record
    void* buffer = malloc(M * sizeof(void));
    if (buffer == NULL) {
        printf("Failed to allocate memory for UE connection buffer\n");
        return;
    }

    // Initialize the new record and add it to the list
    UE_CONNECTION_RECORD_T* new_record = malloc(sizeof(UE_CONNECTION_RECORD_T));
    if (new_record == NULL) {
        printf("Failed to allocate memory for UE connection record\n");
        return;
    }
    new_record->ue_id = ue_id;
    new_record->adaptive_bandwidth_allocation_policy = adaptive_bandwidth_allocation_policy;
    new_record->buffer = buffer;
    list->records[list->num_records++] = new_record;
}

// Remove an UE connection record from the list
void remove_ue_connection(UE_CONNECTION_LIST_T* list, int ue_id) {
    // Find the index of the record to be removed
    int i;
    for (i = 0; i < list->num_records; i++) {
        if (list->records[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the record is found, remove it from the list and free its buffer
    if (i < list->num_records) {
        UE_CONNECTION_RECORD_T* removed_record = list->records[i];
        free(removed_record->buffer);
        free(removed_record);
        list->num_records--;
    }
}

// Update the bandwidth allocation policy for a UE connection record
void update_bandwidth_allocation(UE_CONNECTION_LIST_T* list, int ue_id, int adaptive_bandwidth_allocation_policy) {
    // Find the index of the record to be updated
    int i;
    for (i = 0; i < list->num_records; i++) {
        if (list->records[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the record is found, update its bandwidth allocation policy
    if (i < list->num_records) {
        UE_CONNECTION_RECORD_T* updated_record = list->records[i];
        updated_record->adaptive_bandwidth_allocation_policy = adaptive_bandwidth_allocation_policy;
    }
}
