    newNode->data->RNTI = RNTI;
    newNode->data->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Add the new node to the linked list
    if (*head == NULL) {
        *head = newNode;
    } else {
        LinkedListNode *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to remove a node from the linked list
void removeNode(LinkedListNode **head, int RNTI) {
    // Check if the linked list is empty
    if (*head == NULL) {
        return;
    }

    // Find the node with the matching RNTI value and remove it from the linked list
    LinkedListNode *current = *head;
    while (current != NULL && current->data->RNTI != RNTI) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current == *head) {
        *head = (*head)->next;
    } else {
        LinkedListNode *previous = (*head);
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }
    free(current->data);
    free(current);
}

// Function to validate the linked list for duplicate RNTIs
void validateList(LinkedListNode *head) {
