    assert(rntiHash != NULL);
    for (int i = 0; i < 10000; i++) {
        rntiHash[i] = -1;
    }

    // Iterate through the linked list and check for duplicate RNTIs
    LinkedListNode *current = head;
    while (current != NULL) {
        if (rntiHash[current->data->RNTI] != -1) {
            removeNode(&head, current->data->RNTI);
        } else {
            rntiHash[current->data->RNTI] = 1;
        }
        current = current->next;
