    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;
    }

    // Initialize list and count
    list->list = NULL;
    list->count = 0;

    // Generate random CRCFLAG for each structure
