        // Set RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG randomly
        pdu->rx_ue_information_tag = rand() % 65535;
        pdu->rnti = rand() % 4294967295;
        pdu->crc_indication_rel8_tag = rand() % 255;

        // Add structure to list
        pthread_mutex_lock(&list_mutex);
        if (list->count == 0) {
            list->list = pdu;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *last = list->list + list->count - 1;
            last->next = pdu;
        }
        list->count++;
        pthread_mutex_unlock(&list_mutex);
    }

    return list;
}

// Define function to free memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (!list) {
        return;
    }

    // Free memory for each structure in list
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->list;
    while (pdu) {
        NFAPI_CRC_INDICATION_PDU_T *next = pdu->next;
        free(pdu);
        pdu = next;
    }

    // Free memory for the list itself
    free(list);
}
