// Define the packet structure
typedef struct {
    uint64_t timestamp;
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t payload_len;
    char* payload;
} packet_t;

// Define the network interface structure
typedef struct {
    int fd; // File descriptor for the network interface
    bool is_valid; // Flag to indicate if the interface is valid
    uint32_t num_packets; // Number of packets in the array
    packet_t* packets; // Array of packet structures
} netif_t;

// Function to initialize and configure a network interface for handling data packets
int init_netif(netif_t* iface) {
    // Check if the interface is already initialized
    if (iface->is_valid) {
        return 0;
    }

    // Open the network interface file descriptor
    iface->fd = open("/dev/eth0", O_RDWR);
    if (iface->fd < 0) {
        perror("Failed to open network interface");
        return -1;
    }

    // Set the interface to non-blocking mode
    int flags = fcntl(iface->fd, F_GETFL);
    if (flags < 0 || fcntl(iface->fd, F_SETFL, flags | O_NONBLOCK) < 0) {
        perror("Failed to set non-blocking mode");
        close(iface->fd);
        return -1;
    }

    // Allocate memory for the packet array
    iface->packets = (packet_t*)malloc(sizeof(packet_t) * 1024);
    if (!iface->packets) {
        perror("Failed to allocate memory for packet array");
        close(iface->fd);
        return -1;
    }

    // Initialize the number of packets in the array
    iface->num_packets = 0;

    // Set the interface as valid
    iface->is_valid = true;

    return 0;
}

// Function to populate an array of packet structures with random data
int populate_packet_array(netif_t* iface, int num_packets) {
    // Check if the interface is valid
    if (!iface->is_valid) {
        return -1;
    }

    // Allocate memory for each packet structure
    for (int i = 0; i < num_packets; i++) {
        packet_t* packet = &iface->packets[i];
        packet->payload = (char*)malloc(sizeof(char) * 1024);
        if (!packet->payload) {
            perror("Failed to allocate memory for payload");
            return -1;
        }
    }

    // Fill each packet with random data
    for (int i = 0; i < num_packets; i++) {
        packet_t* packet = &iface->packets[i];
        packet->timestamp = get_timestamp();
        packet->src_ip = get_random_ip();
        packet->dst_ip = get_random_ip();
        packet->payload_len = get_random_payload_length();
        for (int j = 0; j < packet->payload_len; j++) {
            packet->payload[j] = get_random_char();
        }
    }

    return 0;
}

// Function to validate packet integrity by calculating a checksum and verifying it upon insertion into the array
int validate_packet(netif_t* iface, int index) {
    // Check if the interface is valid
    if (!iface->is_valid) {
        return -1;
    }

    // Calculate the checksum for the packet
    uint32_t checksum = calculate_checksum(iface->packets[index]);

    // Verify the checksum
    if (checksum != iface->packets[index].checksum) {
        perror("Checksum verification failed");
        return -1;
    }

    return 0;
}

// Function to handle a series of data packets and populate an array of packet structures
int handle_packets(netif_t* iface, int num_packets) {
    // Check if the interface is valid
    if (!iface->is_valid) {
        return -1;
    }

    // Populate the packet array with random data
    populate_packet_array(iface, num_packets);

    // Validate each packet's integrity
    for (int i = 0; i < num_packets; i++) {
        validate_packet(iface, i);
    }

    return 0;
}
