} NFAPI_CRC_INDICATION_LIST_T;

// Define the error rate thresholds for filtering unreliable indications
#define ERROR_RATE_THRESHOLD 0.1

// Define the function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Allocate memory for the list if it is NULL
    if (list->list == NULL) {
        list->list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->count = 1;
    } else {
        // Reallocate memory for the list to accommodate new elements
        list->list = realloc(list->list, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->count++;
    }

    // Generate a random RNTI for the new element
    uint16_t rnti = rand() % 65536;

    // Set the CRCFLAG to a randomly set value
    uint8_t crcflag = (rand() % 2) ? 0 : 1;

    // Add the new element to the list
    list->list[list->count - 1].RX_UE_INFORMATION_TAG = rnti;
    list->list[list->count - 1].RNTI = rnti;
    list->list[list->count - 1].CRCFLAG = crcflag;
}

// Define the function to validate the CRC flag using predefined error rate thresholds
void validate_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Calculate the error rate for the current PDU
    double error_rate = (double) pdu->CRCFLAG / (double) pdu->RX_UE_INFORMATION_TAG;

    // Filter out unreliable indications based on the predefined error rate threshold
    if (error_rate > ERROR_RATE_THRESHOLD) {
        printf("Filtering out unreliable CRC indication with RX_UE_INFORMATION_TAG %d and CRCFLAG %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->CRCFLAG);
    } else {
        printf("Accepting reliable CRC indication with RX_UE_INFORMATION_TAG %d and CRCFLAG %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->CRCFLAG);
    }
}

