Here's an example C function for managing a list of TCP connection records in a high-performance network server application:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

// Structure to store connection information
typedef struct {
    int id; // Unique connection ID
    char ip[INET_ADDRSTRLEN]; // Peer IP address
    uint16_t port; // Port number
    enum { ESTABLISHED, IDLE, CLOSED } state; // Connection state flag
} connection_record_t;

// List of all active connections
static connection_record_t *connections = NULL;

// Lock for synchronizing access to the list of connections
static pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and manage a list of TCP connection records
void init_connection_list(int num_connections) {
    // Allocate memory for the list of connections
    connections = (connection_record_t *)malloc(num_connections * sizeof(connection_record_t));
    if (!connections) {
        perror("Failed to allocate memory for connection list");
        exit(1);
    }

    // Initialize the list of connections with unique IDs and empty state flags
    for (int i = 0; i < num_connections; i++) {
        connections[i].id = i + 1;
        connections[i].state = ESTABLISHED;
    }
}

// Function to update the connection state based on network events
void update_connection_state(int id, enum { ESTABLISHED, IDLE, CLOSED } new_state) {
    // Acquire lock for synchronizing access to the list of connections
    pthread_mutex_lock(&connections_lock);

    // Find the connection record with the specified ID
    int i;
    for (i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            break;
        }
    }

    // Update the state flag of the found connection record
    if (i < num_connections) {
        connections[i].state = new_state;
    } else {
        printf("Connection with ID %d not found\n", id);
    }

    // Release lock for synchronizing access to the list of connections
    pthread_mutex_unlock(&connections_lock);
}

// Function to retrieve the connection state based on network events
enum { ESTABLISHED, IDLE, CLOSED } get_connection_state(int id) {
    // Acquire lock for synchronizing access to the list of connections
    pthread_mutex_lock(&connections_lock);

    // Find the connection record with the specified ID
    int i;
    for (i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            break;
        }
    }

    // Return the state flag of the found connection record, or CLOSED if not found
    enum { ESTABLISHED, IDLE, CLOSED } state = CLOSED;
    if (i < num_connections) {
        state = connections[i].state;
    }

    // Release lock for synchronizing access to the list of connections
    pthread_mutex_unlock(&connections_lock);

    return state;
}
