    OUT_OF_MEMORY,
    INVALID_INPUT,
    LOGGING_FAILURE
} ErrorCode;

// NFAPI_CRC_INDICATION_PDU_T structure definition
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Array of NFAPI_CRC_INDICATION_PDU_T structures
