// Lock for protecting concurrent access to the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage an array of NFAPI_CRC_INDICATION_PDU_T structures
ErrorCode manageCrcIndicationArray(int32_t N) {
    // Check if the input is valid
    if (N < 0 || N > 1000) {
        return INVALID_INPUT;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array needs to be resized
    if (N != crcIndicationArraySize) {
        // Free any existing memory allocated for the array
        free(crcIndicationArray);

        // Allocate new memory for the array
        crcIndicationArray = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
        if (crcIndicationArray == NULL) {
            pthread_mutex_unlock(&mutex);
            return OUT_OF_MEMORY;
        }

        // Initialize the array with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        for (int i = 0; i < N; i++) {
            crcIndicationArray[i].RX_UE_INFORMATION_TAG = rand() % 1000;
            crcIndicationArray[i].RNTI = rand() % 1000;
            crcIndicationArray[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        }

        // Update the size of the array
        crcIndicationArraySize = N;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return SUCCESS;
}

// Function to populate the array with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
void populateCrcIndicationArray() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Populate the array with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < crcIndicationArraySize; i++) {
        crcIndicationArray[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crcIndicationArray[i].RNTI = rand() % 1000;
        crcIndicationArray[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to free allocated memory when no longer needed
void freeCrcIndicationArray() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Free any existing memory allocated for the array
    if (crcIndicationArray != NULL) {
        free(crcIndicationArray);
        crcIndicationArray = NULL;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to handle memory allocation failures robustly
void handleMemoryAllocationFailure() {
    // Log a message indicating that memory allocation failed
    printf("Memory allocation failure\n");

    // Free any existing memory allocated for the array
    freeCrcIndicationArray();
}

// Function to handle potential race conditions during deallocation and synchronizing access to shared resources
void handleRaceConditions() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if any other thread is currently accessing the array
    if (crcIndicationArray != NULL) {
        // Wait for the other thread to finish accessing the array
        while (1) {
            if (pthread_mutex_trylock(&mutex) == 0) {
                break;
            } else {
                usleep(10);
            }
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

