} NFAPI_UE_INFO_T;

// Define the array of UE information structures
NFAPI_UE_INFO_T *ue_info_array = NULL;

// Define the maximum number of entries in the array
#define MAX_NUM_ENTRIES 10000

// Define the predefined valid range for RNTIs
#define MIN_RNTI 0
#define MAX_RNTI 65535

// Define the function to dynamically allocate and populate an array of UE information structures
NFAPI_UE_INFO_T *allocate_ue_info_array(uint16_t num_entries) {
    // Check if the number of entries is within the valid range
    assert(num_entries <= MAX_NUM_ENTRIES);

    // Allocate memory for the array of UE information structures
    NFAPI_UE_INFO_T *ue_info_array = (NFAPI_UE_INFO_T *)malloc(sizeof(NFAPI_UE_INFO_T) * num_entries);
    if (!ue_info_array) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the RNTIs and CRC indication tags for each structure
    for (uint16_t i = 0; i < num_entries; i++) {
        ue_info_array[i].rnti = MIN_RNTI + (rand() % (MAX_RNTI - MIN_RNTI));
        ue_info_array[i].crc_indication_rel8.crflag = rand() & 0x1;
    }

    // Ensure no two consecutive structures share the same RNTI value
    for (uint16_t i = 0; i < num_entries - 1; i++) {
        if (ue_info_array[i].rnti == ue_info_array[i + 1].rnti) {
