// Define the structure for an NFAPI_RX_FRAME_T
typedef struct {
    RRC_PDU_T rrc_pdu;
    uint64_t timestamp;
    void* payload;
} NFAPI_RX_FRAME_T;

// Define the linked list node for managing the frames
typedef struct Node {
    NFAPI_RX_FRAME_T frame;
    struct Node* next;
} Node;

// Define the linked list head
Node* head = NULL;

// Define the mutex for protecting concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new frame to the linked list
void addFrame(NFAPI_RX_FRAME_T* frame) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Create a new node for the frame
    Node* newNode = malloc(sizeof(Node));
    newNode->frame = *frame;
    newNode->next = NULL;

    // If the linked list is empty, set the head to the new node
    if (head == NULL) {
        head = newNode;
    } else {
        // Otherwise, add the new node to the end of the linked list
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing frame in the linked list
void updateFrame(NFAPI_RX_FRAME_T* frame) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find the node for the frame in the linked list
    Node* current = head;
    while (current != NULL && &(current->frame) != frame) {
        current = current->next;
    }

    // If the frame was found, update its payload and timestamp
    if (current != NULL) {
        current->frame.payload = frame->payload;
        current->frame.timestamp = frame->timestamp;
    } else {
        printf("Frame not found in linked list\n");
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the frames in the linked list and process their payloads
void iterateFrames(void (*processPayload)(NFAPI_RX_FRAME_T*)) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Iterate over the frames in the linked list and process their payloads
    Node* current = head;
    while (current != NULL) {
        processPayload(&(current->frame));
        current = current->next;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to reclaim unused memory in the linked list
void reclaimMemory() {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Iterate over the frames in the linked list and free any unused nodes
    Node* current = head;
    while (current != NULL) {
        if (current->frame.payload == NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}
