}

// Function to scale the system effectively with increasing data volume and concurrent user requests
void scale(int numThreads) {
    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Create a new linked list for each thread
    Node **lists = malloc(sizeof(Node *) * numThreads);
    for (int i = 0; i < numThreads; i++) {
