    Node *current = head;
    while (current != NULL) {
        int threadIndex = current->data->tag % numThreads;
        add(lists[threadIndex], current->data);
        current = current->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
