// Define the structure for a MAC PDU
typedef struct {
    MAC_HEADER_T header;
    MAC_PAYLOAD_T payload;
} MAC_PDU_T;

// Define the dynamic array of MAC PDUs
static MAC_PDU_T* pdu_array = NULL;
static size_t pdu_count = 0;
static size_t pdu_capacity = 0;

// Function to add a new PDU entry
int mac_pdu_add(MAC_HEADER_T header, MAC_PAYLOAD_T payload) {
    // Check if the array is full
    if (pdu_count == pdu_capacity) {
        // Double the capacity of the array
        size_t new_capacity = pdu_capacity * 2;
        MAC_PDU_T* new_array = realloc(pdu_array, new_capacity * sizeof(MAC_PDU_T));
        if (new_array == NULL) {
            // Handle out-of-memory condition
            return -1;
        }
        pdu_array = new_array;
        pdu_capacity = new_capacity;
    }

    // Add the new PDU entry to the array
    MAC_PDU_T* new_pdu = &pdu_array[pdu_count];
    memcpy(&new_pdu->header, header, sizeof(MAC_HEADER_T));
    memcpy(&new_pdu->payload, payload, sizeof(MAC_PAYLOAD_T));
    pdu_count++;

    return 0;
}

// Function to update an existing PDU entry
int mac_pdu_update(size_t index, MAC_HEADER_T header, MAC_PAYLOAD_T payload) {
    // Check if the index is valid
    if (index >= pdu_count) {
        return -1;
    }

    // Update the PDU entry in the array
    MAC_PDU_T* pdu = &pdu_array[index];
    memcpy(&pdu->header, header, sizeof(MAC_HEADER_T));
    memcpy(&pdu->payload, payload, sizeof(MAC_PAYLOAD_T));

    return 0;
}

// Function to retrieve a PDU entry by index
int mac_pdu_get(size_t index, MAC_HEADER_T* header, MAC_PAYLOAD_T* payload) {
    // Check if the index is valid
    if (index >= pdu_count) {
        return -1;
    }

    // Retrieve the PDU entry from the array
    MAC_PDU_T* pdu = &pdu_array[index];
    memcpy(header, &pdu->header, sizeof(MAC_HEADER_T));
    memcpy(payload, &pdu->payload, sizeof(MAC_PAYLOAD_T));

    return 0;
}

// Function to free the memory allocated for the PDU array
void mac_pdu_free() {
    if (pdu_array != NULL) {
        free(pdu_array);
        pdu_array = NULL;
        pdu_count = 0;
        pdu_capacity = 0;
    }
}
