// Define the function to populate the list of RX UE information structures
void populate_rx_ue_info_list(int num_threads) {
    // Initialize the list of RX UE information structures
    rx_ue_info_list = (RX_UE_INFO *)malloc(sizeof(RX_UE_INFO) * LIST_SIZE);
    if (!rx_ue_info_list) {
        printf("Failed to allocate memory for the list of RX UE information structures\n");
        return;
    }

    // Initialize the mutex and condition variable for protecting the list from concurrent access
    pthread_mutex_init(&rx_ue_info_list_mutex, NULL);
    pthread_cond_init(&rx_ue_info_available, NULL);

    // Create a thread pool to populate the list of RX UE information structures
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, populate_rx_ue_info_list_thread, NULL)) {
            printf("Failed to create thread %d\n", i);
            return;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL)) {
            printf("Failed to join thread %d\n", i);
            return;
        }
    }

    // Clean up the mutex and condition variable
    pthread_mutex_destroy(&rx_ue_info_list_mutex);
    pthread_cond_destroy(&rx_ue_info_available);
}

// Define the thread function to populate a single RX UE information structure
void *populate_rx_ue_info_list_thread(void *arg) {
    // Loop until the list is full or a new RX UE information structure is available
    while (1) {
        // Acquire the mutex to protect the list from concurrent access
        pthread_mutex_lock(&rx_ue_info_list_mutex);

        // Check if the list is full
        if (rx_ue_info_list_size >= LIST_SIZE) {
            // Release the mutex and return
            pthread_mutex_unlock(&rx_ue_info_list_mutex);
            break;
        }

        // Check if a new RX UE information structure is available
        if (rx_ue_info_available) {
            // Populate the next available RX UE information structure
            populate_next_rx_ue_info();
        } else {
            // Release the mutex and wait for a new RX UE information structure to become available
            pthread_mutex_unlock(&rx_ue_info_list_mutex);
            pthread_cond_wait(&rx_ue_info_available, &rx_ue_info_list_mutex);
        }
    }
}

// Define the function to populate a single RX UE information structure
void populate_next_rx_ue_info() {
    // Initialize the RX UE information structure
    RX_UE_INFO *rx_ue_info = (RX_UE_INFO *)malloc(sizeof(RX_UE_INFO));
    if (!rx_ue_info) {
