int generate_valid_rnti() {
    // Generate a random RNTI between 0 and 65535
    int rnti = rand() % 65536;

    // Check if the RNTI is already in use
    pthread_mutex_lock(&rx_ue_info_list_mutex);
    for (int i = 0; i < rx_ue_info_list_size; i++) {
        if (rx_ue_info_list[i].rnti == rnti) {
