    MAC_TIMING_INFO timing_info;
} MAC_PDU_T;

// Define a function to allocate memory for a new PDU structure
MAC_PDU_T* alloc_pdu() {
    // Allocate memory for the PDU structure
    MAC_PDU_T* pdu = malloc(sizeof(MAC_PDU_T));
    if (pdu == NULL) {
        printf("Error: Failed to allocate memory for new PDU\n");
        return NULL;
    }

    // Initialize the PDU structure with default values
    memset(pdu, 0, sizeof(MAC_PDU_T));

    // Return a pointer to the allocated PDU structure
    return pdu;
}

// Define a function to deallocate memory for a PDU structure
void free_pdu(MAC_PDU_T* pdu) {
    if (pdu != NULL) {
        // Deallocate memory for the PDU structure
        free(pdu);
    }
}

// Define a function to add a new PDU structure to the array
void add_pdu(MAC_PDU_T* pdu, MAC_PDU_T** pdu_array, int* pdu_count) {
    // Check if the PDU structure is valid
    if (pdu == NULL || pdu->payload.data == NULL) {
        printf("Error: Invalid PDU structure\n");
        return;
    }

    // Check if the payload is valid
    if (!validate_payload(pdu)) {
        printf("Error: Invalid payload\n");
        return;
    }

    // Allocate memory for a new array element if necessary
    if (*pdu_count == 0) {
        *pdu_array = malloc(sizeof(MAC_PDU_T));
        if (*pdu_array == NULL) {
            printf("Error: Failed to allocate memory for PDU array\n");
            return;
        }
    } else {
        // Reallocate memory for the array with a new element
        *pdu_array = realloc(*pdu_array, (*pdu_count + 1) * sizeof(MAC_PDU_T));
        if (*pdu_array == NULL) {
            printf("Error: Failed to reallocate memory for PDU array\n");
            return;
        }
    }

    // Copy the new PDU structure into the array
    memcpy(&(*pdu_array)[*pdu_count], pdu, sizeof(MAC_PDU_T));
    (*pdu_count)++;
}

// Define a function to remove a PDU structure from the array
void remove_pdu(MAC_PDU_T** pdu_array, int* pdu_count, MAC_HEADER header) {
    // Check if the array is empty
    if (*pdu_count == 0) {
        return;
    }

    // Find the index of the PDU structure with the matching header
    int i = 0;
    while (i < *pdu_count && !header_match(header, &(*pdu_array)[i])) {
        i++;
    }

    // Check if the PDU structure was found
    if (i == *pdu_count) {
        printf("Error: PDU with header %d not found\n", header);
        return;
    }

    // Remove the PDU structure from the array
    memmove(&(*pdu_array)[i], &(*pdu_array)[i + 1], (*pdu_count - i) * sizeof(MAC_PDU_T));
    (*pdu_count)--;
}

// Define a function to validate the payload of a PDU structure
bool validate_payload(MAC_PDU_T* pdu) {
    // Calculate the checksum of the payload data
    uint32_t checksum = calculate_checksum(pdu->payload.data, pdu->payload.length);

    // Compare the calculated checksum with the expected value
    if (checksum == pdu->payload.checksum) {
        return true;
    } else {
        printf("Error: Invalid payload\n");
        return false;
    }
}

// Define a function to calculate the checksum of a block of data
uint32_t calculate_checksum(const void* data, size_t length) {
    // Initialize the checksum with a seed value
    uint32_t checksum = 0xFFFFFFFF;

    // Iterate over the data and update the checksum
    const uint8_t* ptr = (const uint8_t*)data;
    for (size_t i = 0; i < length; i++) {
        checksum ^= *ptr++;
    }

    return checksum;
}

// Define a function to compare the header of two PDU structures
bool header_match(MAC_HEADER header1, MAC_HEADER header2) {
    // Compare the source and destination addresses
    if (header1.src != header2.src || header1.dst != header2.dst) {
        return false;
    }

    // Compare the protocol ID
    if (header1.protocol_id != header2.protocol_id) {
        return false;
    }

    return true;
}
