    // Set the values of the new element
    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    newElement->CRCFLAG = CRCFLAG;

    // Add the new element to the array
    crcIndicationArray[crcIndicationArraySize++] = newElement;
}

// Function to clear the array when it is no longer needed
void clearCrcIndicationArray() {
    for (size_t i = 0; i < crcIndicationArraySize; i++) {
        free(crcIndicationArray[i]);
    }
    crcIndicationArraySize = 0;
}

