    // Allocate memory for the dynamic array
    lte_uu_packets = (LTE_Uu_Packet_t*)malloc(sizeof(LTE_Uu_Packet_t) * INITIAL_PACKETS_CAPACITY);
    if (!lte_uu_packets) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for LTE Uu packets\n");
        return;
    }
    lte_uu_packets_len = INITIAL_PACKETS_CAPACITY;
