// Function to insert a new LTE Uu packet into the dynamic array
void insert_lte_uu_packet(LTE_Uu_Packet_t* packet) {
    // Check if the dynamic array needs to be resized
    if (lte_uu_packets_len == lte_uu_packets_capacity) {
        // Resize the dynamic array by a factor of 2
        size_t new_capacity = lte_uu_packets_capacity * 2;
        LTE_Uu_Packet_t* new_array = (LTE_Uu_Packet_t*)realloc(lte_uu_packets, sizeof(LTE_Uu_Packet_t) * new_capacity);
        if (!new_array) {
            // Handle memory allocation failure gracefully
            printf("Error: Failed to resize LTE Uu packets array\n");
            return;
        }
        lte_uu_packets = new_array;
        lte_uu_packets_capacity = new_capacity;
    }
    // Insert the new packet into the dynamic array
    lte_uu_packets[lte_uu_packets_len++] = *packet;
}

// Function to retrieve a LTE Uu packet from the dynamic array by its unique identifier
