    // Iterate over the dynamic array and find the matching packet
    for (size_t i = 0; i < lte_uu_packets_len; i++) {
        if (lte_uu_packets[i].ue_id == ue_id) {
            return &lte_uu_packets[i];
        }
    }
    // Return NULL if the packet is not found
    return NULL;
}

// Function to periodically clean up unused entries in the dynamic array
void cleanup_unused_entries() {
    // Iterate over the dynamic array and remove any unused entries
    for (size_t i = 0; i < lte_uu_packets_len; i++) {
        if (!lte_uu_packets[i].seq_id) {
            // Remove the unused entry by shifting all subsequent entries one position back
            for (size_t j = i + 1; j < lte_uu_packets_len; j++) {
                lte_uu_packets[j - 1] = lte_uu_packets[j];
            }
            // Decrement the length of the dynamic array by one
            lte_uu_packets_len--;
        }
    }
}
