    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node to store the elements
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Define the function to manage the dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
void manage_array(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    // Initialize the mutex for synchronization
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define the function to add a new element to the array
    void add(NFAPI_CRC_INDICATION_PDU_T *data) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if the array is full
        if (size == 0) {
            // Reallocate the array with a new size
            array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (size + 1));
            // Initialize the new element
            array[size] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            size++;
        } else {
            // Insert the new element at the end of the array
            array[size - 1]->next = malloc(sizeof(Node));
            array[size - 1]->next->data = data;
            array[size - 1]->next->next = NULL;
        }

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to retrieve an element from the array by RNTI
    NFAPI_CRC_INDICATION_PDU_T *retrieve(RNTI rnti) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Iterate through the array until we find the element with the matching RNTI
        for (int i = 0; i < size; i++) {
            if (array[i]->rnti == rnti) {
                // Release the lock on the mutex
                pthread_mutex_unlock(&mutex);
                return array[i];
            }
        }

        // If we didn't find the element, return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Define the function to remove an element from the array by RNTI
    void remove(RNTI rnti) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Iterate through the array until we find the element with the matching RNTI
        for (int i = 0; i < size; i++) {
            if (array[i]->rnti == rnti) {
                // Remove the element from the array
                Node *temp = array[i];
                array[i] = temp->next;
                free(temp);
                break;
            }
        }

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to calculate statistics about the current state of the list
    void stats() {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

