// Define the function for measuring the performance of the function under different loads
double measure_performance(NFAPI_CRC_INDICATION_LIST_T *list, int load) {
    // Initialize the start time and end time variables
    struct timespec start, end;

    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Start the timer before processing the data
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Process the data under the specified load
    for (int i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *indication = &list->data[i];
