    // Stop the timer after processing the data
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Unlock the list to allow concurrent access from multiple threads
    pthread_mutex_unlock(&list->mutex);

    // Calculate the elapsed time in milliseconds
    double elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1e6;

    // Return the performance under the specified load
    return elapsed / load;
}
